window.ATLAS_I18N_LOR={"01IO012":["Bliźniacze Dyscypliny","Daj sojusznikowi +3|+0 albo +0|+3 w tej rundzie.","","„Nie bój się zmiany. Sprawi, że poznasz swoje ograniczenia i zwiększysz swą świadomość. To nasz najlepszy nauczyciel”. — Karma","Zaklęcie",[],["Ionia"],"ZWYKŁE"],"01IO015":["Yasuo","Gdy nałożysz Ogłuszenie lub Wycofasz wroga, zadam mu 2 pkt. obrażeń.","Udało ci się Ogłuszyć lub Wycofać 5+ jednostek.","„Śmierć jest niczym wiatr…”","Jednostka",[],["Ionia"],"Bohater"],"01IO020":["Powierniczka Masek","Gdy mnie przywołasz, daj innym sojusznikom +1|+0 w tej rundzie.","","„Nastał dzień, w którym staniesz się przykładem dyscypliny, ciężkiego treningu, skromności i równowagi. Witaj w szeregach Kinkou”.","Jednostka",[],["Ionia"],"ZWYKŁE"],"01IO045":["Zwiastun Wiosny","Wsparcie: Daj wspieranemu przeze mnie sojusznikowi Kradzież Życia w tej rundzie.","","„Zimy owej usłyszeliśmy \nkroki w głębokim śniegu. \nI zieleń buchnęła liści. \nI koniec był zimy biegu”.\n — Poemat Shon-Xan","Jednostka",[],["Ionia"],"ZWYKŁE"],"01IO008":["Fae Ostrzowładna","Gdy Ogłuszysz lub Wycofasz jednostkę, przyznaj mi +2|+0.","","„Myślisz, że jestem urocza? Futrzasta? Zobaczymy, jak spodoba ci się TO!”","Jednostka",["YORDLE"],["Ionia"],"RZADKIE"],"01IO040":["Ostrze Życia Kinkou","","","„Kiedyś w tym miejscu było pełno naszych szkół, świątyń i domostw. Teraz możemy tylko przemykać się przez ich spowite cieniem ruiny. Zakon Zeda splugawił dziedzictwo tego świętego miejsca. Dopilnuję, aby gorzko tego pożałował”.","Jednostka",[],["Ionia"],"ZWYKŁE"],"01IO041":["Karma","Koniec rundy: Stwórz w ręce losowe zaklęcie z twoich regionów.","Masz Oświecenie.","„Dzięki zadumie możemy się skupić, by pokonać każdą przeszkodę”.","Jednostka",[],["Ionia"],"Bohater"],"01IO011":["Powrót","Wycofaj sojusznika.","","Rozważny wojownik nie rusza bezmyślnie do bitwy, umiejąc ocenić sytuację. Skuteczny odwrót poprawi szanse w kolejnym starciu.","Zaklęcie",[],["Ionia"],"ZWYKŁE"],"01IO009":["Zed","Atak: Przywołaj atakujący Żywy Cień o moich statystykach.","Widziałem, jak ja lub moje sojusznicze Żywe Cienie uderzyliśmy wrogi Nexus dwa razy.","„Równowaga jest dla głupców. Mrok wskazał mi ścieżkę prawdziwej potęgi”.","Jednostka",[],["Ionia"],"Bohater"],"01IO014":["Mędrzec z Zielonej Polany","Gdy mnie przywołasz, przyznaj sojusznikom w ręce +1|+1.","","Ioniańska wiedza została skrzętnie spisana, jednak dopiero legendy i nauki przekazywane przez najstarszych mędrców tej krainy potrafią tchnąć w te księgi nowe życie.","Jednostka",[],["Ionia"],"ZWYKŁE"],"01IO005":["Zwinny Poro","","","„Może zabrzmi to dziwnie, ale ostatnie, co pamiętam, to... futerko...?” — Navoriański Rabuś","Jednostka",["PORO"],["Ionia"],"ZWYKŁE"],"01IO044":["Navoriański Konspirator","Aby mnie zagrać, Wycofaj sojusznika.","","„Chodź, musimy się stąd wydostać! Jak mam na imię? Powiem ci po drodze, zaufaj mi...”","Jednostka",[],["Ionia"],"ZWYKŁE"],"01IO023":["Brylantowy Lwobrońca","Zagraj: Przyznaj sojusznikowi w ręce +3|+3.","","„W czasach konfliktu wieśniacy szukali pomocy u pradawnej strażniczki Jesiennej Doliny. Ci, którzy przemówili do jej serca, byli obdarzani błogosławieństwem, które mogło przechylić szalę zwycięstwa”.\n– Saga Pierwotnej Krainy","Jednostka",[],["Ionia"],"RZADKIE"],"01IO029":["Zasiane Ziarna","Przyznaj sojusznikom w ręce +1|+0.","","„To nie tylko nasiona, moje dzieci. To dziedzictwo tej ziemi i nadzieja na lepszą przyszłość”. — Karma","Zaklęcie",[],["Ionia"],"RZADKIE"],"01IO003":["Znak Śmierci","Usuń Efemeryczność sojusznika i przyznaj ją wrogowi.","","„Jestem ostrzem w mroku”. — Zed\n\n","Zaklęcie",[],["Ionia"],"RZADKIE"],"01IO047":["Cienisty Błysk","Przyznaj WSZYSTKIM walczącym stronnikom Efemeryczność.","","Gdy zakłóci się balans struktur magii, zaczynają przenikać do świata śmiertelników. Skutki są raczej niepożądane.","Zaklęcie",[],["Ionia"],"EPICKIE"],"01IO026":["Inspirujący Mentor","Zagraj: Przyznaj sojusznikowi w ręce +1|+0.","","„Lata treningu wyrzeźbiły tę muskulaturę! Setki godzin spędzonych na obserwacji ptaków, opisywaniu chmur i podnoszeniu tacek ze słodkimi drożdżóweczkami. Kto inny miałby tyle zapału?”","Jednostka",[],["Ionia"],"ZWYKŁE"],"01IO024":["Brzask i Zmierzch","Przywołaj 2 dokładne kopie sojusznika. Otrzymują Efemeryczność.","","„Shen to człowiek rozdarty między dwoma światami. I zawiedzie każdy z nich. Ja żyję wyłącznie dla Ionii”. — Zed","Zaklęcie",[],["Ionia"],"RZADKIE"],"01IO028":["Łuskowaty Zębacz","Zagraj: Przyznaj mi +3|+0 lub +0|+3.","","Jeden z najstarszych mieszkańców Zielonej Polany. Przetrwał lata zmian dzięki nieustającej adaptacji.","Jednostka",["GAD"],["Ionia"],"ZWYKŁE"],"01IO057":["Cienista Skrytobójczyni","Gdy mnie przywołasz, dobierz 1 kartę.","","Bezszelestnie mknie\nPrzedzierając się przez cienie\nŚladem jedynie pazury.","Jednostka",[],["Ionia"],"ZWYKŁE"],"01IO032":["Shen","Wsparcie: Daj wspieranemu przeze mnie sojusznikowi Barierę w tej rundzie.","Widziałem, jak sojusznicy otrzymali Barierę 5+ razy.","„Niczym złączone dłonie świat żywych i świat duchowy stale się splatają…” ","Jednostka",[],["Ionia"],"Bohater"],"01IO013":["Mroczny Upiór","","","„Co poświęcisz w zamian za moc? Twoja ścieżka rozpocznie się od przysięgi i zakończy dopiero, gdy zabierze ci wszystko, co masz do zaoferowania”. — Zed","Jednostka",[],["Ionia"],"ZWYKŁE"],"01IO018":["Pośpiech","Daj sojusznikowi +1|+0 i Szybki Atak w tej rundzie.","","Walka to jedynie wyścig, w którym jedna ze stron pierwsza odbierze drugiej życie.","Zaklęcie",[],["Ionia"],"ZWYKŁE"],"01IO056":["Yone Ścigający Wiatr","Zagraj: Ogłusz 2 wrogów.","","„Gdy byłem dzieckiem, zapytałem brata, czy wiatr ucieka, czy jedynie za czymś podąża. Od tego czasu kroczył za mną, pragnąc dalszych nauk. Teraz ja kroczę za nim, pragnąc sprawiedliwości”.\n","Jednostka",[],["Ionia"],"RZADKIE"],"01IO016":["Mędrzec Zefiru","Zagraj: Stwórz w ręce dokładną kopię karty innej niż Mędrzec Zefiru.","","„Gdy wojownik zaczął opłakiwać porażkę, zwrócił się do niego członek starszyzny: »Poszukaj mędrca w chmurach. Tylko on może zwrócić światu to, co stracone, ale wciąż w pamięci«”.\n— Saga Pierwotnej Krainy","Jednostka",["PTAK"],["Ionia"],"RZADKIE"],"01IO036":["Zwiadowcy z Zielonej Polany","Uderzenie: Zmniejsz koszt najdroższej jednostki w ręce o 1.","","„Tu patrol! Mamy tu futrzastego... nie... DWA futrzaste stwory, pędzą prosto na nas! Prosimy o wspa... ach. Chwila. Znowu mam odwróconą lunetę...”","Jednostka",["YORDLE"],["Ionia"],"ZWYKŁE"],"01IO033":["Minah Rączonoga","Zagraj: Wycofaj 3 wrogów.","","„Właśnie przedzieraliśmy się przez wrzosowisko, gdy nagle znikąd pojawił się ten DZIECIAK i BACH, BACH, BACH, położył nas na łopatki!” — Navoriański Rabuś","Jednostka",[],["Ionia"],"EPICKIE"],"01IO001":["Rytuał Odnowienia","Ulecz sojusznika lub swój Nexus o 4 pkt. Dobierz 1 kartę.","","„Tylko gdy umysł dozna oświecenia, ciało może poczuć się spełnione”. — Karma","Zaklęcie",[],["Ionia"],"RZADKIE"],"01IO010":["Wsparcie","Zamień 2 sojuszników. Daj im Barierę w tej rundzie.","","„Równowaga pozwala mi stąpać pewnie”. — Shen\n","Zaklęcie",[],["Ionia"],"RZADKIE"],"01IO022":["Duch","Daj sojusznikowi Nieuchwytność w tej rundzie.","","„Pozostań w cieniu. Nie wracaj, dopóki nie wypełnisz zadania”. — Zed","Zaklęcie",[],["Ionia"],"ZWYKŁE"],"01IO021":["Pisklę Nieboskrzydła","Gdy mnie przywołasz, daj innym sojusznikom +2|+2 w tej rundzie.","","„Wiosna najwcześniej kwitnie na klifach Ionii. To stamtąd, wzbudzona biciem młodych skrzydeł, nadchodzi delikatna bryza zapowiadająca łagodniejszą porę roku”.\n– Saga Pierwotnej Krainy","Jednostka",[],["Ionia"],"EPICKIE"],"01IO054":["Przenikliwość Wieków","Stwórz w ręce inne losowe zaklęcie z twoich regionów.\nOświecenie: Stwórz zamiast tego 2 zaklęcia.","","„Gdy twoja nadzieja gaśnie, wiedz, że nigdy nie jesteś sam. Przeszłość jest po naszej stronie. Niezliczone razy widziała jutro, które przynosi nadzieję”. — Karma","Zaklęcie",[],["Ionia"],"RZADKIE"],"01IO027":["Cicha Wieszczka Cieni","Uderzenie w Nexus: Stwórz moją kopię w ręce.","","„Ciało przemija. Jest kruche. Delikatne jak granica między światłem i cieniem”.","Jednostka",[],["Ionia"],"EPICKIE"],"01IO031":["Pochłaniacz Chmur","Twoje zaklęcia Błyskawiczne i Skupienia kosztują o 1 mniej.","","Jego pieśni docierały aż do wiosek — długie, niskie fale dźwiękowe staczały z niebios ku zboczom, każda bezkształtna i dziwna niczym popołudniowy obłok.","Jednostka",[],["Ionia"],"RZADKIE"],"01IO002":["Wola Ionii","Wycofaj jednostkę.","","Gdy najeźdźcy po raz pierwszy postawili stopę na ioniańskiej ziemi, szybko przekonali się, że nie wystarczy zniewolić jej mieszkańców.","Zaklęcie",[],["Ionia"],"ZWYKŁE"],"01IO017":["Navoriański Zwiadowca Ostrzy","Gdy mnie przywołasz, daj mi Nieuchwytność w tej rundzie.","","„Dorwę go, żaden problem. Wyciągnij mnie stamtąd, a podzielę się łupem. Nie pożałujesz!”","Jednostka",["YORDLE"],["Ionia"],"ZWYKŁE"],"01IO042":["Sparingpartner","Gdy przywołasz innego sojusznika, daj mi +1|+1 w tej rundzie.","","„Po co komu walka, jeśli nikt cię nie dopinguje?”","Jednostka",[],["Ionia"],"ZWYKŁE"],"01IO006":["Duet z Zielonej Polany","Gdy przywołasz innego sojusznika, daj mi +1|+0 w tej rundzie.","","„Hej, uważaj na te gałęzie! W lewo! W LEWO!”\n„Kiedy ja usiądę na TWOIM grzbiecie, Futrzaku, to udamy się tam, gdzie ty chcesz. Teraz lepiej zdaj się na mnie!”","Jednostka",[],["Ionia"],"RZADKIE"],"01IO050":["Mistrzyni Ścieżek Kinkou","Przymierze: Przywołaj sojusznika o koszcie 1 ze swojej talii.","","Gdziekolwiek nie pójdzie robi wszystko, by inni mogli iść w jej ślady.","Jednostka",[],["Ionia"],"RZADKIE"],"01IO048":["Yusari","","","„Twój zakon wypędził nas z naszych ziem. Udowodniłeś swą potęgę, mistrzu Zedzie. Teraz pozwól, że udowodnię, iż jestem godzien twych nauk”.","Jednostka",[],["Ionia"],"RZADKIE"],"01IO007":["Ren Cieniste Ostrze","Uderzenie: Stwórz w ręce kartę Mroczny Upiór.","","„Uciekaj. Walcz. Kryj się. To bez znaczenia. Cienie i tak tobą zawładną”.","Jednostka",[],["Ionia"],"EPICKIE"],"01IO053":["Szmaragdowy Przebudzony","Oświecenie: Otrzymuję +4|+4.","","„Wojna karmi się naszymi najprostszymi instynktami. Na szczęście te nie mają władzy nad największymi z cnót: zaufaniem, cierpliwością i kontemplacją”.","Jednostka",[],["Ionia"],"ZWYKŁE"],"01IO004":["Mikstura Zdrowia","Ulecz sojusznika lub swój Nexus o 3 pkt.","","Każde pokolenie, region czy rodzina ma swoje sprawdzone lekarstwa. Niektóre są oczywiście bardziej skuteczne od innych.","Zaklęcie",[],["Ionia"],"ZWYKŁE"],"01IO049":["Negacja","Zatrzymaj Szybkie zaklęcie, Powolne zaklęcie lub umiejętność.","","Nie.","Zaklęcie",[],["Ionia"],"RZADKIE"],"01IO052":["Navoriański Rozbójnik","Gdy mnie przywołasz, przywołaj kartę Navoriański Rabuś o moich statystykach.","","„Byłem wędrownym grajkiem. Znali mnie w każdej wiosce stąd do Placidium. Potem pojawili się Noxianie. Teraz żyję za skradziony pieniądz. Matka miała rację, trzeba było zostać znachorem...”","Jednostka",[],["Ionia"],"ZWYKŁE"],"01IO030":["Empireum","","","„Ściągające na nas kłęby chmur wiły się niczym olbrzymi wąż, a potężny wiatr wgniótł nasz oddział w ziemię. Próbowaliśmy za nim podążać, ale jak można złapać wiatr?” — Generał Legionu","Jednostka",["SMOK"],["Ionia"],"EPICKIE"],"01IO019":["Opiekunka Zielonej Polany","Gdy sojusznik otrzyma Barierę, przyznaj mi +2|+0.","","„Polana chroni swoich mieszkańców. A ty... ty nie jesteś stąd...”","Jednostka",[],["Ionia"],"ZWYKŁE"],"01IO046":["Nawałnica Stali","Ogłusz atakującego wroga.","","„Hasagi!” – Yasuo","Zaklęcie",["ŻYWIOŁ"],["Ionia"],"RZADKIE"],"01IO037":["Schronienie Ducha","Daj sojusznikowi Barierę i Kradzież Życia w tej rundzie.","","„To ostrze należało niegdyś do mojego ojca. Oby zapewniło ci siły, których niegdyś mi brakowało”. — Shen","Zaklęcie",[],["Ionia"],"ZWYKŁE"],"01IO043":["Rzekotwórca","Uderzenie: Dobierz zaklęcie.","","„Jesteśmy dumnymi dziećmi Pierwotnej Krainy. Jej magia przenika naszą vastajańską krew i nasze ziemie”.","Jednostka",[],["Ionia"],"RZADKIE"],"01IO038":["Mniszka Pustelnica","Zagraj: Wycofaj wszystkich pozostałych sojuszników.","","„Refleks i instynkt to jedyni kompani, jakich potrzebuję”.","Jednostka",[],["Ionia"],"RZADKIE"],"01IO039":["Zmiennokształtne Cienie","Wycofaj sojusznika i przywołaj na jego miejsce Żywy Cień.","","Czy faktycznie mierzysz się z wrogiem, którego widzisz? A może to tylko iluzja stworzona z cieni?","Zaklęcie",[],["Ionia"],"ZWYKŁE"],"01IO055":["Strażnik Ki","Przyznaj Barierę sojusznikowi w ręce.\nDobierz 1 kartę.","","„Kinkou strzeże tych, którzy pilnują równowagi”. — Shen\n","Zaklęcie",[],["Ionia"],"ZWYKŁE"],"01NX020":["Draven","Gdy mnie przywołasz lub Uderzysz: Stwórz kartę Wirujący Topór w ręce.","Uderzyłem łącznie 2+ kartami Wirujące Topory.","„Chcesz autograf? Ustaw się w kolejce”.","Jednostka",[],["Noxus"],"Bohater"],"01NX006":["Vladimir","Zagraj: Zadaj 1 pkt. obrażeń dowolnej liczbie sojuszników, aby zadać tyle samo obrażeń wrogowi.","5+ twoich sojuszników przetrwało obrażenia.","Bezwzględny. Zimny. Okrutny. Fascynujący. Bystry. Czarujący.\nNie do odparcia...","Jednostka",[],["Noxus"],"Bohater"],"01NX004":["Zabójczy Cios","Zabij jednostkę o Sile 3 lub mniejszej.","","Wszyscy kiedyś umierają. Słabi umierają szybciej.","Zaklęcie",[],["Noxus"],"RZADKIE"],"01NX048":["Szkarłatny Opiekun","Gdy przetrwam obrażenia, stwórz losową Szkarłatną jednostkę w ręce.","","„Rad jestem was widzieć, moi mili!” „Żyję dla tych słów! Dostaliście zaproszenie?” „Oczywiście! Bal Rozkoszy!” „Szansa to dla was na poznanie mej rodziny”. „Jakież wyuzdanie! A ty, Kye? Przyjdziesz?”","Jednostka",[],["Noxus"],"ZWYKŁE"],"01NX038":["Darius","","Widzę, że wrogi Nexus ma połowę swojego początkowego Zdrowia lub mniej.","„Żelazna wola i tytaniczna siła. Lepszego generała Legion Tryfariański nie widział”. – Swain\n","Jednostka",[],["Noxus"],"Bohater"],"01NX023":["Pajęcza Chmara","Gdy mnie przywołasz, przyznaj innym sojuszniczym Pająkom +2|+0.","","Jedno spojrzenie i jesteś jej własnością. Jedno ukąszenie i jesteś pokarmem dla jej dzieci.","Jednostka",["PAJĄK"],["Noxus"],"RZADKIE"],"01NX013":["Rozstrzygający Manewr","Ogłusz wroga. Daj wszystkim sojusznikom +2|+0 w tej rundzie.","","„Byle głupiec może rzucić się z całą swą siłą na wroga. Potrzeba dalekowzroczności, by wiedzieć, że najlepiej zachować tę siłę na decydujący moment”. – Swain","Zaklęcie",[],["Noxus"],"RZADKIE"],"01NX046":["Pajęczy Wartownik","Zagraj: Ogłusz wroga.","","„Ależ mnie ona pociąga! Jej długie nogi, głos ociekający słodyczą i oczy czerwone jak róże. I pomyśleć, że postanowiła zjeść ze mną kolację!” — Lekkomyślny Arystokrata","Jednostka",["PAJĄK"],["Noxus"],"ZWYKŁE"],"01NX047":["Transfuzja","Zadaj 1 pkt. obrażeń sojusznikowi i daj innemu sojusznikowi +2|+2 w tej rundzie.","","„Ktoś daje, ktoś odbiera, moja droga. Ty dajesz, a ja odbieram”. — Vladimir","Zaklęcie",[],["Noxus"],"ZWYKŁE"],"01NX040":["Sabotażystka Legionu","Atak: Zadaj 1 pkt. obrażeń wrogiemu Nexusowi.","","„Nasi Łamacze Tarcz potrafią przepołowić człowieka. Legion ma jednak w zanadrzu jeszcze inne talenty, wymagające nieco więcej… finezji”. – Swain","Jednostka",[],["Noxus"],"ZWYKŁE"],"01NX025":["Braterska Więź","Przyznaj 2 sojusznikom +2|+0.","","„Więzi stworzone w czasie wojny są tak samo mocne, jak więzy rodzinne. Właściwie w obu chodzi o krew”. — Weteran Legionu","Zaklęcie",[],["Noxus"],"ZWYKŁE"],"01NX055":["Pająk Domowy","Gdy mnie przywołasz, przywołaj kartę Pajączek.","","„Moje pajączki kochają towarzystwo. Szkoda, że towarzystwo nie kocha ich z wzajemnością”. — Elise","Jednostka",["PAJĄK"],["Noxus"],"ZWYKŁE"],"01NX030":["Szkarłatna Adeptka","Gdy przetrwam obrażenia, zadaj 1 pkt. obrażeń wrogiemu Nexusowi.","","„Ósme piekła, Edvin, przystojniaku! Właśnie o tobie myślałam.” „Bal... I my, wszyscy razem.” „Razem ze mną! Moja para to świetna zabawa.” „Uroczo! A może nic?”","Jednostka",[],["Noxus"],"RZADKIE"],"01NX007":["Konferansjer z Areny","Atak: Daj innym atakującym sojusznikom +1|+0 w tej rundzie.","","Zaryczał z radością. Przez moment cała arena pulsowała w rytm bicia jego serca, a zebrany tłum zdawał się mieścić w jego triumfującej dłoni.","Jednostka",[],["Noxus"],"RZADKIE"],"01NX021":["Maruder Legionu","Atak: Przyznaj sojuszniczym Maruderom Legionu +1|+1, gdziekolwiek są.","","Za Legionem Tryfariańskim zawsze ciągnie się ogon w postaci rabusiów, szukających łatwych łupów i ofiar.","Jednostka",[],["Noxus"],"ZWYKŁE"],"01NX009":["Ulubieniec Tłumu","Gdy mnie przywołasz, przyznaj mi +1|+1 za każdego innego sojusznika.","","Niektórzy walecznicy są uwielbiani za charyzmę. Inni za szybkość i technikę. Vessid nie ma żadnej z tych cech, jednak nikt inny nie potrafi tak sprawnie zamieniać wrogów w krwawą miazgę.","Jednostka",[],["Noxus"],"RZADKIE"],"01NX011":["Tornado Śmierci","Walczący sojusznik uderza walczącego wroga.","","„Jak ja kocham tę robotę”. — Draven","Zaklęcie",[],["Noxus"],"ZWYKŁE"],"01NX053":["Rozliczenie","Jeśli masz jednostkę o Sile 5+, zabij WSZYSTKIE jednostki o Sile 4 lub mniejszej.","","„KTO JEST GOTÓW DO BOOOOJUUUUUU?” — Konferansjer z Areny","Zaklęcie",[],["Noxus"],"EPICKIE"],"01NX054":["Przerażający Ryk","Ogłusz wszystkich wrogów o Sile 4 lub mniejszej.","","„Bierze głęboki oddech, czy to będzie... Tak! Wsłuchajcie się, mili państwo! To słynny okrzyk bojowy Grzmota! Aż trzęsiemy się ze strachu, Grzmooot!” — Konferansjer z Areny","Zaklęcie",[],["Noxus"],"RZADKIE"],"01NX029":["Weteran Legionu","Gdy inny sojusznik przetrwa obrażenia, przyznaj mu +1|+0.","","Powrócił z wojny na skraju wyczerpania i bliski śmierci. Do zdrowia przywrócił go dopiero mężowski dotyk i lecznicza maść. Noxus nie szczędził środków, aby móc korzystać z jego doświadczenia na długo po zakończeniu przezeń walk.","Jednostka",[],["Noxus"],"EPICKIE"],"01NX014":["Shiraza, Ostrze","Zadaję podwójne obrażenia Nexusowi.","","„Co powiedział?! Ten dureń ma chyba cegły zamiast mózgu. Cóż, przynajmniej nadrabia siłą...” ","Jednostka",[],["Noxus"],"EPICKIE"],"01NX042":["Katarina","Gdy mnie przywołasz, stwórz Ulotną kartę Krawędź Ostrza w ręce.","Uderzyłam raz. Gdy awansuję, Wycofaj mnie.","„Nic tak nie wyostrza zmysłów, jak rzucanie do demaciańskich celów…”","Jednostka",[],["Noxus"],"Bohater"],"01NX051":["Kapitan Farron","Gdy mnie przywołasz, stwórz 2 Zdziesiątkowania w ręce.","","Głęboko w Slumsach Zaun młody Brenn Farron był uważany za prawdziwy postrach. Niestabilny. Odrażający. W szeregach Noxusu stał się rozchwytywany. Doceniany. Nie do zatrzymania.","Jednostka",[],["Noxus"],"EPICKIE"],"01NX012":["Tylna Straż Legionu","","","Noxiańscy żołnierze sieją postrach na polach bitewnych i splendor spływa na tych, którzy najskuteczniej szlachtują nieprzyjaciół. Dlatego dla wielu służba w tylnej straży jest tylko karą i niczym więcej.","Jednostka",[],["Noxus"],"ZWYKŁE"],"01NX043":["Krawędź Ostrza","Zadaj 1 pkt. obrażeń dowolnemu celowi.","","„W odpowiednich rękach ostrze jest w stanie przeciąć wszystko... dosłownie wszystko”. — Katarina","Zaklęcie",[],["Noxus"],"ZWYKŁE"],"01NX037":["Grenadier Legionu","Ostatnie Tchnienie: Zadaj 1 pkt. obrażeń wrogiemu Nexusowi.","","Każdy Noxianin szybko uczy się, że oddać życie za imperium to słuszny cel. Mało kto jednak decyduje się na wybuchową karierę grenadiera Legionu.","Jednostka",[],["Noxus"],"ZWYKŁE"],"01NX010":["Generał Legionu","Gdy mnie przywołasz, przyznaj mi +1|+1 za każdą Ogłuszoną lub Wycofaną przez ciebie jednostkę w tej grze.","","Wszyscy Noxianie znają trzy Zasady Siły, jednak jeśli żołnierz ma awansować, musi opanować je do perfekcji.","Jednostka",[],["Noxus"],"ZWYKŁE"],"01NX017":["Bębniarka Legionu","Wsparcie: Daj wspieranemu przeze mnie sojusznikowi Szybki Atak w tej rundzie.","","Legion poszerzał wpływy imperium z każdym uderzeniem wojennego bębna. Nic nie mogło ich powstrzymać. I nic nie powstrzymało.","Jednostka",[],["Noxus"],"ZWYKŁE"],"01NX003":["Bukmacher z Areny","Początek rundy: Odrzuć kartę o najmniejszym koszcie i dobierz 1.","","„...Widzisz, postawiłeś na Shirazę jako JEDYNEGO OCALAŁEGO ZAWODNIKA. Ten ioniański dzieciak żyje. Urwało mu ramię, ale nie jest martwy, nie? Zawsze możesz podbić stawkę...”","Jednostka",["YORDLE"],["Noxus"],"RZADKIE"],"01NX039":["Dalekowzroczność","Po zagraniu lub odrzuceniu przyznaj sojusznikom +1|+0.","","„Ci, którzy nie dostrzegają przyszłości, nie zasługują na jej doświadczenie”. — Jericho Swain","Zaklęcie",[],["Noxus"],"RZADKIE"],"01NX041":["Tryfariański Łamacz Tarcz","","","„Nie mam czasu na oblężenie. Wyślijcie Łamaczy Tarcz”. — Darius","Jednostka",[],["Noxus"],"ZWYKŁE"],"01NX036":["Minotaur Walecznik","Początek rundy: Ogłusz Najsłabszego wroga.","","„Nie obchodzi mnie, kto cię wykiwał i kto wisi ci kasę. Mam ruszać od razu na arenę, to płacisz z góry. Nie ma zniżki za ckliwe historie”.","Jednostka",[],["Noxus"],"RZADKIE"],"01NX044":["Taran","Atak: Przyznaj mi +4|+0.","","„Sir, odmówili otwarcia bramy. Chcą rozmawiać z Dariusem, ale on dotrze dopiero za dwa dni. Czy mamy posłać jeźdźców?”\n„To nie będzie konieczne”.","Jednostka",[],["Noxus"],"EPICKIE"],"01NX005":["Szkarłatna Arystokratka","Zagraj: Zadaj 1 pkt. obrażeń sojusznikowi i przyznaj mu +1|+0 oraz Zmiażdżenie.","","„Ach, ty też? Mówimy o Balu...” „Edvinie, moja też tam będzie i jak ja to wytrzymam?” „Wspaniały pomysł, ale mój ojciec by mnie wydziedziczył... Może założymy identyczne suknie?”","Jednostka",[],["Noxus"],"ZWYKŁE"],"01NX016":["Tryfariański Kandydat","Gdy mnie przywołasz, przyznaj mi +2|+0, jeśli masz innego sojusznika z Noxusu.","","„Zdobędziesz tytuł, gdy ostrze twego topora stępi się od czaszek wrogów, a buty przesiąkną ich krwią”. — Weteran Legionu","Jednostka",[],["Noxus"],"ZWYKŁE"],"01NX019":["Potęga","Daj sojusznikowi +3|+0 i Zmiażdżenie w tej rundzie.","","„Subtelność jest trochę przereklamowana. Nie mówię, że jest zła. Tylko przereklamowana”. — Darius","Zaklęcie",[],["Noxus"],"ZWYKŁE"],"01NX015":["Pupilek","","","Kocha je wszystkie, ale tego szczególnie.","Jednostka",["PAJĄK"],["Noxus"],"ZWYKŁE"],"01NX050":["Lotos Śmierci","Zadaj 1 pkt. obrażeń WSZYSTKIM walczącym jednostkom.","","„Zatańcz ze mną!” — Katarina","Zaklęcie",[],["Noxus"],"RZADKIE"],"01NX056":["Shunpo","Zadaj 2 pkt. obrażeń wrogowi i Zjednocz Siły.","","Zanim dostrzeżesz ostrze, będzie już za późno.","Zaklęcie",[],["Noxus"],"ZWYKŁE"],"01NX033":["Tryfariańska Asesorka","Gdy mnie przywołasz, dobierz 1 kartę za każdego posiadanego sojusznika o Sile 5+.","","„Potrzeba wyjątkowo wprawnego oka, by wybrać godnych zasilenia szeregów Legionu Tryfariańskiego. Ona jednak potrafi oddzielić wilki od owiec z wielu kilometrów”. — Generał Legionu","Jednostka",[],["Noxus"],"RZADKIE"],"01NX052":["Krew za Krew","Zadaj 1 pkt. obrażeń sojuszniczemu stronnikowi. Jeśli przetrwa, stwórz jego kopię w ręce.","","Nic nie zostawia takiego bałaganu jak pierwsza lekcja hemomanty.","Zaklęcie",[],["Noxus"],"ZWYKŁE"],"01NX045":["Dziki Walecznik","","","„A teraz... PAZUR! Poprzednio byliśmy świadkami KRWAWEJ rzezi w starciu z Szaloną Piątką... obecnie Szaloną Trójką. Zaczynamy! Obstawiamy dzisiejszą ofiarę! Cztery do jednego!” — Karl, Bukmacher z Areny","Jednostka",[],["Noxus"],"RZADKIE"],"01NX031":["Ambitna Tryfarianka","","","Wcielenie do Legionu Tryfariańskiego wystarczy większości żołnierzy, ale nie wszystkim.","Jednostka",[],["Noxus"],"RZADKIE"],"01NX002":["Zdziesiątkowanie","Zadaj 4 pkt. obrażeń wrogiemu Nexusowi.","","„Czasami potrzeba geniusza taktyki, aby przełamać obronę fortecy. A czasem wystarczy mocniej uderzyć”. — Darius","Zaklęcie",[],["Noxus"],"RZADKIE"],"01NX008":["Jeździec na Bazyliszku","Przymierze: Przyznaj mi +1|+1 i Zmiażdżenie.","","Ta jednostka korzysta z koni, ale nie do jeżdżenia. Po prostu bestie bardzo lubią się nimi posilać.","Jednostka",[],["Noxus"],"RZADKIE"],"01NX034":["Przytulaśny Poro","","","„W Noxusie nie ma miejsca dla... dla słab... Może ktoś ZABRAĆ ODE MNIE TO CHOLERSTWO?!” — Darius","Jednostka",["PORO"],["Noxus"],"ZWYKŁE"],"01NX035":["Największy Fan Dravena","Gdy mnie przywołasz, przenieś Dravena na wierzch swojej talii, jeśli nie masz go w ręce lub w grze.","","„Chcesz autograf? U-ustaw się w kolejce!”","Jednostka",[],["Noxus"],"ZWYKŁE"],"01NX026":["Brawurowy Tryfarianin","","","„Brawura to wada. Jednak wystarczy odrobina treningu w Legionie, aby przekuć ją w narzędzie”. – Swain","Jednostka",[],["Noxus"],"ZWYKŁE"],"01NX027":["Eliksir Gniewu","Daj sojusznikowi +3|+0 w tej rundzie.","","„Gdy otwarta dłoń zostanie odtrącona, zaciśnij ją w pięść”.\n– Noxiańska maksyma","Zaklęcie",[],["Noxus"],"ZWYKŁE"],"01NX022":["Noxiańska Gilotyna","Zabij zranioną jednostkę, by stworzyć Ulotną kartę Noxiańska Gilotyna w ręce.","","Dla Dariusa litość jest ujmą na honorze.","Zaklęcie",[],["Noxus"],"RZADKIE"],"01NX032":["Szkarłatny Przebudzony","Gdy mnie przywołasz, zadaj 1 pkt. obrażeń wszystkim innym sojusznikom.","","„Edvinie, nawet, jeśli odmówię, zaciągniesz mnie swoim sposobem. Więc... w porządku”.","Jednostka",[],["Noxus"],"RZADKIE"],"01NX024":["Kato, Łapa","Wsparcie: Daj wspieranym przeze mnie sojusznikom +3|+0 i Zmiażdżenie w tej rundzie.","","„Shiraza to świetna dziewczyna... Znaczy się przyjaciółka! Wcale ze sobą nie chodzimy. Ale gdyby tak było, to życzyłbym jej szczęśliwej rocznicy. Dziękuję, to wszystko”.","Jednostka",[],["Noxus"],"EPICKIE"],"01NX049":["Przebiegłość","Ogłusz wroga.","","„Daj wrogom dość liny, by mogli się powiesić, a nie będziesz marnować czasu, aby ciągnąć ich na egzekucję”. — LeBlanc","Zaklęcie",[],["Noxus"],"ZWYKŁE"],"01DE031":["Piewcy Świtu","Koniec rundy: Przyznaj innym sojusznikom +1|+1, jeśli sojusznik zginął w tej rundzie.","","„Zło czyha na nasze życie, jednak dziś nie czeka go triumf. Pamiętajcie o poległych i noście wspomnienia o nich jak zbroję!”","Jednostka",[],["Demacia"],"EPICKIE"],"01DE022":["Lucian","","Widziałem, jak 4+ sojuszników lub sojusznicza Senna umiera.","„Nic mi nie będzie, Senno, dopóki mam ciebie”.","Jednostka",[],["Demacia"],"Bohater"],"01DE019":["Mobilizacja","Zmniejsz koszt sojuszników w ręce o 1.","","„W ciągu niespełna dwóch tygodni z pola na front. W Demacii tego oczekujemy od każdego zdolnego do walki”. — Garen","Zaklęcie",[],["Demacia"],"RZADKIE"],"01DE042":["Lux","","Widziałam, jak zagrywasz zaklęcia o łącznym koszcie 6+. Gdy awansuję, stwórz kartę Ostatnia Iskra w ręce.","„Zawsze wiedziałam, że jestem inna. Z mojego wnętrza bije światło... Nie wiem dokładnie, czym jest, ale muszę się tego dowiedzieć!” ","Jednostka",[],["Demacia"],"Bohater"],"01DE010":["Szybkoskrzydły Lansjer","Ostatnie Tchnienie: Stwórz w ręce losowego Elitarnego.","","„Potrzeba wielkiej odwagi, by zawierzyć swój los srebrnoskrzydłemu. Toczą bój wysoko w przestworzach, zwarci, pewni i nieznający strachu”. — Garen","Jednostka",["ELITARNY","PTAK"],["Demacia"],"RZADKIE"],"01DE020":["Obrończyni Gwardii","","","„Nie wiedzieliśmy, czym dokładnie były te stworzenia. Mieliśmy jednak świadomość, że nasi kompani walczą u naszego boku. I tylko to się liczyło”.","Jednostka",["ELITARNY"],["Demacia"],"ZWYKŁE"],"01DE034":["Kowal Bitewny","Gdy przywołasz Elitarnego, przyznaj mu +1|+1.","","Wojny wygrywa się w kuźni.","Jednostka",[],["Demacia"],"RZADKIE"],"01DE002":["Tianna Obrończyni Korony","Gdy mnie przywołasz, Zjednocz Siły.","","„Nasz ród przelał krew dla tej krainy. Nie pozwolę ci porzucić honoru naszej rodziny dla paru świetlnych sztuczek”.","Jednostka",[],["Demacia"],"EPICKIE"],"01DE012":["Garen","Gdy mnie przywołasz, daj innym sojusznikom +1|+1 w tej rundzie.","Uderzyłem dwa razy.","Trening i wytrzymałość to droga żołnierza. Nawet w obliczu wielkiego niebezpieczeństwa nie zawahamy się.","Jednostka",["ELITARNY"],["Demacia"],"Bohater"],"01DE017":["W Pojedynkę","Jeśli masz dokładnie 1 sojusznika, przyznaj mu +3|+3.","","Gdy inni padają w boju, los zwycięstwa spada na barki prawdziwego bohatera.","Zaklęcie",[],["Demacia"],"RZADKIE"],"01DE045":["Fiora","","Zabiłam 2 wrogów.","„Od areny do turnieju, od placu treningowego po pole bitwy — nieustannie szukam godnego przeciwnika. Nie spocznę, póki nie będę miała pewności, że jestem najlepsza”.","Jednostka",[],["Demacia"],"Bohater"],"01DE052":["Formacja Świetlistej Stali","Gdy mnie przywołasz lub Zaatakuję: Daj sojusznikom Barierę w tej rundzie.","","„Ta formacja stanowi podstawę naszej taktyki. Wymaga od żołnierzy bezgranicznego ufania tarczom swoim i tarczom kompanów. Tak długo, jak dzierżycie je w dłoniach, nasze królestwo jest bezpieczne”. — Garen\n","Jednostka",[],["Demacia"],"EPICKIE"],"01DE021":["Bezwzględny Pościg","Zjednocz Siły.",""," „Każdy musi zmierzyć się ze swoimi lękami. Na twoje szczęście już tu jestem!” — Lucian\n","Zaklęcie",[],["Demacia"],"ZWYKŁE"],"01DE025":["Zniewolenie","Sojusznik Zniewala jednostkę.","","„Nie opieraj się. Jesteśmy prawem, a ty musisz się nam podporządkować. To wszystko”. — Łowca Magów Przesłuchujący","Zaklęcie",[],["Demacia"],"ZWYKŁE"],"01DE007":["Osąd","Walczący sojusznik uderza wszystkich walczących wrogów.","","Sprawiedliwość zatacza koło.","Zaklęcie",[],["Demacia"],"EPICKIE"],"01DE055":["Pojedynkowicz z Rodu Laurentów","Zagraj: Przyznaj Wyzwanie sojusznikowi w ręce.","","„Wydawał się nadętym bufonem z drogim mieczem, a okazało się, że naprawdę potrafi korzystać z ostrza! Zażądałbym rewanżu, jednak przez ten jego akcent trudno było zrozumieć, jak ma na imię”. – Demaciański podporucznik","Jednostka",[],["Demacia"],"ZWYKŁE"],"01DE048":["Łowca Magów Podżegacz","Przyznaj mi +2|+2, jeśli udało ci się zagrać zaklęcie o koszcie 6+ w tej grze.","","„Wiele wieków temu, w czasie Wojen Runicznych, dzika magia rzuciła Runeterrę na kolana. Nasz zakon powstał po to, aby wyplenić magię z naszego królestwa. Bez względu na to, czy zagrożenie przychodziłoby z zewnątrz, czy rodziło się wewnątrz murów dających nam schronienie”. — Podręcznik Łowcy Magów","Jednostka",[],["Demacia"],"RZADKIE"],"01DE001":["Chorąży Gwardii","Przymierze: Przyznaj innym sojusznikom +1|+1.","","„Musisz rozumieć brzemię naszego sztandaru. Ta chorągiew symbolizuje króla, rody szlacheckie i wszystkich obywateli. Stanowi świadectwo naszej niezłomnej wiary w Demacię. Noś go z dumą”. — Tianna Obrończyni Korony ","Jednostka",["ELITARNY"],["Demacia"],"RZADKIE"],"01DE043":["Kucharze Wojskowi","Wsparcie: Daj wspieranemu przeze mnie sojusznikowi +1|+1 w tej rundzie.","","Żadnego z członków demaciańskiej armii nie wolno lekceważyć.","Jednostka",[],["Demacia"],"ZWYKŁE"],"01DE049":["Zuchwały Poro","","","„Nasz nowy rekrut ma w sobie determinację i odwagę godną najlepszego żołnierza. Czy któregoś dnia zasili szeregi Gwardii? Jest... mniejszy od innych nowicjuszy, ale niczego nie można wykluczyć”. — Sierżant Gwardii","Jednostka",["PORO"],["Demacia"],"ZWYKŁE"],"01DE053":["Kawaler z Rodu Laurentów","Uderzenie: Stwórz w ręce innego losowego stronnika z twoich regionów z Wyzwaniem.","","„...Wielkie nieba”. — Fiora","Jednostka",[],["Demacia"],"EPICKIE"],"01DE033":["Pamięć","Kosztuję o 1 mniej za każdego sojusznika, który zginął w tej rundzie. Przywołaj losowego stronnika z Demacii o koszcie 5.","","„Dziś stajemy naprzeciw niesprawiedliwości, z którą spotkali się ci przed nami. Poświęcenie naszych towarzyszy nie poszło na marne”. — Jaśniejąca Strażniczka","Zaklęcie",[],["Demacia"],"RZADKIE"],"01DE044":["Podwójna Chwała","W pełni ulecz sojusznika, po czym podwój jego Siłę i Zdrowie.","","Mówi się, że demaciański wojownik wart jest dwóch przeciwników. I nie są to czcze przechwałki.","Zaklęcie",[],["Demacia"],"RZADKIE"],"01DE024":["Łowca Magów Kurator","Ostatnie Tchnienie: Stwórz w ręce losowe zaklęcie o koszcie 6+ z regionu innego niż Demacia.","","„Magiczne przedmioty mają w sobie coś przyciągającego. Jednak te potężne artefakty lepiej zostawić ekspertom. Ich moc może okazać się zbyt potężna dla ignorantów o dobrych intencjach, których nie brakuje wśród naszych obywateli”.\n– Podręcznik Łowcy Magów","Jednostka",[],["Demacia"],"ZWYKŁE"],"01DE004":["Srebrnoskrzydła Awangarda","Zagraj: Przywołaj moją dokładną kopię.","","Spadli z nieba niczym srebrzyste błyskawice. Pędzili w kierunku celu z gracją i pewnością. Potem zniknęli tak szybko, jak się pojawili. ","Jednostka",["ELITARNY","PTAK"],["Demacia"],"ZWYKŁE"],"01DE011":["Uczeń z Rodu Laurentów","","","„CO ZROBIŁ? Powierzyłem mu bezcenną podwójną szablę samego Pierre’a de Guillarda! Miał użyć jej wyłącznie do treningu!” — Strażnik Ostrzy Laurentów","Jednostka",[],["Demacia"],"ZWYKŁE"],"01DE047":["Sukcesja","Przywołaj kartę Nieustraszona Gwardia.","","Rynsztunek Nieustraszonej Gwardii jest przekazywany z żołnierza na żołnierza. Każdy rekrut musi czuć ciężar swojego obowiązku i dumę, która z niego płynie.","Zaklęcie",[],["Demacia"],"ZWYKŁE"],"01DE046":["Pogranicznik Gwardii","","","Cisza wcale nie oznacza bezpieczeństwa.","Jednostka",["ELITARNY"],["Demacia"],"ZWYKŁE"],"01DE050":["Oczyszczenie","Ucisz stronnika.","","„Twój petrucytowy Szaroznak to podstawowa ochrona przed magią. To także symbol naszej powinności i zwierzchnictwa nad innymi. Chroń go za wszelką cenę”.\n– Podręcznik łowcy magów","Zaklęcie",[],["Demacia"],"ZWYKŁE"],"01DE040":["Łowca Magów Przesłuchujący","Przyznaj mi +1|+1 i Wyzwanie, jeśli udało ci się zagrać zaklęcie o koszcie 6+ w tej grze.","","„Obywatele Demacii, moim świętym obowiązkiem jest was strzec. Potrzebujemy jednak waszego wsparcia, bowiem nawet w naszych murach wciąż czyhają plugawi magowie!”\n","Jednostka",[],["Demacia"],"RZADKIE"],"01DE036":["Giermek Gwardii","Gdy przywołasz Elitarnego, zmniejsz mój koszt o 1.","","„Każda napotkana osoba i każda przebyta podróż czegoś mnie nauczyły. Jednak im mądrzejsza i silniejsza się stawałam, tym wyraźniej uzmysławiałam sobie, jak długa jeszcze przede mną droga...” — Cithria, Giermek Gwardii\n","Jednostka",["ELITARNY"],["Demacia"],"ZWYKŁE"],"01DE037":["Riposta","Daj sojusznikowi +3|+0 i Barierę w tej rundzie.","","„W rzeczy samej, walczysz jak Poro!” — Fiora","Zaklęcie",[],["Demacia"],"RZADKIE"],"01DE014":["Posiłki","Przywołaj 2 Nieustraszone Gwardie, po czym przyznaj Elitarnym sojusznikom +1|+1.","","„Nasi wrogowie wiedzą, że jeśli skrzywdzą jednego z nas, odpowie im cała armia”.\n– Kodeks Gwardii\n","Zaklęcie",[],["Demacia"],"RZADKIE"],"01DE015":["Jaśniejąca Strażniczka","Gdy mnie przywołasz, przyznaj mi Kradzież Życia i Wytrzymałość, jeśli w tej rundzie zginął sojusznik.","","„Zimne dłonie nieumarłych ciągnęły w dół jej kompanów niczym morskie fale. Została tylko ona – jaśniejący kaganek sprawiedliwości, którego ostrze przy każdym ciosie wyśpiewywało imiona poległych”. – Demaciański podporucznik","Jednostka",[],["Demacia"],"RZADKIE"],"01DE003":["Strażnik Ostrzy Laurentów","Zagraj: Przyznaj sojusznikowi +2|+2.","","„To prawda, jest w nich piękno. Jednak nie różnią się od innych instrumentów. Aby wydobyć z nich potencjał, potrzebna jest wprawna ręka mistrza”. ","Jednostka",[],["Demacia"],"RZADKIE"],"01DE026":["Pojedynek","Sojusznik i wróg uderzają siebie nawzajem.","","„Dość gadania, niech przemówią ostrza”. — Fiora","Zaklęcie",[],["Demacia"],"ZWYKŁE"],"01DE032":["Pryzmatyczna Bariera","Daj sojusznikowi Barierę w tej rundzie.","","„Świat odwróci się od ciebie, jeśli nie rozumie twojej inności. Odmienność podobno czyni słabym. A ja uważam, że nas hartuje i buduje w nas współczucie. Będę cię chronić, choćby miały nadejść najmroczniejsze czasy!” — Lux","Zaklęcie",[],["Demacia"],"ZWYKŁE"],"01DE027":["En Garde","Daj sojusznikom Wyzwanie w tej rundzie.","","„Żaden żyjący obywatel Demacii nie odmówiłby lekcji szermierki u członka rodu Laurentów. Cóż, prawdopodobnie by jej też nie przeżył”. — Fiora","Zaklęcie",[],["Demacia"],"RZADKIE"],"01DE006":["Sierżant Gwardii","Gdy mnie przywołasz, stwórz w ręce Za Demacię!.","","„Prowadzi ćwiczenia od świtu do zmierzchu, a potem bez wahania pierwszy rusza do boju. Twardy jak stal i nieugięty jak skała. Ciężko o lepszego dowódcę”. – Demaciański podporucznik","Jednostka",["ELITARNY"],["Demacia"],"RZADKIE"],"01DE038":["Senna, Strażniczka Światła","Gdy sojuszniczy Lucian zginie po raz pierwszy, przyznaj mi +1|+1 i Podwójny Atak.","","„Nasi Strażnicy to pierwsza linia obrony oddzielająca nas od fali bezwzględnych nieumarłych uderzającej w królestwo ludzi. Musimy uderzyć pierwsi i NIGDY się nie zatrzymywać, gdy na szali jest życie naszych pobratymców”.","Jednostka",[],["Demacia"],"RZADKIE"],"01DE041":["Ramię w Ramię","Daj 2 sojusznikom +3|+3 w tej rundzie.","","„Osłaniaj mnie, wchodzę!”\n„Hej, to moja kwestia!”\n— Lorn i Dax ze Wschodniego Batalionu","Zaklęcie",[],["Demacia"],"RZADKIE"],"01DE035":["Za Demacię!","Daj sojusznikom +3|+3 w tej rundzie.","","„To nasz dom, nasze rodziny i towarzysze w boju. Nasza duma, honor, siła. Dziś będziemy walczyć w obronie tych wartości. Walczyć o przetrwanie. Krzyczmy więc głośno, aby wrogowie nas usłyszeli: ZA DEMACIĘ!” – Sierżant Gwardii","Zaklęcie",[],["Demacia"],"RZADKIE"],"01DE018":["Jaśniejący Cios","Daj sojusznikowi +1|+1 w tej rundzie.","","„Nieumarli walczą, jakby jutro dla nich nie istniało. Dopilnujemy, by faktycznie tak było”. — Lucian\n\n","Zaklęcie",[],["Demacia"],"ZWYKŁE"],"01DE009":["Obrończyni Świetlistej Stali","Zagraj: Daj sojusznikowi Barierę w tej rundzie.","","„Nasz naród cieszy się dobrobytem, ponieważ los każdego z naszych wojowników jest dla nas na wagę złota”. — Król Jarvan III","Jednostka",[],["Demacia"],"ZWYKŁE"],"01DE039":["Cithria z Chmurowego Pola","","","„Co noc, nim poszłam spać, matka ostrzyła swój miecz i opowiadała mi historie o największych bohaterach Demacii. Moje sny zawsze były pełne przygód. Teraz czas napisać własną historię”.","Jednostka",["ELITARNY"],["Demacia"],"ZWYKŁE"],"01DE056":["Pierwsze Ostrze Gwardii","Atak: Przyznaj mi +2|+2.","","Rozbrzmiewa bitewny okrzyk, moje nogi twardo stoją na polu bitwy. Wystarczy rozkaz mej pani, abym poznał moje przeznaczenie i wypełnił jej wolę.","Jednostka",["ELITARNY"],["Demacia"],"ZWYKŁE"],"01DE029":["Szybkopióry Tropiciel","Gdy przywołasz innego sojusznika, przyznaj mi Wyzwanie.","","Krewniacy srebrnoskrzydłych brzytwodziobów mają instynkt drapieżcy swoich kuzynów, ale jednocześnie zdają się zupełnie nie przejmować swoim niepozornym rozmiarem.","Jednostka",["PTAK"],["Demacia"],"ZWYKŁE"],"01DE028":["Kawaleria Gwardii","","","Gwardia nie potrzebowała bitewnych bębnów i pochwalnych hymnów, gdy ruszała do boju. Żołnierzom wystarczył miarowy tętent podkutych kopyt uderzających o splamioną krwią ziemię.","Jednostka",["ELITARNY"],["Demacia"],"ZWYKŁE"],"01DE013":["Kamizelka Kolcza","Przyznaj sojusznikowi Wytrzymałość.","","Demaciańska stal jest znana na całym świecie ze swej wytrzymałości. Kowale, którzy ją wytwarzają, są równie sławni co mocarni.","Zaklęcie",[],["Demacia"],"ZWYKŁE"],"01DE023":["Łowczyni Magów Poszukiwaczka","Stwórz kartę Zniewolenie w ręce, jeśli udało ci się zagrać zaklęcie o koszcie 6+ w tej grze.","","„Proszę wybaczyć to nagłe najście, jednak oczekujemy pełnej współpracy. Doszły nas wieści o... podejrzanej aktywności...”","Jednostka",[],["Demacia"],"ZWYKŁE"],"01DE051":["Cithria Śmiała","Atak: Daj innym atakującym sojusznikom +1|+1 i Postrach w tej rundzie.","","„Opowieści i legendy nigdy nie były dla mnie tylko fikcją. To przygody, które wzywały mnie do działania. Opuściłam Chmurowe Pole, aby przeżyć własną przygodę. Okazało się jednak, że mam znaleźć ich wiele. A to dopiero początek”.\n","Jednostka",["ELITARNY"],["Demacia"],"EPICKIE"],"01DE054":["Odkupicielka Gwardii","Gdy mnie przywołasz, dobierz kartę jednostki, jeśli w tej rundzie zginął sojusznik.","","„Nasi polegli bracia i siostry zostaną upamiętnieni każdym okrzykiem bojowym, każdym ciosem i każdą strzaskaną tarczą! Dzisiaj czeka nas zwycięstwo!”","Jednostka",["ELITARNY"],["Demacia"],"ZWYKŁE"],"01DE030":["Srebrnoskrzydła Pogromczyni","","","Strzały frunęły z murów fortecy jak rozwścieczone osy, jednak żadna nie była w stanie trafić przecinającego niebo srebrzystego punktu. ","Jednostka",["PTAK"],["Demacia"],"ZWYKŁE"],"01PZ040":["Jinx","","Widzę, że twoja ręka jest pusta.","„O co chodzi, Rybeńko?”\n„Martwię się o ciebie, Jinx! Za każdym razem, kiedy się nudzisz, chcesz…”\n„…coś wysadzić! Świetny pomysł, Rybeńko!”","Jednostka",[],["Piltover i Zaun"],"Bohater"],"01PZ008":["Teemo","Uderzenie w Nexus: Umieść 5 kart Trujący Grzyb na losowych kartach w talii przeciwnika.","Udało ci się umieścić 15+ Trujących Grzybów.","„Zasada harcerza nr 154: Nigdy nie bój się nieznanego! Zasada 276: Mieszkańcy lasu to nasi przyjaciele! Zasada 354: Jeśli coś jest futrzaste, można to pogłaskać, ale zdecydowanie nie należy tego jeść! Zasada 417...”","Jednostka",["YORDLE"],["Bandle City","Piltover i Zaun"],"Bohater"],"01PZ056":["Heimerdinger","Gdy zagrasz zaklęcie, stwórz w ręce Ulotne Działko o identycznym koszcie. Kosztuje ono 0 many.","Widziałem, jak przywołujesz sojusznicze Maszyny o łącznej Sile 12+.","„Szalony naukowiec? Pff! Jestem nad wyraz opanowany! Może mam tylko niewielki bałagan na biurku i trochę zróżnicowane zainteresowania naukowe”.","Jednostka",["YORDLE"],["Bandle City","Piltover i Zaun"],"Bohater"],"01PZ013":["Wzmocniony Eksperymentator","Zagraj: Odrzuć wszystkie karty z ręki. Dobierz 3 karty. Zadaj wrogowi 3 pkt. obrażeń.","","W pogoni za marzeniami stracił obie ręce, jednak nigdy się nie poddał. Nic nie mogło stanąć mu na drodze.","Jednostka",[],["Piltover i Zaun"],"EPICKIE"],"01PZ007":["Paradna Elektroplatforma","Wsparcie: Stwórz 4 kopie wspieranego sojusznika w swojej talii.","","Huk armat przyciągnął na plac tłumy, które nie mogły doczekać się przedstawienia. Pozbycie się resztek konfetti z włosów zajęło im później całe tygodnie.","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"01PZ018":["Geniusz z Akademii","","","Jak ona celuje? To bardzo dobre pytanie.","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"01PZ019":["Pilny Czeladnik","Gdy mnie przywołasz, odzyskaj 2 many zaklęć.","","Nie każdy może od razu osiągnąć coś w Piltover. Niektórym trzeba na przykład pomóc spojrzeć na naukę w nieco inny sposób.","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"01PZ025":["Handlarz Grzybów","Gdy zagrasz zaklęcie, umieść 3 Trujące Grzyby w talii przeciwnika.","","„Dobre są?”\n„Oczywiście! Tylko najwyższa jakość! Sam z nimi gadałem!”\n„Dobra, w takim razie... chwila, co?”\n„No, ten na przykład zaraz się żeni!”\n„Ile już zjadłeś?”\n„Żeni się z ostrygą!”","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"01PZ048":["Corina Veraza","Zagraj: Unicestwij 5 kart z wierzchu swojej talii, aby zadać 1 pkt. obrażeń wszystkim wrogom i wrogiemu Nexusowi za każde unicestwione zaklęcie.","","„Ci ograniczeni Piltoverczycy znają się tylko na technice. Nie umieją docenić delikatnego artyzmu łodyżek, płatków i komórek w mych kultywatorach. Nie zasługują na to, ale zgotuję im najpiękniejszą zagładę w historii”.","Jednostka",[],["Piltover i Zaun"],"EPICKIE"],"01PZ028":["Kontroler-Prowizorka","Po zagraniu lub odrzuceniu przywołaj kartę Złomujący Krab.","","Wystarczyło nieco złomu i kilka chwil, aby młoda konstruktorka przypomniała sobie o niecodziennym źródle inspiracji — widzianej niegdyś istocie wędrującej wzdłuż brzegu rzeki w odległej dżungli.","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"01PZ050":["Wzmacniająca Siła Czarów","Daj sojusznikowi +4|+0 i Szybki Atak w tej rundzie.","","„Jak się zaświeci, to zaczyna trochę łaskotać. To normalne, prawda?” — Ezreal","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"01PZ054":["Wybuchowiec Nowicjusz","Atak: Zadaj 2 pkt. obrażeń wrogiemu Nexusowi.","","„Wiesz, co robisz?”\n„Nie”.\n„Ta odpowiedź mnie nie zadowala”.\n„To po co pytasz?”","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"01PZ030":["Podejrzany Osobnik","Zagraj: Wybierz stronnika. Przemień mnie w jego dokładną kopię.","","„Witajcie, drodzy chembaronowie!”","Jednostka",["YORDLE"],["Piltover i Zaun"],"RZADKIE"],"01PZ017":["Sprzedawca Używanych Beczek","Gdy mnie przywołasz, przywołaj 2 Niebezpieczne Beczki.","","„Ziel cię przysyła? Mówiłem mu, żeby się wypchał. Nie mogę przyjąć zwrotu czegoś, co widzę pierwszy raz na oczy, nie? Jeśli was to jednak interesuje, miałem nową dostawę beczek, z którymi za pewną kwotę jestem gotów się rozstać...”","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"01PZ038":["Poławiacz ze Slumsów","Zagraj: Odrzuć 1 kartę, aby dobrać kolejną.","","W Slumsach nic się nie marnuje.","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"01PZ036":["Ezreal","Uderzenie w Nexus: Stwórz Ulotny Mistyczny Strzał w ręce.","Wrogie jednostki stały się twoim celem 8+ razy.","„Gogle? Są. Szal? Jest. Wspaniała rękawica o magicznych właściwościach, które są mi w stu procentach znane? Są, są i… są!”","Jednostka",[],["Piltover i Zaun"],"Bohater"],"01PZ035":["Jae Medarda","Gdy stanę się celem, dobierz 1 kartę.","","Jako dziedzic fortuny prestiżowego Klanu Medarda z Piltover, Jae zawsze wolał spędzać czas na uganianiu się za pradawnymi artefaktami niż na zarządzaniu rodzinnym biznesem... Ojciec nie był zadowolony.","Jednostka",[],["Piltover i Zaun"],"EPICKIE"],"01PZ010":["Grzybowa Chmura","Umieść 5 kart Trujących Grzybów w talii przeciwnika.","","Najpierw słyszysz głuche pyknięcie pękającego kapelusza. Potem unieruchamiający, przeszywający ból. Na koniec z oddali dobiega cię chichot...","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"01PZ045":["Urwis z Zaun","Zagraj: Odrzuć 1 kartę, aby dobrać kolejną.","","„A mogłoby się zdawać, że typy ze Slumsów trzymają się razem”.\n„Za dużo czasu zajmuje im użalanie się nad sobą”.\n„Co za szkoda. O... Widziałeś moją sakiewkę?”","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"01PZ002":["Podejrzany Oberżysta","Gdy mnie przywołasz, stwórz w ręce losową kartę za każdą kartę Podejrzany Oberżysta przywołaną przez ciebie w tej grze.","","„Ta, daje tyciego kopa — a Slumsy mają tyci smrodek. Kubeł znajdziesz przy barze”.","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"01PZ004":["Celna Salwa","Zadaj 3 pkt. obrażeń wrogowi lub wrogiemu Nexusowi, 2 innemu i 1 kolejnemu.","","„Gdy ma się talent, nie ma czegoś takiego jak szczęśliwy traf”. — Ezreal","Zaklęcie",[],["Piltover i Zaun"],"EPICKIE"],"01PZ020":["Brawurowa Poro","","","Jej pierwszy lot miał miejsce przez pomyłkę — w czasie porannej toalety wpadła do działa używanego w Dzień Postępu. Teraz jest ulubienicą mieszkańców Piltover. Zawsze może liczyć na pełne entuzjazmu westchnienia tłumu, gdy frunie w przestworzach.","Jednostka",["PORO"],["Piltover i Zaun"],"ZWYKŁE"],"01PZ046":["Fałszywe Kopie","Wybierz kartę w ręce. Stwórz dokładne 4 kopie tej karty w swojej talii.","","Naśladownictwo to najszczersza forma złodziejstwa.","Zaklęcie",[],["Piltover i Zaun"],"RZADKIE"],"01PZ052":["Mistyczny Strzał","Zadaj 2 pkt. obrażeń dowolnemu celowi.","","„Nigdy nie pudłuję. Ale zdarzają mi się strzały ostrzegawcze...” — Ezreal","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"01PZ033":["Pogoń za Perfekcją","Jeśli udało ci się zagrać w tej grze 20 nowych kart, przywołaj kartę Kotastrofa.","","„Koniec końców wszyscy, którzy pracowali nad wizją von Yippa, zostali oszukani. Nie wiedzieliśmy, co tworzymy, i jaką przerażającą moc wypuścimy na świat”. – Piltoverski inżynier projektu","Zaklęcie",[],["Piltover i Zaun"],"EPICKIE"],"01PZ005":["Hextechowy Transmogulator","Przemień stronnika w dokładną kopię innego stronnika.","","„PODOBNO CHCIAŁAŚ STRACIĆ NA WADZE”.\n„I DLATEGO WYGLĄDAM TERAZ JAK YORDLE?”\n„PRZECIEŻ STRACIŁAŚ NA WADZE!”\n„...ALE JESTEM TERAZ YORDLEM!”","Zaklęcie",[],["Piltover i Zaun"],"RZADKIE"],"01PZ021":["Sługusy Midenstokke’a","Uderzenie w Nexus: Przywołaj moją dokładną kopię.","","„Panie Berz, znaleźliśmy pana śpiącego WEWNĄTRZ skarbca. Leżał pan pod złotymi kołami zębatymi i ściskał wyłamane drzwi sejfu”.\n„To nie byłem ja. Pewnikiem mój sobowtór”.\n„Ale nadal trzyma pan drzwi”.\n„Tak? Udowodnij”.","Jednostka",[],["Piltover i Zaun"],"RZADKIE"],"01PZ031":["Szok Statikka","Zadaj 1 pkt. obrażeń wrogowi lub wrogiemu Nexusowi i 1 pkt. kolejnemu.\nDobierz 1 kartę.","","„I tak oto poznaliśmy wyładowania łukowe! Oczywiście mój poprzednik snuł już teorie o takim zdarzeniu, ale źle oszacował zasięg wyładowań. Biedaczek...” — Heimerdinger","Zaklęcie",[],["Piltover i Zaun"],"RZADKIE"],"01PZ059":["Złoty Miażdżyciel","","","ZABIJAĆ. MIAŻDŻYĆ. NISZCZYĆ. I JESZCZE RAZ.","Jednostka",["MASZYNA"],["Piltover i Zaun"],"ZWYKŁE"],"01PZ001":["Przetrząsanko","Aby zagrać, odrzuć do 2 kart. Dobierz 1 kartę za każdą odrzuconą kartę.","","„Ooooo rany! PIĘCIU EGZEKUTORÓW I GOLEM? Chwila, moment! Mam coś dla was! Seeeeekundka...” — Jinx","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"01PZ057":["Złomowy Montaż","Przywołaj 2 Złomujące Kraby.","","Dwa łagodne stworzenia, niegdyś zmuszone do rozłąki przez niemożliwy do pokonania teren, nareszcie mogły spotkać się w chłodnych wodach Slumsów.","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"01PZ027":["Promień Termogeniczny","Aby zagrać, zużyj całą manę.\nZadaj tyle samo obrażeń jednostce.","","„Wykorzystaliśmy cały swój czas i zasoby. Promień co prawda działa, ale nie jesteśmy w stanie wyregulować jego zużycia energii”. – Zauński eksperymentator","Zaklęcie",[],["Piltover i Zaun"],"RZADKIE"],"01PZ055":["Błyskotliwa Studentka","Gdy dobierzesz kartę, daj mi +1|+0 w tej rundzie.","","Wyobraźnia jest iskrą, która rozpala twórczy płomień. Jednak dopiero badania są w stanie go podsycić.","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"01PZ014":["Nielicencjonowany Wynalazek","Przywołaj Nielegalne Urządzenie.","","„Ich pomyłki mają różne skutki: wstrząsy odległych eksplozji, szkodliwe wyziewy z kominów. Niedługo któryś z nich rozwali całe nasze miasto”. – Filantrop z Piltover","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"01PZ034":["Poszukiwacz ze Slumsów","Przymierze: Stwórz kartę Mapa Slumsów w ręce. Kosztuje 0 many w tej rundzie.","","Zauńskie dzieci wkrótce zaczęły przeszukiwać stare tunele i ukryte głębiej części Alei. Jakże interesujący odkryli świat. I jakich poznali przyjaciół.\n","Jednostka",[],["Piltover i Zaun"],"RZADKIE"],"01PZ003":["Robot Budujący","Gdy zagrasz zaklęcie, przyznaj mi +1|+1.","","„Byle bałwan może zbudować maszynę. Tylko geniusz potrafi tchnąć w robotyczny umysł pierwiastek PRAWDZIWEGO postępu! Wkrótce ci przeklęci biurokraci będą się przede mną płaszczyć...” — Klas Henwick","Jednostka",[],["Piltover i Zaun"],"RZADKIE"],"01PZ044":["Chempunk Solówkarz","Zagraj: Zadaj 1 pkt. obrażeń wszystkim wrogom.","","„…Jego solówka przechodzi w harmonijną skalę molową, po czym zaczyna się wirtuozerskie arpeggio tuż przed niesamowitym przejściem. Pewnie nawet nie masz pojęcia, o czym mówię”. – Max Bliff, strażnik bramy","Jednostka",[],["Piltover i Zaun"],"RZADKIE"],"01PZ029":["Dostojny Dobroczyńca","Zagraj: Pokaż epicką kartę z twoich regionów.","","„Byłem wtedy pełen gniewu i niszczyłem moich przeciwników, pnąc się po szczeblach kariery. Teraz chcę wykorzystać swoje bogactwa do czynienia dobra. Mam nadzieję, że pozwoli to zmyć moje dawne grzechy”.","Jednostka",[],["Piltover i Zaun"],"RZADKIE"],"01PZ051":["Rusznikarka Frajdy","Wszystkie twoje zaklęcia i Umiejętności zadają 1 dodatkowy pkt. obrażeń.","","„Potrzebujesz porządnego wstrząsu? Dobrze trafiłeś!”","Jednostka",[],["Piltover i Zaun"],"RZADKIE"],"01PZ023":["Profesor von Yipp","Gdy przywołasz sojusznika o koszcie 1, przyznaj mu +2|+2.","","„Dziś chcę zaprezentować radzie mój najnowszy wynalazek. W demonstracji pomoże mi mój szanowny kolega...”","Jednostka",["KOT"],["Piltover i Zaun"],"RZADKIE"],"01PZ024":["Niestabilny Prądotwórca","Przyznaj mi +4|+0 i Szybki Atak, jeśli udało ci się rzucić zaklęcie o koszcie 6+ w tej grze.","","Imię i nazwisko: Klas Henwick, Wiek: 51, Rodzaj uprawnień: Klasa 2 warunkowa, Status uprawnień: Odebrane, Komentarz: Podmiot zignorował wielokrotne nakazy zmniejszenia mocy po eksplozji w laboratorium (sprawa 13X764NM). NIE WPUSZCZAĆ.","Jednostka",[],["Piltover i Zaun"],"RZADKIE"],"01PZ049":["Dzień Postępu!","Dobierz 3 karty i zmniejsz ich koszt o 1.","","DZIEŃ POSTĘPU!\nŚwiętuj z nami na placu SŁONECZNYCH WRÓT!\nZobacz prawdziwe HEXTECHOWE CUDA!\nZachwyć się wyczynami BRAWUROWEJ PORO!\nDowiedz się, co CZŁOWIEK JUTRA ma do powiedzenia o TERAŹNIEJSZOŚCI!\nWstęp WOLNY!\nZapraszamy wszystkie dzieci z Piltover!","Zaklęcie",[],["Piltover i Zaun"],"EPICKIE"],"01PZ006":["Strażnik Placu","Kosztuję o 1 mniej za każde zaklęcie zagrane przez ciebie w tej grze.","","Masz dwadzieścia sekund na wykonanie polecenia.","Jednostka",[],["Piltover i Zaun"],"RZADKIE"],"01PZ053":["Stadko Łompów","Gdy mnie przywołasz, stwórz w ręce kartę Grzybowa Chmura.","","„Ciągle się skradają. Mogą WYDAWAĆ SIĘ szalone, ale mają wielki plan. Trzeba go tylko dostrzec. Tak jak ja! Wielkie plany. Ważne plany! Grzybki. Ser... Sorbet. O czym to ja...?” — Handlarz Grzybów","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"01PZ012":["Ogniste Gryzaki!","Gdy mnie odrzucisz, przywołaj mnie.","","„DO DZIEŁA, GRYZACZKI!” — Jinx","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"01PZ039":["Zabawmy się!","Aby zagrać, odrzuć 1 kartę.\nZadaj 3 pkt. obrażeń dowolnemu celowi.","","„OGNIA, OGNIA, OGNIA!” — Jinx","Zaklęcie",[],["Piltover i Zaun"],"RZADKIE"],"01PZ016":["Przebłysk Geniuszu","Stwórz w ręce losowe zaklęcie o koszcie 6+ z twoich regionów.\nOdzyskaj manę zaklęć.","","Wystarczy jedno objawienie, aby spisać historię na nowo.","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"01PZ058":["Fałszywy Łomp","Gdy mnie przywołasz, stwórz 2 Grzybowe Chmury w ręce.","","„Widziałem niezłą sztukę! Ciężka jak koń i twarda jak skalniak. Miej na nią oko. Nie bez kozery jest królową tej gromadki!” — Handlarz Grzybów","Jednostka",["YORDLE"],["Piltover i Zaun"],"RZADKIE"],"01PZ009":["Aeronauta Amator","","","„Osobista maszyna do latania? Nonsens! Hm, tak właściwie to przed chwilą kazałem wyrzucić prototyp asystentowi. Gdzie on się właściwie podziewa?” – Inżynier z Piltover","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"01PZ042":["Nieustraszona Żeglarka","Wsparcie: Daj wspieranemu przeze mnie sojusznikowi Nieuchwytność w tej rundzie.","","Wielu mieszkańców Piltover uważa, że nieznane powinno się poznawać przez naukę i wynalazki, pozostając w bezpiecznych granicach Miasta Postępu. A jednak garstka śmiałków decyduje się opuścić mury, by poznać nieznane większego kalibru — świat.","Jednostka",[],["Piltover i Zaun"],"RZADKIE"],"01PZ026":["Mapa Slumsów","Przyznaj sojusznikowi Nieuchwytność.","","„Pilciaki myślą, że wiedzą wszystko, a ich mapy pokazują tylko miejsca, o których wiedzą od nas! Nic nie przebije wiedzy lokalsów. I ta wiedza może być twoja... za odpowiednią opłatą”. — Ajuna Lem, Poszukiwacz ze Slumsów","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"01PZ043":["Chempunk Kieszonkowiec","Uderzenie w Nexus: Stwórz w ręce dokładną kopię losowego zaklęcia z talii przeciwnika.","","Ci, których wygnano w podziemia Miasta Postępu, mieli zginąć w bratobójczych waśniach. Zamiast tego połączyli siły i stworzyli dla siebie nową ojczyznę. Zaun nie miał wiele do zaoferowania, ale był ich własnym miejscem.","Jednostka",[],["Piltover i Zaun"],"RZADKIE"],"01PZ047":["Niebezpieczna Beczka","Ostatnie Tchnienie: Zadaj 1 pkt. obrażeń OBU Nexusom.","","„Powiedziałbym, żebyś założył kombinezon, ale tu na dole jest wilgotniej niż pod pachą łompa. Masz chociaż rękawice? Upewnij się, że ten syf nie skapnie ci na nic ważnego”. – Ziel, zauński majster","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"01FR024":["Anivia","Atak: Zadaj 1 pkt. obrażeń wszystkim wrogom i wrogiemu Nexusowi.\nOstatnie Tchnienie: Wskrześ mnie jako Aniviajo.","Masz Oświecenie.","„Narodziłam się na tych nieprzyjaznych ziemiach i będę ich strzec za wszelką cenę. I ani czas, ani wojny, ani śmierć mnie nie powstrzymają”.","Jednostka",["PTAK"],["Freljord"],"Bohater"],"01FR039":["Tryndamere","","Jeśli miałbym zginąć, zamiast tego awansuję.","„Nie umieraj za słuszną sprawę. Żyj dla niej...”","Jednostka",[],["Freljord"],"Bohater"],"01FR006":["Dziedzictwo Zrodzonych z Lodu","Przyznaj sojusznikowi i jego wszystkim sojuszniczym kopiom +2|+2, gdziekolwiek są.","","„Niewielu jest nas, Zrodzonych z Lodu. Naszą krew nasyca magia Freljordu. Nasi przodkowie wygnali starożytne zło, a teraz my stoimy na straży tych ziem, aby nigdy nie powróciło”. — Gregor Strażnik","Zaklęcie",[],["Freljord"],"ZWYKŁE"],"01FR022":["Zwiastujący Jastrząb","Gdy mnie przywołasz, przyznaj dwóm pierwszym sojusznikom z wierzchu twojej talii +1|+1.","","„Trzy razy nasi wojowie ruszali ku avarosańskim wrotom i trzy razy napotkali łuczników gotowych do strzału. Cóż za magia pozwala im przewidzieć nasze ataki?” — Sznytan Steffen","Jednostka",["PTAK"],["Freljord"],"ZWYKŁE"],"01FR042":["Kąsające Wiatry","Nałóż Odmrożenie na 2 wrogów.","","„Rzucasz mi wyzwanie na moich własnych ziemiach? Mierz siły na zamiary, maluchu”. – Anivia","Zaklęcie",["ŻYWIOŁ"],["Freljord"],"RZADKIE"],"01FR009":["Braum","Gdy po raz pierwszy przetrwam obrażenia, przywołaj kartę Potężny Poro.","Udało mi się przetrwać 10+ pkt. obrażeń.","„Tatku, opowiedz mi o Braumie i jego drzwiach!”\n„Albo o tym, jak jego upadek rozłupał górę na pół!”\n„A może o tym, jak ocalił gospodę przed szalejącym yeti?!”","Jednostka",[],["Freljord"],"Bohater"],"01FR018":["Szronozębny Wilk","Uderzenie: Gdy uderzę jednostkę o Sile 0, zabij ją.","","Drapieżniki z północnych rubieży nauczyły się, że najłatwiej poluje się na zwierzynę już osłabioną przez mróz.","Jednostka",["PIES"],["Freljord"],"RZADKIE"],"01FR036":["Avarosański Strzelec","Zagraj: Zadaj 1 pkt. obrażeń wrogowi.","","We Freljordzie albo polujesz, albo głodujesz.","Jednostka",[],["Freljord"],"ZWYKŁE"],"01FR045":["Sznytan Steffen","Gdy przetrwam obrażenia, przyznaj mi +3|+0.","","„Przypieczętowałem swą przysięgę wobec Zimowego Szponu, gdy Sejuani dała mi moją pierwszą bliznę. Każda kolejna została zdobyta ku jej czci”.","Jednostka",[],["Freljord"],"ZWYKŁE"],"01FR008":["Samotny Poro","Gdy mnie przywołasz, stwórz w ręce innego losowego Poro o koszcie 1.","","„Całe życie spędziłem we Freljordzie, a mimo to nic nie łamie mi serca tak, jak widok tego smutnego malucha”. \n– Hodowca Poro","Jednostka",["PORO"],["Freljord"],"ZWYKŁE"],"01FR055":["Strzaskanie","Zadaj 4 pkt. obrażeń wrogowi, jeśli ma Siłę równą 0. Jeśli nie, nałóż na niego Odmrożenie.","","„Gdy zima pojawia się w tych krainach, silni zostają wystawieni na próbę, a słabi giną”. — Sznytan Steffen","Zaklęcie",["ŻYWIOŁ"],["Freljord"],"ZWYKŁE"],"01FR038":["Ashe","Atak: Nałóż Odmrożenie na Najsilniejszego wroga.","Udało ci się zredukować Siłę 5+ wrogów do 0. Gdy awansuję, stwórz kartę Kryształowa Strzała na wierzchu talii.","„Kiedy spoglądam na mój dom, dobrze widzę, czym jest, lecz także to, czym być może. Dostatek i dobrobyt nie tylko dla mego ludu, lecz także dla tych, którzy pragną pokoju. Zjednoczony Freljord”.","Jednostka",[],["Freljord"],"Bohater"],"01FR029":["Prośba o Pomoc","Dobierz Bohatera.","","„Nadciągają zbóje! Rozpalić ognie ostrzegawcze i bić na alarm! Potrzebna nam będzie wszelka pomoc!” — Avarosański Wartownik","Zaklęcie",[],["Freljord"],"RZADKIE"],"01FR035":["Bezblizna Najeźdźczyni","Gdy przetrwam obrażenia, przyznaj mi +3|+0.","","„Avarosanie uczą swoje dzieci, jak dożyć do starości, delikatni i niezdolni do obronienia siebie i swoich pobratymców. Nasze potomstwo rodzi się w ogniu bitwy”.\n– Vrynna, Matka Blizn","Jednostka",[],["Freljord"],"ZWYKŁE"],"01FR020":["Lawina","Zadaj 2 pkt. obrażeń WSZYSTKIM jednostkom.","","Duszą każdej lawiny jest drobny kamyczek, który nie potrafił uleżeć na miejscu.","Zaklęcie",["ŻYWIOŁ"],["Freljord"],"RZADKIE"],"01FR014":["Pacholę Yeti","Ostatnie Tchnienie: Stwórz w swojej talii 2 karty Wściekłe Yeti.","","„Było z niego takie spokojne maleństwo! Trudno uwierzyć, że wyrosło na... cóż... yeti”. — Avarosański Traper","Jednostka",["YETI"],["Freljord"],"ZWYKŁE"],"01FR049":["Tropiący Wilk","Gdy mnie przywołasz, twój przeciwnik przywołuje Zając Śnieżny.","","„Z zająca wilka nie stworzysz”.\n– Przysłowie Zimowego Szponu","Jednostka",["PIES"],["Freljord"],"ZWYKŁE"],"01FR037":["Avarosańska Eskorta","Przymierze: Przyznaj pierwszemu sojusznikowi z wierzchu swojej talii +3|+3 i Zmiażdżenie.","","Gdy posiłki ustawiły się wzdłuż grani, zwiadowcy złożyli pokłon wojmatce. Dla nich królowa Ashe, ucieleśnienie samej Avarosy, stanowiła nadzieję na pokój.","Jednostka",[],["Freljord"],"RZADKIE"],"01FR026":["Dziki Pazur Alfa","","","Siła ogiera i drapieżność dzikiego kota.","Jednostka",["KOT"],["Freljord"],"ZWYKŁE"],"01FR030":["Krucha Stal","Nałóż Odmrożenie na wroga o Zdrowiu 3 lub mniejszym.","","„Zimniutko wam? Miejmy nadzieję, że wasz duch jest lepiej zahartowany niż wasza letnia stal!” — Braum","Zaklęcie",["ŻYWIOŁ"],["Freljord"],"ZWYKŁE"],"01FR013":["Vrynna Matka Blizn","Gdy przetrwam obrażenia, przyznaj mi +3|+0.","","„Wolałabym umrzeć z zimna niż dzielić dom z tymi słabeuszami Ashe. Ale jeśli pożądają ciepła, z chęcią im je dam”.","Jednostka",[],["Freljord"],"EPICKIE"],"01FR019":["Tchnienie Zimy","Zabij wszystkich wrogów o Sile 0, po czym nałóż Odmrożenie na wszystkich wrogów.","","Wojmatka Zima jest pierwszą i ostatnią przeszkodą, jaką napotykają śmiałkowie najeżdżający Freljord. Jej krwioprzysięzcy to bezlitosny wicher i tnący mróz.","Zaklęcie",["ŻYWIOŁ"],["Freljord"],"EPICKIE"],"01FR041":["Avarosański Strażnik Płomienia ","Gdy mnie przywołasz, przyznaj sojusznikom w swojej talii +1|+1.","","„Zjednoczone plemiona pod jednym sztandarem! Wierzę, że któregoś dnia siły Freljordu połączą się w jedno”.","Jednostka",[],["Freljord"],"EPICKIE"],"01FR025":["Pasterz Poro","Gdy mnie przywołasz, dobierz Poro, jeśli Widzisz Poro.","","Stado potrzebuje tylko miłości i towarzystwa. Z resztą futrzaki poradzą sobie same.\n","Jednostka",[],["Freljord"],"RZADKIE"],"01FR054":["Najeźdźczyni Pań Blizn","","","„Słabi zbierają żniwa, jednak to silni z nich korzystają. Ci mali Avarosanie wkrótce się przekonają, do której grupy należą!”","Jednostka",[],["Freljord"],"RZADKIE"],"01FR021":["Tarkaz Bezplemienny","Atak: Zadaj 1 pkt. obrażeń WSZYSTKIM walczącym jednostkom.","","„Tarkaz był bardziej waleczny i zaprawiony w boju od innych. Potrafił przyjąć porażkę z godnością. Przynajmniej tak mi się zdawało...” — Tryndamere","Jednostka",[],["Freljord"],"EPICKIE"],"01FR043":["Serce Puchu","Zagraj: Połącz swoich stronników Poro w kartę Puch Poro i przyznaj jej ich statystyki i pozytywne słowa klucze.","","„Dobrze, ostatnia historia. Tylko cicho, bo obudzicie mamę!”\n„Dawno temu bandyci napadli na wioskę Avarosy. Jej wojska były nieliczne. Wydawało się, że są skazani na niepowodzenie. Wtedy pojawił się niepozornie wyglądający Poro i zaproponował Avarosie pomoc…”","Jednostka",["PORO"],["Freljord"],"RZADKIE"],"01FR033":["Tajemnicze Kamienie","Początek rundy: Otrzymaj dodatkowy kryształ many w tej rundzie.","","„Te starożytne kurhany przypominają nam o tym, że jesteśmy tylko ogniwem w niekończącym się łańcuchu plemion, które przemierzają te nieprzyjazne krainy”. — Ashe","Jednostka",[],["Freljord"],"ZWYKŁE"],"01FR011":["Lodowy Łucznik","Zagraj: Nałóż Odmrożenie na wroga.","","Avarosanie są dumni z panujących na ich ziemiach mroźnych zim oraz swoich skutych lodem terenów. Ich bystroocy obrońcy idą nawet o krok dalej. ","Jednostka",[],["Freljord"],"ZWYKŁE"],"01FR050":["Przyjazny Oberżysta","Zagraj: Ulecz sojusznika lub swój Nexus o 3 pkt.","","„Witamy w Podpitej Sowie! Zapraszamy na gorącą potrawkę i mocne napitki, które wypędzą najgorszy chłód! Śmiało, nie krępuj się!”","Jednostka",[],["Freljord"],"ZWYKŁE"],"01FR052":["Ta, Która Wędruje","Zagraj: Unicestwij WSZYSTKIE jednostki o Sile 4 lub mniejszej w grze i w rękach.","","„Jakimś cudem wydostałem się z pobojowiska. Ujrzałem głęboką szramę znaczącą teren dookoła. Po moich kompanów ostał się czarny popiół, a w oddali przesuwał się przerażający kształt...” — Wędrowiec Bjerg","Jednostka",[],["Freljord"],"EPICKIE"],"01FR016":["Poro-Chrupki","Przyznaj sojuszniczym Poro +1|+1, gdziekolwiek są.","","„Wciągają je w mgnieniu oka, a potem patrzą tymi swoimi wielki ślepiami bezbronnego szczeniaczka. Spróbuj im odmówić”. – Avarosański twórca przysmaków","Zaklęcie",[],["Freljord"],"ZWYKŁE"],"01FR005":["Bitewny Szał","Przyznaj sojusznikowi +8|+4.","","„Powiadają, że mam... temperament”. — Tryndamere","Zaklęcie",[],["Freljord"],"RZADKIE"],"01FR023":["Zew Wojmatki","Przywołaj pierwszą jednostkę z wierzchu swojej talii teraz i na początku KAŻDEJ rundy.","","Pewnego dnia rozbrzmi wołanie, które rozpozna każdy mieszkaniec Freljordu. Wszyscy powstaną, bo będzie to dzień, w którym powrócą starożytni wrogowie tej krainy.","Zaklęcie",[],["Freljord"],"EPICKIE"],"01FR047":["Dziki Mistyk","Oświecenie: Otrzymuję +4|+4.","","„Ci, którzy nauczą się ryczeć niczym dzikie bestie, szybko zapominają swojego ojczystego języka”. — Anivia","Jednostka",[],["Freljord"],"ZWYKŁE"],"01FR056":["Mroźny Yeti","Gdy mnie przywołasz, nałóż Odmrożenie na wrogów o Zdrowiu 3 lub mniejszym.","","„AaaaaaaAAaaaAaaaaaa!” — Wędrowiec Bjerg","Jednostka",["YETI"],["Freljord"],"RZADKIE"],"01FR027":["Samiec Elnuka","","","Avarosańskie legendy opowiadają o „starym wuju elnuku”. Ten zgryźliwy osobnik marzył tylko o spłachetku zieleni i kolejnej kłótni. ","Jednostka",["ELNUK"],["Freljord"],"ZWYKŁE"],"01FR057":["Mentalność Stada","Daj sojusznikom +2|+2 i Zmiażdżenie w tej rundzie.","","Pojedynczy skowyt przeszył nocną ciszę, po czym dołączyły do niego kolejne. Kilka chwil później cała wataha wyła już jednym głosem. Chór oszalałych bestii zwiastował rozlew krwi.","Zaklęcie",[],["Freljord"],"RZADKIE"],"01FR004":["Eliksir Żelaza","Daj sojusznikowi +0|+2 w tej rundzie.","","„Paskudny dzień, co? Nie martw się, w Sowie mamy napitek tak konkretny, że zaraz zapomnisz o chłodzie i jeszcze zachce ci się zapasów z niedźwiedziem!” — Przyjazny Oberżysta","Zaklęcie",[],["Freljord"],"ZWYKŁE"],"01FR048":["Avarosański Traper","Gdy mnie przywołasz, stwórz kartę Wściekły Yeti wśród pierwszych 3 kart z wierzchu swojej talii.","","„Cały tydzień nic! Albo te bestie mnie wyczuwają, albo coś je odstrasza...” ","Jednostka",[],["Freljord"],"ZWYKŁE"],"01FR017":["Stado Elnuków","Zagraj: Przywołaj każdego Elnuka spośród 6 kart z wierzchu swojej talii, a pozostałe karty wtasuj z powrotem.","","„Avarosanie są jak elnuki. To tępo patrzący trawożercy, których powalają bezbliźni. Tylko liczebność sprawia, że utrzymują się przy życiu”. – Vrynna, Matka Blizn","Jednostka",["ELNUK"],["Freljord"],"ZWYKŁE"],"01FR046":["Włóż w To Trochę Serca","Przyznaj zranionemu sojusznikowi +3|+3.","","„…Chociaż odniósł ciężkie rany, Braum odrzucił głowę do tyłu i gromko się zaśmiał. Wiedział, że to w najcięższych czasach rodzą się bohaterowie!”\n– Opowieść o Braumie","Zaklęcie",[],["Freljord"],"RZADKIE"],"01FR012":["Katalizator Eonów","Otrzymaj pusty kryształ many i ulecz swój Nexus o 3 pkt.","","Kamień wieczności przewyższa swym blaskiem rubiny i szafiry. To piękny klejnot o legendarnych właściwościach regeneracyjnych. ","Zaklęcie",[],["Freljord"],"ZWYKŁE"],"01FR040":["Szronokła Szamanka","Początek rundy: Nałóż Odmrożenie na Najsilniejszego wroga.","","„Nie staniesz się jednością z naturą, ukrywając się przed mrozem. Musisz stawić czoła jego dzikości”.","Jednostka",[],["Freljord"],"RZADKIE"],"01FR031":["Starożytny Yeti","Koniec rundy: Zmniejsz mój koszt o 1.","","„Co to było? Brzmiało jak kichnięcie. Czy lodowce... kichają?” — Wędrowiec Bjerg\n","Jednostka",["YETI"],["Freljord"],"RZADKIE"],"01FR053":["Potężny Poro","","","„Stary Długoróg stracił oko, broniąc samego Króla Poro przed dzikim pazurem! W końcu liczy się rozmiar serca, nie oręża”. — Pasterz Poro\n","Jednostka",["PORO"],["Freljord"],"ZWYKŁE"],"01FR010":["Ślubowanie Krwioprzysięzcy","Przyznaj 2 sojusznikom +0|+3.","","„Stanę się pochodnią wzniecającą ogień w twoim sercu. Tarczą u twego boku. Pomóż mi znaleźć siłę, aby chronić nas i naszych pobratymców. Niechaj nasze żywoty płyną razem niczym krew pieczętująca tę przysięgę”. — Tryndamere","Zaklęcie",[],["Freljord"],"RZADKIE"],"01FR001":["Błyskawiczne Zamrożenie","Nałóż Odmrożenie na wroga.","","Zimno atakuje bez ostrzeżenia. Nawet najsilniejszy wojownik ukorzy się przed nim.","Zaklęcie",["ŻYWIOŁ"],["Freljord"],"RZADKIE"],"01FR032":["Gwiezdny Wieszcz","Gdy zagrasz zaklęcie, przyznaj pierwszemu sojusznikowi z wierzchu talii +1|+1.","","„Daj im dobre uszy, aby słyszeli nadchodzący wiatr. Zwinne nogi, aby mogli przedrzeć się przez zaspy. Wprawne oczy, aby dostrzegli niebezpieczeństwo za mroźnym horyzontem”.","Jednostka",[],["Freljord"],"RZADKIE"],"01FR051":["Niewiarygodne Historie","Jeśli masz Yeti, przywołaj kartę Wściekły Yeti. Jeśli nie, stwórz ją na wierzchu swojej talii.","","„...A ten ma paszczę pełną powykrzywianych kłów, ogromne piąchy i oszalałe ślepia. No i potrafi RYKNĄĆ, AŻ IGŁY Z SOSEN LECĄ! Tak mówił mi wujek Bjerg!” – Ingvar Młodsza","Zaklęcie",[],["Freljord"],"ZWYKŁE"],"01FR034":["Ci, Którzy Wytrwali","Gdy mnie przywołasz, przyznaj mi +1|+1 za każdego sojusznika, który zginął.","","„Ach, stary Bjerg się nacierpiał. Stracił całą załogę na północy i wrócił po wielu miesiącach wychudzony i blady. Teraz ciągle bełkocze o ogromnych bestiach i wielkich pazurach. Biedaczysko…” – Przyjazny Oberżysta","Jednostka",[],["Freljord"],"RZADKIE"],"01FR007":["Bełkoczący Bjerg","Gdy mnie przywołasz, dobierz jednostkę o Sile 5+.","","„M-musicie mi uwierzyć! Był wielki! WIEEEELKI!”","Jednostka",[],["Freljord"],"ZWYKŁE"],"01FR003":["Avarosański Wartownik","Ostatnie Tchnienie: Dobierz 1 kartę.","","„Kiedyś szukałem swego miejsca na odległych polach bitewnych. Teraz udało mi się je odnaleźć u boku rodaków. Tu jest mój dom. Moje oczy i dłonie będą strzegły ich bezpieczeństwa”.","Jednostka",[],["Freljord"],"ZWYKŁE"],"01SI038":["Widmowa Figlarka","Gdy zginie inny sojusznik, zadaj 1 pkt. obrażeń wrogiemu Nexusowi.","","Jej najokrutniejszą sztuczką nie było szlachtowanie żołnierzy zwabionych dziewczęcym płaczem. Najgorsze było zasiewanie w sercach ocalałych niepewności, która pozwalała im ignorować krzyki ich własnych córek...","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"01SI049":["Zdradzieckie Spojrzenie","Zabij sojusznika, aby dobrać 2 karty.","","„Myliłem się. Nie powinniśmy byli zaglądać za bladą kurtynę. Jakakolwiek wiedza się za nią znajduje, wiąże się ze zbyt wysoką ceną”. — Arie Wrence, nieustraszony obrońca","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"01SI053":["Elise","Atak: Przywołaj atakującą kartę Pajączek.","Początek rundy: Masz 3+ inne Pająki.","Elise przewodziła niegdyś potężnemu noxiańskiemu rodowi. Jej mroczna więź z Wyspami Cienia zapewniła jej wieczną młodość i piękno w zamian za kilka niczego niepodejrzewających dusz. To była łatwa decyzja.","Jednostka",["PAJĄK"],["Wyspy Cienia"],"Bohater"],"01SI057":["Starożytny Krokolisz","Aby mnie zagrać, zabij 2 sojuszników.","","„Wrzucić je do klatki, byle już...\nZabrać co do jednej każdą z dusz...\nNie wypuszczać ich już nigdy, co to, to nie…\nInaczej będą jątrzyć całe dnie...”","Jednostka",["GAD"],["Wyspy Cienia"],"RZADKIE"],"01SI023":["Pasterka Dusz","Gdy przywołasz Efemerycznego sojusznika, przyznaj mu +1|+1.","","Tylko upadli wiedzieli, że nie szła sama. Tylko oni widzieli niezliczonych towarzyszy, których prowadziła w nieznane.","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"01SI010":["Nawałnica Cieni","Przywołaj 2 Widmowych Jeźdźców.","","Żyją teraz tak, jak niegdyś umarli: lojalni do samego końca.","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"01SI042":["Hecarim","Atak: Przywołaj 2 atakujących Widmowych Jeźdźców.","Udało ci się zaatakować 7+ Efemerycznymi sojusznikami.","To nie burza. To Cień Wojny pojawia się na horyzoncie.","Jednostka",[],["Wyspy Cienia"],"Bohater"],"01SI027":["Świeża Ofiara","Jeśli 3+ sojuszników zginęło w tej rundzie, przywołaj kartę Vilemaw.","","„Klękaj przed swoim bogiem. Albo jeszcze lepiej — zgiń przed nim”. — Elise","Zaklęcie",[],["Wyspy Cienia"],"RZADKIE"],"01SI048":["Przeklęty Stróż","Ostatnie Tchnienie: Przywołaj kartę Oswobodzona Abominacja.","","Szaleństwo i czas. Nie ma gorszego połączenia.","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"01SI018":["Skryba Udręki","Gdy mnie przywołasz, stwórz w ręce kopię sojusznika, który zginął w tej grze.","","„Nasz biedny autor nie wiedział jednak, że Zrujno... Zrujn... no nie, tusz znowu się rozlał! Autor nie wie... nie, nie nie!”","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"01SI030":["Kalista","","Widziałam, jak 3+ sojuszników ginie.","Za życia była generałem, strażniczką i bohaterką. Jednak gdy ciało umarło, został jedynie płomień odwetu, nieśmiertelny duch zemsty.","Jednostka",[],["Wyspy Cienia"],"Bohater"],"01SI035":["Rhasa, Rozrywacz","Zagraj: Zabij 2 Najsłabszych wrogów, jeśli w tej rundzie zginął sojusznik.","","„Powiedzieli nam… Nazwali to drogą legend. Zmierzaliśmy… ku przyszłości Demacii. Żeglowaliśmy z wielką nadzieją. Ale… ci wszyscy nieszczęśnicy… Po co to wszystko?” − Arie Wrence, demaciański żołnierz","Jednostka",[],["Wyspy Cienia"],"EPICKIE"],"01SI005":["Kraboduch","Kosztuję o 1 mniej za każdego sojusznika, który zginął w tej grze.","","Niegdyś ta bestia nękała dawno zapomniane królestwo. Teraz przetrzebia opuszczone pola bitewne, stale powiększając swą skorupę orężem poległych i posilając się ich duszami.","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"01SI037":["Złowieszczy Poro","","","Cóż, są gorsze sposoby na śmierć.","Jednostka",["PORO"],["Wyspy Cienia"],"ZWYKŁE"],"01SI052":["Thresh","","Widziałem, jak ginie 6+ jednostek.","„Trzeszczą, świszczą złe łańcuchy,\nZaraz będzie brzuch rozpruty…”","Jednostka",[],["Wyspy Cienia"],"Bohater"],"01SI033":["Dowódca Ledros","Zagraj: Zadaj wrogiemu Nexusowi obrażenia równe połowie jego zdrowia (zaokrąglając w górę).\nOstatnie Tchnienie: Przywróć mnie do ręki.","","Większość dusz zatraciła się przez lata, wraz z upływem których uleciała pamięć o dawnym życiu. Jednak udręka mocno trzymała Ledrosa w przeszłości. Niektórych ran nawet czas nie zaleczy.","Jednostka",[],["Wyspy Cienia"],"EPICKIE"],"01SI003":["Harrowing","Wskrześ 6 Najsilniejszych sojuszników, którzy zginęli w tej grze, i przyznaj im Efemeryczność.","","Są takie noce, gdy fala wygłodniałych dusz wypełnia Czarną Mgłę. Ta pozwala im pokonać morza, aby mogły posilać się żywymi i nasycać stale rosnący mrok nieżycia.","Zaklęcie",[],["Wyspy Cienia"],"EPICKIE"],"01SI041":["Nieumarły","Ostatnie Tchnienie: Wskrześ mnie na początku następnej rundy i przyznaj mi +1|+1 za każdy raz, gdy zginąłem.","","Stary męczennik pamiętał moment posłania kompanów na pewną śmierć. Nie pamiętał już jednak, dlaczego to zrobił...","Jednostka",[],["Wyspy Cienia"],"EPICKIE"],"01SI045":["Absorpcja Duszy","Zaczerpnij 4 pkt. Zdrowia z sojusznika.","","„Co was zabije, to mnie wzmocni”. — Thresh","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"01SI036":["Niepokojące Mrowienie","Jeśli sojusznik zginął w tej rundzie, przywołaj 2 Pajączki.","","Zimny dreszcz w obliczu niebezpieczeństwa jest niczym w porównaniu z tym samym uczuciem, ale pod skórą.","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"01SI051":["Udręczony Geniusz","Gdy zginie inny sojusznik lub Ostatnie Tchnienie: odzyskaj manę zaklęć.","","Harował dniami i nocami, chcąc udoskonalić swoją kompozycję. I nagle, w mgnieniu oka, przeszyła go mroczna cisza. Inni uciekali w popłochu. On niczego nie zauważył.","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"01SI012":["Nieświadomy Wyspiarz","Zagraj: Przyznaj sojusznikowi w ręce Efemeryczność i zmniejsz jego koszt o 1.","","Biedaczysko...","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"01SI031":["Żelazny Herold","Atak: Przyznaj mi +1|+0 za każdego posiadanego Efemerycznego sojusznika.","","Hecarim po śmierci, podobnie jak za życia, roztacza swe plugawe, mroczne rządy. Jedynie jego najlojalniejsze dusze wciąż odpowiadają i bez wahania ruszają na rzeź.","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"01SI034":["Czarna Włócznia","Jeśli w tej rundzie zginął sojusznik, zadaj jednostce 4 pkt. obrażeń.","","„Nasza włócznia śpiewa dla poległych!” — Kalista","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"01SI043":["Lekkomyślny Arystokrata","Ostatnie Tchnienie: Przywołaj kartę Pajączek.","","„P-pani Elise? Gdzie... gdzie się podziewasz?”","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"01SI009":["Zmieszane Dusze","Wsparcie: Przyznaj wspieranemu przeze mnie sojusznikowi +2|+0 i Efemeryczność.","","Niektórzy widzą w Zrujnowaniu tylko śmierć i zniszczenie. Dla innych szklanka jest w połowie pełna.","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"01SI007":["Przeklęta Relikwia","Przywołaj 3 Wyzwolone Dusze.","","Tych starożytnych artefaktów pożądają zarówno spragnieni bogactw żyjący, jak i martwi, którzy za wszelką cenę chcą zatrzymać je dla siebie.","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"01SI056":["Rozwścieczony Pełzak","Gdy mnie przywołasz, daj +1|+0 innym sojuszniczym Pająkom i -1|-0 wrogom w tej rundzie.","","„Potrafią opleść człowieka w mniej niż minutę... Czy mam zademonstrować?” — Elise","Jednostka",["PAJĄK"],["Wyspy Cienia"],"RZADKIE"],"01SI001":["Zemsta","Zabij jednostkę.","","Zdradzeni wzywają swym ostatnim tchnieniem Kalistę, mając nadzieję, że jej włócznia zapewni im zemstę.","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"01SI019":["Pudło","Zadaj 3 pkt. obrażeń każdemu wrogowi, który został przywołany w tej rundzie.","","„Nikt nie ucieknie”. — Thresh","Zaklęcie",[],["Wyspy Cienia"],"RZADKIE"],"01SI011":["Krwiożerczy Rzeźnik","Aby mnie zagrać, zabij sojusznika.","","Jesteś tym, co jesz.","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"01SI014":["Zjawa z Mgły","Gdy mnie przywołasz, inne sojusznicze Zjawy z Mgły otrzymują +1|+0, gdziekolwiek są.","","Te widma z Wysp dawno wyzbyły się swojej tożsamości. Stanowią teraz część wygłodniałej, nienazwanej masy.","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"01SI022":["Znak Wysp","Przyznaj sojusznikowi +2|+2 i Efemeryczność.","","Potęga, ale za jaką cenę?","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"01SI006":["Opętanie","Skradnij wrogiego stronnika w tej rundzie. (Nie możesz zagrać, gdy masz już 6 sojuszników lub lokacji).","","Obudził się w podejrzanie cichym obozie z dłońmi lśniącymi czerwienią. ","Zaklęcie",[],["Wyspy Cienia"],"RZADKIE"],"01SI028":["Rozszczepienie Duszy","Przywołaj dokładną kopię sojusznika. Otrzymuje Efemeryczność i statystyki 1|1.","","„Wyłowiłem to ciało z wody, aby dowiedzieć się, co za biedak tak skończył. Gdy położyłem dłoń na jego ramieniu, obrócił się. Jego twarz… wyglądała jak moja”. – Arie Wrence, demaciański żołnierz","Zaklęcie",[],["Wyspy Cienia"],"RZADKIE"],"01SI025":["Okrucieństwo","Zabij sojusznika, aby zadać obrażenia równe jego Sile dowolnemu celowi.","","Zabijanie jest niczym dla tych, którzy nigdy nie doświadczą śmierci.","Zaklęcie",[],["Wyspy Cienia"],"RZADKIE"],"01SI046":["Zew Mgły","Wskrześ losowego sojusznika, który zginął w tej rundzie.","","„Mgła oddziela duszę od ciała, zostawiając tylko nędzną parodię życia. Widziałem, jak zatruwa moją ojczyznę. Dlatego teraz zmierzam na te przeklęte wyspy, aby położyć kres koszmarowi”. – Arie Wrence, nieustraszony obrońca","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"01SI050":["Przebudzenie Pomiotu","Przywołaj 3 Pajączki, po czym przyznaj sojuszniczym Pająkom +1|+0.","","Najbardziej głodne są zaraz po wykluciu.","Zaklęcie",[],["Wyspy Cienia"],"RZADKIE"],"01SI016":["Piewczyni Upiorów","Przymierze: Przywołaj kartę Zjawa z Mgły.","","Pojawia się bezgłośnie. Jednak potworności, które kroczą za nią, są mniej subtelne.","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"01SI021":["Rekini Rydwan","Ostatnie Tchnienie: Następnym razem, gdy Efemeryczny sojusznik zaatakuje, wskrześ mnie jako atakującego.","","„Co takiego widziała? Rozumiem. Szaleństwo to bezwzględna kochanka, aptekarzu. Przynajmniej inni gadają z sensem”. — Demaciański chirurg","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"01SI032":["Kronikarka Upadku","Zagraj: Zabij sojusznika, po czym go wskrześ.","","Pewnego razu usiadła z ojcem, gdy ten studiował stare zakurzone tomiszcza. Miał nadzieję, że kiedyś przejmie po nim rolę lorda kustosza — ale nie w taki sposób.","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"01SI058":["Eteryczny Łącznik","Zagraj: Zabij sojusznika, aby przywołać losowego stronnika o koszcie o 2 wyższym.","","Duchy, dajcie mi swój głos! Razem zaprowadzimy nieskończoną ciemność!","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"01SI054":["Uścisk Nieumarłego","Zaczerpnij 3 pkt. Zdrowia z jednostki.","","Martwi niczego nie pragną tak, jak uciszenia pulsu żywych.","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"01SI044":["Widmowa Matrona","Zagraj: Wybierz sojusznika w ręce. Przywołaj jego dokładną kopię. Otrzymuje Efemeryczność.","","Zrujnowanie dotknęło każdego, kto znalazł się w jego zasięgu. Dobrotliwi stali się nikczemni. Odważni stali się bezwzględni. Rozum zastąpiła nienawiść.","Jednostka",[],["Wyspy Cienia"],"EPICKIE"],"01SI039":["Pajęcza Potworność","","","Niektóre nikczemne duchy przybierają formę miejscowych zwierząt, jednak w znacznie koszmarniejszym wydaniu.","Jednostka",["PAJĄK"],["Wyspy Cienia"],"ZWYKŁE"],"01SI020":["Ożywiający Płomienie","Gdy mnie przywołasz, wskrześ Najsilniejszego poległego sojuszniczego bohatera.","","Do czego może się przydać gasnąca świeca, poza podpaleniem kolejnej?","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"01SI029":["Gasnący Krzyk","Zadaj 1 pkt. obrażeń wszystkim wrogom. Ulecz swój Nexus o 3 pkt.","","Co nas zabije, to ich wzmocni.","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"01SI004":["Postrach Mrocznej Wody","","","Część uciekających przed Zrujnowaniem wskoczyła w morskie odmęty z nadzieją, że tam zła moc ich nie dosięgnie. Mylili się.","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"01SI026":["Ofiara Strażnika","Ostatnie Tchnienie: Stwórz w ręce innego losowego stronnika z Ostatnim Tchnieniem o koszcie 3 lub niższym.","","Wstrzymał oddech i modlił się, aby strażnik go nie zauważył. Nie wiedział jednak, że ten pościg był jedynie początkiem udręki, którą miał mu zgotować Thresh...","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"01SI040":["Przerażająca Uczta","Zaczerpnij 1 pkt. Zdrowia z jednostki, aby przywołać kartę Pajączek.","","„Moja pani! Nie sądziłem, że... tak bardzo uwielbiasz pająki! Czy mogłabyś je ode mnie odwołać? P-pani Elise? Proszę?” — Lord Sassen, Lekkomyślny Arystokrata","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"01SI015":["Zrujnowanie","Zabij WSZYSTKIE jednostki.","","I pomyśleć, że coś tak czystego i niewinnego jak miłość mogło stworzyć takie okrucieństwo. ","Zaklęcie",[],["Wyspy Cienia"],"EPICKIE"],"01SI055":["Pożeracz Dusz","","","„Gdy nasze statki zaczęły zbliżać się do tych nawiedzonych ziem, zacząłem się zastanawiać: czy te abominacje zrodziły się na brzegach tej wynaturzonej krainy? Czy kiedykolwiek prowadziły normalne życie?” – Arie Wrence, demaciański żołnierz","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"01SI047":["Ulotne Wspomnienia","Wybierz stronnika. Stwórz jego Efemeryczną kopię w ręce.","","Na jedną chwilę wszystko sobie przypomniała. Przyćmione promienie słońca tańczyły na jej skórze, dorodne jeżyny pękały w jej ustach, a łagodna melodia polany rozbrzmiewała w chłodnej bryzie. A potem... wszystko zniknęło.","Zaklęcie",[],["Wyspy Cienia"],"RZADKIE"],"02PZ001":["Niemiaużliwe","Gdy mnie przywołasz, dobierz 1 kartę.\nNastępnie, jeśli udało ci się zagrać w tej grze co najmniej 10 innych nowych kart, przyznaj mi +4|+0.","","Nic nie mogło powstrzymać jego ucieczki spod władzy tych żałosnych ludzi. Nawet odrobina wody...","Jednostka",["KOT"],["Piltover i Zaun"],"EPICKIE"],"02PZ010":["Doświadczony Detektyw","Gdy mnie przywołasz, WSZYSCY gracze dobierają 1 kartę.","","Niektórzy śledczy polegają na instynkcie, by rozwikłać zagadkę. Inni uruchamiają swoje kontakty. Ale detektyw J.S. Harknor wszystko zawdzięcza skrupulatności i papierkowej robocie. A tej wykonuje najwięcej ze wszystkich.","Jednostka",["YORDLE"],["Piltover i Zaun"],"ZWYKŁE"],"02PZ006":["Mam Cię!","Gdy mnie dobierzesz, kosztuję o 2 mniej w tej rundzie.\nZadaj 3 pkt. obrażeń jednostce.","","„Panie Berz, może pan założyć te kajdanki?”\n„A co będę z tego miał?”\n„Może je pan zatrzymać”.\n„...No dobra”.\n„Jesteś aresztowany. Brać go!”","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"02PZ004":["Niszczyciel Skarbca","Daj sojusznikowi +2|+0 w tej rundzie.\nStwórz Ulotną kartę Niszczyciel Skarbca w ręce.","","„Pozwól, że dam przemówić moim pięściom”. — Vi","Zaklęcie",[],["Piltover i Zaun"],"RZADKIE"],"02PZ007":["Dociekliwa Detektyw","Gdy zagrasz kartę o koszcie 2, dobierz 1 kartę i przyznaj jej Ulotność.","","„Każdy detektyw potrafi reagować na rozwój wydarzeń. Dobry potrafi go przewidzieć. Wybitny powstrzymać”. — Podręcznik Strażnika","Jednostka",[],["Piltover i Zaun"],"RZADKIE"],"02PZ002":["Zevi, Główny Mechanik","Gdy dobierzesz kartę, przyznaj jej Ulotność i stwórz jej dokładną kopię w ręce.","","W wieku pięciu lat stworzyła pierwszy na świecie ultradźwiękowy nóż. Chociaż nie był zbyt praktyczny (i zazwyczaj służył jej do krojenia chleba), pozwolił jej postawić pierwsze kroki w szeregach Departamentu Zbrojeniowego Strażników.","Jednostka",[],["Piltover i Zaun"],"EPICKIE"],"02PZ008":["Vi","Gdy jestem w grze lub w ręce, przyznaj mi +1|+0, gdy zagrasz inną kartę (maks. +8|+0).","Udało mi się Uderzyć za 10+ pkt. obrażeń jednym Uderzeniem.","„Oficer Vi, proszę! Pomyśl o ludziach! O zniszczeniach! O PAPIERKOWEJ ROBOCIE PRZY SKARGACH!” — Dociekliwa Detektyw","Jednostka",[],["Piltover i Zaun"],"Bohater"],"02PZ009":["Poszlaki","Stwórz w ręce losową kartę o koszcie 2 z twoich regionów. Kosztuje o 2 mniej w tej rundzie.","","„A więc... — rzekł śledczy Harknor — poszlaka prowadzi nas do...”","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"02PZ003":["Szykuj Się!","Gdy mnie dobierzesz, kosztuję o 2 mniej w tej rundzie.\nZwiększ statystyki sojusznika do 4|4.","","„Kłopoty w porcie! Weź to i przekaż im moje pozdrowienia”. — Zevi, Główny Mechanik","Zaklęcie",[],["Piltover i Zaun"],"RZADKIE"],"02PZ005":["Patrolujący Strażnicy","Gdy mnie dobierzesz, kosztuję o 1 mniej w tej rundzie.","","Sposób, w jaki posterunkowy Mir biegał, szybko stał się żartem pośród Strażników. Posterunkowa Kepple nie rozumiała żartu.","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"02BW040":["Skoruporażacz ","","","„MOJOM NAJWIĘKSZOM SIŁOM JEST UMIEJENTNOŚĆ KONTROLOWAŃA ZWYKŁYH LUDZI, A PODOBNO TAKRZE ORTOGRAFJA” — Wiadomość zapisana na piasku","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"02BW057":["Oślizgły Jeździec Fal","","","„Kapitanie, widziałem nad rafą dziwy nie z tego świata. Co ten kretyn nawkładał do pomarańczy? Muszę się dowiedzieć...” — Bosman","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"02BW041":["Bestia z Głębin","","","„Nie lękaj się bestii, które znasz,\nwszak przetrwać można ich widmo.\nCo jednak z tymi, które nie w czas\nwciągnęły nieszczęśników na dno?” — Tekst wydrapany na jednej z belek tawerny w Bilgewater","Jednostka",["POTWÓR MORSKI"],["Bilgewater"],"ZWYKŁE"],"02BW013":["Grasująca Nożowniczka","","","„...i wtedy ten kretyn powiedział, że biodra kołyszą mi się jak morskie fale. Ja na to, żeby przestał tyle gadać, bo utnę mu jęzor”.","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"02BW034":["Małpi Bożek","Początek rundy: Zadaj mi 2 pkt. obrażeń i przywołaj kartę Prochowa Małpka.","","„To drobna… pamiątka. Załoga zwinęła ją mojemu rywalowi, stukniętemu starcowi. Wygląda na to, że jego gadki na temat starożytnych, tajemniczych mocy nie były dalekie od prawdy…” — Miss Fortune","Jednostka",[],["Bilgewater"],"RZADKIE"],"02BW056":["Pożeracz z Głębin","Zagraj: Unicestwij wroga o Zdrowiu mniejszym od mojego.","","„Wypłynąłem niegdyś\nz Bilgewater Zatoki,\nGdy nagle z odmętów — widok to trwogi!\nTopielica o skrzydlatych uszach...” — „Ballada o Skrzydłouchej Topielicy”","Jednostka",["POTWÓR MORSKI"],["Bilgewater"],"EPICKIE"],"02BW060":["Korsarka Szyderczej Salwy","Gdy sojusznicy atakują, zadaj 1 pkt. obrażeń wrogiemu Nexusowi.","","„Niski wzrost daje zaskakującą przewagę w walce. Nikomu nie przychodzi do głowy patrzeć pod nogi!”","Jednostka",["YORDLE"],["Bilgewater"],"ZWYKŁE"],"02BW011":["Yordlowy Naciągacz","Przymierze: Zwędź 1 kartę i stwórz w ręce kartę Strzał Ostrzegawczy.","","„Wiesz, że przyjaciele powinni sobie pomagać? Co my tu mamy... Podoba mi się błysk w twoim oku. Nie mówiąc o błysku twojego ostrza! Tak, w rzeczy samej, piękna broń”.","Jednostka",["YORDLE"],["Bilgewater"],"RZADKIE"],"02BW030":["Kolekcjoner Wraków","Gdy mnie przywołasz, Wyrzuć 2 karty i stwórz w swojej talii 2 Skarby.","","„W dzisiejszych czasach skarbów jest więcej pod wodą, niż nad nią. Byłoby łatwo je dorwać, gdyby nie ona”. — Hardy Rzeźnik","Jednostka",["POTWÓR MORSKI"],["Bilgewater"],"EPICKIE"],"02BW019":["Bańkowy Miś","","","Przez rafy Wysp Węży przepływają magiczne prądy, dzięki którym w wodzie kwitnie wyjątkowe życie.","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"02BW007":["Arogancka Hazardzistka","Aby mnie zagrać, odrzuć 2 karty.\nAtak: Dobierz 2 karty i przyznaj im Ulotność.","","„W sumie nie ma o czym gadać. Przy stołach pełno jest półgłówków, którzy są bardziej zajęci zdzieraniem sobie gardeł, niż samą grą. Nie żeby mi to przeszkadzało. Kasa to kasa. A zawsze lepiej, żeby była w mojej kieszeni”.","Jednostka",[],["Bilgewater"],"RZADKIE"],"02BW014":["Stworzenia z Koralowca","Gdy mnie przywołasz, stwórz w ręce losowe zaklęcie o koszcie 1 z twoich regionów.","","Na płytkich wodach zawsze można spotkać wiele form życia morskiego, jednak żadne miejsce nie równa się Lazurowej Ścieżce. To magiczne miejsce nie z tego świata, pełne istnych cudów.","Jednostka",[],["Bilgewater"],"RZADKIE"],"02BW055":["Harda Nadzorczyni","Grabież: Przyznaj sojusznikom o koszcie 1 +1|+0, gdziekolwiek są.","","Jak tylko wystrzeli, Haki muszą działać błyskawicznie. Krew w wodzie przyciąga różnego rodzaju towarzystwo… A żadne nie jest mile widziane.","Jednostka",[],["Bilgewater"],"EPICKIE"],"02BW017":["Dostawca Cytrusów","Grabież: Ulecz sojuszników i swój Nexus o 3 pkt., po czym Zjednocz Siły.","","„Każdy marynarz myśli, że jest twardy! Warczy na wrogów, wymachuje bronią. To wszystko ważne, ale nie zapominajmy o pomarańczach! Ma się po nich ładną cerę, zęby nie wypadają, a jestem kontent. Tak więc zajadaj, albo wypad za burtę”.","Jednostka",[],["Bilgewater"],"RZADKIE"],"02BW038":["Piorunka Bryzgopłetwa","Gdy mnie przywołasz, dobierz ze swojej talii zaklęcie o koszcie 3 lub mniejszym.","","Piorunka ukończyła niegdyś zawody Lazurowej Ścieżki w niecałe 3 minuty. Pod koniec musiała nawet uniknąć roztrzaskanego kadłuba Morskiej Kawki! Prądy tamtego dnia były WSPANIAŁE.","Jednostka",[],["Bilgewater"],"EPICKIE"],"02BW021":["Brzytwołuski Łowca","Zagraj: Przyznaj wrogowi Podatność.","","„Podobno potrafi przepłynąć całe mile, by znaleźć swój cel. A gdy już to zrobi, nigdy nie pudłuje. Nie wiem, czy to bardziej człowiek, czy ryba, ale na pewno zna te wody lepiej od nas”. — Hardy Rzeźnik","Jednostka",[],["Bilgewater"],"RZADKIE"],"02BW035":["Szeryf Lariette Rose","Gdy mnie przywołasz, przyznaj wszystkim wrogom Podatność.","","W Bilgewater może nie obowiązywać żadne prawo, jednak garstka dzielnych dusz za murami naszego gwarnego miasta nie boi się egzekwować pojmowanej na swój sposób sprawiedliwości.","Jednostka",[],["Bilgewater"],"EPICKIE"],"02BW058":["Hardy Rzeźnik","Grabież: Przyznaj mi +1|+1.","","Przystąpić do Hardych Haków to nie lada wyzwanie. Żeglarz musi się znać na okrętach, na bitwie i oprawianiu mięsa. Najbardziej szemrane typy potrafią udowodnić swoje zdolności w tych trzech kategoriach przy jednej okazji.","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"02BW028":["Działonowy Rex","Grabież: Zagraj Kanonada 7 razy na losowych wrogów.","","„Nie zważaj na trupy, nie zważaj na wrak,\nBitwa dobiegła już końca.\nKapitana to kres, spotkał Rexa wszak,\nI nigdy nie ujrzy już słońca”. — „W domu z tobą, Sally”","Jednostka",[],["Bilgewater"],"EPICKIE"],"02BW037":["Oko Otchłani","Uderzenie w Nexus: Dobierz 1 kartę.","","„Tak jest, zawołali, wiatru w żagle daj,\ni wyruszyli ku odległemu Nashramae.\nNatura złośliwa nie obeszła ich bokiem,\na ci, co przeżyli, spotkają się z Wszechwidzącym Okiem!” — „Wszechwidzące Oko”","Jednostka",["POTWÓR MORSKI"],["Bilgewater"],"RZADKIE"],"02BW008":["Bosman","Zagraj: Przywołaj kartę Beczka Prochu lub losowego stronnika o koszcie 1.","","Szybko się nauczył, że nic tak nie motywuje leniwego marynarza jak podpalony lont.","Jednostka",["YORDLE"],["Bilgewater"],"RZADKIE"],"02BW047":["Kopacze Mętów","Gdy mnie przywołasz, Wyrzuć 3 karty.","","Trzeba mieć nie lada talent, by zdatny do żeglugi sprzęt zamienić w bezwartościowe śmieci. Jeśli jednak jest coś, w czym są oni dobrzy, to właśnie w tym. I w niczym innym.","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"02BW004":["Majtek Drogi przez Mękę","Gdy mnie przywołasz, przywołaj kartę Beczka Prochu.","","„No, możemy stawić im czoła o świcie, jak ich załoga będzie gotowa, a działa załadowane. Ale możemy też zostawić im w nocy prezent. Cichaczem...”","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"02BW002":["Droga przez Mękę","Gdy mnie przywołasz, dobierz kartę Gangplank.\nPodwój wszystkie obrażenia zadawane przez twoje zaklęcia, Umiejętności i sojuszników.","","„Zmów paciorek i opuść żagle,\nDrogi przez Mękę nadszedł czas.\nŚmierci zew poczujesz nagle,\nBo Drogi przez Mękę nadszedł czas!” — Czas Drogi przez Mekę","Jednostka",[],["Bilgewater"],"EPICKIE"],"02BW016":["Jednoręki Bot","Gdy mnie przywołasz lub na Początku rundy: Przyznaj mi +0|+1 za każdą kartę dobraną w ostatniej rundzie. Następnie losowo zmień moje statystyki.","","Jeden z prototypów wykręcił trzy bomby i eksplodował. Późniejsze modele zostały pozbawione tej „funkcji”.","Jednostka",[],["Bilgewater"],"RZADKIE"],"02BW027":["Łowcza Flota","Gdy mnie przywołasz, twój przeciwnik przywołuje Złoty Narwal.","","Złoty połysk pod taflą wody nie pochodzi od monet ani żył kruszcu. To lśniący róg przebiegłego wroga kapitana Floty Rzezi.","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"02BW050":["Wprawna Solistka","Grabież: Zmniejsz koszt sojuszników w ręce i talii o 2.","","„Dołącz do nas w tej muzycznej podróży! Delektuj się melodiami z całej Runeterry! Pamiętaj jednak, że udział nie jest darmowy, a napiwki są wręcz wskazane…” — Organizator pokazu","Jednostka",[],["Bilgewater"],"RZADKIE"],"02BW015":["Syrena","Gdy mnie przywołasz, dobierz kartę Miss Fortune.\nGdy atakuję, wszystkie twoje zaklęcia i Umiejętności zadają dodatkowo 1 pkt. obrażeń.","","Syrena to okręt nie do podrobienia. Szerokie, perłowe żagle i polerowane drewno sprawiają, że ten statek robi co najmniej takie wrażenie, jak kapitan stojąca za jego sterami.","Jednostka",[],["Bilgewater"],"EPICKIE"],"02BW010":["Plądrujący Poro","Grabież: Przyznaj mi 2 losowe słowa klucze.","","„Jego facjata figuruje na listach gończych dłużej niż większości oprychów. To chciwy i okrutny diabeł, który nie odpuszcza nikomu. Najgorsze jest to... że jest też całkiem uroczy”. — Gangplank","Jednostka",["PORO"],["Bilgewater"],"ZWYKŁE"],"02BW009":["Rekin Bilarda","Gdy mnie przywołasz, dobierz 1 kartę na Początku kolejnej rundy i przyznaj jej Ulotność.","","„To nie ma sensu. Wbijałam gładko jedna za drugą, ale ostatnia... za nic nie chciała wejść. Chyba nie mam dziś szczęścia...” — Arogancka Hazardzistka","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"02BW005":["Najemniczka","Gdy mnie przywołasz, przyznaj Najsilniejszemu wrogowi Podatność.","","„To twoja facjata? Cóż, masz gorszą gębę, niż przypuszczałam. Miejmy nadzieję, że chociaż twoja głowa jest coś warta”.","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"02BW039":["Łowcy Jaull","Gdy mnie przywołasz, stwórz w ręce losowego Potwora Morskiego.","","Pragnienie bogactwa pcha niezliczone załogi poza płycizny. Biedacy szybko się przekonują, jak przerażające potrafią być wody i dlaczego tak niewielu powraca.","Jednostka",[],["Bilgewater"],"RZADKIE"],"02BW006":["Mistyczny Mag","Zagraj: Przemień sojusznika w losowego stronnika o koszcie 5.","","„Marvolio? Gdzie... Gdzie są moje ręce?”\n„Zaraz sprawię, że się pojawią! Ta-daa! Ekhm. Ta... daa...!”\n„...GDZIE MOJE RĘCE?!”\n„DOBRA, KONIEC PRZEDSTAWIENIA! DZIĘKUJĘ, DOBRANOC!”","Jednostka",[],["Bilgewater"],"RZADKIE"],"02BW036":["Złoty Narwal","","","Legendy głoszą, że blady rogaty wieloryb ukradł coś Brodatej Damie. W ramach kary Dama pokryła chciwe stworzenie błyszczącym złotem, by do końca życia musiało uciekać przed chciwymi ludźmi.","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"02BW033":["Handlarz z Czarnego Rynku","Gdy dobierzesz wrogą kartę, zmniejsz jej koszt o 1.\nGrabież: Zwędź 1 kartę.","","„Jeśli czegoś szukasz, ja to mam! Znajdziesz u mnie także wyjątkowy asortyment… Tylko pamiętaj, nie ja ci to sprzedałem!”","Jednostka",[],["Bilgewater"],"RZADKIE"],"02BW032":["Gangplank","Gdy mnie przywołasz, przywołaj kartę Beczka Prochu.","Udało ci się zadać obrażenia wrogiemu Nexusowi w 5+ różnych rundach.","„Nie gap się zbyt długo, bo zauważy. I nie mów o nim źle, bo słyszy każdy szept w Bilgewater. Nadchodzi. Głowa w dół. Oczy jeszcze niżej”. – Majtek Drogi przez Mękę","Jednostka",[],["Bilgewater"],"Bohater"],"02BW022":["Miss Fortune","Gdy sojusznicy atakują, zadaj 1 pkt. obrażeń wszystkim walczącym wrogom i wrogiemu Nexusowi.","Widziałam, jak atakujesz 4 razy.","„Miss Fortune? Dla ciebie Pani Kapitan”.","Jednostka",[],["Bilgewater"],"Bohater"],"02BW046":["Fizz","Gdy zagrasz zaklęcie, zatrzymaj wszelkie wrogie zaklęcia i Umiejętności wymierzone we mnie i daj mi Nieuchwytność w tej rundzie.","Udało ci się zagrać 6+ zaklęć.","Spośród wszystkich legendarnych postaci Bilgewater Fizz uchodzi za najbardziej nieprzewidywalnego. Niektórzy marynarze przeklinają go za niezliczone wraki spoczywające na wybrzeżu…","Jednostka",["YORDLE"],["Bandle City","Bilgewater"],"Bohater"],"02BW026":["Twisted Fate","Zagraj: Zagraj Kartę Przeznaczenia.","Widziałem, jak dobierasz 9 kart.","„Patrz mi na ręce, policz karty i spróbuj nadążyć. No i pamiętaj...”","Jednostka",[],["Bilgewater"],"Bohater"],"02BW053":["Nautilus","","Gdy udało ci się osiągnąć Głębokość. Gdy awansuję, skopiuj Wyrzuconych sojuszników o koszcie 4+ do swojej talii.","„Rancoura zatopiła kotwica. Finn także poszedł na dno. Została nas już tylko garstka, lecz noc nadciąga… a z nią zimno. Wybacz mi, mamo, miałaś rację. Tytan żyje”. — Odzyskana notka","Jednostka",[],["Bilgewater"],"Bohater"],"02BW061":["Kieszonkowe Asy","Gdy mnie dobierzesz, kosztuję o 1 mniej w tej rundzie.\nPrzyznaj sojusznikowi +2|+1.","","„Nie ma to jak dobra passa. To co, jeszcze jedną partyjkę?” — Twisted Fate","Zaklęcie",[],["Bilgewater"],"ZWYKŁE"],"02BW024":["Podwójne Kłopoty","Przywołaj 2 losowych stronników o koszcie 1.","","„Ej, Gav... To nie tego gościa tropimy? Chyba znalazł towarzystwo”.\n„Baz... czy to człowiek-rekin?”\n„To niespodziewany przypływ gotówki, stary. Do dzieła”. — Baz i Gav, początkujący łowcy nagród","Zaklęcie",[],["Bilgewater"],"RZADKIE"],"02BW003":["Silnoręki","Grabież: Wycofaj DOWOLNEGO stronnika do swojej ręki.","","„Teraz pracujesz dla nas!” — Bosman","Zaklęcie",[],["Bilgewater"],"RZADKIE"],"02BW025":["Mącenie Wody","Przyznaj wrogowi Podatność i przywołaj kartę Wielki Ząb.","","„Rekin!” – Fizz","Zaklęcie",[],["Bilgewater"],"ZWYKŁE"],"02BW012":["Więcej Prochu!","Przywołaj 2 Beczki Prochu.","","„Beczka!” — Gangplank","Zaklęcie",[],["Bilgewater"],"ZWYKŁE"],"02BW018":["Paktujemy?","Zadaj 1 pkt. obrażeń dowolnemu celowi.\nJeśli to go zabije, zadaj 1 pkt. obrażeń wrogiemu Nexusowi.","","Gangplank preferuje krótką formę negocjacji, którym często towarzyszy rozlew krwi.","Zaklęcie",[],["Bilgewater"],"ZWYKŁE"],"02BW048":["Uciekinier","Przywołaj losowego stronnika o koszcie 1.","","„Co sądzisz, Baz? Nie wygląda na twardziela”.\n„Na pewno, Gav? W końcu uciekł z paki…”\n„Czyli jest przebiegły, a nie mocny. No dawaj!” — Baz i Gav, początkujący łowcy nagród","Zaklęcie",[],["Bilgewater"],"ZWYKŁE"],"02BW043":["Wybierz Kartę","Aby zagrać, umieść kartę z ręki w swojej talii.\nDobierz 2 karty na Początku kolejnej rundy i przyznaj im Ulotność.","","„Szczęście biorę we własne ręce”. — Twisted Fate","Zaklęcie",[],["Bilgewater"],"RZADKIE"],"02BW051":["Psotny Rozrabiaka","Usuń atakującego sojusznika z walki, aby Zjednoczyć Siły.","","„Jestem o sus przed tobą!” – Fizz","Zaklęcie",[],["Bilgewater"],"RZADKIE"],"02BW054":["Prąd Morski","Ogłusz wroga.\nUmieść tę jednostkę w talii przeciwnika, jeśli masz kartę Nautilus.","","„Na dno z nimi…” — Nautilus","Zaklęcie",[],["Bilgewater"],"RZADKIE"],"02BW042":["Złączenie Umysłów","W tej rundzie zwiększ Siłę i Zdrowie sojuszników, tak aby były równe liczbie pozostałych zaklęć zagranych przez ciebie w tej grze.","","Prądy i pływy wokół Bilgewater słusznie budzą grozę, a to z uwagi na ich siłę i niespodziewane zmiany biegu. Żaden marynarz nie zna jednak prawdziwej potęgi tych wód.","Zaklęcie",[],["Bilgewater"],"EPICKIE"],"02BW059":["Złomostrzał","Wyrzuć 3 karty.\nZadaj 7 pkt. obrażeń jednostce.","","„Jak poszli na dno, to było warto”. — Powiedzenie z Bilgewater","Zaklęcie",[],["Bilgewater"],"RZADKIE"],"02BW023":["Pokusa z Głębin","Zmniejsz koszt sojuszniczych Potworów Morskich o 1, gdziekolwiek są.\nDobierz Potwora Morskiego.","","Marynarze szepczą o mrocznych czasach, które mają nadejść. Morza się zagotują, a z fal wyłonią się niewyobrażalne monstra.","Zaklęcie",[],["Bilgewater"],"RZADKIE"],"02BW031":["Dwustrzał","Zadaj 2 pkt. obrażeń wrogowi.\nJeśli to go zabije, zadaj 4 pkt. obrażeń wrogiemu Nexusowi.","","„Zawsze najpierw strzelam”. — Miss Fortune","Zaklęcie",[],["Bilgewater"],"RZADKIE"],"02BW029":["Szaber","Wyrzuć 2 karty.\nDobierz 2 karty.","","Szczątki statków nie zostają długo na powierzchni. Każdy dobry korsarz potrafi szybko rozróżnić cenny ładunek od bezwartościowych rupieci…","Zaklęcie",[],["Bilgewater"],"ZWYKŁE"],"02BW049":["Zrabowany Skarb","Zwędź 1 kartę.\nGrabież: Zwędź jeszcze 1 kartę.","","Co moje, to moje. A co twoje… to też moje.","Zaklęcie",[],["Bilgewater"],"ZWYKŁE"],"02BW001":["Ostrzegałem","Nałóż na wroga Podatność w tej rundzie. Jeśli zginie w tej rundzie, dobierz 1 kartę.","","„Uszy do góry — i do boju, chłopcze! Jak kapitan zobaczy, że się ślamazarzysz, to przeciągnie cię pod kilem, a potem rzuci na pożarcie mewom. No, a teraz szoruj!” — Majtek Drogi przez Mękę","Zaklęcie",[],["Bilgewater"],"ZWYKŁE"],"02BW063":["Zręczna Ręka","Grabież: Dobierz losową niebędącą bohaterem kartę z ręki przeciwnika.","","„W kartach nie chodzi o szczęście. Chodzi o ludzi. Potrafisz sprawić, żeby przeciwnik podważał każdą swoją decyzję? To jest moment, w którym zgarniasz wszystko”. — Twisted Fate","Zaklęcie",[],["Bilgewater"],"RZADKIE"],"02BW045":["Deszcz Kul","Zadaj 1 pkt. obrażeń trzem losowym wrogom lub wrogiemu Nexusowi.","","„Ognia!” — Miss Fortune","Zaklęcie",[],["Bilgewater"],"ZWYKŁE"],"02BW020":["Strzał Ostrzegawczy","Zadaj 1 pkt. obrażeń wrogiemu Nexusowi.","","„Chłopaku, masz strzelać razem z nami! Na tym polega salwa!” — Bosman","Zaklęcie",[],["Bilgewater"],"ZWYKŁE"],"02BW044":["Za Burtę","Wyrzuć 4 karty.","","„Jeśli coś nie przedstawia żadnej wartości, ląduje za burtą. To samo dotyczy każdego z was. A teraz wracać do roboty!” — Bosman","Zaklęcie",[],["Bilgewater"],"RZADKIE"],"02BW062":["Nawigatorka z Wysp","Gdy mnie przywołasz, przywołaj losowego stronnika o koszcie 1 i przyznaj mu Zwiad.","","„Niech jaśnieje mocno światło Matki Węży,\nNiechaj roztacza się wśród chmur i ponad morzami.\nNieboskłon spogląda dobrodusznie szarymi oczyma,\nOdbijając jej spojrzenie.\nUśmiecha się ze spokojem...”\n — Modlitwa do Nagakabourossy","Jednostka",[],["Bilgewater"],"RZADKIE"],"02FR009":["Wilczy Jeździec","Grabież: Otrzymujesz pusty kryształ many.","","Młodzi jeźdźcy Zimowego Szponu dostają pod opiekę wilcze szczenię, gdy tylko są w stanie trzymać broń. Od najmłodszych lat ich życie wypełnia walka. Wilk uczy się okaleczać i rozszarpywać ofiarę, a młodzieniec poznaje metody grabieży i rabunku.","Jednostka",[],["Freljord"],"ZWYKŁE"],"02FR004":["W Okowach Mrozu","Daj wrogowi Odmrożenie i Podatność w tej rundzie.","","„Ciepłokrwiści nie przeżyliby we Freljordzie nawet dnia!” — Sejuani","Zaklęcie",["ŻYWIOŁ"],["Freljord"],"RZADKIE"],"02FR002":["Sejuani","Zagraj: Nałóż na wroga Odmrożenie i Podatność w tej rundzie.","Udało ci się zadać obrażenia wrogiemu Nexusowi w 5+ różnych rundach.","Chociaż jej korbacz z Prawdziwego Lodu budzi grozę, prawdziwą bronią jest sama Sejuani. Ochrzczona w mroźnych wiatrach Freljordu i sprawdzona w jego lodowatym klimacie.","Jednostka",[],["Freljord"],"Bohater"],"02FR001":["Dziewica Płomieni","Początek rundy: Zadaj 1 pkt. obrażeń WSZYSTKIEMU.","","„W znoju sieją swoje pola,\nCiężka praca to ich dola,\nPodpalimy każdy plon,\nBo tak chce Zimowy Szpon!” — Rymowanka dzieci Zimowego Szponu","Jednostka",[],["Freljord"],"RZADKIE"],"02FR005":["Duchowy Wędrowca Niedźwiedzi","Grabież: Przemieniam się w kartę Burzowy Pazur Niedźwiedzi.","","Niedźwiedź zaczyna jako człowiek, jednak szybko porzuca okowy śmiertelnego życia na rzecz dzikiej, nieposkromionej mocy, którą zapewnia im wielki duch Volibeara.","Jednostka",[],["Freljord"],"ZWYKŁE"],"02FR010":["Wspólne Łupy","Przyznaj trzem pierwszym sojusznikom z wierzchu talii +1|+1.\nGrabież: Dobierz 1 z nich.","","„Każdemu po równo”. — Okrutna Najeźdźczyni","Zaklęcie",[],["Freljord"],"RZADKIE"],"02FR008":["Łupieżczyni Kła","Gdy mnie przywołasz, dobierz kartę Sejuani.\nGrabież: Podwój Siłę i Zdrowie sojuszników w swojej talii.","","„Gdy wiosna przynosi dość ciepła, byśmy mogli obsiać pola, przynosi także łodzie... a ziarna, które gwarantowało dobrobyt, zaczyna brakować”. — Avarosański Strażnik Płomienia","Jednostka",[],["Freljord"],"EPICKIE"],"02FR007":["Gniew Północy","Daj sojusznikowi +3|+4 w tej rundzie.","","„Stań się jednością z bestią!” — Sejuani","Zaklęcie",[],["Freljord"],"ZWYKŁE"],"02FR006":["Okrutna Najeźdźczyni","","","Zimowy Szpon to niezrównana siła we Freljordzie, a wszyscy mieszkańcy krainy dobrze znają jej bezwzględnych najeźdźców. Gdy rządza krwi przejmuje nad nimi kontrolę, można już się tylko modlić o szybką śmierć.","Jednostka",[],["Freljord"],"ZWYKŁE"],"02FR003":["Aurora Porealis","Stwórz w ręce 2 losowe Poro i 2 karty Poro-Chrupki.","","„Gdy wypowiesz swe życzenie\nI wnet spojrzysz w niebios stronę,\nUjrzyj stworzenia futrzaste,\nMałych Poro całą sforę”. – Ingvar Młodsza","Zaklęcie",[],["Freljord"],"EPICKIE"],"02NX001":["Lewiatan","Gdy mnie przywołasz, dobierz kartę Swain.\nPoczątek rundy: Zadaj 1 pkt. obrażeń wrogiemu Nexusowi dwukrotnie.","","Na jego widok miejscowa ludność Ionii uznała, że to musi być potwór. Niewiele się mylili. Był to stalowy okręt noxiańskiej floty, jej największa zdobycz technologiczna.","Jednostka",[],["Noxus"],"EPICKIE"],"02NX007":["Swain","Uderzenie w Nexus: Zadaj 3 pkt. obrażeń wrogiemu Nexusowi.","Udało ci się zadać 14+ pkt. obrażeń poza walką.","„Moc niezrozumiała dla zwykłych śmiertelników pozwoliła mi ujrzeć więcej. Spoglądam przez ciemność, której inni się lękają”.","Jednostka",[],["Noxus"],"Bohater"],"02NX006":["Niszczyciel Miast","Początek rundy: Zadaj 1 pkt. obrażeń wrogiemu Nexusowi.","","Głos starca był zaskakująco spokojny. „Jakiż jest cel zbierania kamieni i budowania z nich wysokich murów, jeśli Noxianie zawsze są w stanie je zniszczyć?”","Jednostka",[],["Noxus"],"RZADKIE"],"02NX002":["Aurok Błyszczący Róg ","Atak: Ogłusz wszystkich zranionych wrogów.","","„Przez całe pokolenia byliśmy zniewoleni. Dopiero gdy Noxus odebrał nam nasze ziemie zrozumieliśmy, czym może być wolność. Dlatego walczymy za imperium”.","Jednostka",[],["Noxus"],"EPICKIE"],"02NX009":["Krwiożercze Stado","Zadaj 4 pkt. obrażeń zranionej lub Ogłuszonej jednostce.","","Wsłuchaj się. Słyszysz? To grzmot setek par łopoczących skrzydeł.","Zaklęcie",[],["Noxus"],"RZADKIE"],"02NX004":["Imperialna Niszczycielka","Zagraj: Zadaj 1 pkt. obrażeń sojusznikowi, aby zadać 2 pkt. obrażeń wrogiemu Nexusowi.","","„Szybko i po cichu... I nagle wybuch”.","Jednostka",[],["Noxus"],"ZWYKŁE"],"02NX003":["Noxiański Zapał","Zadaj 3 pkt. obrażeń sojusznikowi, aby zadać 3 pkt. obrażeń dowolnemu celowi.","","„Po trupach do celu”. — Jericho Swain","Zaklęcie",[],["Noxus"],"ZWYKŁE"],"02NX010":["Opancerzony Jeździec Kła","Wrogowie o Sile 4 lub mniejszej nie mogą zadać mi obrażeń.","","„Bestii bojowej nie da się tak po prostu zatrzymać. Najlepiej zejść jej z drogi”. — Jeździec na Bazyliszku","Jednostka",[],["Noxus"],"RZADKIE"],"02NX008":["Ręka Śmierci","Zadaj 2 pkt. obrażeń wrogowi oraz 1 pkt. obrażeń wrogiemu Nexusowi.","","„Spróbuj godnie umrzeć”. — Swain","Zaklęcie",[],["Noxus"],"ZWYKŁE"],"02NX005":["Żelazna Balista","","","„Oblężenie to łatwizna, jeśli masz odpowiednie narzędzia. Niszczycielem ich wywabisz, a balistą wykończysz”. — Inżynier oblężeń","Jednostka",[],["Noxus"],"ZWYKŁE"],"02DE003":["Lojalny Borsumiś","","","To prawda, co mówią — zwierzak upodabnia się do właściciela.","Jednostka",[],["Demacia"],"ZWYKŁE"],"02DE008":["Wielkorogi Towarzysz","","","Rekrut zwiadowców spędza całe miesiące w lesie ze swymi kompanami, aby nauczyć się przewidywać każdy ruch swego jelenia. Musi być cierpliwy, bowiem gdy ich dusze się połączą, nic ich już nie rozdzieli.","Jednostka",[],["Demacia"],"ZWYKŁE"],"02DE004":["Strażnik Zielonego Korzenia","","","„Moją powinnością jest chronić ten las i każdego z jego mieszkańców”.","Jednostka",["ELITARNY"],["Demacia"],"ZWYKŁE"],"02DE006":["Quinn","Gdy mnie przywołasz, przywołaj kartę Valor.","Widziałam, jak atakujesz 4 razy.","„Nasza Quinn zawsze była nieustraszoną zwiadowczynią rycerstwa. Z Valorem przeczesującym przestworza stanowią niepowstrzymany duet”. — Genevieve Wiązowe Serce, zwiadowczyni rycerstwa","Jednostka",[],["Demacia"],"Bohater"],"02DE009":["Łowczy Weteran","Ostatnie Tchnienie: Przywołaj kartę Lojalny Borsumiś.","","Betrand zaczynał jako Harcerz Bandle. Zdobył wszystkie odznaki z wyjątkiem „Pogodnej Duszy”.","Jednostka",["YORDLE"],["Demacia"],"RZADKIE"],"02DE005":["Nieugięta Wola","Przyznaj sojusznikowi „Nie mogę otrzymać obrażeń ani zginąć”.","","Zwiadowczyni zignorowała ból w zranionej nodze i stanęła z mieczem w dłoni raz jeszcze. Nie tylko hart ducha dodawał jej sił, ale także siła samej Demacii.","Zaklęcie",[],["Demacia"],"EPICKIE"],"02DE002":["Oślepiający Nalot","Przywołaj Valora.","","„Zostaw moje włosy! TYLKO NIE WŁOSY!” — Maruder Legionu","Zaklęcie",[],["Demacia"],"RZADKIE"],"02DE010":["Genevieve Wiązowe Serce","Gdy mnie przywołasz, daj innym sojusznikom +1|+1 w tej rundzie.","","Widok demaciańskich zwiadowców w boju potrafi zainspirować. Walczą jak jeden organizm — połączenie zwierzęcia i człowieka. Ramię w ramię są w stanie dokonać niemożliwego.","Jednostka",[],["Demacia"],"EPICKIE"],"02DE007":["Determinacja Strażniczki","Daj sojusznikom Wytrzymałość w tej rundzie.","","„Gdy pojawi się wróg, nie pozwólcie, by strach zajrzał w wasze serca. Strzeże nas sam las”. — Strażnik Zielonego Korzenia","Zaklęcie",[],["Demacia"],"RZADKIE"],"02DE001":["Wspólny Atak","Wybierz wroga. 2 sojuszników Uderza w niego jeden po drugim.","","„Ze mną, razem!” — Strażnik Zielonego Korzenia","Zaklęcie",[],["Demacia"],"ZWYKŁE"],"02SI005":["Wyssanie Magii","Wyrzuć 3 karty.\nUlecz sojuszników o 3 pkt.","","„Wyspy zostaną oczyszczone”. — Maokai","Zaklęcie",[],["Wyspy Cienia"],"RZADKIE"],"02SI010":["Wędrownik Martwego Zakwitu","Gdy mnie przywołasz, Wyrzuć 3 karty.","","„Wielki drzewiec pokazał więcej... stworzeń. Istota... roztaczać wokół siebie życie... niesamowite, jak... aż tutaj. To naprawdę Błogosławione Wyspy!” — Odzyskany dziennik","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"02SI008":["Maokai","Gdy w danej rundzie po raz pierwszy przywołasz innego sojusznika, Wyrzuć 2 karty i przywołaj kartę Sadzonka.","Twoje jednostki zginęły lub twoje karty zostały Wyrzucone 25+ razy.","Te przeklęte ziemie nie złamały ducha Maokaia. Upór drzewca był zbyt wielki, a jego gniew nie miał końca. Nic nie mogło go powstrzymać.","Jednostka",[],["Wyspy Cienia"],"Bohater"],"02SI007":["Ciernista Ropucha","Ostatnie Tchnienie: Wyrzuć 2 karty i ulecz swój Nexus o 2 pkt.","","„...niesamowity gatunek... znalazłem takie w dzieciństwie... nie postarzał ani o dzień! Ciekawe... w kolejnym mieście. Kto wie, może będą żyć wiecznie!” — Odzyskany dziennik","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"02SI003":["Postrach Fal","Sojusznicze Potwory Morskie otrzymują Postrach.\nAtak: Daj wrogom -2|-0 w tej rundzie.","","Za późno zorientowali się, że grozi im niebezpieczeństwo. Ogromna bestia otworzyła szczęki i ruszyła na nich. Myśliwi mogli tylko czekać na śmierć, gdy szczęki powoli zacisnęły się na ich statku.","Jednostka",["POTWÓR MORSKI"],["Wyspy Cienia"],"EPICKIE"],"02SI001":["Kolekcjoner z Nigdygaju","Gdy zginie inny sojusznik, Zaczerpnij 1 pkt. Zdrowia z wrogiego Nexusa.","","„Ostatnio natknąłem się na Nivena... nowy przewoźnik! Zabrał nas... do... Śpiewać to on umie! Zanim... muszę zaprosić go na obiad”. — Odzyskany dziennik","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"02SI002":["Przerośnięty Pnączak","Gdy zagrasz stronnika, zabij go, aby przywołać kartę Przerośnięty Pnączak.","","„Dzisiaj kolejny niezwykły... pojawił się nieopodal... dzieci się boją. Ale... niegroźny. Węszył tylko... całkiem ufne stworzenie. Muszę przynieść mu więcej jagód!”\n– Odzyskany dziennik","Jednostka",[],["Wyspy Cienia"],"EPICKIE"],"02SI004":["Skażony Opiekun","Zagraj: Zabij sojusznika, aby przywołać 2 Sadzonki.","","„Każde serce jest ogrodem, w którym mogą wyrosnąć korzenie!”","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"02SI006":["Drzewna Bestia","Gdy po raz pierwszy ginie sojusznik, przyznaj mi +2|+2.","","Stworzenia Wysp Cienia dawno porzuciły ckliwość i sentymenty. Najważniejsze to znaleźć pożywienie.","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"02SI009":["Rzut Sadzonką","Przywołaj kartę Sadzonka na początku następnej tury.","","„Łiiiiii!” — Sadzonka","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"02IO008":["Fala Dźwięku","Daj sojusznikowi Wyzwanie w tej rundzie.\nStwórz Ulotne Uderzenie Rezonansu w ręce.","","„Poznaj siebie...” — Lee Sin","Zaklęcie",[],["Ionia"],"ZWYKŁE"],"02IO002":["Łuski Smoka","Gdy mnie przywołasz, stwórz w ręce kartę Smocza Ochrona.","","„Uczeń musi wykazywać się współczuciem. Smok darzył miłością Pierwotną Krainę i zapewnił jej ciepło życia”. — Nauki Smoka","Jednostka",[],["Ionia"],"ZWYKŁE"],"02IO006":["Lee Sin","Gdy zagrasz zaklęcie, daj mi Wyzwanie w tej rundzie.\nJeśli zagrasz kolejne, daj mi Barierę w tej rundzie.","Udało ci się zagrać 8+ zaklęć.","„Smok sprzyja tym, którzy są godni. Potrzebującym daje wolę do życia. Chorym ukojenie. Zagubionym światło. A niepewnym cel...”","Jednostka",[],["Ionia"],"Bohater"],"02IO004":["Rogi Smoka","","","„Uczeń nigdy nie może się poddawać. Smok wydobył lądy spod morskich fal i dał nam dom, o który warto walczyć”. — Nauki Smoka","Jednostka",[],["Ionia"],"ZWYKŁE"],"02IO003":["Oko Smoka","Początek rundy: Przypływ: Przywołaj kartę Smoczątko.","","„Uczeń musi mieć jasność umysłu. Smok roztacza bowiem promienie słońca na nieboskłonie i odkrywa przed nami prawdy o świecie”.\n— Nauki Smoka","Jednostka",[],["Ionia"],"EPICKIE"],"02IO001":["Szpony Smoka","Gdy jestem w ręce, przywołaj mnie po zagraniu 2 zaklęć w rundzie.","","„Uczeń musi być zawsze skupiony na swych naukach. Gdy Smok zaryczał po raz pierwszy, obdarzył młode dusze darem magii”. — Nauki Smoka","Jednostka",[],["Ionia"],"ZWYKŁE"],"02IO005":["Ogłuszająca Dłoń","Ogłusz wroga, aby przywołać Ogon Smoka.","","„Nie widzieliście mojego odejścia i nie ujrzycie też powrotu”. — Ogon Smoka","Zaklęcie",[],["Ionia"],"RZADKIE"],"02IO010":["Odwrót","Wycofaj sojusznika, by stworzyć Ulotne Wróć w ręce.","","Pierwsi Noxianie, którzy postawili stopę na plażach Ionii, natknęli się na słabego i nieprzygotowanego wroga. Wielu poległo, jednak garstka znalazła drogę ucieczki...","Zaklęcie",[],["Ionia"],"RZADKIE"],"02IO007":["Smoczy Gniew","Sojusznik kopie wroga w jego Nexus, najpierw Uderzając wroga, a następnie wrogi Nexus.\nJeśli wróg przetrwa, Wycofaj go.","","„Muszę uwolnić smoka, inaczej pochłonie mnie od środka”. — Lee Sin","Zaklęcie",[],["Ionia"],"EPICKIE"],"02IO009":["Głęboka Medytacja","Przypływ: Kosztuję o 2 mniej.\nDobierz 2 inne zaklęcia.","","Medytacja to podróż bez celu. Ścieżka, którą można podążać tylko wtedy, gdy straci się jej koniec z oczu.","Zaklęcie",[],["Ionia"],"RZADKIE"],"03NX019":["Polowanie na Słabych","Twój przeciwnik odrzuca Najsłabszego stronnika z ręki.","","„W tym świecie nie ma miejsca dla słabych. Każdy dzień jest dla nich nową udręką, kolejnym dociśnięciem imadła. Nie interesuje mnie śmierć, tylko miłosierdzie”. – Arrel Tropicielka","Zaklęcie",[],["Noxus"],"RZADKIE"],"03NX022":["Dzikie Pazury","Sojusznik Uderza wroga. Jeżeli sojusznik posiada Zmiażdżenie, zadaj nadwyżkę obrażeń wrogiemu Nexusowi.","","„Oooch, dzikus ma dziś w sobie BRUTALNĄ energię! Trzymajcie się z dala od tych pazurów, ludziska!” \n– Konferansjer z Areny","Zaklęcie",[],["Noxus"],"EPICKIE"],"03NX007":["Riven","Gdy mnie przywołasz, jeżeli posiadasz Token ataku lub gdy zyskasz Token ataku, Przekuj.","Udało ci się stworzyć kartę Ostrze Wygnańca.","„Nie będę uciekać przed swoją przeszłością. Poprzysięgłam naprawić to, co zniszczyłam…”","Jednostka",[],["Noxus"],"Bohater"],"03NX006":["Rękojeść Broni","Daj sojusznikowi +2|+0 w tej rundzie. Przekuj.","","„By poznać swego wroga, najpierw trzeba poznać jego broń. Powiem ci, jak się porusza, jak myśli i kiedy uderzy. Oręż jest odbiciem swego właściciela”. – Arrel Tropicielka","Zaklęcie",[],["Noxus"],"ZWYKŁE"],"03NX002":["Arrel Tropicielka","Koniec rundy: Jeśli w tej rundzie zagrasz wobec mnie zaklęcie, uderzę Najsłabszego wroga.","","„Ukryj się, a cię znajdziemy.\nOddychaj, a cię usłyszymy.\nUciekaj, a cię zabijemy”.","Jednostka",[],["Noxus"],"EPICKIE"],"03NX018":["Pochwycenie","Ogłusz wroga.\nJeśli masz Dariusa, Zjednocz Siły.","","„Ja się tym zajmę!” — Darius","Zaklęcie",[],["Noxus"],"RZADKIE"],"03NX009":["Gniewna Jeźdźczyni","","","„Polowanie na innego żołnierza nie ma sobie równych. By go wytropić, trzeba myśleć i czuć tak jak on. By go pojmać, trzeba obawiać się go tak, jak on obawia się ciebie. To więź, jakiej doświadczą nieliczni, lecz ja wielbię ją ponad wszystko inne”.","Jednostka",[],["Noxus"],"ZWYKŁE"],"03NX017":["Żądny Krwi Bazyliszek","Zagraj: Zadaj 1 pkt. obrażeń sojusznikowi i wrogowi 4 razy.","","Trenerzy bazyliszków odmawiają swoim bestiom żywego jedzenia w dniach poprzedzających bitwę. Kiedy w końcu zostają spuszczone, nie rozróżniają przyjaciela od wroga i są kompletnie niepokorne.","Jednostka",["GAD"],["Noxus"],"EPICKIE"],"03NX015":["Sztuka Przetrwania","W tej rundzie Zdrowie sojuszników nie może spaść poniżej 1 pkt.\nPo odrzuceniu w tej rundzie Zdrowie twojego Najsilniejszego sojusznika nie może spaść poniżej 1 pkt.","","„Smocze ogary podjęły trop. Znajdą ją i skończymy z tym. To jedyna możliwość”. – Arrel Tropicielka","Zaklęcie",[],["Noxus"],"RZADKIE"],"03NX014":["Naostrzona Determinacja","Daj sojusznikowi +3|+2 w tej rundzie.","","„Tak, zajmę się twoją bronią, zaopiekuję wierzchowcami i przygotuję cholerną strawę. Nadaję się do czegoś jeszcze?”\n – Erath, Giermek Ostrza","Zaklęcie",[],["Noxus"],"ZWYKŁE"],"03NX003":["Giermek Ostrza","Ostatnie Tchnienie: Przekuj.","","„Jak mówiły łowczynie – sto dni i sto nocy. Sto pęcherzy na tych stopach, sto robaków w moim śniadaniu. Sto ostrzy tu, sto pomst tam. I grubo ponad sto udręk z rąk tej trójki, poważnie…” ","Jednostka",[],["Noxus"],"ZWYKŁE"],"03NX001":["Tkaczka Run","Gdy mnie przywołasz, Przekuj.","","„Większość broni to prymitywne narzędzia, niewiele lepsze od rąk, które je dzierżą. Jednak broń przesiąknięta runiczną magią to coś więcej niż zwykła stal”.","Jednostka",[],["Noxus"],"ZWYKŁE"],"03NX005":["Brutalna Łowczyni","Gdy mnie przywołasz, daj mi Szybki Atak w tej rundzie.","","„Tu jesteś. WIEDZIELIŚMY, że nie odpuścisz sobie walki! A przynajmniej na to liczyliśmy”.","Jednostka",[],["Noxus"],"RZADKIE"],"03BW006":["Jack Zwycięzca","Początek rundy: Stwórz w ręce kartę Na Dnie z Rybkami.","","Lata spędzone na ringu bokserskim były dla Jacka cenną lekcją. Nauczył się, że jeśli jego przeciwnik może krwawić, może także czuć strach. Opanował moc milczącego spojrzenia i niekontrolowanej agresji.","Jednostka",[],["Bilgewater"],"EPICKIE"],"03BW010":["Egzotyczny Obiad","Sojusznik Zniewala innego sojusznika, zyskując jego statystyki.","","„Wejdź do środka, przyjacielu, a wszystko, czego pragniesz, będzie twoje. Na wieki wieków”. – Tahm Kench","Zaklęcie",[],["Bilgewater"],"ZWYKŁE"],"03BW005":["Utopione Koszty","Umieść jednostkę lub lokację w jej talii.","","„Ależ przyjacielu, spełniłem wszystkie twoje pragnienia. Nigdy nie powiedziałem, że to będzie trwać wiecznie”. – Tahm Kench","Zaklęcie",[],["Bilgewater"],"RZADKIE"],"03BW004":["Tahm Kench","Gdy mnie przywołasz lub na Początku rundy: Stwórz w ręce kartę Smakosz.","Zniewoliłem 3+ jednostki. Kiedy awansuję, Unicestwij Zniewolonych przez mnie wrogów i uwolnij moich sojuszników.","„Znam ten wyraz twarzy, przyjacielu. Widzę, co czujesz. Karty, które trzymasz, nie są tymi, na które zasługujesz. Masz chrapkę na coś lepszego, co? Może pozwolisz, żebym zaspokoił twój głód. Będziesz się rozkoszować wszystkim, czego tylko możesz zapragnąć. Potrzebuję tylko naskrobać twoje imię na papierze… a ty, przyjacielu, zaznasz niekończącej się satysfakcji”.","Jednostka",[],["Bilgewater"],"Bohater"],"03BW002":["Leniuchujący Jaszczur","Początek rundy: Zadaj mi 2 pkt. obrażeń.","","„Ach, ludzie są głupi! Daj im zimnego napitku, usadź w ciepłym fotelu, a wyjawią wszelakie tajemnice dowolnej przyjaznej twarzy. A czyja twarz może być przyjaźniejsza, niż twarz młodego Leonarda, hmm?” – Rechoczący Wróżbita","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"03BW014":["Małpie Figle","Przywołaj kartę Prochowa Małpka.\nGrabież: Przywołaj kolejną kartę na początku następnej rundy.","","„Ooo… Uważasz, że są urocze? WCALE NIE! Wszędzie włażą, są brudniejsze niż pokład pełen ludzi z chorobą morską, a co gorsza NIE ZAMYKAJĄ IM SIĘ PYSKI! ŻADNYCH MAŁP NA STATKU. KONIEC KROPKA”. — Bosman","Zaklęcie",[],["Bilgewater"],"ZWYKŁE"],"03BW007":["Pięściornica","Zagraj: Zadaj mi 3 pkt. obrażeń.","","„Jasne, Pablo może i jest teraz jak ryba bez wody… he, he… No i taaa, oberwał parę pięści prosto w łeb… Ale wiesz co, kolego? Na tej dzielni nie ma drugiego takiego zabijaki”. – Rozgarnięta Drobnica","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"03BW016":["Bombowy Statek","Zadaj jednostce 1 pkt. obrażeń.\nPrzywołaj karty Beczki Prochu w liczbie równej zadanym obrażeniom.","","„Młody Gerent podniósł alarm tuż przed pierwszym łupnięciem. Zatrzęsło całym kadłubem, fok ogarnęły płomienie, a jednak Jilldaw wytrzymała. Myślałem, że już po wszystkim, lecz wraz z Gerentem spojrzeliśmy w otwarte morze, gdzie dostrzegliśmy płynące w naszą stronę kolejne cztery łodzie, wszystkie wypełnione prochem”. – Ocalały z okrętu Jilldaw","Zaklęcie",[],["Bilgewater"],"RZADKIE"],"03BW001":["Doki Rzezi","Początek rundy: Wyrzuć 1. Jeżeli jesteś na Głębokości, zniszcz mnie i przywołaj losowego Potwora Morskiego.","","Każdego dnia okoliczni mieszkańcy przechadzają się przez Doki Rzezi, aby obejrzeć potworności, które łowcy z Bilgewater wydobyli z głębin. Bestie są zazwyczaj martwe. Zazwyczaj.","Lokacja",[],["Bilgewater"],"EPICKIE"],"03BW015":["Zgrzybiały Dziad","Zagraj: Zadaj mi 2 pkt. obrażeń.","","„ZADZWONISZ TYM CHOLERNYM DZWONKIEM? JUŻ JA POKAŻĘ TEMU SZTYWNEMU PIERDOWI, SKĄD SĄ MOJE TYTUŁY, A JAK! »PABLO OSIEM PIĘŚCI«, »KRWAWY KRAKEN«, »MACKI GROZY«! TO TWOJE TYCI ŻĄDEŁKO BĘDZIE PŁAKAĆ ZA MAMUNIĄ, JAK Z TOBĄ SKOŃCZĘ!” – Pięściornica","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"03BW003":["Rozgarnięta Drobnica","Zagraj: Zadaj 1 pkt. obrażeń wszystkim innym sojusznikom i przyznaj mi +1|+0 za każdego z nich.","","Zdobywanie potęgi często jest dość brutalne… ale zwykle nie jest to aż tak pioruńsko niechlujne.","Jednostka",[],["Bilgewater"],"RZADKIE"],"03BW017":["Wijąca Rozdymka","Kosztuję o 1 mniej za każde zaklęcie zagrane przez ciebie w tej grze.\nGdy mnie przywołasz, stwórz w ręce losowe zaklęcie o koszcie 1 z twoich regionów.","","„Stój płosto, nowicjuszu! Masz dokonać infiłtłacji na tyłach włoga, podłoszyć jak najwięcej bąbełków i pszekzać nam szysko, co zobacysz! SZYYYYSKOOO! ZŁOZUMIANO?!” \n – Admiłał Shelly, Skoruporażacz","Jednostka",[],["Bilgewater"],"EPICKIE"],"03BW008":["Rechoczący Wróżbita","Zagraj: Zadaj mi i sojusznikowi 1 pkt. obrażeń, żeby dobrać 1 kartę.","","„Stara Babs miała trochę nieszczęśliwych wypadków. Za czasów świetności zdarzyło się jej zabić kilku okolicznych, ale to raczej pomaga jej podtrzymywać autentyczność”. – Leniuchujący Jaszczur","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"03BW020":["Prochowe Pandemonium","Przywołaj kartę Prochowa Małpka za każdą udaną aktywację Grabieży w tej grze.","","„Och, te okopcone stworki nie są takie złe. Mam dla ciebie radę – uwielbiają fajerwerki. Niszczysz więc zapasy prochu wroga, no a małpki… one po prostu robią swoje”. \n– Miss Fortune","Zaklęcie",[],["Bilgewater"],"EPICKIE"],"03BW009":["Szantaż","Zadaj 2 pkt. obrażeń sojusznikowi, żeby przyznać 2 wrogom Podatność.","","„Powiesz, skąd masz te »dodatkowe beczki«, Slim? Co? Jeśli nie, zawsze możemy się zabawić w przeciąganie liny. Twój język na rękę Jimbo. A, słuchaj, mordo… na ciebie nie ma co stawiać”. – Rozgarnięta Drobnica","Zaklęcie",[],["Bilgewater"],"RZADKIE"],"03DE010":["Wielki Plac","Gdy przywołasz sojusznika, daj mu +1|+1 i Wyzwanie w tej rundzie.","","Tianna spojrzała na zgromadzonych, oceniając zebrane tutaj zastępy. Jedynym dźwiękiem unoszącym się na placu był trzask jej powiewającej na wietrze chorągwi. Krótko przytaknęła z zadowoleniem, po czym z okrzykiem uniosła chorągiew. „Kto z was jest gotów walczyć za Demacię?” Okrzyk zgromadzonego tłumu zatrząsł górami w posadach.","Lokacja",[],["Demacia"],"EPICKIE"],"03FR009":["Howling Abyss","Początek rundy: Stwórz w ręce losowego bohatera 2. poziomu. Nie może on znajdować się w twojej ręce, talii ani wśród zagranych przez ciebie kart.","","Bohaterowie stają na tym moście, wzywani tutaj przez nieznane. Przezwyciężają okrutny mróz i sypiące się z niego kamienie, aby się przekonać, co ich czeka po drugiej stronie – zwycięstwo czy śmierć.","Lokacja",[],["Freljord"],"EPICKIE"],"03MT005":["Rozbieżne Ścieżki","Dobierz lokację lub zniszcz lokację.","","Targon to kapryśne miejsce. Tutaj niezłomni uginają się, a zniszczeni znów są łączeni w całość.","Zaklęcie",[],["Targon"],"ZWYKŁE"],"03SI009":["Krypty Helii","Początek rundy: Jeśli to możliwe, zabij swojego najdroższego sojusznika, aby przywołać ze swojej talii sojusznika o koszcie większym o 1.","","Cóż innego wabiłoby dusze w to przeklęte miejsce lepiej, niż obietnica wiecznego życia i nieskończonych bogactw?","Lokacja",[],["Wyspy Cienia"],"EPICKIE"],"03IO006":["Klasztor w Hiranie","Początek rundy: Stwórz w ręce kartę Sanktuarium.","","W ioniańskich górach kryje się wiele sanktuariów, w których schronienie znajdzie każdy, kto tylko pragnie skupić się na sobie i ukoić ducha.","Lokacja",[],["Ionia"],"EPICKIE"],"03NX013":["Spalona Ziemia","Zabij zranioną jednostkę lub zniszcz lokację.","","„Smocze ogary podjęły trop. Znajdą ją i skończymy z tym. To jedyna możliwość”. – Arrel Tropicielka","Zaklęcie",[],["Noxus"],"ZWYKŁE"],"03NX004":["Noxrajska Arena","Koniec rundy: Twój Najsilniejszy sojusznik i Najsłabszy wróg uderzają siebie nawzajem.","","„Jak się trzymacie, faaaaani waleczników? Jesteście gotowi na noc palących DRESZCZY w KRĘGU OGNIA? O nie, zdaje się, że Tyci Trik wyciągnął dziś PECHOWY los. Ma się zmierzyć z potężnym, wyrywnym GRANAKIEEEEM Wielkim! Niech ktoś woła medyków, to będzie szybka runda!” – KONFERANSJER Z ARENY","Lokacja",[],["Noxus"],"EPICKIE"],"03DE004":["Kapitan Arrika","Zagraj: Zniewol jednostkę lub lokację.","","Jako dziecko Arrika na własne oczy widziała, do jak ogromnych zniszczeń jest w stanie posunąć się Noxus, kiedy wysłannicy tego imperium pustoszyli jej dom. Gdy zaciągnęła się do wojska, poprzysięgła sobie, że nie pozwoli, by noxiańska flaga załopotała nad demaciańską ziemią, ani by jakiekolwiek dziecko zostało osierocone.","Jednostka",["ELITARNY"],["Demacia"],"RZADKIE"],"03IO005":["Z Powrotem w Domu","Wycofaj sojuszniczą jednostkę lub lokację, by Wycofać wrogą jednostkę lub lokację.","","„Trevvvvorrrrrr, wracaaaaaj…” – Dom Trevora","Zaklęcie",[],["Ionia"],"ZWYKŁE"],"03MT052":["Gwiezdne Źródło","Koniec rundy: Ulecz rannych sojuszników o 1 pkt. Następnie, jeśli zobaczę, że uleczysz sojuszników z 22+ pkt. obrażeń, wygraj grę.","","„Aż do świętych spadów płynących,\nW głąb wód i źródeł uzdrowienia,\nLśniące światło, blask wód skrzących,\nUsłysz, jak rzeka pieść swą śpiewa,\nWysoko na górze kryształowej”.\n – Poezja Ottranów","Lokacja",[],["Targon"],"EPICKIE"],"03MT064":["Szczyt Targonu","Początek rundy: Zmniejsz koszt losowej karty w ręce KAŻDEGO gracza do 0 w tej rundzie.","","Kryształowy strażnik Targonu pilnuje bramy do astralnego wymiaru. Przed jego obliczem wszystko niknie – nadzieja, zwątpienie, strach. Jego próby pozbawiają wszelkich doczesnych zmartwień, obnażając prawdziwą istotę duszy wspinacza. To na tej podstawie jest on oceniany, wszak strażnik jest wielkim sędzią. ","Lokacja",[],["Targon"],"EPICKIE"],"03SI008":["Obrót w pył","Zabij sojusznika, aby zabić jednostkę lub zniszczyć lokację.","","Nic nie trwa długo na tych nawiedzonych wyspach. Wszystko dobiegnie końca.","Zaklęcie",[],["Wyspy Cienia"],"RZADKIE"],"03PZ001":["Uniwersytet Piltover","Początek rundy: Odrzuć wszystkie karty z ręki. Stwórz 3 losowe karty w ręce i przyznaj im Ulotność.","","Wynalazki profesora Cecila B. Heimerdingera uczyniły go sławnym, ale to jego animowane wykłady i nagminnie nieprzewidywalne prezentacje na zajęciach najlepiej wryły się w pamięć najbystrzejszych umysłów z Piltover.","Lokacja",[],["Piltover i Zaun"],"EPICKIE"],"03FR003":["To, co patrzy","Zagraj: Unicestwij WSZYSTKIE lokacje lub zadaj 3 pkt. obrażeń WSZYSTKIM pozostałym jednostkom.","","„Nie było czasu na zabranie dobytku czy ostrzeżenie innych. Mogliśmy jedynie uciekać do lasu i patrzeć, jak nasze domy ulegają zniszczeniu”. – Avarosański Strażnik Płomienia","Jednostka",[],["Freljord"],"RZADKIE"],"03MT026":["Rahvun, Włócznia Brzasku","Brzask: Stwórz losową kartę Brzasku w ręce.\nDla nas zawsze jest dzień.","","„Zachowajcie wiarę, Ra-Horakowie, a nasze światło nigdy nie zgaśnie!”","Jednostka",[],["Targon"],"RZADKIE"],"03MT067":["Kryształowy Koziorożec","Zagraj: Przyznaj sojusznikowi Zmiażdżenie.","","Ci, którzy pragną zdobyć Targon, słusznie postąpiliby, gdyby obłaskawili miejscową faunę. Żadna istota nie jest lepiej obeznana z niebezpiecznymi wyzwaniami rzucanymi przez Targon, nikt nie potrafi poruszać się zwinniej po tych lodowych zboczach.","Jednostka",[],["Targon"],"ZWYKŁE"],"03MT084":["Tworzenie Gwiazd","Wezwij Astralną kartę o koszcie 7 lub wyższym, a następnie ulecz sojusznika lub swój Nexus o 5 pkt.","","„Wejrzyj w gwiazdy. Jeśli ci się poszczęści, odwzajemnię spojrzenie”. — Aurelion Sol","Zaklęcie",[],["Targon"],"ZWYKŁE"],"03MT221":["Kły","Zagraj: Wezwij Astralną kartę o koszcie 3 lub mniejszym.","","„Księżycowa Matko, wskaż mi drogę,\nNiechaj niebo się rozstąpi,\nWskaż mi wyższą prawdę”.\n– Modlitwa Lunari","Jednostka",[],["Targon"],"EPICKIE"],"03MT093":["Gwiezdna Piłeczka","Zadaj 5 pkt. obrażeń wrogowi, który zaatakował w tej rundzie lub jest Ogłuszony.","","„Ka-bum!” – Zoe","Zaklęcie",[],["Targon"],"ZWYKŁE"],"03MT073":["Zwiastunka Zmierzchu Lunari","Gdy mnie przywołasz, stwórz w ręce kartę Pył Kwiatów Zmierzchu.","","„Kwiaty zmierzchu kwitną nocą, i to tylko podczas pełni księżyca. Z pyłu tego dumnego symbolu Lunari korzystamy od wieków, ponieważ tylko my wiemy, jak odpowiednio je zbierać”.","Jednostka",[],["Targon"],"ZWYKŁE"],"03MT002":["Załamanie Firmamentu","Kosztuję o 2 mniej za każdego posiadanego przez ciebie sojuszniczego Smoka lub Astralnego. Zadaj 15 pkt. obrażeń wszystkim wrogom.","","„Gdy nadejdzie pora, Runeterra posłuży mi za przykład dla innych. Być może będę nosił przy sobie jej tlące się truchło przez całą wieczność, niczym zabawkę. Martwą, bezwartościową zabawkę. Sam nie wiem. Nie zastanawiałem się nad tym”. — Aurelion Sol","Zaklęcie",[],["Targon"],"EPICKIE"],"03MT217":["Aphelios","Zmrok: Wybierz księżycową broń, którą chcesz stworzyć w ręce.\nW każdej rundzie po pierwszym zagraniu 2 innych kart stwórz w ręce księżycową broń danej Fazy, jeżeli jeszcze jej nie posiadasz.","Zagrano 4+ księżycowych broni.","„Przy każdym konflikcie pokazujemy Solari, że jesteśmy godni szacunku. Nauczyliśmy ich, że światło księżyca jest równe światłu ich słońca. Nauczyliśmy ich, żeby nie umniejszać tego, co jest im nieznane. A co do lekcji, których jeszcze musimy im udzielić…” – Kaznodzieja Lunari","Jednostka",[],["Targon"],"Bohater"],"03MT044":["Strażnik Słońca","Brzask lub gdy aktywujesz inny Brzask: Przyznaj mi +1|+1.","","„Lśniący opiekunie, twój gniew płonie niczym słońce w samo południe. Przybądź, by ukarać tych, którzy naruszają spokój tego świętego miejsca”. — Inskrypcja Strażnika Słońca","Jednostka",[],["Targon"],"EPICKIE"],"03MT056":["Diana","Zmrok lub gdy aktywujesz inną kartę Zmroku: Daj mi Wyzwanie w tej rundzie.","Udało ci się aktywować Zmrok 4+ razy.","Stała pośród nich, szykując się do walki. Promieniowała światłem, przyozdobiona srebrem i błękitem. Jej oczy lśniły niczym gwiazdy. Gdy księżyc wzeszedł i swym blaskiem otulił jej postać, każdy obecny Lunari zamknął oczy — wszyscy pełni wdzięczności pogrążyli się w cichej modlitwie o jej bezpieczeństwo.","Jednostka",[],["Targon"],"Bohater"],"03MT020":["Majestatyczny Gwiazdoróg","Zagraj: Ulecz sojusznika i swój Nexus o 3 pkt.","","„Widzisz tę gwiazdę wędrującą po nocnym niebie? To dorosły gwiazdoróg. Podczas gdy młode obłaskawiają nas swą uzdrawiającą magią do momentu, w którym można je zwrócić niebu, dorosłe osobniki same korzystają z tej mocy. Ujrzenie i rozpoznanie jednego z nich uznawane jest za szczęście. Prawdziwym szczęściem jednak jest opieka nad gwiazdorogiem”. — Lidari, Strażniczka Gwiazd","Jednostka",[],["Targon"],"ZWYKŁE"],"03MT091":["Odjazdowa Mapa Nieba","Wezwij Astralną kartę o koszcie 3 lub mniejszym.","","„A te trzy WYJĄTKOWO jasne gwiazdy nazywam… Astralną Skakanką! A może odwróconym uśmiechem?” – Zoe","Zaklęcie",[],["Targon"],"RZADKIE"],"03MT047":["Cygnus, Tropiciel Księżyca","Zmrok: Daj sojusznikowi Nieuchwytność w tej rundzie.","","Lunari czekali na zmrok i bezpieczeństwo, jakie zapewniał. Droga przed nimi zdawała się opuszczona, jednak Cygnus wiedział, że niedaleko znajduje się obóz Solari. Na jego gest pozostali cicho ustawili się w szeregu za nim.","Jednostka",[],["Targon"],"EPICKIE"],"03MT094":["Cienista Lunari","Zmrok: Przyznaj mi Nieuchwytność.","","„Zwróćmy się ku niebiosom, ku słońcu, ku światłu naszej pa… Zaraz... Co...? Co to takiego...?” — Kapłan Solari","Jednostka",[],["Targon"],"ZWYKŁE"],"03MT036":["Błogosławieństwo Targonu","Przyznaj sojusznikowi +3|+3.","","„Podarunek od Targonu”. — Taric","Zaklęcie",[],["Targon"],"RZADKIE"],"03MT092":["Górska Koza","Uderzenie: Stwórz w ręce kartę Klejnot.","","Kozy z Góry Targon są bardziej niebezpieczne od swych zwykłych kuzynów, ponieważ klejnoty zdobiące ich rogi zadają bolesne rany. ","Jednostka",[],["Targon"],"RZADKIE"],"03MT060":["Barczysty Obrońca","Początek rundy: Ulecz swój Nexus o 3 pkt. Zadaj mi obrażenia równe wartości leczenia.","","„Nikt nie zna dróg Targonu lepiej niż ja, dlatego często jestem w towarzystwie… co bardziej upartych gwiazdorogów. Mają szczęście, że się nimi opiekuję!” ","Jednostka",[],["Targon"],"EPICKIE"],"03MT001":["Przebiegłe Futrzaki","Zagraj: Ogłusz wrogów o Sile 2 lub mniejszej.","","Przez krystaliczną ciszę górskiego stoku rozniosły się dzwoniące dźwięki spadającego lodu, a podróżujący mogliby przysiąc, że wysoko ponad nimi słychać też było… śmiech.","Jednostka",[],["Targon"],"ZWYKŁE"],"03MT055":["Soraka","Wsparcie: Ulecz mnie i wspieranego przeze mnie sojusznika o 4 pkt.","Udało ci się uleczyć zranionych sojuszników 4+ razy.","„Uzdrawianie z samej swojej natury jest altruizmem. Nie musisz zabierać ich sił – oddają ją z własnej woli. Okaż im współczucie, a zobaczysz, jak będą lśnić”.","Jednostka",[],["Targon"],"Bohater"],"03MT048":["Obdarowywaczka","Gdy mnie przywołasz, stwórz w ręce Klejnot.","","„Mówią, że Protektor pobłogosławił te klejnoty. Miej je przy sobie, a będzie z tobą obecny duchem”.","Jednostka",[],["Targon"],"ZWYKŁE"],"03MT082":["Promienie Świtu","Daj sojusznikom +1|+1 w tej rundzie.\nAktywuj efekt Brzasku sojusznika.","","„Powstajemy wraz ze świtem! Maszerujemy ku światłu!” — Leona","Zaklęcie",[],["Targon"],"RZADKIE"],"03MT058":["Taric","Wsparcie: Daj mi i wspieranemu przeze mnie sojusznikowi Wytrzymałość w tej rundzie. Skopiuj na tego sojusznika ostatnie zaklęcie zagrane przez ciebie w tej rundzie tylko na mnie (można skopiować tylko raz).","Widziałem, jak bierzesz na cel lub wspierasz sojuszników 7+ razy.","„Szlachetna dobroć Tarica inspiruje każdego, kto go spotka, by znalazł w sobie ciepło, które ogrzeje go nawet w najzimniejsze noce”. — Górski Wróżbita","Jednostka",[],["Targon"],"Bohater"],"03MT062":["Zakręcona Iskrolożka","Zagraj: Jeśli Widzisz Astralną kartę, przyznaj sojusznikowi +1|+1 i Tarczę Magii.","","„…i wtedy iskierkowy motylek jawi się niczym gwiezdny pył, który opada na ziemię, by unieść się ponownie ku górze, są wspaniałe i widziałam jednego wczorajszej nocy, był taki piękny, a mnie tak burczy w brzuchu, a motylek poleciał ku GWIAZDOM, po czym…”","Jednostka",[],["Targon"],"RZADKIE"],"03MT040":["Iskierkowy Motylek","","","„Nadzieja to coś delikatnego, co stale wznosi się wyżej i nigdy nie powinno zostać pochwycone”. – Kapłanka Lunari","Jednostka",[],["Targon"],"ZWYKŁE"],"03MT086":["Szalona Artystka","Zagraj: Odrzuć 1 kartę, aby Wezwać Astralną kartę o koszcie 3 lub mniejszym.","","„To moja ulubiona! Nazywam ją «Metafizyczną Tożsamością Świadomej Psyche». Chyba że przechylisz głowę… Wtedy wygląda jak dwie łyżeczki”.","Jednostka",[],["Targon"],"RZADKIE"],"03MT016":["Wystraszony Stąpacz","","","„Ooo, wielki Stąpacz nie chce przejść przez malutki portal? W porządku, możemy… HA, HA, HA! Żartowałam, WŁAŹMITU!” — Zoe","Jednostka",[],["Targon"],"ZWYKŁE"],"03MT054":["Leona","Brzask: Ogłusz Najsilniejszego wroga.","Udało ci się aktywować Brzask 5+ razy.","Stała pośród nich, szykując się do walki. Promieniowała światłem, przyozdobiona szkarłatem i złotem. Jej oczy lśniły żarem. Gdy słońce wzeszło, odziewając ją w lśniącą koronę, każdy obecny Solari opuścił wzrok — nie ze wstydu, lecz z szacunku dla jaśniejącej przywódczyni.","Jednostka",[],["Targon"],"Bohater"],"03MT220":["Rozstaje Dróg","Zmrok: Ogłusz wroga. Jeżeli jest to stronnik, Ogłusz go ponownie na początku kolejnej rundy.","","„Księżycowa Matko, zapadła nasza noc,\nPozwól nam powstrzymać oprawców,\nNiechaj dotknie ich żałości moc”\n– Modlitwa Lunari","Jednostka",[],["Targon"],"RZADKIE"],"03MT021":["Nieskończony Rozszczepiacz Umysłów","Zagraj: Wybierz 2 wrogów.\nPoczątek rundy: Ogłusz ich.","","Wędrowcy, którzy skrzyżują spojrzenie z tym stworzeniem, podobno obdarzani są tak ogromną wiedzą, wspaniałą przenikliwością, że ich umysły tego nie wytrzymują.","Jednostka",["SMOK"],["Targon"],"EPICKIE"],"03MT006":["Inviolus Vox","W każdej rundzie, gdy sojusznik z Furią zabije wroga po raz pierwszy, stwórz w ręce losowego stronnika Smoka.","","„Zwróćcie wzrok ku niebu i zobaczcie to, co ja! Wpierw sygnał, wszak nocą lśnią. Następnie furię, gdyż za dnia wszystko płonie. Zobaczycie! Wszyscy zobaczymy!” — Zwiastunka Smoków","Jednostka",["SMOK"],["Targon"],"EPICKIE"],"03MT015":["Oblicze Nieskończoności","Wezwanie.","","Niebiosa unoszą się nad tobą. Czarny gobelin przeplatany migoczącymi gwiazdami. W jego obliczu jesteś drobny i słaby. Gdzie najpierw skierujesz wzrok?","Zaklęcie",[],["Targon"],"ZWYKŁE"],"03MT013":["Klątwa Księżycowej Poświaty","Ucisz 2 wrogie jednostki w tej rundzie.\nZmrok: Nie mogą one blokować w tej rundzie.","","„Nieprzywykli do blasku księżyca muszą nauczyć się widzieć w jego świetle, inaczej nic nie zobaczą”. – Diana","Zaklęcie",[],["Targon"],"ZWYKŁE"],"03MT009":["Zoe","Uderzenie w Nexus: Stwórz w ręce kartę Odjazdowa Mapa Nieba lub, jeśli już taką masz, zmniejsz jej koszt o 1.","Widziałam, jak zagrywasz 10 kart o różnych nazwach.","„Hejka! Co robicie? Czy to KARCIANKA? Też mogę zagrać? Że co? JESTEM w TWOJEJ grze? Ha! Co za dziwaczny wymiar…”","Jednostka",[],["Targon"],"Bohater"],"03MT087":["Aurelion Sol","Zagraj: Wezwij Astralną kartę o koszcie 7 lub wyższym.\nPoczątek rundy: Stwórz losową Astralną kartę w ręce.","Koniec rundy: Łączna Siła twoich sojuszników wynosi 20+.","„Nie obchodzi mnie, co o mnie napiszesz, mierna kreaturo! Tylko dopilnuj, by określały mnie takie przymioty, jak przystojny. I wspaniały. Oraz bardzo, ale to bardzo inteligentny. Wiesz, jak to się pisze?”","Jednostka",["SMOK"],["Targon"],"Bohater"],"03MT019":["Bastion","Przyznaj sojusznikowi +1|+1 i Tarczę Magii.","","„Poczuj respekt przed Górą”. — Taric","Zaklęcie",[],["Targon"],"ZWYKŁE"],"03MT214":["Lot","Uderzenie w Nexus: Dobierz 1 kartę i umieść mnie wśród pierwszych 3 kart z wierzchu swojej talii.","","„Księżycowa Matko, obdarz mnie pewnością siebie,\nNapełnij mnie wiarą Lotu,\nPokieruj mnie na mą ścieżkę”.\n– Modlitwa Lunari","Jednostka",["PTAK"],["Targon"],"RZADKIE"],"03MT071":["Tyari Wędrowiec","Wsparcie: Przyznaj wspieranemu przeze mnie sojusznikowi +0|+2.","","W trakcie wyprawy trzeba być otwartym na podróż, która z pewnością cię zmieni. W trakcie wyprawy przyjmujesz coś nowego… a jakąś część siebie zostawiasz za sobą. ","Jednostka",[],["Targon"],"ZWYKŁE"],"03MT008":["Życzenie","W pełni ulecz zranionych sojuszników.","","„Za żywych!” – Soraka","Zaklęcie",[],["Targon"],"RZADKIE"],"03MT023":["Słoneczny Rozbłysk","Zadaj jednostce 6 pkt. obrażeń.\nBrzask: Zamiast tego Ucisz ją w tej rundzie i zadaj jej 6 pkt. obrażeń.","","Niewielu przetrwa spotkanie z niezachwianym spojrzeniem słońca.","Zaklęcie",[],["Targon"],"RZADKIE"],"03MT045":["Astralna Ochrona","Ulecz sojusznika o 4 pkt. i przyznaj mu +0|+4.","","„Myślałeś, że nas pokonałeś? Ha! Dopiero się rozgrzewamy”. – Barczysty Obrońca","Zaklęcie",[],["Targon"],"ZWYKŁE"],"03MT080":["Strażnik Źródeł","Gdy mnie przywołasz, stwórz w ręce kartę Dary Źródła.","","„Przez większość czasu strzegę źródeł, ale najważniejszą odpowiedzialnością pasterza jest jego stado. Priorytety często zderzają się ze sobą”.","Jednostka",[],["Targon"],"ZWYKŁE"],"03MT042":["Złodziejka Czarów","Pokaż wrogie zaklęcie zagrane w tej grze.","","„Och, to było FANTASTYCZNE! Ale o ile lepsze by było, gdybym to ja to zrobiła? Naraziński!” – Zoe","Zaklęcie",[],["Targon"],"RZADKIE"],"03MT057":["Słoneczny Architekt Solari","Brzask: Daj mi Kradzież Życia w tej rundzie.","","Słoneczny Architekt stał w skupieniu, gdy światło wlało się do pomieszczenia. Artefakt Solari okiełznał wspaniałe promienie słońca, by stworzyć potężne zaklęcie dla jego broni.","Jednostka",[],["Targon"],"ZWYKŁE"],"03MT041":["Mentor Skał","Wsparcie: Przyznaj wspieranemu przeze mnie sojusznikowi +2|+2.\nOstatnie Tchnienie: Stwórz 3 karty Klejnoty w ręce.","","— Załapałeś wszystko, co powiedział?\n— Nic a nic. Ale wydawał się z niego miły gość.\n— Emir i Haley, Górska Ekspedycja","Jednostka",["YORDLE"],["Targon"],"EPICKIE"],"03MT027":["Ostrze Zenitu","Przyznaj sojusznikowi +1|+2. Daj mu Zmiażdżenie w tej rundzie.\nBrzask: Dobierz kartę Ostrze Zenitu.","","„Niechaj słońce napełni cię swą siłą!” — Kapłanka Solari","Zaklęcie",[],["Targon"],"ZWYKŁE"],"03MT096":["Kapłanka Solari","Brzask: Wezwij Astralną kartę o koszcie 4, 5 lub 6.","","Solari patrzą ku gwiazdom, szukając przewodnictwa, podobnie jak inni Targonianie — gwiazdą najbliższą ich wierze jest słońce.","Jednostka",[],["Targon"],"RZADKIE"],"03MT028":["Tarczowniczka Solari","Brzask: Daj mi +0|+4 w tej rundzie.","","— Głupotą było nie przyjść pod osłoną nocy — rzekła Tarczowniczka. — Złóż broń i podejdź spokojnie.\nLunari przykucnęła w ciszy, szykując raz jeszcze swe zakrzywione ostrza.\n— Niech więc tak będzie.\nSolari uniosła tarczę, by odbić promienie wschodzącego słońca. ","Jednostka",[],["Targon"],"ZWYKŁE"],"03MT089":["Strażnik Półksiężyca","Zmrok: Przyznaj mi +2|+0.","","„Stoicki opiekunie, delikatny dotyk pełni księżyca regeneruje twą siłę. Przebudź się i chroń nas przed tymi, którzy wkraczają na teren tego świętego miejsca”. — Inskrypcja Strażnika Półksiężyca","Jednostka",[],["Targon"],"RZADKIE"],"03MT051":["Wiodący Dotyk","Ulecz sojusznika lub swój Nexus o 2 pkt. Dobierz 1 kartę.","","Gwiazdorogi lśnią najjaśniej, kiedy są szczęśliwe.","Zaklęcie",[],["Targon"],"ZWYKŁE"],"03MT003":["Smoczy Uścisk","Dobierz 2 różne Smoki lub przyznaj sojuszniczym Smokom +1|+1 oraz Zmiażdżenie.","","„Ich pisk brzmi jak chrypiący kot. Jeśli go usłyszysz, jak najszybciej znajdź schronienie. Rozumiesz? Bo tam, gdzie są smocze jaja, będą i smoki”. — Targoński poszukiwacz","Zaklęcie",[],["Targon"],"RZADKIE"],"03MT098":["Słoneczne Ożywienie","Przyznaj sojusznikowi +0|+2.","","„Nasza tarcza jest naszą wiarą i determinacją, a ufność pokładamy w świetle!” — Tarczowniczka Solari","Zaklęcie",[],["Targon"],"ZWYKŁE"],"03MT215":["Podarunki z Zaświatów","Wybierz księżycową broń, którą chcesz stworzyć w ręce.","","„Wyciągnij dłoń, Apheliosie…” – Alune","Zaklęcie",[],["Targon"],"ZWYKŁE"],"03MT063":["Księżycem Śniąca","Zagraj: Wezwanie.\nZmrok: Zmniejsz koszt tej karty o 1.","","„Spójrzcie na naszych przyjaciół na nocnym niebie! Widzicie tę bardzo jasną gwiazdę? To Posłaniec zerka na nas swym okiem! A ta słaba gromada? To Szachraj kryjący się za chmurami! A tam… KULUN, CICHO! Nie sięgniesz ich stąd!”","Jednostka",[],["Targon"],"ZWYKŁE"],"03MT100":["Smok Zaćmienia","Brzask: Kolejny Smok lub Astralny, którego zagrasz, ma koszt zmniejszony o 2.\nZmrok: Stwórz w ręce losowego Smoka i Astralnego stronnika.","","Smocza łuska (Smok Zaćmienia, Draco Obscuratus)\nUwagi: Łuska ma niebywałe właściwości optyczne. Wysoce odblaskowa w bezpośrednim świetle słonecznym.\nNabazgrane: ŚWIECI TEŻ W NOCY!\n– Notatki Andena Mayne’a, Jajogłowego Badacza","Jednostka",["SMOK"],["Targon"],"RZADKIE"],"03MT076":["Górski Wróżbita","Twoje Astralne karty kosztują o 1 mniej.\nPrzymierze: Wezwanie.","","„Pod przewodnictwem gwiazd można się wiele nauczyć. Dla nas są czymś stałym, sposobem na wyznaczenie naszej drogi”.","Jednostka",[],["Targon"],"RZADKIE"],"03MT029":["Gwiezdna Pasterka","Gdy leczysz zranionego sojusznika, przyznaj mi +2|+0.","","„Odkąd tylko zobaczyłam pierwszą smugę na nocnym niebie, pokochałam gwiazdorogi. Gdybym tylko wiedziała, że spotkam ich tak wiele!”","Jednostka",[],["Targon"],"RZADKIE"],"03MT219":["Świątynia Spowita Całunem","W każdej rundzie, gdy po raz pierwszy zagrasz 2 inne karty, odzyskaj 2 pkt. many i przyznaj swojemu Najsilniejszemu sojusznikowi +1|+0.","","To tutaj, w świecie duchów, Alune łączy się ze swoim bratem, Apheliosem. To właśnie ona szepcze słowa pocieszenia do niemego zabójcy i to ona sięga przez całun, aby wręczyć mu broń odkupienia.","Lokacja",[],["Targon"],"RZADKIE"],"03MT079":["Gwiezdny Urwis","Jeśli Widzisz Astralną kartę, kosztuję o 2 mniej.","","„Dorośli to LAMUSY. Najbardziej luzackimi dzieciakami w okolicy są Zoe i jej ziomale. Sporo się od nich uczę, wiesz? Nie to co od tej głupiej promieniującej blaskiem kapłanki. ECH…”","Jednostka",[],["Targon"],"ZWYKŁE"],"03MT007":["Mały Gwiazdoróg","","","„Jak wszystkie raczkujące stworzenia, młode gwiazdorogi ruszają w swój pierwszy niezgrabny lot. Są wtedy niczym pozostałe gwiazdy na nocnym niebie, wszak spadają nieporadnie. Na szczęście jesteśmy tu, by je złapać, a gdy będą gotowe, zwracamy je”. — Lidari, Strażniczka Gwiazd","Jednostka",[],["Targon"],"ZWYKŁE"],"03MT038":["Obrońca Białego Płomienia","","","To dzieci Targonu jako pierwsze zaprzyjaźniły się z młodszymi, spokojniejszymi smokami. Być może te młode stworzenia same czuły niewinną ciekawość dzieci, oferując im ochronę, zamiast je krzywdzić. ","Jednostka",["SMOK"],["Targon"],"ZWYKŁE"],"03MT014":["Zwiastunka Smoków","Sojusznicze Smoki kosztują o 1 many mniej.","","Chmury wirowały wokół potężnych cielsk, a niebo zdało się drżeć z każdym ich niezadowolonym okrzykiem. Wiedziała, co ją czeka, a mimo to nie bała się, lecz gotowa była na spotkanie z przeznaczeniem.","Jednostka",[],["Targon"],"RZADKIE"],"03MT110":["Z drogi","Do końca gry sojusznicze wzmocnienia „w tej rundzie” (z wyjątkiem Bariery) są stałe. Dobierz 1 kartę.","","„You know I mean everything that I say\nWhen you see me coming get out of the way\nI came to slay I came to slay\nBack and I’m better and ready to stay”.\n– Kai’Sa, „THE BADDEST”","Zaklęcie",[],["Targon"],"EPICKIE"],"03MT017":["Znak Posłańca","Stwórz w swojej talii 5 kart Posłańców.","","„Czas mija, przestworza się zmieniają — Wąż odsuwa się, a jego miejsce na górze zajmuje Posłaniec. Rozpoczyna się sezon obfitości…” — Kapłanka Lunari","Zaklęcie",[],["Targon"],"RZADKIE"],"03MT025":["Odłamki Góry","Reszta twojej ręki jest pełna Klejnotów.","","„Każdy klejnot połyskuje w świetle. Zupełnie niczym życie śmiertelników, każdy ma własny wewnętrzny ogień”. — Taric","Zaklęcie",[],["Targon"],"EPICKIE"],"03MT216":["Cienie Niebios","Gdy mnie przywołasz, odzyskaj 2 pkt. many zaklęć, jeżeli Widzisz kartę Zmroku.","","„Księżycowa Matko, pozwól mi pamiętać,\nŻe choć trwam w samotności,\nTo twe dzieci tańczą nade mną\nI nigdy mnie nie opuszczą”.\n— Modlitwa Lunari","Jednostka",[],["Targon"],"ZWYKŁE"],"03MT012":["Sędzia Szczytu","Kosztuję o 1 mniej za każdego sojusznika obranego przez ciebie za cel lub Wspartego przez ciebie w tej grze.","","Sędzia to ostatni górski sprawdzian, wszak tylko strażnik potrafi wejrzeć poza uczynki wspinacza i wejść w jego duszę.","Jednostka",[],["Targon"],"EPICKIE"],"03MT085":["Cichutko","Ucisz jednostkę w tej rundzie.","","„Poznają, co to spokój”. — Soraka","Zaklęcie",[],["Targon"],"RZADKIE"],"03MT081":["Górska Ekspedycja","Wsparcie: Przyznaj wspieranemu przeze mnie sojusznikowi +2|+2. Jeśli sojusznik ma Wsparcie, przyznaj wspieranemu przez niego sojusznikowi +2|+2 i przekaż premię każdemu kolejnemu wspieranemu sojusznikowi.","","Każdy, kto rzuca wyzwanie Górze Targon, ma własną motywację. Niektórzy robią to, by wykazać się przed swymi towarzyszami. Inni z kolei chcą udowodnić coś samym sobie.","Jednostka",[],["Targon"],"EPICKIE"],"03MT030":["Astronomka","Gdy leczysz zranionego sojusznika, daj mu Nieuchwytność w tej rundzie.","","„Gwiazdy pozostają z nami tylko na pewien czas. Kiedy zrobię już dla nich wszystko, co mogę, wysyłam je z powrotem do nieba, w towarzystwie nagłego wybuchu gwiezdnego blasku… i wierzgających kopyt”.","Jednostka",[],["Targon"],"RZADKIE"],"03MT088":["Żołnierz Solari","Brzask: Daj mi +1|+1 w tej rundzie.","","Stał na straży heretyckiej więźniarki, kiedy słońce zaczęło muskać go ciepłymi promieniami. Ignorował słodkie błagania, które szybko zamieniły się w gorzką ciszę.","Jednostka",[],["Targon"],"ZWYKŁE"],"03MT033":["Dziadek Rumul","Zagraj: Przyznaj 2 sojusznikom +0|+4.","","„Nadstaw uszu, Osu. Słyszysz? Dzwonki! Dziadek wrócił!” — Illi, Gwiezdna Pasterka","Jednostka",[],["Targon"],"RZADKIE"],"03MT035":["Księżycowa Kaskada","Daj sojusznikowi +1|+1 w tej rundzie.\nZmrok: Dobierz 1 kartę.","","„Pod osłoną nocy, w bladym świetle księżyca”. — Diana","Zaklęcie",[],["Targon"],"ZWYKŁE"],"03MT075":["Kapłanka Lunari","Zmrok: Wezwanie.","","„O, gwiazdy nad nami, wędrujące niczym pielgrzymi przez nocny bezmiar — zostańcie z nami na chwilę, opowiedzcie o tym, co widziałyście”. — Peany wieczornej pory","Jednostka",[],["Targon"],"RZADKIE"],"03MT218":["Szkielet Gwiazd","Jeżeli Widzisz jednego z Astralnych, stwórz kartę Posłaniec w swojej talii i przyznaj Astralnym sojusznikom +1|+1, gdziekolwiek są.","","„Niechaj bawi się Posłaniec,\nNiechaj jego radość\nRozświetli gwiazdy”.\n– Modlitwa Lunari","Zaklęcie",[],["Targon"],"EPICKIE"],"03MT074":["Senna Bańka Kłopotów","Ogłusz wroga. Stwórz Ulotną kartę Gwiezdna Piłeczka w ręce.","","„Pora na drzemkę! Jeden iskierkowy motylek, dwa iskierkowe motylki, trzy… Hej, a co to takiego?!” – Zoe","Zaklęcie",[],["Targon"],"RZADKIE"],"03MT072":["Zespolony Podżegacz","","","Chętnych na zdobycie Góry Targon czekają liczne trudności. Niektóre, jak niekończące się podejścia, z wolna pozbawiają śmiałków sił. Inne z kolei dopadają niemal natychmiast.","Jednostka",["SMOK"],["Targon"],"ZWYKŁE"],"03MT039":["Poro-Motyl","","","W kosmosie nikt nie usłyszy twojego zacieszu.","Jednostka",["PORO"],["Targon"],"ZWYKŁE"],"03PZ019":["Połatany Porobot","Kiedy jestem w twojej ręce, posiadam losowe słowo klucz, które zmienia się co rundę. Gdy mnie przywołasz, przyznaj mi to słowo klucz.","","Może nie jest tak przytulaśny jak oryginał, ale nie można mu odmówić SŁODYCZY.","Jednostka",["PORO"],["Piltover i Zaun"],"RZADKIE"],"03PZ005":["Bot Balistyczny","Początek rundy: Stwórz w ręce kartę Zapłon.","","„Obiekt poprosił, byśmy zachowali wyłącznie jego umysł, argumentując, że właśnie w nim przechowuje on każdą urazę”.\n– Dziennik Ulepszacza, wpis nr 1011","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"03PZ004":["Promień Śmierci – Mk 1","Zadaj jednostce 1 pkt. obrażeń. Stwórz kartę Promień Śmierci – Mk 2 wśród pierwszych 3 kart z wierzchu swojej talii.","","„Dziś udało mi się udowodnić, że promienistą energię można skupić w jeden potężny promień! Dzięki odpowiednim usprawnieniom mógłby on służyć za narzędzie o niebywałej precyzji, jednak w tej materii wciąż pozostaje wiele do zrobienia”.\n– Adnotacje do projektu Viktora","Zaklęcie",[],["Piltover i Zaun"],"RZADKIE"],"03PZ003":["Viktor","Gdy mnie przywołasz lub na Początku rundy: Stwórz w ręce kartę Ulepszenie Hexrdzenia.","Udało ci się zagrać 7+ stworzonych kart.","„Zaun doświadczyło wielu tragedii. W końcu jednak nadszedł czas zmian. A jak to bywa w przypadku każdego wielkiego postępu, wszystko musi zacząć się właśnie od ciebie”.","Jednostka",[],["Piltover i Zaun"],"Bohater"],"03PZ010":["Zmechanizowana Naśladowczyni","Atak: Przyznaj mi wszystkie słowa klucze sojuszników.","","„Jestem taka jak ty, tylko lepsza”.","Jednostka",[],["Piltover i Zaun"],"EPICKIE"],"03PZ022":["Daj z siebie wszystko","Zwiększ Siłę i Zdrowie wszystkich sojuszników do najwyższej wartości Siły i Zdrowia wśród sojuszników.\nPrzyznaj wszystkim sojusznikom sojusznicze słowa klucze.","","„I know I know\nYou want some more\nIf you ready let’s go\nGiving it all”\n– Seraphine, „MORE”","Zaklęcie",[],["Piltover i Zaun"],"EPICKIE"],"03PZ014":["Zaplanowane Twory","Stwórz w ręce kartę Uzbrojony Mechanik, Bot Balistyczny lub Nyandroid i przyznaj jej +1|+1.","","„Rozsądek i możliwość podejmowania decyzji są tym, co oddziela ludzi od ich podstawowych instynktów zwierzęcych”. – Viktor","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"03PZ013":["Iteratywne Ulepszenie","Wybierz stronnika. Stwórz w ręce jego kopię z +1|+1.","","„Samodoskonalenie się to gra, w której jesteś bohaterem i złoczyńcą. Czeka cię walka. Może nawet pomyślisz, że wygrałeś. Koniec końców jednak zawsze sam będziesz stał na swojej drodze”. – Zmechanizowana Naśladowczyni","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"03PZ025":["Test Warunków Skrajnych","Usuń Ulotność ze wszystkich kart w ręce. Kiedy mnie odrzucisz, dobierz 1 Ulotną kartę.","","„Toż to pesteczka, serio. Wymieniłam stalową ramę na wytrzymalszy stop, który sama też wymyśliłam, a obwody przepięłam z dala od zawiasów, żeby nie doszło do zwarcia systemów. Łatwizna”. – Zevi, Główny Mechanik","Zaklęcie",[],["Piltover i Zaun"],"RZADKIE"],"03PZ012":["Uzbrojony Mechanik","","","„Ekstra, nowe ramię! Zawsze chciałem sobie takie sprawić. Co następne? Koła grawitacyjne zamiast nóg? Elektropasy? METALOWE ZĘBY? W sumie to twarz może zostać. Lubię ją”.","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"03PZ020":["Odlewnia Hexrdzenia","Początek rundy: WSZYSCY gracze dobierają 1 kartę.","","„Niech sobie komentują moje metody. Nie zaprzeczą postępowi… Światło mej wiedzy lśni niczym kaganek niesiony przez mrok ignorancji!” – Viktor","Lokacja",[],["Piltover i Zaun"],"RZADKIE"],"03PZ002":["Nyandroid","","","„Całe lata spędzone w piltoverskiej akademii tylko po to, by moje technologie uznano za zbyt niebezpieczne, a moją osobę wydalono jako zbyt uroczą! Miau do Zaun, gdzie znam przynajmniej jeden wielki umysł, który podziela moje ambicje…”","Jednostka",["KOT"],["Piltover i Zaun"],"RZADKIE"],"03PZ011":["Reperkusje","Zadaj 3 pkt. obrażeń jednostce lub zniszcz lokację.","","„Ten świetlisty promień poprowadzi nas w marszu na Piltover. Nic nie stanie na drodze naszej Wielkiej Ewolucji!”\n – Viktor","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"03PZ017":["Trójpromienny Próbnik","Zadaj jednostce 1 pkt. obrażeń. Przyzwij losowego stronnika o koszcie 1. Gdy jestem w ręce i zagrasz kartę o koszcie 3, zwiększ obie wartości o 1.","","„...I raz, dwa, TRZY!!! Och. Ojej… kolejny nieprzewidziany rezultat?!” — Heimerdinger","Zaklęcie",[],["Piltover i Zaun"],"EPICKIE"],"03PZ018":["Działo Poro","Aby zagrać, odrzuć 1 kartę.\nStwórz 2 karty Brawurowe Poro w ręce.","","Dwa puszyste stworzenia upadły z gracją na wiwatujący tłum, zostawiając za sobą chmurę puchu i delikatny zapach pysznych wypieków.","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"03SI004":["Prześladowcze Cienie","Wybierz stronnika spośród 4 kart z wierzchu swojej talii.\nDobierz go, pozostałe karty umieść z powrotem w swojej talii, a następnie stwórz identyczną Efemeryczną kopię w ręce.","","„Dalej… otoczcie ich…” — Nocturne","Zaklęcie",[],["Wyspy Cienia"],"RZADKIE"],"03SI001":["Wszechcienisty Łowca","Zmrok: Stwórz moją kopię w ręce.","","„Najpierw była tylko para oczu i samotny głos rozbrzmiewający pośród cieni. Wzmagał się on za każdym razem, gdy się odwracałem. Był jeszcze bardziej wściekły. Głośniejszy. Jak tylko zobaczyłem Ząb, zacząłem biec, ile sił w nogach”. – Łupieżca z Zęba Wieloryba","Jednostka",[],["Wyspy Cienia"],"EPICKIE"],"03SI018":["Obżarstwo","Zabij sojusznika z Ostatnim Tchnieniem, aby przywołać ze swojej talii stronnika, którego koszt jest o 1 większy.","","„PODANO DO STOOOŁUUU!” – Krwiożerczy Rzeźnik","Zaklęcie",[],["Wyspy Cienia"],"RZADKIE"],"03SI012":["Niegodny Przejścia","Unicestwij wszystkie jednostki, które zostały przywołane, ale nie zagrane, w tej rundzie.","","„Oczywiście, że śmierć jest obecna i w Demacii. Widzimy, jak odbiera nam ukochanych i wiemy, że pewnego dnia przyjdzie i po nas. Jednak na tych wyspach… niemalże czuć śmierć w powietrzu. Czuję ją z każdym oddechem, słyszę, jak szepcze mi do ucha. To nie jest jakiś wymysł. Śmierć jest ze mną tu i teraz. I w końcu dopadnie nas wszystkich”.\n— Z notatek Jensa Tommena, historyka","Zaklęcie",[],["Wyspy Cienia"],"RZADKIE"],"03SI014":["Wdzierające się Cienie","Przyznaj WSZYSTKIM swoim sojusznikom w ręce i talii +2|+2 oraz Efemeryczność.","","„Umysł czy ciało — obawiam się, że koszmary Wyspy Cienia w końcu każdego złamią, a obłęd zapanuje po wsze czasy”.\n— Z notatek Jensa Tommena, historyka","Zaklęcie",[],["Wyspy Cienia"],"EPICKIE"],"03SI016":["Bez opamiętania","Zaczerpnij 1 pkt. Zdrowia z jednostki.\nStwórz 2 kopie karty Bez opamiętania w swojej talii. Po każdym trzykrotnym wystąpieniu tego efektu przemień wszystkie moje kopie, gdziekolwiek są, w kartę Pakuj manatki.","","„We go hard, ’til we get it, get it\nWe go hard, we so in it, in it\nWe Pop Stars (Pop Stars), only winning, winning now\nAin’t nobody bringing us down, down, down, down”\n– Evelynn, „POP/STARS”","Zaklęcie",[],["Wyspy Cienia"],"EPICKIE"],"03SI007":["Całun Mroku","Następnym razem, kiedy przywołasz sojusznika w tej rundzie, daj mu +1|+0 i Tarczę Magii w tej rundzie.","","„Jak tylko opuścisz Ząb, poczujesz je. Koniuszki palców na swoim karku, delikatne niczym deszcz. Stworzenia ani drgną, kiedy stawiasz im czoła. Nie boją się mego miecza ni pochodni. Niczego. Okropne kreatury”. \n— Łupieżca z Zęba Wieloryba","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"03SI005":["Nocturne","Zmrok: Przyznaj wrogowi Podatność i daj wrogom -1|-0 w tej rundzie.","Udało ci się zaatakować 5+ sojusznikami mającymi Zmrok lub Postrach.","„Wygląda na to, że odpowiednia liczba pochwyconych dusz pozwala naruszyć nasz świat. Tylko nadzieja może odesłać tego potwora do jego wymiaru… Jednak ta sama nadzieja umarła już dawno temu, wraz z ostatnim tchnieniem królowej i wiecznym krzykiem króla”.\n— Z notatek Jensa Tommena, historyka","Jednostka",[],["Wyspy Cienia"],"Bohater"],"03SI006":["Bestia Zagłady","Zmrok: Zaczerpnij 2 pkt. Zdrowia z wrogiego Nexusa.","","Z każdą nocą podróżni stawali się bardziej znużeni. Ich sen był niespokojny, a sny żywe. Spanie nie dawało już wytchnienia, zamiast tego drenowało życie z ich kości.","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"03SI015":["Nieznośne Widmo","Ostatnie Tchnienie: Stwórz 2 moje kopie w talii wroga.","","„Większość duchów na Wyspach Cienia to niebywale przerażające i makabryczne stwory. Ledwie garstka z nich ogranicza się do bycia… no cóż… naprawdę irytującymi”.","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"03SI003":["Styksowy Obserwator","Zmrok: Daj mi +2|+0 i Postrach w tej rundzie.","","Kiedy wdzierają się tu promienie słońca, koszmary tego miejsca budzą się, obserwują i czekają.","Jednostka",["PTAK"],["Wyspy Cienia"],"ZWYKŁE"],"03SI002":["Niewymowna Groza","Zaczerpnij 1 pkt. Zdrowia z dowolnego celu.\nZmrok: Stwórz losową kartę Zmroku w ręce.","","„Z każdym mijającym dniem tracę ducha i wigor, które pozwoliły mi odnaleźć to miejsce. W Zębie Wieloryba roi się od mizerot, które poświęciły się wyprawom. Obawiam się, że im dłużej tu będę, tym pewniej stanę się jednym z nich”.\n— Z notatek Jensa Tommena, historyka","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"03SI010":["Jeździec Zmierzchu","Zmrok: Przyznaj mi +1|+0 za każdy raz, gdy aktywowaliśmy Zmrok w tej grze.","","Z każdym zachodem słońca noc rozpościera swe mroczne skrzydła, wymazując resztki nadziei dnia poprzedniego.","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"03SI013":["Wstające Mgły","Przywołaj kartę Zjawa z Mgły.","","Zjawy mgły poruszają się przez wymiary niewidoczne dla oczu śmiertelników. Pojawiają się bez ostrzeżenia i krzywdzą każdego, kogo napotkają.","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"03IO025":["Grad Pięści","Przyznaj sojusznikowi +1|+0 i Szybki Atak. Jeżeli dany sojusznik już go posiada, zamiast tego przyznaj Podwójny Atak.","","„Bij dużo, bij szybko, bij mocno”. – Rogi Smoka","Zaklęcie",[],["Ionia"],"RZADKIE"],"03IO017":["Pix!","Wsparcie: Daj wspieranemu przeze mnie sojusznikowi +2|+1 w tej rundzie.","","„Pix jest NIESAMOWITY. Mały, świetny i wspaniały!\nUwielbia oposy i lubi też… hrmhmhmhrmszkować!” — Lulu","Jednostka",["WRÓŻKA"],["Ionia"],"ZWYKŁE"],"03IO008":["Fanaberia!","Przemień stronnika w kartę Wiewiórka o statystykach 1|1 i Ucisz go w tej rundzie.","","„Uraczando!” — Lulu","Zaklęcie",[],["Ionia"],"ZWYKŁE"],"03IO001":["Dziecię Kwiatów","Gdy otrzymuję Wsparcie, przyznaj mi +2|+0.","","Każdy chce pupila, jednak nikt nie jest gotowy na wiążącą się z tym odpowiedzialność. Trzeba je wyprowadzać, stosować zbilansowaną dietę… trenować w domu. To sporo roboty.","Jednostka",["WRÓŻKA"],["Ionia"],"ZWYKŁE"],"03IO019":["Jedna Wola","Wybierz sojusznika. Wycofaj WSZYSTKIE pozostałe jednostki i lokacje.","","„Samotnie kroczę swoją ścieżką”. — Mniszka Pustelnica","Zaklęcie",[],["Ionia"],"EPICKIE"],"03IO002":["Lulu","Wsparcie: Wspierany przeze mnie sojusznik rośnie do 4|4 w tej rundzie.","Sojusznicy zostali wsparci 3+ razy.","„Bez obaw, Pix! Wydostaniemy się z Polany i zaurocznościmy WSZYSTEK WSZYSTKIEGO. Gotowy?!”","Jednostka",["YORDLE"],["Bandle City","Ionia"],"Bohater"],"03IO011":["Napakowana Wiewiórka","Uderzenie: Podwój moją Siłę.","","Jego sekretem są szejki ze sproszkowanych żołędzi — cztery razy dziennie.","Jednostka",["WRÓŻKA"],["Ionia"],"RZADKIE"],"03IO009":["Pyszny Wróżkoludź","","","Energia: 104 kJ (25 kcal), węglowodany: 5,88 g, cukry: 3,53 g, błonnik pokarmowy: 3 g, tłuszcz: 0,18 g, białko: 0,98 g, woda: 92 g…","Jednostka",["WRÓŻKA"],["Ionia"],"ZWYKŁE"],"03IO003":["Wróżkowy Przewodnik","Zagraj: Przyznaj sojusznikowi Nieuchwytność.","","„Ciii, tędy! Za chodzącym domkiem na drzewie musimy skręcić w lewo, dalej prosto, mijając gadające kwiaty. Lu, słuchasz? Lu? Lu! LULU! NIE. Karm. Ich! Nie rób tego.”","Jednostka",["YORDLE"],["Ionia"],"RZADKIE"],"03IO007":["Trevor Drzemkozad","Wsparcie: Stwórz atakującą kartę Gulgotek o statystykach wspieranego przeze mnie sojusznika.","","Masz gonić za tym, o czym śnisz, a nie demonstrować to przez nieświadome mamrotanie jakichś guseł, kiedy przez sen unosisz się w pradawnym, magicznym lesie. Rajciu, tak trudno zapamiętać?","Jednostka",["YORDLE"],["Ionia"],"EPICKIE"],"03IO010":["Młoda Wiedźma","Wsparcie: Daj wspieranemu przeze mnie sojusznikowi Szybki Atak i +1|+0 w tej rundzie.","","Sir Ribery Montague opuścił dom, by wykonać ważne zadanie, czy przypodobać się pewnemu znamienitemu rodowi. Przeznaczenie zaprowadziło go do ukrytego lasu Bandle, gdzie młoda Bri szybko zamieniła sir Ribery’ego w żabę, przerywając jego przygodę na rzecz własnej. Biedny Kum!","Jednostka",[],["Ionia"],"ZWYKŁE"],"03IO020":["Niemożniando!","Zatrzymaj Szybkie lub Powolne zaklęcie o koszcie 3 lub mniejszym.","","„Nie rób tak, niemądry sapciuszku! Możesz zrobić krzywdę kłuskom!” – Lulu","Zaklęcie",[],["Ionia"],"RZADKIE"],"03IO022":["Bierz co twoje","Wycofaj sojusznika i wezwij na jego miejsce jego dokładną, Efemeryczną kopię. Zmniejsz jej koszt do 0 w tej rundzie.","","„More\nKnow I got it,\nSo here you go,\nYou look like you could use some more”.\n– Akali, „MORE”","Zaklęcie",[],["Ionia"],"EPICKIE"],"03IO018":["Puchaty Opiekun","Gdy otrzymuję Wsparcie, daj mi +0|+3 w tej rundzie.\nWsparcie: Daj wspieranemu przeze mnie sojusznikowi +3|+0 w tej rundzie.","","Fioletowe leśne wróżkoludzie to urocze małe stworzenia, o które troszczą się wszyscy, którzy je napotkają. No, prawie wszyscy.","Jednostka",["YORDLE"],["Ionia"],"RZADKIE"],"03DE008":["Porucznik Smoczej Straży","Gdy mnie przywołasz i Widzisz Smoka, przyznaj mi Wyzwanie.","","„Gdy straciłem moich towarzyszy w boju pod Wrenomurem, myślałem, że przepadła też moja niezłomność… ale okazuje się, że bitwa porusza starego żołnierza wystarczająco, aby wykrzesał z siebie wszystko.","Jednostka",[],["Demacia"],"ZWYKŁE"],"03DE001":["Konfrontacja","Przyznaj sojusznikowi Wyzwanie.\nJeśli ten sojusznik jest Smokiem, dobierz 1 kartę.","","„Nikt nie ucieknie!” – Shyvana","Zaklęcie",[],["Demacia"],"ZWYKŁE"],"03DE015":["Kamienny Pogromca","WSZYSTKIE zaklęcia kosztują o 1 więcej.","","To, co z początku jest bezkształtnym, niezgrabnie ociosanym blokiem petrucytu, w zdolnych rękach rzeźbiarza szybko staje się czymś więcej. To wtedy dzieło naprawdę ożywa.","Jednostka",[],["Demacia"],"RZADKIE"],"03DE006":["Wyjący Smok","","","Wszystkie stworzenia zaciekle bronią swoich młodych, jednak nieliczne są przygotowane do odparcia potencjalnego zagrożenia równie dobrze, co smoki.","Jednostka",["SMOK"],["Demacia"],"ZWYKŁE"],"03DE025":["Rozżarzony Oddech","Sojusznik z Furią Uderza 2 Najsłabszych wrogów jeden po drugim.","","Przez całe wieki Demacianie znali smoczą furię jedynie z legend. Zmienił to Wrenomur.","Zaklęcie",["ŻYWIOŁ"],["Demacia"],"RZADKIE"],"03DE002":["Atak Koszący","Sojusznik i wróg Uderzają siebie nawzajem. Następnie, jeśli sojusznik jest Smokiem, ulecz go o 5 pkt.","","Gdy rycerz i smok zostali rozdzieleni, dyszący i ranni, smok wydawał się odzyskać siły. Zwęszył krew… i miał ochotę na więcej.","Zaklęcie",[],["Demacia"],"RZADKIE"],"03DE011":["Shyvana","Atak: Daj mi +1|+1 w tej rundzie.","Sojusznicze Smoki zadały 16+ pkt. obrażeń.","„Z jednej strony z samej swojej natury jest naszym najbardziej znienawidzonym wrogiem. Jej podobni z kart historii przynosili Demacii tylko boleść i udrękę. Z drugiej strony ufa jej sam Książę – i można się w niej dopatrzeć cech zdeterminowanego żołnierza i cennego sojusznika. Mam tylko nadzieję, że nie zawiedzie zaufania, które w niej pokładamy”.\n– Strona z raportu porucznika Jerika z Wrenomuru","Jednostka",["SMOK"],["Demacia"],"Bohater"],"03DE003":["Zwiadowca Smoczej Straży","Gdy mnie przywołasz i Widzisz Smoka, Zjednocz Siły.","","„Tam, na horyzoncie! Czy to…?”\n„Na to wygląda.”\n„Skąd masz pewność?”\n„Och, ich nie można pomylić. Zakryj uszy. Będzie głośno”. – Anden i Yessenia","Jednostka",[],["Demacia"],"RZADKIE"],"03DE013":["Gniazdująca Tropicielka","","","„Uważajcie, żołnierze! Jeśli będziemy stąpać ostrożnie i nie naruszymy gniazda, smoczyca pozostanie spokojna. Jeśli wkurzymy ją bardziej… No, wtedy trzeba być gotowym do biegu”. – Anden Mayne, Jajogłowy Badacz","Jednostka",["SMOK"],["Demacia"],"ZWYKŁE"],"03DE005":["Jajogłowy Badacz","Gdy mnie przywołasz, stwórz w ręce losowego Smoka.","","Smocze jajo (Wyjący Smok, Draco Mruckionis) \nLokalizacja: Odzyskane przez badacza Andena Mayne’a podczas Ekspedycji \nUwagi: Okres dojrzewania nieznany. Inkubacja trwa. Ostatnio zaobserwowano ruch w obrębie skorupy. Jajo reaguje na ciepło, światło, młot. Obecne badania niejednoznaczne. \n– Notatki Andena Mayne’a, Jajogłowego Badacza","Jednostka",[],["Demacia"],"ZWYKŁE"],"03DE007":["Kadregrin Piekielny","Gdy mnie przywołasz, przyznaj innym sojuszniczym Smokom +4|+4, gdziekolwiek są.","","Kiedy Demacia ucierpiała z powodu szeregu niespodziewanych smoczych ataków, Shyvana wiedziała, że winą należy obarczyć Kadregrina Piekielnego. Inne smoki, czerpiąc natchnienie z jego zuchwałej natury i potężnych płomieni, siały postrach wśród Demacian. ","Jednostka",["SMOK"],["Demacia"],"EPICKIE"],"03DE012":["Za Poległych","Gdy przywołasz Elitarnego, zmniejsz mój koszt o 1.\nZa każdego sojusznika, który zginął w tej rundzie, przywołaj kartę Nieustraszona Gwardia.","","„Jeśli jeden żołnierz padnie, inny musi zająć jego miejsce. Nasz sztandar nigdy nie może upaść”. — Garen","Zaklęcie",[],["Demacia"],"EPICKIE"],"03DE014":["Bystry Wzrok","Daj sojusznikowi +1|+2 i Bystry Wzrok w tej rundzie.","","Każdy, kto odważy się przedrzeć przez mury Demacii, zostanie powitany przez całą kompanię – przygotowaną i dobrze uzbrojoną.","Zaklęcie",[],["Demacia"],"ZWYKŁE"],"03FR020":["Szramowiska","Gdy sojusznik przetrwa obrażenia, przyznaj mu +1|+0 i Wytrzymałość.","","Zimowy Szpon obejmuje wiele honorowych miejsc, jednak jedną z najwspanialszych okolic są Szramowiska, gdzie znajdują się uszkodzone okręty wojenne, którym udało się powrócić z najazdów. Okręty te obecnie służą za miejsca spotkań dla wojowników i ich krewnych, przy czym odzwierciedlają one cechy plemienia, które je zbudowało \n – są wytrzymałe i potrafią przystosować się do każdej sytuacji.","Lokacja",[],["Freljord"],"EPICKIE"],"03FR007":["Troll Poszukiwacz","Gdy mnie przywołasz i Widzisz kartę o koszcie 8+, przyznaj mi +3|+0.","","Zwiadowca klęknął nad podartym materiałem ukrytym w śniegu. Zimne powietrze niosło zapach ludzkiego potu i dymu.\nWyciągnął z puchu tkaninę, na której końcu dostrzegł wiszący talizman na tle burzowego nieba. Nie było wątpliwości — avarosański talizman. ","Jednostka",[],["Freljord"],"ZWYKŁE"],"03FR004":["Ożywczy Ryk","Wybierz jednostkę w ręce, by ją ujawnić. Ulecz swój Nexus o wartość jej Siły.\nOświecenie: Zmniejsz jej koszt do 0.","","„Dorosłe trolle mają grubą skórę i gęste kości, które szybko się leczą, co czyni z nich strasznych i nieustępliwych wrogów. Należy szybko pozbawić je życia, inaczej odzyskają siły i wrócą kiedy indziej”. — Avarosański Strzelec","Zaklęcie",[],["Freljord"],"RZADKIE"],"03FR017":["Augur z Pradawnych","Zagraj: Jeśli Widzisz kartę o koszcie 8+, przyznaj sojusznikowi Zmiażdżenie i Regenerację.","","Niewiele trolli opanowuje wołania Pradawnych, jednak ci, którzy je znają, przyzywają imiona poprzedników, by tchnąć w swych braci wyjątkową siłę i wytrzymałość.","Jednostka",[],["Freljord"],"RZADKIE"],"03FR006":["Trundle","Gdy mnie przywołasz, stwórz w ręce kartę Lodowa Kolumna.","Widziałem, jak zagrywasz kartę Lodowa Kolumna.","Pochodnie jedna po drugiej rozświetliły przełęcz, pozwalając wyraźnie dostrzec każdy szczegół. Widać było dziesiątki, setki trolli, każdy zwalisty, masywny i zabójczy.\n— Zapytam jeszcze raz — warknął Trundle, zarzucając Zmrażacza Kości na ramię. — Poddacie się, czy mam wam roztrzaskać czaszki?","Jednostka",[],["Freljord"],"Bohater"],"03FR008":["Lodowy Wstrząs ","Daj WSZYSTKIM jednostkom -3|-0 w tej rundzie. Zadaj 3 pkt. obrażeń WSZYSTKIM jednostkom.","","„Zakopać ich żywcem!” — Trundle","Zaklęcie",["ŻYWIOŁ"],["Freljord"],"EPICKIE"],"03FR002":["Wołanie Trolli","Daj sojusznikowi +0|+2, by dać wrogowi -2|-0 w tej rundzie.","","Wołania trolli są bardzo różnorodne. Różnią się w zależności od grupy i często są niezrozumiałe. Mają jednak coś wspólnego — są strasznym przedstawieniem. ","Zaklęcie",[],["Freljord"],"ZWYKŁE"],"03FR011":["Uzgar Starożytny","","","Nim usłyszeli, poczuli. Ziemia trzęsła się pod ich stopami, jednak ich uszu szybko doszedł dźwięk jakby zbliżającej się burzy.\nMeyrick uniósł głowę i nasłuchiwał z szeroko otwartymi oczami.\n— Co to? — wyszeptała szybko Anya, dobywając łuku, jednak Meyrick już pędził ku drodze.\n— W NOGI!","Jednostka",[],["Freljord"],"RZADKIE"],"03FR005":["Troll Pustoszyciel","Gdy mnie przywołasz i Widzisz kartę o koszcie 8+, przyznaj mi Regenerację.","","Gdy dotarli do avarosańskich chat, wezwali Hgar. Śmiejąc się, uniosła Śniegołupsa, gotowa roznieść swą bronią drewniane domki w drzazgi.","Jednostka",[],["Freljord"],"ZWYKŁE"],"03FR018":["Zew Natury","Dobierz każdego Yeti, Poro i Elnuka spośród 4 kart z wierzchu swojej talii. Pozostałe karty umieść z powrotem w talii.","","„...I nagle WIEEELKI, OGROOOMNY ELNUK PRZELECIAŁ przez korony drzew z maciupkim Poro na grzbiecie. Zjawił się także PRZYJAZNY YETI, ponieważ chciał się bawić ze swymi przyjaciółmi. Wszyscy zbiegli górskim zboczem, drąc się wniebogłosy…” – Ingvar Młodsza","Zaklęcie",[],["Freljord"],"ZWYKŁE"],"03FR010":["Oblicze Pradawnych","Początek rundy: Jeśli Widzisz kartę o koszcie 8+, otrzymaj dodatkowy kryształ many w tej rundzie.","","„Powstańcie, Pradawni, powstańcie!\nRządy lodu, niebo przełamcie.\nPowstańcie, Pradawni, powstańcie!\nDajcie nam siłę, im zgubę sprawcie”.\n— Wołanie Trolli","Jednostka",[],["Freljord"],"ZWYKŁE"],"03FR019":["Głosy Pradawnych","Pozyskaj 2 puste kryształy many.\nDobierz każdą kartę o koszcie 8+ spośród 5 kart z wierzchu swojej talii. Pozostałe karty umieść z powrotem w talii.","","Avarosańscy osadnicy od pokoleń słyszą dziwne, tajemnicze dźwięki dobiegające od strony zimowych burz. Kiedy w końcu wyruszyli daleko, daleko na północ, odkryli w końcu ich źródło – pradawne monolity trolli szepczące w zapomnianych przez świat językach, kiedy wiatr przemykał przez ich rozwarte paszcze.","Zaklęcie",[],["Freljord"],"ZWYKŁE"],"03FR025":["Podarunki Trolli","Przyznaj sojusznikowi Regenerację. Jeżeli już ją posiada, zamiast tego przyznaj +2|+2.","","Żałujcie tych, którzy w krwi trolla doszukują się zwycięstwa.","Zaklęcie",[],["Freljord"],"RZADKIE"],"03FR022":["Poczuj moc","Przywołaj 2 różnych, losowych bohaterów ze swojej ręki i talii. Zwiększ ich statystyki do 10|10.","","„We got it all in our hands now\nSo can you handle what we’re all about?”\n– Ahri, „POP/STARS”","Zaklęcie",[],["Freljord"],"EPICKIE"],"04PZ001":["Ekko","Uderzenie: Stwórz Ulotną kartę Czasowa Sztuczka w ręce.","Udało ci się Spojrzeć w Przyszłość 4 lub więcej razy. Gdy awansuję, stwórz 3 kopie karty Chronostrzaskania w swojej talii.","Nie chodzi o to, ile masz czasu, ale jak go spożytkujesz.","Jednostka",[],["Piltover i Zaun"],"Bohater"],"04PZ005":["Chireański Robotnik ze Slumsów","Kiedy przywołasz inną kartę Chireański Robotnik ze Slumsów, Unicestwij mnie i przemień sojusznicze karty Chireańskich Robotników ze Slumsów, gdziekolwiek są, w Oddziały Robotników ze Slumsów.","","Pierwsi zauńscy górnicy, którzy odkryli chirean, uważali ich za nieśmiałe, proste stworzenia. Ale wraz z upływem lat, w miarę jak chireanie przyzwyczaili się ludzi, stopniowo zaczęli ujawniać swoje ścisłe społeczne więzi i niemal wrodzone zrozumienie technologii.","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"04PZ014":["Wzrost Produkcji","Aby zagrać, zużyj całą manę. Przywołaj losowe Wieżyczki, których łączny koszt jest równy zużytej manie.","","„Za mało zasobów?! Ja zbudowałem mój pierwszy zmechanizowany wynalazek z części wyrzuconego zegara i zardzewiałego kondensatora termicznego. Trzeba pracować z tym, co się ma!” – Heimerdinger","Zaklęcie",[],["Piltover i Zaun"],"RZADKIE"],"04PZ003":["Czasowstrzymywacz","Aby zagrać, odrzuć 1 kartę.\nZadaj 1 pkt. obrażeń wrogowi lub wrogiemu Nexusowi i 1 pkt. kolejnemu.","","„Uwaga!” – Ekko","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"04PZ011":["Mierzony Strzał","Dobierz 1 kartę.\nStwórz w swojej talii kartę Równoległa Konwergencja.","","„Rozszczepiam czas…” – Ekko","Zaklęcie",[],["Piltover i Zaun"],"EPICKIE"],"04PZ002":["Upadły Kot","Gdy mnie przywołasz, stwórz kartę Hexytowy Kryształ wśród dolnych 10 kart swojej talii.","","„ALE MOJE PLANY… MIAUUUU!”","Jednostka",["KOT"],["Piltover i Zaun"],"RZADKIE"],"04PZ020":["Uszkodzony Zamianobot","Zagraj: Zamień moje statystyki ze statystykami innej jednostki.","","„– Nowy Jednoręki Bot? Czy przypadkiem wiele lat temu nie zamknięto fabryki, w której powstawały?\n– Też tak myślałem. Chodziło o jakieś toczące się bomby i przypadkowe pożary.\n– Ech…\n– …zagramy?\n– No jasne.”\n– Protektorzy z Zaun","Jednostka",[],["Piltover i Zaun"],"RZADKIE"],"04PZ013":["Elnuk Ochotnik","Gdy mnie przywołasz, stwórz losowego Elnuka wśród pierwszych 6 kart z wierzchu swojej talii.","","„DOBRA, MALEŃKI, SIEDŹ SPOKOJNIE, A JA WCISNĘ TEN PRZEŁĄCZNIK I… BUM! HA! ELNUKI RZĄDZĄ! Przyda nam się więcej trawy. I miejsca”. \n– Praktyczna Perfekcjonistka","Jednostka",["ELNUK"],["Piltover i Zaun"],"RZADKIE"],"04PZ010":["Równoległe Linie Czasowe","Przyznaj stronnikom w twojej ręce „Gdy mnie zagrasz, wybierz 1 z 3 stronników o moim koszcie i przemień mnie w tego stronnika”.","","„Bawimy się na MOICH zasadach”. – Ekko","Zaklęcie",[],["Piltover i Zaun"],"EPICKIE"],"04PZ016":["Bombowy Pawian","Gdy mnie przywołasz, stwórz w ręce kartę Ogniste Gryzaki!.","","Jinx miała kiedyś zwykłego dostawcę, ale biedak wypadł z obiegu. Właściwie to wypadł, ale przez okno. W sumie to wyleciał przez okno i to z wielkim hukiem. Oczywiście za sprawą Jinx.","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"04PZ007":["Czasowa Sztuczka","Spójrz w Przyszłość, a następnie dobierz 1 kartę.","","„To ja kreuję przyszłość…” – Ekko","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"04PZ012":["Praktyczna Perfekcjonistka","Zagraj: Spójrz w Przyszłość. Stwórz 3 kopie wybranej karty w swojej talii.","","„Kay jest świetna. Wyznaje zasadę, że trening czyni mistrza, wiesz? A jak ona trenuje!” – Shomi","Jednostka",[],["Piltover i Zaun"],"RZADKIE"],"04PZ017":["Wielka Ewolucja","Twoje karty mają koszt zmniejszony o 1, posiadają Ulepszenie, są tworzone przez kartę Wielka Ewolucja i od teraz są Maszynami.","","„Postęp jest wszystkim. Wprowadzę przyszłość do tego miasta, czy jest ono na to gotowe, czy nie”. – Viktor","Zaklęcie",[],["Piltover i Zaun"],"EPICKIE"],"04PZ015":["Elastatron 3000","Gdy przywołasz Maszynę, współdzielę z nią słowa klucze.","","„Ach, tak! Elastatron 3000! Elastyczny, twórczy, a do tego niezły przystojniak! Jeśli mógłby mówić, z pewnością mielibyśmy sobie WIELE do powiedzenia”. – Heimerdinger","Jednostka",["MASZYNA"],["Piltover i Zaun"],"EPICKIE"],"04PZ004":["Deskoskoczek","Gdy ujrzysz mnie w Przyszłości, przywołaj mnie.","","„Ach, Shomi DOSKONALE jeździ na deskolotce. Jakie cuda widziałam! Przejście z grindu w odwrócony backslide, później wybicie w powietrze z trzypunktowym, potrójnym zanurzeniem! Czy jakoś tak. No, chodzi mi o to, że wymiata, dobra?” – Praktyczna Perfekcjonistka","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"04BW002":["Kościany Harpun","Sojusznik Uderza wroga, a następnie przechodzi na wierzch twojej talii.","","„Prezent w chwili rozłąki…” – Pyke","Zaklęcie",[],["Bilgewater"],"EPICKIE"],"04BW007":["Diabeł Morski","Zagraj: Każdy sojuszniczy Obserwator Uderza losowego wroga.","","„Nie ma nic lepszego od diabła morskiego, dzięki któremu wiesz komu zaufać, a kogo zabić”. – Pyke","Jednostka",["OBSERWATOR"],["Bilgewater"],"EPICKIE"],"04BW001":["Czerwonopłetwy Pyskomłot","Zagraj: Przyznaj wrogowi Podatność.","","Gdy pyskomłoty niszczą kil statku, zdają się robić to dla zwykłej przyjemności. Rzadko pożerają one biedną załogę, którą zostawiają na pastwę innych stworzeń.","Jednostka",["OBSERWATOR"],["Bilgewater"],"ZWYKŁE"],"04BW005":["Pyke","Gdy Obserwuję, przemień mnie w kartę Śmierć z Głębin.","Sojuszniczy Pyke’owie zadali 15+ pkt. obrażeń.","„…wizje wróciły. Dostrzegam jego błagalny wzrok bijący z wnętrza paszczy diabła morskiego. Próbowaliśmy go wyciągnąć, ale nasza łajba była za mała, a bestia zbyt duża. Nie miałem wyboru. Musiałem odciąć linę. Musiałem…”\n– Przesiąknięty krwią list","Jednostka",["OBSERWATOR"],["Bilgewater"],"Bohater"],"04BW010":["Harpun na Potwory","Grabież: Kosztuję o 2 mniej.\nZadaj jednostce 5 pkt. obrażeń.","","„Bestia dostała, chłopcy! Dźgać ją teraz, póki nie przestanie wierzgać! Nie chcę tu dookoła widzieć ani kropli czystej wody!” – Harda Nadzorczyni","Zaklęcie",[],["Bilgewater"],"ZWYKŁE"],"04BW014":["Do Szeregu","Przywołaj kartę Beczka Prochu.\nStwórz w ręce kartę Załatwić Ich.","","„Zrobione jak prosiłeś, kapitanie. Wystarczy mała iskierka, a łupnie jak należy”. – Majtek Drogi przez Mękę","Zaklęcie",[],["Bilgewater"],"ZWYKŁE"],"04BW011":["Sprzyjające Szczęście","W następnej rundzie Zwędź 1 kartę przy zadawaniu obrażeń wrogiemu Nexusowi.","","„A więc ile jesteś w stanie postawić, przyjacielu?” \n – Tahm Kench","Zaklęcie",[],["Bilgewater"],"EPICKIE"],"04BW015":["Rekiniątko","","","„Może tego nie widać, ale są spragnione krwi. A kiedy urosną i na chwilę się zapomnisz, będą wiedzieć, gdzie jej szukać. Dlatego noś rękawice”. – Łowcy Jaull","Jednostka",["OBSERWATOR"],["Bilgewater"],"ZWYKŁE"],"04BW003":["Rój Pękoszczęków","Zagraj: Rozpoczynam Darmowy Atak.","","„Kap, kap, kap, krew z rany kapie.\nPłyń, płyń, płyń, bo rój cię złapie!\nGryzą zębiska, dziatki łkają.\nW sen bez pobudki zapadają!”\n– Kołysanka z Bilgewater","Jednostka",["OBSERWATOR"],["Bilgewater"],"ZWYKŁE"],"04BW009":["Zatoka Rozpruwacza","Gdy sojusznicy atakują, przed aktywowaniem Obserwacji przyznaj sojusznikowi z samego wierzchu swojej talii Obserwację. Ten sojusznik staje się Obserwatorem.","","Zdradzieckie zatoki Bilgewater wkrótce stały się domem dla najróżniejszych morskich bestii. Czekają tylko na kolejną lekkomyślną załogę, która zignoruje ostrzeżenia kapitana portu.","Lokacja",[],["Bilgewater"],"RZADKIE"],"04BW008":["Zagubione Bogactwa","Dobierz Skarb. Jeżeli nie ma żadnych Skarbów do dobrania, zamiast tego stwórz 2 Skarby w swojej talii.","","„Jesteśmy bogaci!” – Hardy Rzeźnik","Zaklęcie",[],["Bilgewater"],"RZADKIE"],"04BW013":["Rejs Grabieżców","Gdy Odliczam, przywołaj losowego stronnika o koszcie 1.\nOdlicz 2: Przyznaj kosztującym 1 sojusznikom +2|+1 i Postrach.","","„To myślisz, że ci starczy krzepy, żeby nazywać się Hakiem, co? Zobaczy się, srajtuchu. Jak tu z tobą skończymy, to albo będą za ciebie dawać tyle złota, co ważysz, albo to my obciążymy ciebie i rzucimy prosto w fale, na obiadek z bestiami!” – Bosman","Lokacja",[],["Bilgewater"],"RZADKIE"],"04BW004":["Krwawa Przynęta","Stwórz kartę Rój Pękoszczęków na wierzchu swojej talii.","","„Gdyby to ode mnie zależało, wolałbym zostać pożarty przez diabła morskiego zamiast przez te cholerstwa. Lepsza szybka śmierć niż bycie rozerwanym żywcem na oczach własnej załogi”. – Hardy Rzeźnik","Zaklęcie",[],["Bilgewater"],"ZWYKŁE"],"04BW016":["Zniszczony Rex","Zagraj: Za każdą dobraną w tej rundzie kartę zagraj zaklęcie Kanonada na losowych wrogów, maksymalnie do 6 razy.","","„…Rex?” – Bosman","Jednostka",[],["Bilgewater"],"RZADKIE"],"04BW006":["Lista","Przyznaj wrogowi Podatność. Jeżeli już posiada Podatność, Najsilniejszy sojusznik rozpoczyna Darmowy Atak, rzucając mu Wyzwanie.","","„Ty masz imię, a ja listę”. – Pyke","Zaklęcie",[],["Bilgewater"],"RZADKIE"],"04IO008":["Buntowniczy Taniec","Wycofaj jednostkę.\nTaniec z Ostrzami: 1 Ostrze.","","„Wycofać się! Pora, by ktoś inny wkroczył na scenę!”\n– Zinneia Stalowe Crescendo","Zaklęcie",[],["Ionia"],"ZWYKŁE"],"04IO005":["Irelia","Gdy mnie przywołasz lub na Początku rundy: Jeżeli posiadasz Token ataku, stwórz w ręce kartę Obłędny Duet.","Udało ci się zaatakować 14+ sojusznikami.","„Zajmowaliśmy się niegdyś sztuką i pięknem, a nasze serca wznosiły się. Potem jednak zniszczyli nasze mury i przelali naszą krew, przez co spadliśmy z powrotem na ziemię…”","Jednostka",[],["Ionia"],"Bohater"],"04IO020":["Rozproszona Ławica","Zagraj: Dobierz Powolne, Szybkie lub Błyskawiczne zaklęcie.\nOświecenie: Mam Nieuchwytność.","","Dziwne i niepokojąco piękne podniebne pieśni Pochłaniaczy Chmur utrzymywały Czarną Mgłę pod kontrolą… jednak do czasu.","Jednostka",[],["Ionia"],"RZADKIE"],"04IO004":["Rozkwitające Ostrze","Zagraj: Taniec z Ostrzami: 2 Ostrza.","","„Są tacy, którzy uznają kwiat za kruchy i delikatny. Zapominają, jak wiele siły wymaga trwanie przy skromnej ziemi i przywoływanie nadziei każdym rozkwitem”.\n– Zinneia Stalowe Crescendo","Jednostka",[],["Ionia"],"ZWYKŁE"],"04IO003":["Ostrze Obrończyni","Wybierz sojusznika, który zaatakuje razem z kartą Ostrza. Następnie wykonaj Taniec z Ostrzami: 3 Ostrza.","","„Powstrzymać ich odwrót! Noxianie rozpoczęli tę wojnę, ale my ją zakończymy”. – Irelia","Zaklęcie",[],["Ionia"],"RZADKIE"],"04IO015":["Tańcząca Kropla","Gdy mnie Wycofasz, dobierz 1 kartę.","","„Woda jest elastyczna, potrafi się dostosować. Przyjmuje postać odpowiednią w danym momencie, napływając ku wybrzeżu lub cofając się do głębi mórz”. – Mnich z Ionii","Jednostka",[],["Ionia"],"ZWYKŁE"],"04IO014":["Adept Cienia","Gdy przywołasz Efemerycznego sojusznika, daj mi +1|+0 w tej rundzie.","","„Jesteś dymem – szeptem na wietrze. Twoje pięści muszą połączyć się z mrokiem, tak jak cień łączy się z ciemnością. A teraz… od nowa!” – Pani Shi","Jednostka",[],["Ionia"],"ZWYKŁE"],"04IO002":["Zinneia Stalowe Crescendo","Gdy Tańczysz z Ostrzami, atakuję wykorzystując Ostrza.\nZagraj: Taniec z Ostrzami: 1 Ostrze.","","„Zbierzcie się dookoła, kochani. Dziś nasze stopy będą stąpać po ziemiach, które nas wykarmiły, krzewiąc ruchy, których nauczyły nas nasze rody. Jesteśmy dziećmi Ionii i dziś tańczymy dla sztuki, dla wolności i dla siebie nawzajem!”","Jednostka",[],["Ionia"],"EPICKIE"],"04IO007":["Synkopa","Zamień 2 sojuszników.","","„Tańczyć to znaczy poruszać się w harmonii z ruchem otaczającego świata”. – Zinneia Stalowe Crescendo","Zaklęcie",[],["Ionia"],"RZADKIE"],"04IO011":["Prowadź i Podążaj","Wycofaj sojusznika, by stworzyć w ręce kartę Obłędny Duet.","","„Nasz występ będzie… niezapomniany”. \n – Zinneia Stalowe Crescendo","Zaklęcie",[],["Ionia"],"ZWYKŁE"],"04IO013":["Święty Obrońca","Zagraj: Daj sojusznikowi Barierę w tej rundzie i dobierz kartę Shen.\nSojusznicy z Barierą mają Podwójny Atak.","","„Kiedy my walczymy, by chronić tę krainę, sama kraina chroni nas. Czerpiemy siłę z gniewu ziemi i przeganiamy wrogów. W ten sposób zapewniamy równowagę”.\n– Ioniański kapłan","Jednostka",[],["Ionia"],"EPICKIE"],"04IO012":["Cienie Przeszłości","Wycofaj każdego sojusznika i wezwij na jego miejsce kartę Żywy Cień.","","„Niechaj uderzają w cienie, gdzie ich broń nie znajdzie celu”. – Zed","Zaklęcie",[],["Ionia"],"RZADKIE"],"04IO009":["Tancerka Szarf","Zagraj: Taniec z Ostrzami: 1 Ostrze.","","„Och, chłopcy, co za szkoda! Tyle siły i za grosz rytmu, naprawdę? Cóż, zdaje się, że nie WSZYSCY możemy być gwiazdami!”","Jednostka",[],["Ionia"],"RZADKIE"],"04IO001":["Muzycy Polowi","W każdej rundzie po przywołaniu 3 innych sojuszników odzyskaj manę zaklęć i dobierz 1 kartę.","","Dla niektórych muzyka jest wspólnym schronieniem przed trudnościami i przemocą. Dla innych muzyka jest formą oporu.","Jednostka",[],["Ionia"],"EPICKIE"],"04IO006":["Obrońca Wybrzeża","Gdy przywołasz innego sojusznika, daj mi +2|+0 w tej rundzie.","","„Najdroższa Kay,\nzjawili się o poranku. Szeregi łodzi zapełniły horyzont i przysłoniły wschodzące słońce. Ich maszyny pogrążyły Srebrne Równiny w płomieniach. Gęsty dym unosi się teraz w letnim powietrzu. Nie możemy już dłużej czekać z założonymi rękami. Czy będą to grabie czy szpadle, kosy czy miecze, chwytamy dziś za broń i ruszamy na spotkanie przeznaczeniu.\nWiedz, że kocham ciebie i nasz dom bardziej, niż słowa są to w stanie wyrazić”.\n– Zwęglony list","Jednostka",[],["Ionia"],"ZWYKŁE"],"04SH100":["Ostrożne Przygotowania","Aby zagrać, umieść kartę z ręki w swojej talii.\nSpójrz w Przyszłość, a następnie stwórz dokładną kopię wybranej karty w ręce.","","„Nasze dzisiejsze czyny są nasionami, z których wyrosną drzewa przyszłości”. – Tai Aspirujący Chronomanta","Zaklęcie",[],["Shurima"],"ZWYKŁE"],"04SH070":["Niegodni","Daj wrogiemu stronnikowi -4|-0 w tej rundzie.\nJeżeli masz mniej kryształów many niż twój przeciwnik, zamiast tego zabij tego stronnika.","","„Słońce po raz kolejny rozbłyśnie nad ziemiami Shurimy”. \n – Głos Powstałych","Zaklęcie",[],["Shurima"],"EPICKIE"],"04SH081":["Przędzarka Piasku Baccai","Zagraj: Przyznaj wrogowi -1|-0 i Podatność.","","Każde upuszczone przez nią ziarnko odbiera sekundę z ich życia, krusząc je niczym wiatr.","Jednostka",[],["Shurima"],"RZADKIE"],"04SH077":["Głos Powstałych","Jeżeli udało ci się awansować bohatera, sojusznicy mają +2|+0.","","– Widziałem jej przemówienie dawno temu – wiekowy żołnierz uśmiechnął się, a jego wnuczka oczami wyobraźni na moment ujrzała lśniąca złotem Shurimę i Azira, dumnie stojącego ponad miastem zachwalanym przez Głos Powstałych. – Przebudziła w nas pasję, którą od dawna uważaliśmy za straconą.","Jednostka",[],["Shurima"],"EPICKIE"],"04SH019":["Rek’Sai","Gdy Obserwuję lub Atakuję: Przyznaj Obserwującym sojusznikom +1|+0, gdziekolwiek są.\nKoniec rundy: Umieść mnie w talii.","Udało mi się zaatakować z Siłą 10+.","„Młody Jhuraa badał nieznane rejony, jak to ma w zwyczaju, gdy w małej, ukrytej jaskini natrafił na starożytne teksty! Zabraliśmy je do tłumacza w Marrowmark, gdzie okazało się, że zwoje… Zwoje mówią o pradawnej grozie, która nękała naszych przodków. O królowej. Królowej xer’sai!”. \n– Fezhaur, vekaurański starszy","Jednostka",["OBSERWATOR"],["Shurima"],"Bohater"],"04SH138":["Rozgrzeszyciel","Daj sojusznikowi +2|+1 w tej rundzie. Jeżeli w tej grze udało ci się awansować bohatera, stwórz w ręce Powrót Rozgrzeszyciela.","","„Wszyscy doradzali, żebym tego nie używał. Mówili: »Nikt nie może dzierżyć tak potężnej broni«”. – Akshan","Zaklęcie",[],["Shurima"],"ZWYKŁE"],"04SH089":["Pustynna Przyrodniczka","Zagraj: Zniszcz lokację. Jeżeli to sojusznicza lokacja, przywołaj kartę Grymaśny Niedźwiedź Skalny.","","„Kadira coś dzisiaj zniszczyła! Znowu! Tym razem to tylko kamienny mur, ale wyglądał na stary i pewnie był ważny dla czyichś przodków. A jej wymówką jest, że mury buduje się lepiej w Tereshni, ale co to ma... Zezłościła mnie”.\n– Pamiętnik Zaify","Jednostka",[],["Shurima"],"RZADKIE"],"04SH015":["Raz Krwistogrzywy","Atak: Daj wrogom -2|-0 w tej rundzie.","","„Kiedy ta gadzina się wykluła, reszta robiła zakłady, ile pociągnie. Przecież najmniejszy z miotu wybryk, pokraczny po sam czubek ogona, musi paść. Nikt tylko nie pomyślał, żeby obstawić, że mały wybryk zeżre resztę rodzeństwa. He, he”.","Jednostka",[],["Shurima"],"EPICKIE"],"04SH058":["Rzeźbiarka Piasku","Atak: Przywołaj atakującą kartę Piaskowy Żołnierz.","","Niewielu poznaje tajemnice pustyni, a jedynie garstce przyznaje się umiejętność panowania nad jej piaskami, tak jak potrafi to sam Azir. Posiadanie tej mocy i znajomość sekretów piasku to dar, który mogą otrzymać tylko najwierniejsi i najbardziej oddani stronnicy Azira.","Jednostka",[],["Shurima"],"ZWYKŁE"],"04SH080":["Zew Watahy","Aby zagrać, połóż kartę z ręki na wierzchu swojej talii.\nStwórz w ręce 2 losowych Obserwatorów.","","„Niechaj słońce nam świeci, a xer’sai śpią”.\n– Modlitwa kupców","Zaklęcie",[],["Shurima"],"ZWYKŁE"],"04SH035":["Wyczekiwana Zapłata","Stwórz w ręce kartę Szczęśliwe Znalezisko.","","„Pewnie, zdarzają się lepsze i gorsze dni, jak każdemu. W tym zawodzie te gorsze dni bywają naprawdę paskudne, a te lepsze dni są pełne złota”. – Sivir","Zaklęcie",[],["Shurima"],"ZWYKŁE"],"04SH028":["Starodawne Przygotowania","Zagraj: Spójrz w Przyszłość.\nOdlicz 2: Przywołaj kartę Tykający Golem.","","Choć można by pomyśleć, że zostały zatracone na przestrzeni czasu, pogrzebane pod wieloletnimi warstwami piasków, wszystkie maszyny były idealnie rozmieszczone i czekały cierpliwie na wybudzenie.","Lokacja",[],["Shurima"],"ZWYKŁE"],"04SH054":["Poszukiwaczka Skarbów","Gdy mnie przywołasz, stwórz w ręce kartę Piaski Przebudzenia.","","„Dobra, Davu. Włazisz tam, bierzesz… cokolwiek to jest i sprawiasz, że będziemy bogaci. Ja będę bogata. Sprawisz, że będę bogata. Jasne? A jeśli okaże się, że to pułapka, to z góry przepraszam”.","Jednostka",[],["Shurima"],"ZWYKŁE"],"04SH002":["Żniwiarz Baccai","Gdy Zgładzisz jednostkę, przyznaj mi +1|+0.","","„Wszyscy Baccai uciekli lub zostali oszczędzeni po nieudanej próbie Wyniesienia. Od tamtej pory nikt ich nie widział. Kto wie, od jak dawna kryją się w tych ciemnych grobowcach, naznaczeni piętnem swojego wstydu?” – Skryba Kah’nir, „Historia zastępu Wyniesionych”","Jednostka",[],["Shurima"],"RZADKIE"],"04SH042":["Hibernujący Niedźwiedź Skalny","Odlicz 3: Przywołaj kartę Grymaśny Niedźwiedź Skalny.","","„MAM NA IMIĘ ZAIFA I LUBIĘ PISAĆ GŁUPIE RZECZY W MOJEJ GŁUPIEJ KSIĄŻECZCE KIEDY WYDAJE MI SIĘ ŻE WSZYSCY ŚPIĄ. NAWET SAMI”.\n– Pamiętnik Zaify","Lokacja",[],["Shurima"],"ZWYKŁE"],"04SH032":["Bezduszna Miażdżygnatka","Reputacja: Kosztuję o 1 mniej. Gdy mnie przywołasz, przyznaj mi Zmiażdżenie.","","Żołnierz resztkami sił wyciągał dłoń ku swojej włóczni, ale ona mocniej przycisnęła nogę na jego piersi. Mężczyzna z jękiem opuścił rękę. – Nic z tych rzeczy – powiedziała strofującym tonem, szczerząc swoje naostrzone kły w nikczemnym uśmiechu. – Teraz to już moje.","Jednostka",[],["Shurima"],"ZWYKŁE"],"04SH055":["Zdobywczyni Ruin","","","Przed wejściem do krypt najemnicy i hieny grobowe Shurimy muszą nauczyć się przetrwać wśród mniej skrytych zagrożeń pustyni. Największym z nich był bezlitosny żar. Drugim w kolejności były roje jeźdźców z niezdrową potrzebą urządzania rzezi.","Jednostka",[],["Shurima"],"ZWYKŁE"],"04SH039":["Zilean","Zagraj: Stwórz w swojej talii 4 karty Bomby Zegarowe. Następnie Spójrz w Przyszłość.","Widziałem, jak niszczysz 2+ sojusznicze Bomby Zegarowe.","Na przestrzeni wielu lat Zilean ustanowił sieć obiecujących młodych magów z różnych czasów. Każdy z nich był w stanie doprowadzić pracę jego życia do końca, jeżeli miałoby się wydarzyć najgorsze. Choć Zilean był miłym mentorem, który zachęcał do czynienia postępów, głęboki smutek marszczył jego brwi, gdy poszukiwał samotności. W jego oczach natomiast widoczne było zmęczenie, które zrozumieć mógł jedynie ktoś, kto sam przeżył już wiele żywotów.","Jednostka",[],["Shurima"],"Bohater"],"04SH073":["Taliyah","Zagraj: Przywołaj dokładną kopię sojuszniczej lokacji.","Udało ci się przywołać 5+ lokacji.","„Krok koczownika zawsze jest lekki, gdyż nie jest obarczony ciężarem korzeni, a jego dom zawsze znajduje się za horyzontem”.\n– Społeczności Shurimy","Jednostka",[],["Shurima"],"Bohater"],"04SH091":["Khahiri Uczeń","Gdy mnie przywołasz, przyznaj mi +1|+1, jeżeli w tej grze udało ci się Spojrzeć w Przyszłość.","","– Pamiętaj, czego się nauczyliśmy – powiedział Zilean. Jego głos był niespotykanie, wręcz niepokojąco łagodny. – Jesteś pewien, że jesteś gotów?\nKhahiri obdarzył swojego mentora uspokajającym uśmiechem. – Wrócę niebawem. Poza tym od lat każdy dzień spędzałem na przygotowaniu się do tej chwili. Jeśli nie teraz, to kiedy?”","Jednostka",[],["Shurima"],"ZWYKŁE"],"04SH024":["Iglica Solna","Odlicz 2: Przywołaj kartę Grymaśny Niedźwiedź Skalny. Następnie, jeżeli w tej grze udało ci się przywołać 4+ lokacje, przyznaj Najsilniejszemu sojusznikowi +2|+2.","","Shurimański pozyskiwacz soli szybko zapamiętuje, które złoża nadają się do zebrania, a które lepiej zostawić w spokoju.","Lokacja",[],["Shurima"],"ZWYKŁE"],"04SH003":["Azir","Gdy sojusznicy atakują, przywołaj atakującą kartę Piaskowy Żołnierz.","Udało ci się przywołać 12+ sojuszników lub lokacji.","„Azir był arogancki, gdy odziedziczył tytuł imperatora Shurimy. Był ślepy. Gromadził siłę i planował swoje Wyniesienie, aby sprawować rządy nie tylko nad Shurimą, ale nad całym światem”. – Skryba Kah’nir, „Historia zastępu Wyniesionych”","Jednostka",["WYNIESIENI","PTAK"],["Shurima"],"Bohater"],"04SH011":["Badacze Ksenotypu","Gdy mnie przywołasz, przyznaj 3 losowym sojusznikom w swojej talii +3|+3.","","Pustka jest pełna niespodzianek. Każdego dnia się rozrasta i znajduje nowe sposoby infiltrowania wieży, niczym chwasty pokroju ciernistego niewidokrzewu, lecz o wiele bardziej zabójcze. Tym samym prowadzenie badań jest trudne, ponieważ wymaga równie mądrych, co zaradnych badaczy, którzy będą w stanie przewidzieć i zrozumieć zagrożenie.","Jednostka",[],["Shurima"],"RZADKIE"],"04SH130":["Akshan","Gdy mnie przywołasz lub Uderzysz: Przywołaj kartę Pałac Watażki lub rusz ją Naprzód o 1 rundę.","Karta Pałac Watażki ukończyła swoje Odliczanie. Gdy awansuję, przywołaj kartę Skarby Watażki.","„Kodeks Strażników zdaje się być pełen skomplikowanych ograniczeń. Na przykład »Nigdy nie odbieraj życia w imię zemsty« albo »Walcz dla świata, nigdy dla siebie«. A jeśli o mnie chodzi…”","Jednostka",[],["Shurima"],"Bohater"],"04SH114":["Gniew Pustyni","Przyznaj sojuszniczym kartom Piaskowi Żołnierze +1|+0, gdziekolwiek są.\nPrzywołaj dwie karty Piaskowi Żołnierze.","","Nie odpoczywają. Nie wahają się. Nie znają kompromisów, emocji czy ustępstw.","Zaklęcie",[],["Shurima"],"RZADKIE"],"04SH067":["Renekton","Gdy rzucam Wyzwanie wrogowi, daj mi +2|+1 w tej rundzie.","Zadałem 10+ pkt. obrażeń.","„Łatwo można zapomnieć, że był niegdyś człowiekiem, gdyż podobizna krokodyla tak dobrze wpasowuje się w jego zamiłowanie do krwawej walki...” \n– Skryba Kah’nir, „Historia zastępu Wyniesionych”","Jednostka",["WYNIESIENI","GAD"],["Shurima"],"Bohater"],"04SH120":["Ujrzane Możliwości","Stwórz w ręce losową lokację z Odliczaniem lub rusz swoje lokacje 1 rundę Naprzód.","","„Czas jest efemeryczny”. – Zilean","Zaklęcie",[],["Shurima"],"RZADKIE"],"04SH119":["Rykoszet","Reputacja: Kosztuję o 3 mniej.\nZadaj 1 pkt. obrażeń losowemu wrogowi lub wrogiemu Nexusowi 5 razy.","","„Zaraz może się zrobić nieciekawie”. – Sivir","Zaklęcie",[],["Shurima"],"ZWYKŁE"],"04SH068":["Nawoływacz Xer’Sai","Zagraj: Spójrz w Przyszłość.","","Nie każde xer’sai rodzi się zabójcą. Niektóre potrafią przyzywać pobratymców wrzaskami, które przeszywają na wskroś zmysły i niosą się w pustynną dal.","Jednostka",["OBSERWATOR"],["Shurima"],"ZWYKŁE"],"04SH093":["Ukształtowany Kamień","Daj sojusznikowi +1|+1 w tej rundzie.\nJeżeli udało ci się przywołać lokację w tej grze, daj mu +2|+1.","","„Z pomocą ziemi Z PEWNOŚCIĄ się obronimy!” – Taliyah","Zaklęcie",[],["Shurima"],"ZWYKŁE"],"04SH079":["Wróżenie z Piasku","Spójrz w Przyszłość.\nDaj wrogowi -2|-0 w tej rundzie.","","„Ujrzałem swoje przeznaczenie i tym razem nikt mnie nie powstrzyma”. – Azir","Zaklęcie",[],["Shurima"],"RZADKIE"],"04SH038":["Skoczek Skalny","Gdy mnie przywołasz, przywołaj kartę Wzburzone Piaski.","","„Dziś rozpoczęliśmy naszą podróż do Nashramae! Samir strasznie chce przejść przez Bezkres Sai przed kolejną pełnią i robi przez to TYLE zamieszania dookoła! Nie wiedziałam, że jedna deska do zjeżdżania po piasku może zawalić całą wydmę. Sami też nie, ale nic mu nie jest”.\n– Pamiętnik Zaify","Jednostka",[],["Shurima"],"ZWYKŁE"],"04SH104":["Konserwator","Zagraj: Rusz sojuszniczą lokację 3 rundy Naprzód.","","Za każdym razem, gdy Zilean potrzebuje chwili spokoju, powraca do ostatniego ogrodu Icathii – takiego, jakim go pamięta.","Jednostka",[],["Shurima"],"RZADKIE"],"04SH128":["Vekaurańska Wędrowczyni","Gdy mnie przywołasz, przywołaj kartę Pałac Watażki lub rusz ją Naprzód o 2 rundy.","","Widząc Akshana wiszącego pod oknem czwartego piętra, Najah przeklęła pod nosem. Ten piękniś był szybszy. Znowu. Obracając sztylet w dłoni zastanawiała się, co mu powiedzieć. Może tym razem zwróci na nią uwagę.","Jednostka",[],["Shurima"],"ZWYKŁE"],"04SH109":["Ruchome Piaski","Daj wrogowi -4|-0 lub 2 wrogom -1|-0 w tej rundzie. Zablokuj ich pozytywne słowa klucze w tej rundzie.","","Są miejsca na pustyni, gdzie stare ruiny zatopiły się wśród piasków, tworząc wydrążoną pustkę, która może wciągnąć nieuważnych podróżników w swoje odmęty. ","Zaklęcie",["ŻYWIOŁ"],["Shurima"],"ZWYKŁE"],"04SH043":["Żywe Piaski","Zadaj jednostce 4 pkt. obrażeń.\nPrzywołaj 2 karty Piaskowi Żołnierze.","","„Dalej. Otoczyć ich. Nie mogą walczyć z samą ziemią”. – Azir","Zaklęcie",[],["Shurima"],"RZADKIE"],"04SH099":["Powstańcie!","Przywołaj kartę Piaskowy Żołnierz.\nStwórz Ulotną kartę Powstańcie! w ręce.","","„Rozkaz wydany!” – Azir","Zaklęcie",[],["Shurima"],"RZADKIE"],"04SH048":["Wewnętrzne Sanktuarium","Reputacja: Kosztuję o 3 mniej.\nOdlicz 1: Stwórz w ręce 2 karty Szczęśliwe Znaleziska.","","„Na rozszyfrowanie niektórych map trzeba lat, na rozbrojenie niektórych pułapek miesięcy, a przedarcie się przez niektóre krypty trwa całymi tygodniami. Ale kiedy już ci się uda? Każda poświęcona sekunda okazuje się tego warta”. – Sivir","Lokacja",[],["Shurima"],"ZWYKŁE"],"04SH056":["Paskarka","Gdy mnie przywołasz, stwórz w ręce kartę Szczęśliwe Znalezisko.","","„Przyjacielu, tę niespotykaną piękność wyciągnęłam prosto z mitycznego Grobowca Imperatorów, z rąk samego wielkiego Renektona, a w drodze powrotnej napadło mnie dziesięciu… a nawet dwudziestu… Dwudziestu spragnionych krwi jeźdźców! Doprawdy, to istny cud, że taki skarb trafił właśnie w twoje ręce”.","Jednostka",[],["Shurima"],"ZWYKŁE"],"04SH020":["Sivir","","Udało ci się zadać 30+ pkt. obrażeń.","Sivir szła przez życie jako najemniczka, biorąc na siebie wszelkie ryzyka i nagrody, jakie wiązały się z tym wyborem. Pewna niefortunna ekspedycja niemal kosztowała ją wszystko, ale gdy jej krew wsiąknęła w piaski Shurimy, przebudzona została starożytna moc, która wkrótce miała przywrócić Sivir i jej ojczyźnie świetność.","Jednostka",[],["Shurima"],"Bohater"],"04SH057":["Inspirująca Marszałek","Gdy przywołasz innego sojusznika, daj mu +2|+0 w tej rundzie.","","Otrzymanie błogosławieństwa Azira to ogromny zaszczyt. Zaszczytu nadania błogosławieństwa w jego imieniu nie da się określić słowami.","Jednostka",[],["Shurima"],"RZADKIE"],"04SH103":["Bezlitosna Łowczyni","Zagraj: Przyznaj wrogowi Podatność.","","„I… już. Pięknie związane. Renekton lubi, kiedy jego posiłki jeszcze wierzgają”.","Jednostka",[],["Shurima"],"ZWYKŁE"],"04SH065":["Xerxa’Reth Podtytan","Atak: Jeśli moja Siła wynosi 8+, daj mi Postrach, Zmiażdżenie i Tarczę Magii w tej rundzie.","","„Podobno setki lat temu u brzegu rzeki Khaleek istniała wspaniała placówka handlowa zwana Taraleek. Pewnego sądnego dnia potężna bestia przebiła się na powierzchnię, zniszczyła to miejsce i zabiła wszystkich mieszkańców. Jaki potwór byłby do tego zdolny?” – Shurimański historyk","Jednostka",["OBSERWATOR"],["Shurima"],"EPICKIE"],"04SH034":["Ramię Zegara","Gdy mnie przywołasz, stwórz 2 karty Wieki w Oka Mgnieniu w ręce.","","Ciągły łoskot dobiegający z niższych poziomów wieży jest wywoływany przez Ramię Zegara, strażnika wieży, który miarowo nakręca skryte w jej głębinach tryby.","Jednostka",[],["Shurima"],"EPICKIE"],"04SH082":["Ścieżka wśród Ruin","Dobierz 1 kartę.\nJeżeli udało ci się Zgładzić jednostkę w tej rundzie, Zaczerpnij 2 pkt. Zdrowia z wrogiego Nexusa.","","Piachotłuki rekrutują głównie z szeregów swoich wrogów. Ktokolwiek przetrwa ich atak, otrzymuje zaproszenie. Może je przyjąć lub umrzeć.","Zaklęcie",[],["Shurima"],"RZADKIE"],"04SH075":["Zdobycz Imperatora","Daj wrogom Podatność w tej rundzie i przywołaj 6 kart Piaskowi Żołnierze.","","„Maszerujcie, moi wojownicy”. – Azir","Zaklęcie",[],["Shurima"],"EPICKIE"],"04SH018":["Rytuał Dominacji","Zabij sojusznika lub zniszcz jeden ze swoich kryształów many, aby dać wszystkim wrogom -2|-0 w tej rundzie.","","„My walczymy, oni krwawią!” – Renekton","Zaklęcie",[],["Shurima"],"RZADKIE"],"04SH009":["Rozszalały Baccai","Zagraj: Jeżeli udało ci się Zgładzić 4+ jednostki w tej grze, dowolny wróg i ja Uderzamy siebie nawzajem.","","Nienawiść chowającego urazę jedynie się pogłębia, nawet jeżeli ci, wobec których żywi on gniew, od dawna nie żyją.","Jednostka",[],["Shurima"],"RZADKIE"],"04SH049":["Poro Przeznaczenia","Początek rundy: Jeżeli udało ci się awansować bohatera, przemień mnie w kartę Błogosławiona Poro.","","Nie do końca wiedziała, co takiego znalazła… ale było błyszczące i wyglądało na przyzwoitą przekąskę.","Jednostka",["PORO"],["Shurima"],"ZWYKŁE"],"04SH045":["Wyczerpanie","Daj wrogowi -2|-0 i Podatność w tej rundzie.","","Mieszkańcy pustyni wiedzą, jak unikać prażących i bezlitosnych promieni słońca. Z tych, którzy przybywają nieprzygotowani na ich żar, siła i energia uchodzą w zawrotnym tempie.","Zaklęcie",[],["Shurima"],"ZWYKŁE"],"04SH037":["Rozpruta Ziemia","Przywołaj 2 karty Wzburzone Piaski.\nDobierz 1 kartę.","","Choć piaski Bezkresu Sai ujmują swym pięknem, nie są to tereny dla słabych. Wiele żyć przepada wśród wydm i choć dużą część z nich odbierają xer’sai, to sama ziemia też nie pozostaje bez winy.","Zaklęcie",["ŻYWIOŁ"],["Shurima"],"RZADKIE"],"04SH107":["Powstanie Wyniesionych","Awansuj wszystkich Wyniesionych sojuszników na 1. poziomie.","","„Przyszłość zostanie zapisana przez tych, którzy wniebowstąpili!” – Azir","Zaklęcie",[],["Shurima"],"EPICKIE"],"04SH047":["Nasus","Mam +1|+1 za każdą jednostkę, którą udało ci się Zgładzić w tej grze.","Udało mi się Uderzyć za 10+ pkt. obrażeń jednym Uderzeniem.","„Nowo zdobyte przez Nasusa błogosławieństwo pozwoliło mu spędzić niezliczone żywoty na badaniach oraz kontemplacji natury życia i śmierci. Po upadku Shurimy ta sama długowieczność stała się również jego przekleństwem”. \n– Skryba Kah’nir, „Historia zastępu Wyniesionych”","Jednostka",["WYNIESIENI","PIES"],["Shurima"],"Bohater"],"04SH097":["Kurator Sanktuarium","Zagraj: Zabij wrogiego stronnika. Jeżeli udało ci się zgładzić 13+ jednostek w tej grze, zamiast tego zabij wszystkich wrogich stronników, a następnie przywołaj moją kopię.","","Baccai mają za zadanie ochronę wewnętrznego sanktuarium, aby bronić ukrytych w nim pradawnych skarbów, a także dla dobra śmiertelników, którzy uważają się za wystarczająco bystrych lub potężnych, aby znieść ciężar osądu Kustosza.","Jednostka",[],["Shurima"],"EPICKIE"],"04SH026":["Stróż Wydm","Gdy mnie przywołasz, przywołaj kartę Piaskowy Żołnierz.","","„Gdy imperator wydaje rozkaz, zarówno piasek, jak i ja go wykonujemy”.","Jednostka",[],["Shurima"],"ZWYKŁE"],"04SH102":["Złocista Ambasadorka","Przymierze: Dobierz bohatera i przyznaj mu +2|+2.","","„Nasza świetlana przyszłość czeka tuż pod piaskami. To my musimy utorować drogę dla Azira. Złociste imperium pustyni powstanie po raz kolejny!”","Jednostka",[],["Shurima"],"ZWYKŁE"],"04SH001":["Aspirujący Chronomanta","Zagraj: Spójrz w Przyszłość.","","W czasach, kiedy Tai studiował tajniki chronomancji, musiał pogodzić swoją niepewność z determinacją. Lepiej było mieć nadzieję na potencjalne zwycięstwo niż zamartwiać się o wszystko, co może pójść nie tak.","Jednostka",[],["Shurima"],"ZWYKŁE"],"04SH022":["Łamacz Wydm Xer’Sai","","","Choć xer’sai to wybitni kopacze tuneli, tylko ich łamacze wydm są na tyle potężni i silni, by przebić się przez lite skały macierzyste ciągnące się poprzez Bezkres Sai i umożliwić dalsze polowanie w nowych regionach.","Jednostka",["OBSERWATOR"],["Shurima"],"RZADKIE"],"04SH030":["Chronoskok","Daj sojuszniczemu bohaterowi „Następnym razem, gdy w tej rundzie miałaby mnie spotkać śmierć, ulecz mnie całkowicie i przyznaj mi +3|+3”.","","„Nie możemy powstrzymać nieuniknionego… ale możemy je opóźnić”. – Zilean","Zaklęcie",[],["Shurima"],"RZADKIE"],"04SH013":["Przetrwalnia","Gdy mnie przywołasz, dobierz 1 kartę.\nOdlicz 2: Dobierz 1 kartę.","","Zilean ukazuje tym, których przyprowadza do swojej wieży, co tak naprawdę chcą odzyskać. Pokazuje im to, co Konserwator jest w stanie pokazać, nawet jeżeli są to tylko chwile.","Lokacja",[],["Shurima"],"RZADKIE"],"04SH062":["Pogrzebany Słoneczny Dysk","Początek gry: Przywołaj moją 1 kopię ze swojej talii, jeżeli wszystkie karty z twojej talii pochodzą z Shurimy.\nOdlicz 25: Przywróć Słoneczny Dysk.\nPrzenoszę się 9 rund Naprzód za każdy awans Wyniesionego sojusznika w tej grze.","","Gdy Azir spojrzał na Słoneczny Dysk stolicy Shurimy, nie widział w nim tego, czym był, lecz to, czym mógłby być – widział w nim klucz do przywrócenia Shurimie jej dawnej chwały.","Lokacja",[],["Shurima"],"EPICKIE"],"04SH016":["Wysysające Uderzenie","Sojusznik Uderza jednostkę.\nJeżeli ta jednostka zginie, przyznaj sojuszniczym bohaterom +2|+2, gdziekolwiek są.","","„Twa dusza zostanie osądzona”. – Nasus","Zaklęcie",[],["Shurima"],"RZADKIE"],"04SH125":["Vekaurańska Włamywaczka","Zagraj: Daj sojusznikowi +2|+0, aby dać wrogowi -2|-0 w tej rundzie.","","Tena czekała cierpliwie, aż żrąca plwocina jej zwierzaka pokona złocone kraty tylnej bramy pałacowej. Za rogiem czekała ją góra niewysłowionych bogactw… o wiele większych niż to, co wystarczyłoby do przywrócenia Vekaurze jej dawnego blasku.","Jednostka",[],["Shurima"],"RZADKIE"],"04SH108":["Ostrze-Bumerang","Sojusznik Uderza Najsilniejszego i Najsłabszego wroga jeden po drugim.","","„Lepiej się schyl”. – Sivir","Zaklęcie",[],["Shurima"],"RZADKIE"],"04SH066":["Czas w Butelce","Spójrz w Przyszłość i rusz sojuszniczą lokację 2 rundy Naprzód.","","„Gdybyście tylko widzieli czas takim, jakim ja go widzę, wiedzielibyście, iż nie jest on niezmienny”. – Zilean","Zaklęcie",[],["Shurima"],"ZWYKŁE"],"04SH021":["Khahiri Przywrócony","Gdy mnie przywołasz, stwórz w swojej talii moją kopię. Gdy ujrzysz mnie W Przyszłości, przyznaj wszystkim moim sojuszniczym kopiom +2|+2, gdziekolwiek są.","","Khahiri zniknął tylko na moment, po czym nagle pojawił się ponownie. Na widok starszego o niemal dekadę mężczyzny z dziwną, śmiercionośnie wyglądającą bronią w dłoniach, z tłumu dało się słyszeć odgłosy trwogi i troski.","Jednostka",[],["Shurima"],"RZADKIE"],"04SH101":["Oddana Rada","Początek rundy: Jeżeli udało ci się awansować bohatera, ulecz swoich bohaterów i Nexus o 2 pkt. Zdrowia.","","„Obowiązuje mnie przysięga złożona Azirowi i Shurimie, mojej ojczyźnie! Czy ty nie masz zamiaru jej złożyć?”","Jednostka",[],["Shurima"],"RZADKIE"],"04SH012":["Szanowany Hierofant","Gdy mnie przywołasz, twoja karta Pogrzebany Słoneczny Dysk rusza Naprzód o 3 rundy.","","„Och! To Padjuman, członek starszyzny Nashramae! Tatusiu, dzisiaj chyba wszyscy przybyli do naszego miasta!” – Podekscytowany przechodzień","Jednostka",[],["Shurima"],"ZWYKŁE"],"04SH031":["Obiecująca Przyszłość","Przyznaj sojuszniczej lokacji „Efekt ukończenia mojego Odliczania aktywuje się dwa razy”.","","„Śmiertelnicy tak wiele czasu spędzają na czekaniu. Moją najszczerszą nadzieją jest, że każdy z nich otrzyma sowitą nagrodę za swą cierpliwość”. – Zilean","Zaklęcie",[],["Shurima"],"EPICKIE"],"04SH004":["Ciężar Osądu","Zadaj 2 pkt. obrażeń bohaterowi lub 4 pkt. obrażeń stronnikowi.","","„Jedno życie w zamian za tak wiele innych. Jedno życie, by inni żyli pełnią możliwości”. – Nasus","Zaklęcie",[],["Shurima"],"ZWYKŁE"],"04SH059":["Rytuał Negacji","Zabij sojusznika lub zniszcz jeden ze swoich kryształów many, aby zatrzymać wszystkie wrogie Szybkie zaklęcia, Powolne zaklęcia i Umiejętności.","","Analiza to główny filar chronomancji. Wiele działań należy powstrzymać, aby znaleźć przyszłe rozwiązania.","Zaklęcie",[],["Shurima"],"EPICKIE"],"04SH044":["Nakręcany Opiekun","Zagraj: Rusz sojuszniczą lokację 2 rundy Naprzód.","","Konstrukty strzegące wieży Zileana są w stanie znosić surowość pustyni przez całe tysiąclecia, i to nie tylko ze względu na ich sprytną konstrukcję.","Jednostka",[],["Shurima"],"ZWYKŁE"],"04SH076":["Starożytna Klepsydra","Unicestwij sojusznika, aby przywołać kartę Posąg Inercji w jego miejsce wraz z tym sojusznikiem przechowywanym wewnątrz.","","„Och, Tai! Chodź tutaj! Przyda nam się twoja pomoc”.\n– Xetsa, Badaczka Pustki","Zaklęcie",[],["Shurima"],"RZADKIE"],"04SH118":["Piaski Przebudzenia","Przywołaj kartę Piaskowy Szarżownik.","","„Skrzynia może być coś warta, ale to, co siedzi w środku, nie ma żadnej wartości. To znaczy, że nie warto jej otwierać. Mówię z doświadczenia”. – Sivir","Zaklęcie",[],["Shurima"],"ZWYKŁE"],"04SH072":["Wieszczka","Gdy mnie przywołasz, przyznaj sojuszniczym bohaterom i lokacjom Tarczę Magii.","","„Ach, nie spodziewałeś się ujrzeć wody na środku pustyni. Nie obawiaj się. Podejdź, zaspokój pragnienie, obmyj stopy. Odpocznij chwilę w cieniu. Oto nowa Shurima Azira, a tu jest oaza”.","Jednostka",[],["Shurima"],"ZWYKŁE"],"04SH041":["Zwiadowczyni Sai","Zagraj: Spójrz w Przyszłość. Jeżeli wybierzesz lokację, przyznaj mi Nieuchwytność.","","„Mieliśmy dziś kłopoty! Ogromna burza szła z zachodu, a Taliyah minęła na południu tunele xer’sai. Ja zauważyłam świątynię na północy i póki co jesteśmy bezpieczni w jej murach z terakoty. Pozostali już śpią, a mój płomień, tak jak ja, też już przysypia. Obym spała dobrze”.\n– Pamiętnik Zaify","Jednostka",[],["Shurima"],"ZWYKŁE"],"04SH005":["Krwawy Maruder","","","Piachotłuki wszystko robią wspólnie ze swoimi towarzyszami. Walczą, polują, zabijają… i jedzą.","Jednostka",[],["Shurima"],"ZWYKŁE"],"04SH083":["Dzikie Przeczucie","Spójrz w Przyszłość.","","„Płetwa wzbudza strach, lecz to zęby niosą śmierć”. \n– Shurimańskie powiedzenie","Zaklęcie",[],["Shurima"],"RZADKIE"],"04SH092":["Nadszedł Czas","Przywołaj kartę Tykający Golem.\nJeżeli w tej grze udało ci się Spojrzeć w Przyszłość, przywołaj zamiast tego 2 takie karty.","","„Chodź tu i przestań zrzędzić! Masz piach w zębatkach”. \n– Tai Aspirujący Chronomanta","Zaklęcie",[],["Shurima"],"ZWYKŁE"],"04SH046":["Chimera Piaskowa","Kosztuję o 1 mniej za każdy atak wyprowadzony przez sojusznika w tej grze.","","Shurimanie spostrzegli, że powrotowi Azira towarzyszyło pojawienie się pradawnych bestii z legend – stworzonych z piasku, co jednak nie ujmuje ich majestatowi.","Jednostka",[],["Shurima"],"RZADKIE"],"04SH105":["Grobowiec wśród Piasków","Gdy sojusznicy atakują, przywołaj atakującą kartę Piaskowy Szarżownik.","","Gdy przechodzili przez wąwóz, Rzeźbiarka Piasku wymówiła magiczne słowa. Powiew wiatru przeszedł echem przez kanion, zamieniając się w ryk nadciągających kopyt.","Lokacja",[],["Shurima"],"RZADKIE"],"04SH131":["Lina z Hakiem","Sojusznik obrany przez ciebie za cel w tej rundzie Uderza wroga.","","„Nikt nie spodziewa się liny z hakiem!” – Akshan","Zaklęcie",[],["Shurima"],"RZADKIE"],"04SH074":["Młode Xer’Sai","","","Gdy łowcy unieruchomią karawanę, niekiedy wycofują się, pozwalając swym młodym zaatakować. W ten sposób niewyrośnięte xer’sai udoskonalają swój instynkt, pozwalający rozróżnić dźwięki pustyni od tych, które wydają ich ofiary.","Jednostka",["OBSERWATOR"],["Shurima"],"ZWYKŁE"],"04SH137":["Brzęcząca Chmara","Gdy mnie przywołasz, stwórz w ręce moją kopię, jeżeli w tej grze udało ci się awansować bohatera.","","Myślano, że ogromne skarabeusze zginęły w czasach upadku Imperium Shurimy. Jednak pełzające macki Mgły sięgnęły głęboko w piaski, związując te starożytne stworzenia przysięgą wierności wobec Viego.\n","Jednostka",[],["Shurima"],"EPICKIE"],"04SH069":["Bezwzględny Drapieżnik","Daj sojusznikowi +2|+0, aby dać wrogowi Podatność w tej rundzie.","","„Rozerwać ich na strzępy!” – Renekton","Zaklęcie",[],["Shurima"],"ZWYKŁE"],"04SH121":["Rytuał Wezwania","Zabij sojusznika lub zniszcz jeden ze swoich kryształów many, aby dobrać bohatera.","","„Konieczna ofiara”. – Nasus","Zaklęcie",[],["Shurima"],"ZWYKŁE"],"04SH110":["Tkanie Skał","Pokaż lokację, na którą starczy ci many.","","„Chodźmy, mamy wiele do zobaczenia!” – Taliyah","Zaklęcie",["ŻYWIOŁ"],["Shurima"],"EPICKIE"],"04SH051":["Piedestał Imperatora","Gdy sojusznicy atakują, przywołaj atakującą kartę Piaskowy Żołnierz.","","Rzeźbiarze Piasku wznieśli ręce, kształtując piasek w znajomą formę uzbrojonych żołnierzy bez twarzy – niezmordowaną armię gotową do walki za ich boskiego imperatora. ","Lokacja",[],["Shurima"],"RZADKIE"],"04SH106":["Duchowy Ogień","Daj wrogom -2|-0 i „Koniec rundy: Zadaj mi 2 pkt. obrażeń” w tej rundzie.","","„Ich dusze będą płonąć”. – Nasus","Zaklęcie",[],["Shurima"],"RZADKIE"],"04SH129":["Vekaurański Osiłek","Uderzenie: Stwórz w ręce kartę Szczęśliwe Znalezisko.","","– Dobra, Barb. To ostatni strażnicy na tym piętrze, ale nadal musimy się pilnować.\n– BLARGH-BLAAA!\n– Użyj wewnętrznego głosu, Barbara.\n– Blarb.\n– O to chodzi.","Jednostka",[],["Shurima"],"RZADKIE"],"04FR006":["Inkwizytor Draklornów","Gdy mnie przywołasz, przywołaj kartę Zamarznięty Niewolnik.\nKoniec rundy: Jeżeli Odliczanie którejkolwiek twojej karty Zamarznięci Niewolnicy wynosi 4 lub mniej, rusz Naprzód i zmniejsz je do 0.","","„Moja pani przychodzi do mnie w snach. Jej głos jest zaledwie szeptem. „Za mną\" – nakazuje. Nie śmiem nie spełnić jej żądania”.","Jednostka",[],["Freljord"],"EPICKIE"],"04FR012":["Pogrzebanie pod Lodem","Unicestwij każdego z wrogów, aby przywołać kartę Lodowy Grobowiec w ich miejsce wraz z tym wrogiem przechowywanym wewnątrz.","","„Z czasem zimno przenika przez wszystko”. – Lissandra","Zaklęcie",["ŻYWIOŁ"],["Freljord"],"EPICKIE"],"04FR016":["Łupy Wojenne","Przyznaj sojusznikowi +1|+2.\nGrabież: Zamiast tego przyznaj +2|+4.","","„Wy, Avarosanie, tylko słabniecie i popuszczacie pasa na swoich żyznych ziemiach. Śpijcie więc dziś spokojnie, wy godne pożałowania miernoty, i śnijcie o skarbach jutra, podczas gdy my będziemy je zdobywać”. – Vrynna, Matka Blizn","Zaklęcie",[],["Freljord"],"ZWYKŁE"],"04FR013":["Odporność na Zimno","Otrzymaj pusty kryształ many i przyznaj sojusznikowi +0|+2.","","„Strzeż się lodu… a co ważniejsze… strzeż się tego, co pod lodem!” – Napis wyskrobany na ścianie tawerny we Freljordzie","Zaklęcie",["ŻYWIOŁ"],["Freljord"],"ZWYKŁE"],"04FR005":["Lissandra","Gdy mnie przywołasz, przywołaj kartę Zamarznięty Niewolnik i rusz ją Naprzód o 2 rundy.","Udało ci się przywołać 2+ sojuszników o koszcie 8+. Gdy awansuję, stwórz kartę Obserwator w ręce.","„Obserwatorzy czają się tuż za tymi ścianami, zawieszeni w lodzie, zamrożeni w czasie... a podczas gdy oni czekają, ja muszę wprowadzić w życie moje plany...”","Jednostka",[],["Freljord"],"Bohater"],"04FR011":["Ulegnij Zimnu","Nałóż Odmrożenie na wroga.\nPrzywołaj kartę Zamarznięty Niewolnik.","","„Zimno wyzwala wiele reakcji. Poznajmy twoją”. – Lissandra","Zaklęcie",["ŻYWIOŁ"],["Freljord"],"ZWYKŁE"],"04FR001":["Zamarznięty Niewolnik","Odlicz 9: Przywołaj kartę Niewolnik z Mroźnej Straży.","","W szeregach chaotycznej armii Trundle’a istotnie znajdowało się wystarczająco nierozgarniętych wojowników, których można by użyć jako mięso armatnie, jednak Lissandra pragnęła czegoś bardziej lojalnego – czegoś, co służyłoby tylko i wyłącznie jej...","Lokacja",[],["Freljord"],"ZWYKŁE"],"04FR007":["Pogrzebanie","Unicestwij jednostkę, aby przywołać kartę Lodowy Grobowiec w jej miejsce wraz z tą jednostką przechowywaną wewnątrz.","","„Klękaj... albo zamarzaj”. – Lissandra","Zaklęcie",["ŻYWIOŁ"],["Freljord"],"RZADKIE"],"04FR017":["Dar Przodków","Przyznaj pierwszemu sojusznikowi z wierzchu swojej talii +2|+2.\nOświecenie: Przyznaj wszystkim sojusznikom w swojej talii +2|+2.","","Nieposkromione zimno i bezlitosne burze Freljordu zabijają większość śmiałków wkraczających na jego pustkowia. Ci, którym uda się przetrwać, znajdują w sobie jednak wewnętrzną siłę, gnającą ich naprzód przez życie.","Zaklęcie",[],["Freljord"],"ZWYKŁE"],"04FR014":["Wąwóz Rozkładu","Gdy mnie przywołasz, ulecz swój Nexus o 2 pkt.\nOdlicz 1: Zadaj 2 pkt. obrażeń WSZYSTKIM jednostkom.","","Przedziwne kształty uformowane z wykwitów mrocznego lodu pokrywają całą powierzchnię wzdłuż brzegu wąwozu. Skierowane na zewnątrz kolce odstraszają wszystkich potencjalnych intruzów.","Lokacja",[],["Freljord"],"RZADKIE"],"04FR009":["Odłamek Lodu","Zadaj 1 pkt. obrażeń WSZYSTKIEMU.","","„Pogrzebię świat pod lodem”. – Lissandra","Zaklęcie",["ŻYWIOŁ"],["Freljord"],"ZWYKŁE"],"04FR015":["Sławetny Poro","Gdy mnie przywołasz, przyznaj sojuszniczym Poro losowe słowo klucz.","","Istnieje pewna legendarna postać, znana wszystkim Poro. Według opowiadań podczas podróży obdarowuje on swoich puchatych przyjaciół wszelkiego rodzaju upominkami wykutymi w magiczny sposób.","Jednostka",["PORO"],["Freljord"],"RZADKIE"],"04FR019":["Szronozębna Opiekunka","Gdy mnie przywołasz, przywołaj kartę Sfora Szronozębnych.","","Szronozębne wilki otoczyły drüvaska – przyczajone, ostrożne. Czuć było od niego odór śmierci, drażniący i przytłaczający.","Jednostka",["PIES"],["Freljord"],"RZADKIE"],"04FR018":["Przerażający Strażnik","Gdy jestem w ręce, Początek rundy: Jeśli posiadasz 2+ Yeti, przywołaj mnie i stwórz moją kopię w swojej talii.\nZagraj: Dobierz Yeti.","","„…na dodatek są przebiegłe! Gdy byłem tam ostatni raz, udało mi się znaleźć schronienie w jaskini, a w niej śpiące pacholęta. Chciałem trzymać się z daleka, ale wtedy wrócił jeden z wielkoludów, wysoki jak góra i cały pokryty lodem! A teraz słuchaj, bo…” – Bełkoczący Bjerg","Jednostka",["YETI"],["Freljord"],"EPICKIE"],"04FR010":["Trzy Siostry","Stwórz w ręce Ulotną kartę Błyskawiczne Zamrożenie, Gniew Północy lub Pogrzebanie.","","Freljordzkie siostry – Avarosa, Serylda i Lissandra – były w posiadaniu nieposkromionej mocy. Każda z nich postanowiła jednak wykorzystać ją w odmienny sposób – obrały rozbieżne ścieżki łaski, wojny i nikczemności.","Zaklęcie",[],["Freljord"],"RZADKIE"],"04NX002":["Wyszeptane Słowa","Reputacja: Kosztuję o 2 mniej.\nDobierz 2 karty.","","Przed nowinami – pogłoski. Przed pogłoskami – zagranie. Przed zagraniem – uknuty plan.","Zaklęcie",[],["Noxus"],"RZADKIE"],"04NX010":["Cierń Róży","Gdy mnie przywołasz, stwórz w ręce kartę Przebiegłość.","","„Aelano, moja najdroższa przyjaciółko i towarzyszko! Czy widziałaś ostatnio lorda Duina...? A to szkoda. Miałam ogromną nadzieję, że uda mi się z nim zobaczyć. Mam tylko nadzieję, że nie forsował się dzisiaj. Nie zniosłabym, gdyby coś się stało staruszkowi...” – Lady Auvray, Szpieg Czarnej Róży","Jednostka",[],["Noxus"],"ZWYKŁE"],"04NX021":["Walecznik w Stanie Spoczynku","Gdy obierasz mnie za cel, przyznaj mi +1|+0.","","Po stoczeniu niezliczonych bitw Beryn przysiągł nigdy więcej nie dobywać miecza, nawet jeśli miałoby to oznaczać pożegnanie się z życiem. Lecz kiedy dziwne mgły przetoczyły się przez Noxus i zawładnęły Theą, wiedział, że złamie przysięgę. Musiał ją uwolnić za wszelką cenę.","Jednostka",[],["Noxus"],"RZADKIE"],"04NX022":["Zniszczony Walecznik","Gdy mnie przywołasz, stwórz w ręce kartę Najazd o Północy.","","Po zakończeniu wyroku Thea wiedziała, że nigdy już nie wróci do swoich ludzi. Wojna – oraz Noxus – zmieniły ją i uczyniły z niej zabójczynię. Nie wiedziała już, co to pokój. Teraz wykorzystywała swoje nowe umiejętności dla zarobku na arenach.","Jednostka",[],["Noxus"],"RZADKIE"],"04NX015":["Krwawy Interes","Reputacja: Kosztuję o 2 mniej.\nSojusznik o Sile 5+ Uderza wroga.","","„Największym zagrożeniem jest to, które pozostaje niezauważone”. – LeBlanc","Zaklęcie",[],["Noxus"],"ZWYKŁE"],"04NX019":["Wyrywający Się Zębacz","Gdy wróg mnie zablokuje, daj mi +3|+0 w tej rundzie.","","Zaskoczony odpornością stworzenia, które znaleźli na wybrzeżu Ionii, młody generał nalegał, aby zabrać je do swojej ojczyzny i sprawdzić jego prawdziwą siłę.","Jednostka",["GAD"],["Noxus"],"EPICKIE"],"04NX008":["Zajadły Taktyk","Reputacja: Kosztuję o 2 mniej.\nGdy mnie przywołasz, Zjednocz Siły.","","W obrębie wewnętrznych komnat Czarnej Róży noxiańska szlachta zagrywa swoimi pionkami, a śmierć spada na odległe od nich ofiary.","Jednostka",[],["Noxus"],"RZADKIE"],"04NX006":["Szpieg Czarnej Róży","Reputacja: Gdy mnie przywołasz, przemień mnie w dokładną kopię Najsilniejszego sojusznika, który Uderzył w tej rundzie.","","„Tajemnica jest warta tylko tyle, ile kosztuje jej dochowanie”.","Jednostka",[],["Noxus"],"EPICKIE"],"04NX001":["Naśladowca","Reputacja: Kosztuję o 3 mniej.\nGdy w tej rundzie zagrasz kolejne zaklęcie, skopiuj je na te same cele.","","Naśladowanie jest pochlebstwem, a pochlebstwo potrafi być zabójcze.","Zaklęcie",[],["Noxus"],"RZADKIE"],"04NX004":["LeBlanc","","Widziałam, jak zadajesz 15+ pkt. obrażeń. Gdy awansuję, stwórz w ręce kartę Lustrzany Obraz.","„Już, dobrze, nie ma potrzeby, żebyśmy sprzeczali się między sobą. Na chwilę obecną powstrzymamy się od pochopnych działań. Zbierzmy się ponownie po wysłuchaniu naszego emisariusza. Przecież...”","Jednostka",[],["Noxus"],"Bohater"],"04NX016":["Skowyczący Przędnik","Atak: Daj sojuszniczym Pająkom +2|+0 w tej rundzie.","","„Dalej, moje maleństwo. Niech pozostali usłyszą twój głos. Wiesz, jak bardzo ich to ekscytuje. Wiesz, że mnie to cieszy”. – Elise","Jednostka",["PAJĄK"],["Noxus"],"RZADKIE"],"04NX007":["Atakhan Niosący Zniszczenie","Zagraj: Wskrześ Najsilniejszego poległego sojusznika.\nAtak: Przyznaj mi Siłę równą wartości łącznej Siły wszystkich sojuszników.","","Bezimienne wynaturzenie górowało nad nimi w wypełnionej dymem komorze. Magowie śpiewali pozbawione harmonii pieśni, a lęk w ich głosach rósł, wywołując coraz bardziej rozgorączkowane tony. Potwór wdychał ich narastający strach, z każdym oddechem niewyobrażalnie przybierając na sile.","Jednostka",[],["Noxus"],"EPICKIE"],"04NX018":["Szkarłatny Krwiopijca ","Następnym razem, gdy przywołasz kolejnego sojusznika, zadaj mu 1 pkt. obrażeń i przyznaj mi +1|+1.","","„Wiesz, rzadko kto trzyma je jako zwierzaki. Wystarczy jedno draśnięcie tych pazurów, żeby rozpłatać żyłę… ale mnie to nie przeszkadza”. – Clara, Szkarłatna Adeptka","Jednostka",["KOT"],["Noxus"],"ZWYKŁE"],"04NX003":["Znak Złośliwości","Reputacja: Kosztuję o 2 mniej.\nZadaj 2 pkt. obrażeń dowolnemu celowi.","","Po wygranej bitwie nie można się wahać. Trzeba przeć naprzód, ścigać i unicestwić wroga.","Zaklęcie",[],["Noxus"],"ZWYKŁE"],"04NX017":["Przewaga Liczebna","Przywołaj 2 karty Maruderzy Legionu.","","Choć żołnierze Noxusu rzadko pozostawiają ofiary przy życiu, maruderzy robią to jeszcze rzadziej.","Zaklęcie",[],["Noxus"],"ZWYKŁE"],"04NX009":["Cierniste Ostrze","Daj sojusznikowi +5|+0 w tej rundzie.","","„Będziesz zachowywać się z uprzejmością i wdziękiem. Będziesz schlebiać i unieszkodliwiać. Będziesz słuchać. Uczyć się. A gdy nadejdzie czas, uderzysz i Z PEWNOŚCIĄ zabijesz”. – LeBlanc","Zaklęcie",[],["Noxus"],"ZWYKŁE"],"04SI005":["Kindred","Kiedy w każdej rundzie po raz pierwszy uda ci się Zgładzić jednostkę, oznaczamy Najsłabszego wroga.\nKoniec rundy: Zabij oznaczone przez nas jednostki.","Widzieliśmy, jak udało ci się Zgładzić 2+ oznaczone przez nas jednostki.","Był niegdyś mężczyzna samotny\nCo na poły rozpłatał się dwie\nSmutek jego stał się ulotny\nGdy z jednej istoty powstały dwie.","Jednostka",[],["Wyspy Cienia"],"Bohater"],"04SI055":["Viego","Gdy w danej rundzie po raz pierwszy zginie inny sojusznik, przywołaj kartę Wdzierająca Się Mgła.","Widziałem śmierć sojuszników o łącznej Sile 20+.","„Jest w młodym królu coś, co wielce mnie niepokoi. Coś, co skrywa się w jego sercu… Głód, którego nie sposób zaspokoić, pragnienie, którego nie można ukoić”. \n– Z zapisków Nunyo Necrita z Camavoru","Jednostka",[],["Wyspy Cienia"],"Bohater"],"04SI016":["Podjadacz Dusz ","Zagraj: Zabij sojusznika, aby dobrać 2 karty.","","Kryją się w ciemnościach, czekając na zmęczone kiwnięcie głową lub nieobecny umysł. Potem już tylko pazury, bezdenna paszcza, aż w końcu – ciemność.","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"04SI007":["Upiór z Eteru","Zagraj: Zabij sojusznika, aby zabić wroga.","","„Gdy mój czas w tym miejscu dobiega końca, łapię się na rozmyślaniu nie nad moją pierwszą, lecz tą drugą śmiercią. Kim będzie ostatnia dusza, która będzie pamiętać moje imię? I kiedy ona też już opuści ten świat… co wtedy stanie się ze mną?” – Dostojny Dobroczyńca","Jednostka",["PTAK"],["Wyspy Cienia"],"RZADKIE"],"04SI011":["Aż po Zmierzch","Dobierz 1 kartę.\nZmrok: Aktywuj efekt Zmroku sojusznika, ignorując wszelkie wzmianki o obieraniu celu.","","„Podejdź, dziecko. Nie ma powodu do obaw”. \n – Matka w Masce","Zaklęcie",[],["Wyspy Cienia"],"RZADKIE"],"04SI018":["Twisted Treeline","Jeśli widziałem 3+ atakujących sojuszników, mających Postrach lub Zmrok, zniszcz mnie, by przywołać kartę Vilemaw.","","Ołtarze mogą stać puste, a ścieżki nieskalane,\nlecz w mroku czai się zło, przez głupców zapomniane.","Lokacja",[],["Wyspy Cienia"],"EPICKIE"],"04SI015":["Skarabeusz Morski","Gdy zginie inny sojusznik lub Ostatnie Tchnienie: Wyrzuć 1 kartę.","","„No dobra, łachudry, wciągać te pułapki! I pamiętajcie, zobaczy kto jakiego morskiego skarabeusza, to ma odciąć linę i przejść do następnej. Nie mam zamiaru ryzykować kilem za cokolwiek one tam i tak już na pół zeżarły, słyszyta mnie?” \n – Kapitan z Bilgewater","Jednostka",["POTWÓR MORSKI"],["Wyspy Cienia"],"RZADKIE"],"04SI004":["Skrzydła i Fala","Zagraj: Zagraj mnie jako kartę Pierwsza Fala lub jako kartę Ostatni Powiew.","","W Zakonie Kinkou mówi się jedynie o dwóch bóstwach: pierwszej fali, która kołysze życie w swych ciepłych wodach, oraz ostatnim powiewie wiatru, który porywa życie wraz z jego końcowymi, lodowatymi westchnieniami.","Jednostka",[],["Wyspy Cienia"],"EPICKIE"],"04SI017":["Pieśń Wysp","Przyznaj sojusznikowi Kradzież Życia, Postrach i Efemeryczność.","","„Podejdź, dziecko. Patrz, jak ja patrzę. Czuj, jak ja czuję. Nie obawiaj się ciemności”. – Ożywiający Płomienie","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"04SI054":["Camavorski Żołnierz","Gdy mnie przywołasz, przywołaj kartę Wdzierająca Się Mgła.","","Żołnierze z Camavoru maszerowali u boku Viego za życia, a następnie i po śmierci. Ich lojalność była niezłomna.","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"04SI001":["Jagnięcy Spokój","Daj Najsłabszemu sojusznikowi „Nie mogę otrzymać obrażeń ani zginąć” w tej rundzie.","","„Zabłyśnij raz jeszcze, nim nastanie koniec”. – Owca","Zaklęcie",[],["Wyspy Cienia"],"EPICKIE"],"04SI056":["Wyczerpująca Mgła","Zaczerpnij 2 pkt. Zdrowia z 2 wrogów.","","„Wezmę to, co chcę, a odstąpię od tego, czego nie chcę”. \n– Viego","Zaklęcie",[],["Wyspy Cienia"],"RZADKIE"],"04SI012":["Astralny Lis","Zagraj: Zabij sojusznika, by zadać 3 pkt. obrażeń wrogiemu Nexusowi.","","Wiele targońskich plemion opowiada o Lisie, bogu śmierci uosabianym z samotną gwiazdą na nocnym niebie. Legenda głosi, że gdy tylko ktoś umrze, Lis schodzi z góry i unosi duszę martwej istoty ku niebu, by stworzyć własny, mroczny gwiazdozbiór.","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"04SI029":["Rozpacz","Wybierz jednostkę, która Uderzy twój Nexus, a następnie zabij ją.","","„Oddałem wszystko, by ją znaleźć, a i tak to za mało”. \n– Viego","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"04SI009":["Przędzarz Dusz","Gdy mnie przywołasz, przyznaj mi +1|+1 i Postrach, jeżeli w tej rundzie umarł sojusznik.","","„Żył kiedyś niefortunny, młody mężczyzna, który zalecał się do pajęczycy, ani przez moment nie podejrzewając, że skończy w jej sieci…”","Jednostka",["PAJĄK"],["Wyspy Cienia"],"ZWYKŁE"],"04SI013":["Matka w Masce","Zagraj: Zabij sojusznika, aby przyznać mi jego statystyki i słowa klucze.","","Mówią, że to Matka w Masce stworzyła Kindred, tak samo jak stworzyła wszystkie wcielenia śmierci. Ale od kogo otrzymała swoją maskę, jeśli to nie ona ją stworzyła?","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"04SI021":["Pełzający Żmijowij","Aby mnie zagrać, Uderzam sojusznika lub zadaję 3 pkt. obrażeń twojemu Nexusowi.","","Z początku demaciańscy żołnierze myśleli, że słyszą stukot dziesiątek pędzących przez płyty placu szponów. Dopiero po upadku pierwszej wieży strażniczej okazało się, że te wszystkie odnóża należą do jednego stworzenia.","Jednostka",["SMOK"],["Wyspy Cienia"],"ZWYKŁE"],"04SI002":["Duchowa Podróż","Zabij jednostkę, a następnie wskrześ ją.","","„To tylko przerwa”. – Owca","Zaklęcie",[],["Wyspy Cienia"],"RZADKIE"],"04SI053":["Inwazyjne Hydropnącze","Gdy mnie przywołasz lub na Początku rundy: Przywołaj kartę Wdzierająca Się Mgła.","","Maokai bez wytchnienia pracował, by pielęgnować życie na Wyspach Cienia. Ambiwalencja Mgły nie sprawia, że jej ironie są mniej okrutne.","Jednostka",[],["Wyspy Cienia"],"EPICKIE"],"04SI003":["Gasnąca Ikona","Gdy mnie przywołasz, przywołaj kartę Zwierzyna.","","Któż mógłby zapomnieć własnego boga śmierci, oprócz tych, których dotknęła klątwa nieśmiertelności? I czego bóg śmierci może obawiać się bardziej niż bycia zapomnianym? ","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"04SI028":["Camavorski Smok","Aby mnie zagrać, Uderzam sojusznika lub zadaję 3 pkt. obrażeń twojemu Nexusowi.\nGdy zabiję kolejną jednostkę, Zaczerpnij 1 pkt. Zdrowia z wrogiego Nexusa.","","Przez stulecia Czarna Mgła poszukiwała stworzeń na całym świecie, wypaczając je i zmieniając w koszmarne wersje ich samych.","Jednostka",["SMOK"],["Wyspy Cienia"],"RZADKIE"],"04MT014":["Oko Ra-Horaków","Odlicz 1: Ogłusz dwóch Najsłabszych wrogów.\nBrzask: Przywołaj moją kopię, która ma Odliczyć 2.","","„Niechaj słońce uroni nam odrobinę swego światła. Słabi i niegodni będą kajać się przed jej spojrzeniem!” \n – Kapłanka Solari","Lokacja",[],["Targon"],"RZADKIE"],"04MT008":["Malphite","Zagraj: Ogłusz wroga.","Udało ci się przywołać lokacje o całkowitym koszcie 10+ many. Jeżeli posiadasz Token ataku, gdy awansuję, stwórz w ręce kartę Niepowstrzymana Siła.","„A tutaj ostatni pszystanek wycieczki po Tałgonie Głazka! To jest PAPA! To NAJWIĘKSIEJSZY z gigantów na Tałgonie i mówię wam, nieładne rzeczy śpiewa, o nie nie. Tylko nie wspinajcie się na niego! Bałdzo jest łaskotliwy i na pewno nie chcecie, żeby kichnął z wami na bałana!”\n– Przygody z Głazkiem, cz. 6.","Jednostka",[],["Targon"],"Bohater"],"04MT010":["Szczyt Zwieńczony Gwiazdami","Odlicz 2: Stwórz w ręce 2 losowe karty Astralne o koszcie 3 lub mniejszym.","","Ci, którzy wyruszają na wspinaczkę na Górę Targon, szybko są wynagradzani jednymi z najwspanialszych widoków Runeterry. A w miarę jak droga pnie się w górę, tym bogatsze stają się nagrody.","Lokacja",[],["Targon"],"RZADKIE"],"04MT005":["Głazek","Jeżeli udało ci się przyzwać lokację w tej grze, przyznaj mi +2|+2.","","„No więc tak, cześć, jestem Głazek i będę wam pokazywać Tałgon! Jest wielki i wysoki, że oj, oj, oj, więc mam nadzieję, że buciczki do chodzenia macie dobłe! A tełaz ŁUSZAMY!”\n– Przygody z Głazkiem, cz. 1.","Jednostka",[],["Targon"],"ZWYKŁE"],"04MT009":["Spiralne Schody","Odlicz 3: Stwórz w ręce kartę Kiełkująca Siła.","","„A to piełfszy punkt naszej wycieczki! Mówię na to nóziochwiej, bo JEJCIU ile tam schodów! Widok tesz fajny, a to jedna z najlepsiejszych cech Tałgonu. Dobła, IDZIEMY!”\n– Przygody z Głazkiem, cz. 2.","Lokacja",[],["Targon"],"RZADKIE"],"04MT001":["Droga Lawin","Odlicz 2: Unicestwij Najsłabszego wroga.","","„No, to niech FY-SZY-SCY paczą pod nogi, bo tam jest BAŁDZO GŁĘBOKO i ja już tam spadałem kilka łazy i MÓWIĘ WAM, dłuuuugo się leci! A ja jestem tfałdy, to się tylko odbijam, ale wy tak nie łobicie… więc musicie uwa… oooch, a tam jest Klif! Idziemy, idziemy sie przyffitać!”\n– Przygody z Głazkiem, cz. 3.","Lokacja",[],["Targon"],"ZWYKŁE"],"04MT018":["Przerażony Koziorożec","Gdy otrzymuję wsparcie, daj mi i wspierającemu mnie sojusznikowi +1|+1 w tej rundzie.","","„Nie lękaj się, gdy wicher wyje,\nZa siedmioma górami szybko się skryje.\nNie martw się, dziecko, śpij spokojnie,\nNic ci nie grozi, mama jest przy tobie”. \n– Targońska kołysanka","Jednostka",[],["Targon"],"ZWYKŁE"],"04MT004":["Niebieski Strażnik","Ostatnie Tchnienie: Przywołaj kartę Herb Zrozumienia.","","„No, teraz FY-SZY-SCY mówią: »CZEŚĆ, BŁĘKITKU!«. CZEŚĆ, BŁĘKITKU! No, raz nawet myślałem, że odpowiedział »CZEŚĆ, BŁĘKITKU!«, ale jak teraz tak myślę, to może to mój głos się tutaj odbijał od ścian. OJEJKU NO, paczcie jaki jest magiczny i wogle, i nawet niebieski jest, więc jak na moje to on nawet NIE MUSI mówić! DOBRA, PA, PA, BŁĘKITKU, ŁUSZAMY!”\n– Przygody z Głazkiem, cz. 5.","Jednostka",[],["Targon"],"ZWYKŁE"],"04MT013":["Słoneczny Jastrząb Solari","Brzask: Ogłusz Najsilniejszego wroga.","","Solari wierzą, że to właśnie słoneczne jastrzębie Targonu przykuły uwagę Nieśmiertelnego Płomienia swoim blaskiem, napełniając ją inspiracją do stworzenia cyklu śmierci i odrodzenia.","Jednostka",["PTAK"],["Targon"],"ZWYKŁE"],"04MT003":["Żywiołak Ziemi","Jeżeli udało ci się przywołać 4+ lokacji w tej grze, przyznaj mi +3|+0.","","„Słuchajcie, to właśnie jest KLIF! To duuuży, stałszy gość. Mówię wam, on już naprawdę TŁOCHĘ tu siedzi. I wiem, wygląda fajowo i wogle milusio, ale trzyma na kałku tyyyyle cięszkich rzeczy, co czasami niektółych pszytłaczają, więc UWAGA na niego, dobsze? Dziękuję, ruszamy dalej!”\n– Przygody z Głazkiem, cz. 4.","Jednostka",[],["Targon"],"ZWYKŁE"],"04MT002":["Głazokrusz","Zagraj: Jeżeli udało ci się przywołać 4+ lokacji w tej grze, zadaj 4 pkt. obrażeń wrogowi i 2 pkt. obrażeń wrogiemu Nexusowi.","","Od czasu do czasu ogromne kolosy Targonu budzą się ze swego snu i wędrują na nowe tereny wzdłuż stoków wielkiej góry. Tego rodzaju sytuacje nigdy nie przebiegają po cichu, a już na pewno nie w sposób bezpieczny.","Jednostka",[],["Targon"],"EPICKIE"],"04MT006":["Gwiezdne Objawienie","Wezwanie.\nJeśli posiadasz sojuszniczego Astralnego, zamień swoją talię na 20 kopii karty Oblicze Nieskończoności.","","„Patrz, Kulun! Gwiazdy mają tyle historii do przekazania! Którą przeczytamy dzisiaj?” – Księżycem Śniąca","Zaklęcie",[],["Targon"],"EPICKIE"],"04MT012":["Zew Przeznaczenia","Przyznaj sojusznikowi w ręce +8|+8.","","„Pogódź się ze swoim przeznaczeniem i lśnij jaśniej, niż ktokolwiek mógłby się tego spodziewać”. – Taric","Zaklęcie",[],["Targon"],"EPICKIE"],"04MT007":["Wstrząśnienie Ziemi ","Ogłusz wroga. Zadaj mu 3 pkt. obrażeń, jeżeli udało ci się przywołać lokację w tej grze.","","„Oj, oj, no, to się tylko ziemia częsie, to nie że papa coś tam z łączkami łobi. NIE, NIE, A MY IDZIEMY dalej iiiii NA GÓŁĘ!” – Głazek","Zaklęcie",["ŻYWIOŁ"],["Targon"],"RZADKIE"],"04MT015":["Układ Niebios","Brzask: Stwórz losową kartę Zmroku w ręce.\nZmrok: Stwórz losową kartę Brzasku w ręce.","","I tak oto trwa cykl dnia i nocy. Jedno stale podąża za drugim.","Zaklęcie",[],["Targon"],"ZWYKŁE"],"04DE004":["Niestrudzona Zwiadowczyni","Gdy przywołasz Elitarnego, zmniejsz mój koszt o 1.","","Chociaż Noxianie z wielką wprawą zastawili sidła, to nikt nie znał tych lasów lepiej niż demaciańscy zwiadowcy. Każda pęknięta gałąź, każdy ślad pozostawiony na ziemi był poszlaką, dzięki której zbliżali się do swojego księcia.","Jednostka",["ELITARNY"],["Demacia"],"RZADKIE"],"04DE014":["Przynęta na Smoki","Kiedy zagrywasz Smoka, Uderza mnie on, a ty dobierasz 1 kartę.","","„Ten wrzask, tam wysoko, słyszysz? To żaden ptak, chłopcze. To zew polującego smoka”. – Demaciański rolnik","Jednostka",[],["Demacia"],"ZWYKŁE"],"04DE001":["Czcigodny Lord","Kiedy po raz pierwszy rzucam Wyzwanie wrogowi, daj mi Barierę w tej rundzie.","","Otrzymawszy wiadomość o zaginięciu swojego syna, król Jarvan III powierzył swojemu zaufanemu przyjacielowi, lordowi Barretowi Buvelle’owi, zebranie drużyny poszukiwawczej. Książę powrócił, bezpieczny i zdrowy. Lordowi Buvelle’owi, ku bezkresnej udręce króla, nie było to dane.","Jednostka",["ELITARNY"],["Demacia"],"ZWYKŁE"],"04DE012":["Awans","Następnym razem, kiedy zagrasz jednostkę w tej rundzie, przyznaj jej Zwiad. Od teraz staje się Elitarna.","","Gdy odwaga Demacian wystawiana jest na próbę, stają oni na wysokości zadania.","Zaklęcie",[],["Demacia"],"ZWYKŁE"],"04DE003":["Kataklizm","Sojusznik rozpoczyna Darmowy Atak, rzucając Wyzwanie wrogowi.","","„Za króla!” – Jarvan IV","Zaklęcie",[],["Demacia"],"RZADKIE"],"04DE002":["Złota Egida","Daj sojusznikowi Barierę w tej rundzie.\nZjednocz Siły.","","„Jeszcze raz, żołnierzu Demacii!” – Jarvan IV","Zaklęcie",[],["Demacia"],"RZADKIE"],"04DE006":["Zdolności Bojowe","Przyznaj sojusznikowi +1|+1.","","„Mógłbym cię nauczyć tego i owego”. – Lord Buvelle","Zaklęcie",[],["Demacia"],"ZWYKŁE"],"04DE008":["Jarvan IV","Gdy atakujesz, zapłać mój koszt, aby mnie przywołać, a wtedy rzucę Wyzwanie Najsilniejszemu z wrogów.","Sojusznicy przetrwali 3+ Uderzenia wrogich blokujących.","Noxianie wiedzieli, dokąd trop zaprowadzi księcia Jarvana. Wiedzieli, ilu Demacian będzie u jego boku, i byli przekonani, że honor nie pozwoli księciu na wycofanie się. Pułapka została zastawiona.","Jednostka",["ELITARNY"],["Demacia"],"Bohater"],"04DE005":["Cithria Pani Chmur","Gdy mnie przywołasz, podwój Siłę oraz Zdrowie pozostałych sojuszników i przyznaj im Wyzwanie.","","„Kogóż Demacia mogła wysłać swojemu księciu na ratunek, jeżeli nie samą Panią Chmur?” – Król Jarvan III","Jednostka",["ELITARNY"],["Demacia"],"EPICKIE"],"04DE020":["Zniszczony Smoczy Strażnik","Gdy sojusznik z Furią zabije jednostkę, przyznaj mu dodatkowe +1|+1.","","Mgła wypaczyła umysł Gregema, zmuszając go do przeżywania na okrągło wydarzeń z Wrenomuru. Pobudzony długo skrywanym żalem i wściekłością zwrócił się przeciwko swoim towarzyszom, z którymi niegdyś walczył ramię w ramię.","Jednostka",[],["Demacia"],"ZWYKŁE"],"04DE010":["Król Jarvan III","Gdy mnie przywołasz, dobierz kartę Jarvan IV.\nJeżeli jest on już w grze, zamiast tego daj sojusznikom Wyzwanie i Zwiad w tej rundzie.","","„Co takiego poświęci ojciec, żeby uratować syna? Albo jeszcze lepiej – co takiego może poświęcić król?” – LeBlanc","Jednostka",["ELITARNY"],["Demacia"],"EPICKIE"],"04DE016":["Kadregrin Zniszczony","Zagraj: Przyznaj sojusznikowi Wyzwanie i +1|+1.","","Kadregrin siał spustoszenie i wzbudzał strach na długo zanim Czarna Mgła dotarła do Demacii. Jednak pod dowództwem Viego był w stanie wesprzeć siły Zniszczonego Króla swymi umiejętnościami.","Jednostka",["SMOK"],["Demacia"],"RZADKIE"],"04DE013":["Ogromny Głazorożec","Nie otrzymuję obrażeń od wrogich zaklęć ani Umiejętności.","","Mówi się, że wielkie głazorożce pochodzą z czasów, gdy las petrucytowy był jeszcze młody, a ich poroże tworzy materiał podobny do tych starodawnych drzew.","Jednostka",[],["Demacia"],"ZWYKŁE"],"04DE015":["Lot Szybkoskrzydłego","Zagraj: Stwórz w ręce kartę Srebrnoskrzydła Awangarda, Oślepiający Nalot lub Szybkopióry Tropiciel.\nAtak: Daj innym sojusznikom z Wyzwaniem +1|+1 w tej rundzie.","","Sam widok lotu Szybkoskrzydłego inspiruje demaciańskich żołnierzy na polu bitwy. Gdy tylko Szybkoskrzydły przebija się przez chmury, w naziemną armię wstępuje duch walki.","Jednostka",["ELITARNY","PTAK"],["Demacia"],"EPICKIE"],"04DE007":["Skruszona Nowicjuszka","Gdy mnie przywołasz i Widzisz Elitarnego, stwórz w ręce kartę Zszargana Chorągiew.","","Dopiero gdy dotarła do murów miasta, nogi w końcu odmówiły jej posłuszeństwa. Nieustraszona Gwardia dostarczyła jej wiadomość królowi, który uratował księcia. Tym samym naprawiła swe błędy i zachowała honor.","Jednostka",[],["Demacia"],"ZWYKŁE"],"04DE009":["Mężny Jeździec","Kiedy po raz pierwszy rzucam Wyzwanie wrogowi, przemień mnie w kartę Kawaleria Gwardii.","","Po rozpuszczeniu wici każdy żołnierz Demacii został wezwany do pomocy w poszukiwaniach księcia. Szybkość działania była kluczowa.","Jednostka",["ELITARNY"],["Demacia"],"RZADKIE"],"05BC058":["Kennen","Gdy mnie przywołasz, stwórz w ręce kartę Znak Burzy.","Udało ci się przywołać tego samego sojusznika 5+ razy.","Kennen również usłyszał ten ryk, pochodzący… nie wiadomo skąd. Bez znaczenia, czy był to człowiek, czy potwór. Zakon Kinkou ochroni ich ziemię, nie bacząc na ryzyko.","Jednostka",["YORDLE"],["Bandle City","Ionia"],"Bohater"],"05BC010":["Treser Rekinów","Gdy sojusznicy atakują, przywołaj atakującą kartę Krótkoząb.","","Treser ma swój wieczorny rytuał – ryba i piwko na kolację, chwila na bąbelkową fajkę, a później całus dla każdego z rekinów i bajka na dobranoc.","Jednostka",["YORDLE"],["Bandle City","Bilgewater"],"RZADKIE"],"05BC102":["Czerstwy Czarodziej","Początek rundy: Odzyskaj 1 many zaklęć.","","Skoro zacięcie papierem to najwyższy wymiar bólu, nikt nie zna bólu lepiej niż bibliotekarz.","Jednostka",["YORDLE"],["Bandle City"],"ZWYKŁE"],"05BC230":["Duchowy Portal","Aby zagrać, odrzuć 1 kartę. Przyznaj sojusznikom +1|+1.","","„Nigdy nie pamiętam, jak to wszystko działa”. – Poppy","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"05BC099":["Napakowany Zwiadowca","Gdy mnie przywołasz, przyznaj mi +1|+1 za każdego innego sojuszniczego Yordla.","","„Mój sekret? Trzeba by zapytać moich bicepsów. To one robią całą robotę”.","Jednostka",["YORDLE"],["Bandle City"],"RZADKIE"],"05BC133":["Tristana","Mam +1|+0 za każdego sojusznika Z Wielu Regionów, którego udało ci się przywołać w tej grze.\nGdy przywołasz sojusznika Z Wielu Regionów, przyznaj mu +1|+0.","Udało ci się przywołać 5+ sojuszników Z Wielu Regionów.","„Okej, plan A jest taki: wpadamy tam i zaczynamy strzelać. Jeśli plan A się nie powiedzie, przechodzimy do planu B: spadamy stamtąd, cały czas strzelając. Potem przegrupowujemy się i rozpoczynamy plan C, który tak naprawdę jest planem A…”","Jednostka",["YORDLE"],["Bandle City"],"Bohater"],"05BC023":["Mininat","Koniec rundy: Jeżeli w tej rundzie udało ci się zadać obrażenia wrogiemu Nexusowi, Przemień mnie w kartę Meganat.","","Mininaty lubią: drzemki na nagrzanych kamieniach nieopodal terenów plemiennych Nakotak. Mininaty nie lubią: bycia spychanymi z wyżej wymienionych kamieni przez zuchwałych Yordlów…","Jednostka",[],["Bandle City"],"EPICKIE"],"05BC029":["Yuumi","Początek rundy: Przyznaj +1|+1 jednostce, do której się Przywiązuję. W innym przypadku przyznaj mi +1|+1.","Mnie lub jednostce, do której się Przywiązuję, udało się zaatakować 3 razy.","Yuumi musiała przyznać, że mimo całego marudzenia bardzo lubiła Książkę. Lubiła jej zapach. Lubiła jej ilustracje. Nawet lubiła skakać przez jej portale! Ale nic nie mogło się równać z Norrą, czekającą na nią bezpiecznie w domu…","Jednostka",["WRÓŻKA","KOT"],["Bandle City","Targon"],"Bohater"],"05BC078":["Elektroharpun","Aby zagrać, odrzuć 1 kartę. Zadaj 2 pkt. obrażeń jednostce oraz 2 pkt. obrażeń wrogiemu Nexusowi.","","„Dajmy im prawdziwy pokaz!” – Rumble","Zaklęcie",[],["Bandle City"],"RZADKIE"],"05BC106":["Ślimogbur","","","„Mimo niewielkiego rozmiaru Ślimogbury są niezwykle łakome oraz wyróżniają się cechą, którą najlepiej można opisać sformułowaniem »niezły charakterek«”.\n– Ekologiczny Dziennik Konchiologa, dzień 17","Jednostka",[],["Bandle City","Bilgewater"],"ZWYKŁE"],"05BC161":["Gnar","Uderzenie: Stwórz w ręce kartę Patyk do Tykania lub – jeśli już taką masz – zmniejsz jej koszt o 2.","Koniec rundy: W tej rundzie udało ci się zadać obrażenia wrogiemu Nexusowi.","Dawno temu Gnar i jego pobratymcy żyli w dostatku w Dolinie Nakotak. Było to niewinne miejsce, nietknięte pułapkami współczesności. Cóż za nieszczęście, że upływ czasu odebrał je Gnarowi. Jakież to jednak szczęście, że w Bandle City czas nie działa dokładnie tak, jak można by tego oczekiwać.","Jednostka",["YORDLE"],["Bandle City","Freljord"],"Bohater"],"05BC073":["Pomysłowa Chemiczka","Gdy mnie przywołasz, przywołaj kartę Bomba Samoróbka.","","Giselle była najlepszą uczennicą profesora Heimerdingera, dopóki nie usłyszała o dziwnych eksperymentach Ziggsa przeprowadzanych w Zaun. Od tamtej pory obchodziły ją tylko hextechowe miny i dostanie się na staż. ","Jednostka",["YORDLE"],["Bandle City"],"ZWYKŁE"],"05BC039":["Burkliwy Grenadier","Przymierze: Przywołaj losowego stronnika Yordla o koszcie 3 lub mniejszym.","","„Alice ma dwa strzały: jeden na powitanie, a drugi na pożegnanie. Chcecie się poznać?”","Jednostka",["YORDLE"],["Bandle City"],"RZADKIE"],"05BC148":["Wściekły Wróżkoludź","Gdy mnie przywołasz, 4-krotnie przyznaj mi Wpływ, jeśli w tej grze udało ci się zadać obrażenia wrogiemu Nexusowi 4+ razy.","","Mięciutki z zewnątrz, twardy i wściekły w środku.","Jednostka",["WRÓŻKA"],["Bandle City","Piltover i Zaun"],"ZWYKŁE"],"05BC119":["Stwór","Ostatnie Tchnienie: Stwórz moją kopię w ręce na początku kolejnej rundy.","","„Prawdziwemu złoczyńcy stworów nigdy za wiele! Te kurduple znają swoje miejsce w szeregu, są posłuszne i zawsze dopytują o szczegóły dotyczące powierzonego im zadania”.\n– Fragment rozdziału 2. „Jak zostać superzłoczyńcą” autorstwa lorda Veigara","Jednostka",[],["Bandle City","Wyspy Cienia"],"ZWYKŁE"],"05BC019":["Tęczowa Ryba","","","Tęczowa ryba z ogromną radością przeprowadzała rekonesans z powietrza, nawet jeżeli oznaczało to, że musiała wyskakiwać o wiele wyżej niż kiedykolwiek wcześniej. Z chęcią chwytała się każdej chwili wytchnienia – choćby najkrótszej – od głodnego spojrzenia Yuumi.","Jednostka",["WRÓŻKA"],["Bandle City"],"ZWYKŁE"],"05BC093":["Veigar","Gdy mnie przywołasz, stwórz w ręce kartę Mrok, jeśli jej nie posiadasz. Początek rundy: Mrok pod twoją kontrolą otrzymuje 1 dodatkowy pkt. obrażeń, gdziekolwiek jest.","Udało ci się zadać 12+ pkt. obrażeń za pomocą Mroku.","„Świat zadrży przede mną. Zostanie naznaczony przeze mnie na wieki. Ugnie się w obliczu mej siły. Zadygocze, widząc mój potężny cień!”\n– Fragment rozdziału 1. „Jak zostać superzłoczyńcą” autorstwa lorda Veigara","Jednostka",["YORDLE"],["Bandle City","Wyspy Cienia"],"Bohater"],"05BC007":["Zbieracze Kamieni","","","Yordle nie pojęły jeszcze grawitacji, ale to, co dzieje się w Bandle City, i tak jest sprzeczne z prawami fizyki.","Jednostka",["YORDLE"],["Bandle City"],"ZWYKŁE"],"05BC174":["Przyjaźń!","Daj sojusznikowi Barierę lub Tarczę Magii w tej rundzie.","","„Będę chroniła cię moimi dzikimi i groźnymi... miau!” \n– Yuumi","Zaklęcie",[],["Bandle City"],"RZADKIE"],"05BC185":["Muszelkowa Gra","Odzyskaj manę zaklęć. Daj sojusznikowi Nieuchwytność i +1|+1 w tej rundzie.","","„WIDZĘ, jak wchodzą do muszli, ale gdy WYBIERAM tę muszlę, jest pusta. Zaczynam podejrzewać, że ta gra jest ustawiona…”\n– Ekologiczny Dziennik Konchiologa, dzień 14","Zaklęcie",[],["Bandle City"],"RZADKIE"],"05BC096":["Tenor Terroru","Gdy mnie przywołasz, przywołaj kartę Bestialski Bas, jeśli w tej grze udało ci się zagrać stworzoną kartę lub zabić jednostkę za pomocą zaklęcia.","","Jeśli Veigar potrzebowałby skomponować skalę sprawiedliwości, ta dwójka z pewnością najlepiej nadawałaby się do tej roboty. Oni ogarniają wszystkie skale. No, może oprócz tych muzycznych.","Jednostka",["YORDLE"],["Bandle City","Wyspy Cienia"],"RZADKIE"],"05BC088":["Rumble","Zagraj: Odrzuć do 3 kart, by przyznać sojuszniczym kartom Rumble Wpływ za jedną odrzuconą kartę, Szybki Atak za dwie oraz Tarczę Magii za trzy, gdziekolwiek są.","Widziałem, jak sojuszniczy Mecha Yordlowie zadają 12+ pkt. obrażeń.","„Dooobra, to powinno załatwić sprawę”.\n„BŁĄD”.\n„CO?! Dopiero to naprawiłem!”\n„NIEUCHRONNA AWARIA SYSTEMU”.\n„Wyłącz to. WYŁĄCZ TO!”\n– Rumble i Tristy","Jednostka",["MECHA","YORDLE"],["Bandle City","Noxus"],"Bohater"],"05BC056":["Mnich Podmuchu","Gdy mnie przywołasz, stwórz w ręce kartę Pozycja Chmury.","","„Technika naszej szkoły wywodzi się z kontroli oddechu, gdyż początkiem nawet największej nawałnicy jest wiatr”.","Jednostka",["YORDLE"],["Bandle City"],"RZADKIE"],"05BC190":["Mechakomentator z Areny","Atak: Daj innym atakującym sojusznikom +2|+0 w tej rundzie.","","„Jak to robię, że nie tracę głosu po komentowaniu walk co noc? Płuczę gardło olejem silnikowym. Po pięć minutek, rano i wieczorem”.","Jednostka",["YORDLE"],["Bandle City","Noxus"],"EPICKIE"],"05BC042":["Shake z Fioletowej Jagódki","Zwiększ statystyki sojusznika do 3|3 w tej rundzie.","","„Kiedyś byłem taki, jak ty – nie mogłem unieść nawet grzyba. Później trafiłem jednak na »Shake’a z Fioletowej Jagódki«. Znajdziecie w nim wszystko, czego potrzebuje każdy yordlowy paker. Po ostrym wycisku tankujcie tego shake’a, a zmienicie się w tak wypasionego gościa jak ja!”\n– Ulotka reklamowa","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"05BC205":["Horyzont Zdarzeń","Ogłusz wroga i Ogłusz wszystkich wrogów o Sile 2 lub mniejszej.","","„Nie ruszaj się…” – Veigar","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"05BC223":["Pyszna Zasadzka","Wybierz 1 z 3 jednostek lub zaklęć z talii przeciwnika i umieść 3 Trujące Grzyby na wszystkich kopiach wybranej karty.","","„Zasada 986: Pułapki to NIE zabawki… ale świetnie się nimi bawi!”","Zaklęcie",[],["Bandle City"],"RZADKIE"],"05BC091":["Biletowa z Areny","Zagraj: Odrzuć 1 kartę, aby Pokazać Mecha Yordla i zmniejszyć jego koszt o 1.","","„BILETY! KUPUJCIE BILETY! TERAZ ZNIŻKAAAAAAAA O PÓŁ CENY! Kurczaczki, jeśli nie sprzedam tych biletów, szef mnie zabije… Dosłownie”.","Jednostka",["YORDLE"],["Bandle City"],"ZWYKŁE"],"05BC163":["Ziggs","Atak: Zadaję 1 pkt. obrażeń blokującej mnie jednostce oraz wrogiemu Nexusowi.","Udało ci się zniszczyć 4+ sojusznicze lokacje.","„WAŻNE jest, by zawsze robić dobre wrażenie. Przyjdzie do nas nowy inspektor bezpieczeństwa, wiesz, co to znaczy!”\n„Koniec z eksplozjami?”\n„CO?! Nie! To znaczy eksplozje tam, gdzie tego nie zauważy. »Koniec z eksplozjami…« Oszalałeś?!” – Ziggs i Otto","Jednostka",["YORDLE"],["Bandle City","Shurima"],"Bohater"],"05BC151":["Czarodziejka Luster","Gdy zagrasz stworzonego stronnika, przywołaj jego dokładną kopię. Gdy zagrasz stworzone zaklęcie, skopiuj je na te same cele.","","„O tak, to prawdziwa mistrzyni luster. Dzięki niej moje projekty są jeszcze bardziej wysublimowane. Niewielka manipulacja światłem sprawia nawet, że niektóre osoby zyskują na tak mile widzianej wertykalności...” – Projektant Wysokiej Klasy","Jednostka",["YORDLE"],["Bandle City"],"EPICKIE"],"05BC027":["Hextechowe Miny","Gdy mnie przywołasz lub zniszczysz, Ogłusz Najsilniejszego wroga.","","„Jak to wygląda niebezpiecznie?” – Ziggs","Lokacja",[],["Bandle City"],"ZWYKŁE"],"05BC200":["Yordlowy Portal","Aby zagrać, odrzuć 1 kartę. Pokaż Yordla, który kosztuje 3 lub mniej i go przywołaj.","","„Nigdy nie zostawiamy kanonierów!” – Tristana","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"05BC021":["Skacząca Bomba","Zadaj 2 pkt. obrażeń jednostce lub zadaj 1 pkt. obrażeń dwóm wrogom.","","„He, he, ale urwał!” – Ziggs","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"05BC167":["Komandoska z Bandle","Uderzenie w Nexus: Stwórz w ręce kartę Głodna Kotosowa.","","„Na ulicy strzelanko, w domu kołysanko!”","Jednostka",["YORDLE"],["Bandle City"],"ZWYKŁE"],"05BC179":["Yordlowy Zwiadowca","Atak: Przyznaj sojusznikom o Sile równej lub mniejszej ode mnie +0|+1.","","„Poppy! Wspaniałe wykonanie naszej najnowszej taktyki. Co sądzisz o nazwaniu jej »Orzeszkowy Sztorm«?”\n„Ale ja zwyczajnie walnęłam łobuzów moim młotem. Może nazwiemy ją po prostu »Młot«?”\n„Tak nazywają się poprzednie trzy!” – Kip i Poppy","Jednostka",["YORDLE"],["Bandle City","Demacia"],"EPICKIE"],"05BC214":["Megapiekielna Bomba","Zadaj 1 pkt. obrażeń wszystkim wrogom. Następnie powtórz tę czynność.","","„Pora na… »Wielkie Bum«!” – Ziggs","Zaklęcie",[],["Bandle City"],"RZADKIE"],"05BC221":["Grzybowy Krąg","Gdy mnie przywołasz lub na Początku rundy: Daj mi w tej rundzie Siłę równą liczbie innych sojuszniczych Wróżek będących w grze lub Przywiązanych.","","Te małe głupotki są całkiem słodkie, a grzyby tego było mało – uwielbiają towarzystwo.","Jednostka",["WRÓŻKA"],["Bandle City","Ionia"],"RZADKIE"],"05BC041":["Poppy","Atak: Przyznaj sojusznikom o Sile równej lub mniejszej ode mnie +1|+1.","Ja i moi sojusznicy zaatakowaliśmy 3 razy.","Pokora to oznaka heroizmu, ale według wielu historyków Poppy aż z tym przesadza.","Jednostka",["YORDLE"],["Bandle City","Demacia"],"Bohater"],"05BC176":["Grasujący Pocisk","Przyznaj sojusznikowi +1|+0. Zadaj wrogowi 1 pkt. obrażeń.","","„Wziuuuuuuu!” – Yuumi","Zaklęcie",[],["Bandle City"],"RZADKIE"],"05BC105":["Kanonierzy z Bandle","Kosztuję o 1 mniej za każdego sojusznika Z Wielu Regionów, którego udało ci się przywołać w tej grze.\nGdy mnie przywołasz, 3-krotnie przyznaj mi Wpływ.","","Prawdziwi kumple.","Jednostka",["YORDLE"],["Bandle City"],"RZADKIE"],"05BC066":["Szybkie Pióro","","","„G… d… z… i… e… j… e… s… t… N… o… r… r… a…? Wielkie nieba, i co ja mam odpowiedzieć?” – Mysi Opiekun","Jednostka",["WRÓŻKA"],["Bandle City"],"ZWYKŁE"],"05BC177":["Smok Origami","","","– Jeszcze jedno zagięcie… i widzisz? To żyrafa! Nazywa się Skarpeta.\n– Dlaczego Skarpeta?\n– Norra kocha skarpetki, więc jego też pokocha!” \n– Mysi Opiekunowie","Jednostka",["WRÓŻKA"],["Bandle City"],"EPICKIE"],"05BC136":["Wysypisko","Aby zagrać, odrzuć 1 kartę.\nPokaż Mecha Yordla.","","„Złom. Rupieć. Badziewie… Ooo, WŁAŚNIE o to mi chodziło!” – Rumble","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"05BC164":["Zatruta Strzałka","Zadaj 1 pkt. obrażeń dowolnemu celowi i umieść 3 Trujące Grzyby w talii przeciwnika.","","„Ha, ha! W sam środek!” – Teemo","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"05BC194":["Drzewo Bandle","Początek rundy: Stwórz w ręce stronnika z nowego regionu. Jeżeli widziałem sojuszników z 10 regionów, wygrywasz grę.","","Sięgając niebotycznie wysoko wzwyż, Drzewo Bandle stanowi nieodłączną część serca miasta. Pod jego rozłożystymi, powykręcanymi gałęziami wielu Yordlów wypatruje promyka nadziei i szansy na przyjaźń, inni natomiast widzą złowrogi i pełen zagadek monolit. Wszyscy jednak zgodnie stwierdzają, że przyglądając się Drzewu Bandle, można odnieść wrażenie, jakby zaglądało się w duszę czegoś bardzo starego i potężnego.","Lokacja",[],["Bandle City"],"EPICKIE"],"05BC127":["Rissu Milcząca Wichura","Gdy mnie przywołasz, przywołaj kartę Burzowa Chmura.","","Utkanie Burzowej Chmury wymagało czasu, którego Rissu nie miała. Pracowała dłońmi tak szybko, jak mogła, podczas gdy Aberracja zbliżała się. Trochę chmur, odrobina piorunów i… TRZASK! BUM! Udało jej się. Ale czy to wystarczy?","Jednostka",["YORDLE"],["Bandle City"],"EPICKIE"],"05BC216":["Yordlowe Ustrojstwo","Zniszcz lokację lub stwórz w ręce 2 losowych stronników Z Wielu Regionów.","","„Trzymaj się, toczymy się!” – Bombowe Bliźnięta","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"05BC212":["Inspektor Bezpieczeństwa","Początek rundy: Stwórz w ręce kartę Pomyślny Wynik Inspekcji!.","","Wilfred początkowo był bardzo sceptyczny. Później właściwie też był sceptyczny. Można powiedzieć, że był sceptyczny do samego końca. Jednak Ziggs i pozostali eksperci od Hextechowych Min pokazali, że naprawdę znają się na fajerwerkach. ","Jednostka",["YORDLE"],["Bandle City"],"RZADKIE"],"05BC141":["Heroiczny Refren","Daj 2 sojusznikom +2|+1 w tej rundzie.","","„– Oto i bohaterowie stoją ramię w ramię…\n– …poślad w poślad! He, he, he, he!\n– N-nie! Peppy, jak już musisz się wcinać, to proszę cię, przynajmniej w mniej dramatycznych momentach!”\n– Opowieści znad yordlowego ogniska","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"05BC209":["Reakcja na Stres","Spraw, że statystyki jednostki w tej rundzie wynoszą 1|6.","","Bawkatrysy w normalnych okolicznościach są lojalnymi i wiernymi wierzchowcami. Jednak pod wpływem stresu potrafią być dość… niestabilne.","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"05BC210":["Ogniopluj","Daj sojusznikowi +2|+0 i Wpływ.","","„Jeśli nie wyją, to nie jest im wystarczająco ciepło! He, he”. \n– Rumble","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"05BC013":["Przebiegłe Macki","Twój przeciwnik odrzuca kartę z najmniejszym kosztem.","","„Do zapamiętania: Na następnej ekspedycji trzymać wszystkie wartościowe rzeczy w PRZEDNICH kieszeniach”. \n– Ekologiczny Dziennik Konchiologa, dzień 19","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"05BC100":["Grzybkowy Piesek","Uderzenie: Umieść 3 karty Trujące Grzyby w talii przeciwnika.","","„Co się stało, mały? Dwóch rekrutów patrolowało las i natrafiło na strasznego, trawiastego potwora, przez co mogą zginąć długą i bolesną śmiercią? Prowadź!” – Teemo","Jednostka",["PIES"],["Bandle City"],"ZWYKŁE"],"05BC098":["Pokręcony Katalizator","Uderzenie: Mrok otrzymuje od ciebie 1 dodatkowy pkt. obrażeń, gdziekolwiek jest.","","Mrok występuje we wszystkich kształtach i rozmiarach. Niektóre są ZASKAKUJĄCO urocze.","Jednostka",["YORDLE"],["Bandle City"],"ZWYKŁE"],"05BC122":["Yordlowy Świeżak","Gdy przywołasz innego Yordla, daj mi +2|+0 w tej rundzie.","","„Gigantus trawiastus. Te przerażające stworzenia potrafią się zakamuflować, udając zwyczajną trawę. Zaatakują każdego, kto na nich postawi stopę. Jeśli spotkacie jednego na swojej drodze – uciekajcie, gdzie pieprz rośnie!” – Ava Ambitniaczka","Jednostka",["YORDLE"],["Bandle City"],"ZWYKŁE"],"05BC120":["Yordlowy Kapitan","Gdy przywołasz innego sojusznika o Sile równej lub mniejszej ode mnie, przyznaj mu +1|+1.","","„W przygodach chodzi o to, by szukać łobuzów i zmieniać ich w przyjaciół!”","Jednostka",["YORDLE"],["Bandle City"],"ZWYKŁE"],"05BC046":["Piorunująca Pięść","Gdy mnie przywołasz, przemień mnie w kartę Masa Gwałtowny Grzmot, jeśli w tej grze udało ci się przywołać kartę Piorunująca Pięść.","","Masa uderzył w kukłę treningową, a z jego pięści wydostał się piorun, który przepołowił drewno oraz osmalił włoski na jego rękach. Pociągnął za sznur, przyciągając rękę z brązu. Po wielu treningach mógł wreszcie stwierdzić, że jest gotowy. Nagle z oddali dotarł do niego potworny ryk.","Jednostka",["YORDLE"],["Bandle City"],"ZWYKŁE"],"05BC018":["Napuszony Kawalerzysta","","","„Dziewięćset dziewięćdziesiąt osiem… Dziewięćset dziewięćdziesiąt dziewięć… Tysiąc! Proszę bardzo, Bawkuś. Jak zawsze wyglądasz nieskazitelnie. Teraz moja kolej!”","Jednostka",["YORDLE"],["Bandle City","Demacia"],"RZADKIE"],"05BC132":["Niszczący Strzał","Kosztuję o 2 mniej, jeśli posiadasz kartę Tristana lub jeśli w tej grze udało ci się zagrać karty z 4+ regionów.\nZadaj jednostce 3 pkt. obrażeń.","","Każda eksplozja zaczyna się od strzału.","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"05BC168":["Nakrapiana Ropucha","Koniec rundy: Jeżeli w tej rundzie udało ci się zadać obrażenia wrogiemu Nexusowi, Przemień mnie w kartę Gigaponurnik.","","Yordlowie z Doliny Nakotak przez kilka pokoleń starali się zrozumieć swoich sąsiadów – ponurników. Pierwszy był wódz Hegabo, który próbował tykać je patykiem. Po nim nastał wódz Babobu, który próbował tykać je patykiem. Wódz Nakotak ma zupełnie nowy plan: podejmie próbę tykania ich patykiem.","Jednostka",[],["Bandle City"],"RZADKIE"],"05BC014":["Maciupciodaktyl","Koniec rundy: Jeżeli w tej rundzie udało ci się zadać obrażenia wrogiemu Nexusowi, Przemień mnie w kartę Terrordaktyl.","","Stworzenia z Doliny Nakotak są tak samo zróżnicowane i pełne życia, jak tereny, które zamieszkują… Mają też podobną tendencję do wybuchów.","Jednostka",["PTAK"],["Bandle City"],"ZWYKŁE"],"05BC138":["Naprawiacze","Za pierwszym razem, gdy odrzucisz kartę lub zadasz obrażenia wrogiemu Nexusowi, przyznaj mi +2|+1.","","„No dobra, walka była niezła, wszyscy dobrze się bawili. Teraz czas na sprzątanie. Wiecie, co robić – jeśli da się coś wykorzystać, naprawiacie to i do sklepu. Chwila moment i znów będą to kupować. AHA, HA, HA!” – Karl, Szef Areny","Jednostka",[],["Bandle City"],"ZWYKŁE"],"05BC198":["Strzelmy Sobie Fotkę","Zadaj jednostce 1 pkt. obrażeń. Jeśli posiadasz 4+ sojuszników, zadaj 2 pkt. obrażeń.","","„Okej, tego użyjemy do newslettera. Pamiętajcie, by tym razem się uśmiechnąć! Raz… dwa… trzy!” – Tristana\n","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"05BC181":["Pozycja Chmury","Daj sojusznikowi +2|+0 i „Koniec rundy: Wycofaj mnie” w tej rundzie.","","„Uspokój oddech i znajdź w sobie siłę!” – Mnich Podmuchu","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"05BC160":["Proto-Poro","","","Poro niegdyś miały znacznie większe głowy, przez co wyglądały na nieco głupsze i znacznie groźniejsze.","Jednostka",["PORO"],["Bandle City","Freljord"],"ZWYKŁE"],"05BC005":["Wodorostowe Panny","Uderzenie w Nexus: Stwórz w ręce kartę Psikus.","","„O rety, ale miałem właśnie przedziwny sen. Przedzierałem się przez wodorosty w poszukiwaniu mojej muszli na głowę, gdy nagle usłyszałem najpiękniejszą melodię na świecie. Przebudziłem się w fotelu, z piórem w ręku, a teraz piszę te słowa. Nie wydaje mi się jednak, że ta drzemka była zaplanowana…”\n– Ekologiczny Dziennik Konchiologa, dzień 22","Jednostka",[],["Bandle City"],"RZADKIE"],"05BC020":["Asystent Biblioteczny","Uderzenie w Nexus: Dobierz zaklęcie, które kosztuje 3 lub mniej.","","„Jelly to mój NAJLEPSZY PRZYJACIEL! Znaczy po tobie, Książko. I po Norze. No dobra, Jelly to mój TRZECI NAJLEPSZY PRZYJACIEL. Ale to dalej całkiem nieźle, co nie?!” – Yuumi","Jednostka",["WRÓŻKA"],["Bandle City"],"ZWYKŁE"],"05BC049":["Konchiolog","Zagraj: Pokaż zaklęcie z twoich regionów o koszcie 3 lub mniejszym.","","„Dziś zaiste jest pamiętny dzień! Eksploracja na głębokościach! Mam nadzieję, że pójdzie łatwo jak po… wodzie! Ha, ha!”\n– Ekologiczny Dziennik Konchiologa, dzień 1","Jednostka",["YORDLE"],["Bandle City"],"RZADKIE"],"05BC001":["Minizmianka","Przemień jednostkę w kartę Minimaleństwa o statystykach 3|3 i Ucisz ją.","","„Oj, oj! Jakie słodkie! Jakie urocze! Jakie MALUTKIE!”\n – Veigar","Zaklęcie",[],["Bandle City"],"RZADKIE"],"05BC026":["Ukryte Przejścia","Kosztuję o 2 mniej, jeśli w tej grze udało ci się stworzyć 2+ karty. Dobierz 2 karty.","","Niewielu cudzoziemców zna drogę do Bandle City, ale dziwne znaki umieszczone na skałach i drzewach Runeterry stanowią niemałą podpowiedź dla kogoś, kto wie, czego szukać.","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"05BC152":["Poirytowani Podróżnicy","Gdy mnie przywołasz, WSZYSCY gracze dobierają 1 kartę, a następnie twój przeciwnik odrzuca swoją kartę o najwyższym koszcie.","","„Najgorsza. Wycieczka. Na świecie”. – Elle","Jednostka",["YORDLE"],["Bandle City","Piltover i Zaun"],"ZWYKŁE"],"05BC070":["Ava Ambitniaczka","Gdy mnie przywołasz lub na Koniec rundy: Umieść 3 karty Trujące Grzyby w talii przeciwnika.\nPułapki na kartach przeciwnika liczą się podwójnie po aktywacji.","","„Zasada 378: Dobry zwiadowca jest dzielny, brawurowy i zawsze przygotowany!”","Jednostka",["YORDLE"],["Bandle City"],"EPICKIE"],"05BC015":["Maleńki Jaszczur","Koniec rundy: Jeżeli w tej rundzie udało ci się zadać obrażenia wrogiemu Nexusowi, Przemień mnie w kartę Lawowy Jaszczur.","","– Jedz paprykę! – warknął (prawdopodobnie) Nakotak. – Nie, TY jedz paprykę! – odpowiedział (też prawdopodobnie) Jojo. Kiedy tak się kłócili, obok nich przedreptała mała jaszczurka, która właśnie goniła jeszcze mniejszą muchę. Dwaj Yordlowie popatrzyli na jaszczurkę, potem na paprykę, a w końcu – na siebie nawzajem. Gdyby żarówki istniały, właśnie jakaś by się zaświeciła.","Jednostka",["GAD"],["Bandle City"],"ZWYKŁE"],"05BC145":["Yordlowa Giermka","Zagraj: Stwórz w ręce kartę Mały Oszczep lub Mała Tarcza.","","„Moja włócznia też należała kiedyś do wielkiej bohaterki… Poppy trzymała ją przez całą minutę!”","Jednostka",["YORDLE"],["Bandle City"],"ZWYKŁE"],"05BC140":["Saneczkarz Poro","Atak: Przywołaj losowego atakującego Poro o koszcie 1.","","„No i TAMTEN szefundzio Porów mówi „TENDY”, no i oni poszli do horazontu, a za nimi inne dreptały Poro, ale cinszko im było nadonżyć!” – Ingvar Młodsza","Jednostka",["PORO"],["Bandle City","Freljord"],"EPICKIE"],"05BC129":["Szef Areny","","","„Co chwilę na świat przychodzi jakiś bęcwał. Wycisnę z nich wszystko, co się da… ta arena do walk mechów będzie KOPALNIĄ ZŁOTA”.","Jednostka",["YORDLE"],["Bandle City","Noxus"],"ZWYKŁE"],"05BC004":["Wydrośmiornica","Gdy mnie przywołasz, stwórz w ręce kartę Psikus.","","„Ciekawskie i żwawe Wydrośmiornice to niezwykle wesołe stworzonka. A może lepiej brzmi »Ośmiowydry«? Hm, czy przypadkiem nie pakowałem dziś trzech kanapek?”\n– Ekologiczny Dziennik Konchiologa, dzień 7","Jednostka",[],["Bandle City"],"ZWYKŁE"],"05BC155":["Płomienny Mnich","Gdy przywołasz innego sojusznika, przyznaj mi +1|+0.","","„Nawet niewielka iskierka zmienia się w wielki płomień. Żarzymy się niczym twój koniec!”","Jednostka",["YORDLE"],["Bandle City"],"RZADKIE"],"05BC104":["Pierwotna Siła","Przyznaj sojusznikowi +2|+2 i Wpływ.","","Tak, jest przeuroczy. Tak, łatwo się denerwuje. Nie, nie chcesz tego widzieć.","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"05BC218":["Pomoc Wróżek","Stwórz w ręce kartę Głodna Kotosowa, a następnie przyznaj znajdującym się w twojej ręce sojusznikom będącym Wróżkami +1|+1.","","„Kto je ciągle podkarmia?” – Poppy","Zaklęcie",[],["Bandle City"],"RZADKIE"],"05BC192":["Bombowe Bliźnięta","Gdy mnie przywołasz, stwórz w ręce losową lokację o koszcie 2 lub mniejszym.","","Bombowiec Zrzędator-X robił dokładnie to, co powinien: siał chaos. Łatwo też się nim parkowało. ","Jednostka",["YORDLE"],["Bandle City","Shurima"],"ZWYKŁE"],"05BC162":["Wódz Nakotak","Gdy sojusznik się przemienia, w pełni go ulecz i przyznaj mu +1|+1 oraz Wpływ.","","Wódz Nakotak ogłosił się przywódcą plemienia po tym, kiedy w zaspach otaczających ich ziemie odnalazł wielką kość dinozaura. Nikt inny nie miał świadomości, że kości dinozaura równały się przywództwu nad plemieniem, ale też nikomu w zasadzie to nie przeszkadzało. A zatem – Nakotak.","Jednostka",["YORDLE"],["Bandle City"],"RZADKIE"],"05BC032":["Lśniąca Latarnia","W każdej rundzie pierwsza Wróżka, którą zagrasz, kosztuje o 2 mniej.","","„Latarnia podąża za Norrą, księżycowe ćmy podążają za Latarnią, myszy podążają za księżycowymi ćmami! Jeden za drugim, jeden za drugim!","Jednostka",["WRÓŻKA"],["Bandle City"],"RZADKIE"],"05BC166":["Patyk do Tykania","Zadaj 1 pkt. obrażeń dowolnemu celowi. Dobierz 1 kartę.","","Pierwsza zasada eksperymentowania: tyknij to i zobacz, co się stanie.","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"05BC006":["Arsenał","Gdy mnie przywołasz, przyznaj mi losowe słowo klucz za każdą zniszczoną przez ciebie w tej grze sojuszniczą lokację.\nGdy zniszczysz sojuszniczą lokację, przyznaj mi losowe słowo klucz.","","Arnie nieustannie towarzyszył Ziggsowi, a jego pogodne usposobienie było naturalnym lekarstwem na chaotyczną gorliwość Ziggsa. W jego obowiązkach leżało uzupełnianie amunicji, zażegnywanie palących kryzysów i zasłanianie uszu Ziggsa, gdy ten (wielokrotnie) zapominał o ochronie słuchu. ","Jednostka",["YORDLE"],["Bandle City"],"EPICKIE"],"05BC110":["Uczony Wspinacz","","","„Tak, tak, mówiłaś mi już o tym, jak bardzo lubi herbatę, skarpetki, ciebie, guziki i zbieranie małych drobiażdżków, ale jeszcze mi słowa nie powiedziałaś o tym, jak ona WYGLĄDA!” ","Jednostka",["YORDLE"],["Bandle City","Targon"],"ZWYKŁE"],"05BC063":["Wojowniczka Tornada","Gdy mnie przywołasz, przyznaj mi +1|+0 oraz losowe słowo klucz.\nZatrzymuję ulepszenia statystyk oraz słowa klucze, gdy mnie Wycofasz.","","Ćwiczenia oddechowe pozwalają Wojowniczce zachować spokój… Przekształcają rodzący się w niej niepokój w bezwzględny huragan śmiercionośnych ostrzy. ","Jednostka",["YORDLE"],["Bandle City"],"ZWYKŁE"],"05BC217":["Wróżkowa Sadzonka","Pokaż Wróżkę i przyznaj jej +1|+1.","","Każda żyjąca istota wymaga pożywienia. Wróżki nie są wyjątkiem – choć może być trudno stwierdzić, co dokładnie wykorzystują w tym celu.","Zaklęcie",[],["Bandle City"],"RZADKIE"],"05BC180":["Zryw","Wycofaj jednostkę o Sile 3 lub mniejszej.","","„Jesteśmy szybcy! Jesteśmy jak wiatr!” – Kennen","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"05BC040":["Podmianka Talizmanów","Pokaż kartę Wydrośmiornica lub jedno z dwóch zaklęć z twojego regionu o koszcie 3 lub mniejszym.","","„Natychmiast oddaj moją kanapkę!” – Konchiolog","Zaklęcie",[],["Bandle City"],"RZADKIE"],"05BC213":["Łomot","Zadaj wrogowi 1 pkt. obrażeń i Ogłusz go.","","„Lavii!” – Gnar","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"05BC208":["Bohaterska Szarża","Sojusznik Uderza wroga. Jeśli przetrwa, zostaje Ogłuszony.","","„Dalej, ruchy!” – Poppy","Zaklęcie",[],["Bandle City"],"RZADKIE"],"05BC085":["Łobuziasty Wilk Morski","Zagraj: Odrzuć 1 kartę, aby Pokazać Mecha Yordla i przyznać mu Tarczę Magii.","","„Ściszysz no trochę? Ledwie słyszę, jak liczę tę górę forsy!” \n– Karl, Szef Areny","Jednostka",["YORDLE"],["Bandle City"],"RZADKIE"],"05BC112":["Sadzonka Wybuchowej Szyszki","Zagraj: Daj mi Barierę w tej rundzie lub przyznaj mi Wpływ.","","Sadzonki Wybuchowej Szyszki to nieśmiałe stworzenia i choć w pierwszej chwili zawsze podejmą próbę ucieczki, to w sytuacji zagrożenia…","Jednostka",["WRÓŻKA"],["Bandle City","Ionia"],"ZWYKŁE"],"05BC135":["Dwustrzał","Sojusznik Uderza wroga. Jeśli sojusznik pochodzi Z Wielu Regionów, Uderza wroga ponownie.","","„Żołądź M1-85: w pełni automatyczny karabin o dębowej kolbie i lunecie z drzewa z Lasu Bandle. Wykończenie z fioletowej jagódki. Mamusia ugotuje dziś coś pysznego!” \n– Komandoska z Bandle","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"05BC084":["Piszczek","Zagraj: Odrzuć 1 kartę, aby Pokazać Mecha Yordla.","","Mały, ale z WIELKĄ osobowością.","Jednostka",[],["Bandle City"],"ZWYKŁE"],"05BC184":["Bełkoczący Balladziści","Gdy mnie przywołasz, stwórz w ręce kartę Głodna Kotosowa.","","„Oto piosenka,\na Poppy to niezła twardzielka!\nJest z niej straszna… żelka!”\n– Linijki wykreślone ze „Śpiewnika Reginaldaktyla i Faltimiskwika, Znakomitych Bardów”","Jednostka",["YORDLE"],["Bandle City"],"ZWYKŁE"],"05BC116":["Burmistrz Bandle City","W każdej rundzie pierwsza jednostka Z Wielu Regionów, którą zagrasz, kosztuje o 1 mniej.\nZagraj: Pokaż stronnika Z Wielu Regionów.","","Nie ma pewności, czy w Bandle City w ogóle organizowane są wybory na burmistrza, ale pokaźny wąs z pewnością stanowiłby wymóg, by w nich wystartować.","Jednostka",["YORDLE"],["Bandle City"],"EPICKIE"],"05BC111":["Kompania Yordlów ","Daj sojusznikom +2|+2 w tej rundzie. Jeśli udało ci się zagrać karty z 4+ regionów, zamiast tego daj sojusznikom +3|+3.","","„My… wyglądamy naprawdę kozacko”. – Tristana","Zaklęcie",[],["Bandle City"],"RZADKIE"],"05BC224":["Transpozycja","Wycofaj sojusznika. Następny sojusznik o koszcie równym lub mniejszym, którego zagrasz w tej rundzie, kosztuje 0.","","„Prędkość ciała, prędkość umysłu!” – Kennen","Zaklęcie",[],["Bandle City"],"RZADKIE"],"05BC130":["Rozpalony Narwaniec","Atak: Przyznaj bohaterowi znajdującemu się najbliżej wierzchu twojej talii +1|+1 i losowe słowo klucz.","","Letni grill Ottona miał swego rodzaju reputację. Choć gospodarz pałał prawdziwym entuzjazmem do grillowania, to jego goście nie mogli liczyć na zbyt duży wybór, jeżeli chodzi o sposób przyrządzenia steków. Wszystkie były „dobrze wypieczone” albo „wyjątkowo dobrze wypieczone”.","Jednostka",["YORDLE"],["Bandle City","Shurima"],"ZWYKŁE"],"05BC191":["Osąd Strażniczki","Umieść wrogą jednostkę na wierzchu talii wroga.","","„I nie wracaj!” – Poppy","Zaklęcie",[],["Bandle City"],"RZADKIE"],"05BC052":["Śmietnisko Skarbów","Uzupełnij rękę losowymi kartami. Ich koszt wynosi 0 i są one Ulotne. W tej rundzie możesz zagrać jeszcze tylko 3 karty.","","Dla jednych śmieci, dla innych skarbnica części zamiennych.\n","Zaklęcie",[],["Bandle City"],"RZADKIE"],"05BC050":["Ukwialec","Gdy mnie przywołasz, stwórz 2 karty Psikusy w ręce.","","„Osobom cierpiącym na nudności zaleca się SZCZEGÓLNĄ ostrożność w kontaktach z tym gigantem. Wasze wnętrzności będą wam wdzięczne… Sam żałuję, że zjadłem aż dwie kanapki z grzybami…”\n– Ekologiczny Dziennik Konchiologa, dzień 3","Jednostka",[],["Bandle City"],"ZWYKŁE"],"05BC094":["Akolita Zadymiacz","Gdy mnie przywołasz, stwórz w ręce kartę Mrok, jeśli jej nie posiadasz.","","„Koleżka na dachu z pewnością ma wiele historii do opowiedzenia. Wszyscy wiemy, że jest dość gadatliwy. Szkoda tylko, że nie mamy pojęcia, CO dokładnie mówi”. \n– Projektant Wysokiej Klasy","Jednostka",["YORDLE"],["Bandle City"],"ZWYKŁE"],"05BC146":["Malarka z Bandle","Zagraj: Odrzuć 1 kartę, by stworzyć w ręce stronnika Z Wielu Regionów. Zmniejsz jego koszt o 1.","","„W malowaniu nie chodzi o kopiowanie rzeczywistości, tylko wyrażanie tego, jak TY widzisz świat. A teraz widzę, że znów się poruszyłeś. Proszę, nie ruszaj się!”","Jednostka",["YORDLE"],["Bandle City","Piltover i Zaun"],"ZWYKŁE"],"05BC235":["Yordlowy Kowal","Atak: Daj sojusznikom o Sile równej lub mniejszej ode mnie Szybki Atak w tej rundzie.","","„Poppy nigdy mnie nie słucha, więc lepiej ty to zrób – cały sekret nie tkwi w młocie, lecz w Yordlu, który nim macha”.\n","Jednostka",["YORDLE"],["Bandle City"],"ZWYKŁE"],"05BC175":["Kroczący Teleskop","Zagraj: Pokaż Astralnego stronnika o koszcie 3 lub mniejszym, z cechą Epicki lub Z Wielu Regionów.","","Najdziwniejszą rzeczą nie było to, że teleskop wstał, przeciągnął się i zaczął spacerować po pomieszczeniu, lecz fakt, że nalegał na ubieranie się odpowiednio do pogody. Musiał się nieźle postarać, by znaleźć odpowiedni szalik.","Jednostka",["WRÓŻKA"],["Bandle City","Targon"],"RZADKIE"],"05BC182":["Prędkość Błyskawicy","Wycofaj sojusznika, aby zadać 2 pkt. obrażeń dowolnemu celowi.","","„Najpierw trzask, potem bum!” – Kennen","Zaklęcie",["ŻYWIOŁ"],["Bandle City"],"RZADKIE"],"05BC069":["Rozgadany Yordle","Atak: Stwórz Ulotną kartę Zatruta Strzałka w ręce.","","Nie dajcie mu zacząć.","Jednostka",["YORDLE"],["Bandle City"],"RZADKIE"],"05BC057":["Projektant Wysokiej Klasy","Przywołanie mnie zmniejszy koszt zaklęcia Mrok o 1, gdziekolwiek jest.","","„Gdy budujemy szajkę złoczyńców, kluczowym jest, by każdy ze złowieszczych członków wnosił coś wyjątkowego do szalonego zespołu. I tak, na przykład, jeden z moich kolegów ma zabójcze poczucie stylu”.\n– Fragment rozdziału 4. „Jak zostać superzłoczyńcą” autorstwa lorda Veigara","Jednostka",["YORDLE"],["Bandle City"],"RZADKIE"],"05BC108":["Yordlowy Odkrywca","Gdy przywołasz innego Yordla, przyznaj mu +1|+0.","","„Radość z odkrywania jest bezcenna, ale najlepsze odkrycia zwykle są również… ekhm… cenne”.","Jednostka",["YORDLE"],["Bandle City"],"ZWYKŁE"],"05BC183":["Dziadek Wróż","Gdy mnie przywołasz, stwórz w ręce kartę Głodna Kotosowa.\nGdy przywołasz kolejną Wróżkę, przyznaj jej +1|+0.","","„Zbierzcie się wszyscy, zbierzcie i wyczyśćcie uszy;\nto historia Dziadka Wróża, co serca kruszy.\nDzień w dzień czuwał pilnie nad głodnymi ptaszkami,\nkarmił dziwną mieszanką – twarogiem z ziarnami…”\n– Bajka z Bandle City","Jednostka",["WRÓŻKA"],["Bandle City","Ionia"],"RZADKIE"],"05BC188":["Ciekawski Muszelkoludź","Gdy losowo dokonasz wyboru karty niebędącej bohaterem, stwórz w ręce jej kopię i zmniejsz jej koszt o 1.","","Niezwykle nieśmiali i nieuchwytny Muszelkoludzie znani są z chowania się w swoich muszelkach, dopóki nie przeważy ciekawość. Po chwili oswojenia się pokazują swe radosne usposobienie oraz zamiłowanie do wywijania kawałów, na przykład poprzez imitowanie odgłosów innych podwodnych stworzeń.","Jednostka",[],["Bandle City"],"EPICKIE"],"05FR001":["Szaman Mrocznych Wilków","Koniec rundy: Jeżeli w tej rundzie udało ci się zadać obrażenia wrogiemu Nexusowi, Przemień mnie w kartę Berserker Mrocznych Wilków.","","„My nie umieramy jak tchórze! My upadamy z obnażonymi pazurami i wyszczerzonymi kłami. W ten sposób oddajemy hołd Wilkowi”. – Hyara Wszystkowidząca","Jednostka",[],["Freljord"],"ZWYKŁE"],"05FR002":["Szaman Mamutów","Koniec rundy: Jeżeli w tej rundzie udało ci się zadać obrażenia wrogiemu Nexusowi, Przemień mnie w kartę Berserker Mamutów.","","W starciu z drapieżnikami stada mamutów otaczają swoje młode oraz ciężarne samice. Tak też szamani ducha wielkich mamutów zwracają się nie tylko o siłę fizyczną swoich opiekuńczych duchów, lecz także o siłę jedności, dzięki której ochraniają swoje rodziny.","Jednostka",[],["Freljord"],"RZADKIE"],"05FR013":["Udyr","Gdy mnie przywołasz lub Uderzysz: Stwórz w ręce kartę Zamiana Stylu lub – jeśli już taką masz – zmniejsz jej koszt do 0.","Zagrano Zamiana Stylu 3+ razy.","„Duchy kształtują nasz świat tak samo, jak nasz świat kształtuje duchy. Czerpiąc z nich moc, czerpiemy ją z własnego wnętrza”.","Jednostka",[],["Freljord"],"Bohater"],"05FR016":["Zew Szamana","Stwórz w ręce 2 Ulotne karty Zamiany Stylu o koszcie 0.","","„Zobaczysz je… wielkie duchy kłów i szponów, łuski i pióra. W tym momencie zadrżysz ze strachu i zachwytu. Będziesz wiedzieć, że Starzy Bogowie o nas nie zapomnieli”. \n– Hyara Wszystkowidząca","Zaklęcie",[],["Freljord"],"ZWYKŁE"],"05FR012":["Hyara Wszystkowidząca","Gdy mnie przywołasz, stwórz w ręce kartę Zamiana Stylu.\nPierwsza karta Zamiana Stylu, którą zagrasz w każdej rundzie, kosztuje 0.","","Poważana przez wszystkich Hyara Wszystkowidząca, wielka szamanka, straciła wzrok dawno temu. Teraz patrzy oczyma jastrzębi i orłów, które gniazdują na szczytach gór będących jej domem. W dół stoków sprowadziły ją jednak złe wieści… ma nadzieję, że omeny pozostaną jedynie wizjami.","Jednostka",[],["Freljord"],"RZADKIE"],"05FR014":["Gniew Freljordu","Zagraj: Nałóż Odmrożenie na wroga.\nWrogowie z Siłą 3 lub mniejszą nie mogą blokować.","","„Byłam tam wiele lat temu… Najpierw nadeszło szczypiące, nieustępliwe zimno. Następne burza – gniewna i bezlitosna. Ostatni był ryk, który rozbrzmiewał tak ostro, że poczułam go w kościach. Padłam na kolana i modliłam się, aby nie okazało się, że popełniliśmy śmiertelny błąd. Wzywać wielkiego ducha oznacza prośbę o jego zemstę… i jego łaskę”. \n– Hyara Wszystkowidząca ","Jednostka",[],["Freljord"],"EPICKIE"],"05FR017":["Wewnętrzna Bestia","Daj sojusznikowi +1|+1 w tej rundzie. Stwórz w ręce kartę Zamiana Stylu.","","„Zgromadźcie się, duchy. Zgromadźcie…” – Udyr","Zaklęcie",[],["Freljord"],"ZWYKŁE"],"05FR006":["Mówca Kłów","Zagraj: Zadaj 1 pkt. obrażeń OBU Nexusom.","","Niewiele jest rodzin szamańskich, które służyły plemieniu Zimowego Szpona tak długo, jak rodzina Chuluuna. Jako szaman wielkiego morsa zwiastuje i przepowiada on szczodrość morza… oraz czyhające w nim niebezpieczeństwa. ","Jednostka",[],["Freljord"],"ZWYKŁE"],"05FR015":["Wyzwolone Duchy","Przyznaj sojusznikom +1|+1, gdziekolwiek są. Następnie zadaj 1 pkt. obrażeń WSZYSTKIEMU.","","„O pradawni, dodajcie nam sił w starciu z nadchodzącym zimnem i wypędźcie naszych wrogów niepowstrzymanym wiatrem oraz lodem. My bowiem nie zapomnieliśmy was ani należnej wam czci”.\n– Modlitwa Szamana Mrocznych Wilków","Zaklęcie",[],["Freljord"],"RZADKIE"],"05FR005":["Kościany Wróżbita","Gdy przetrwam obrażenia, zadaj 1 pkt. obrażeń wrogiemu Nexusowi.","","Niewielu spogląda w przyszłość z taką wprawą, jak robią to szamani służący Kościanemu Jeleniowi. Jeszcze mniej jest jednak w stanie zdzierżyć widok śmierci unoszącej się nad tymi, którzy przychodzą zaczerpnąć ich przepowiedni.","Jednostka",[],["Freljord"],"ZWYKŁE"],"05FR004":["Lisia Wędrowczyni","Gdy mnie przywołasz, stwórz w ręce kartę Zamiana Stylu.","","„Chętny, lecz rozważny. Szybki, lecz cichy. Droga lisa to radość oglądania, gdy samemu jest się niepostrzeżonym. Mądry przywódca honoruje tych, którzy podążają za duchem lisa, tak w podróży, jak i w wojnie. Żadnej bitwy nie można bowiem wygrać bez tropicieli i zwiadowców”. \n– Vrynna, Matka Blizn","Jednostka",[],["Freljord"],"ZWYKŁE"],"05IO003":["Starożytny Bezdrożnik","Kosztuję o 2 mniej za każdą jednostkę, którą udało ci się Wycofać w tej rundzie.","","„Himon’she, podróżowanie z tobą to prawdziwy zaszczyt. Powiadają, że twoja mądrość nie zna granic. Dokąd zmierzamy?”\n„Och, podążałem za twoimi śladami!” \n– Ahri i Starożytny Bezdrożnik","Jednostka",[],["Ionia"],"ZWYKŁE"],"05IO004":["Ahri","Atak: Za pierwszym razem, gdy przeprowadzam Atak Uderzeniowy, zamień mnie z sojusznikiem po mojej prawej, a następnie Wycofaj go.","Udało ci się Wycofać 5+ jednostek.","Poszukiwała samej siebie w sekretach innych. Wielokrotnie przeglądała się w cudzych oczach. Gdy zmierzała w stronę lasu, zastanawiała się, czy ukaże jej się kolejna soczewka, a może, choć raz, znajdzie na swej drodze lustro.","Jednostka",[],["Ionia"],"Bohater"],"05IO023":["Urok","Wycofaj sojusznika, aby dać wrogowi Podatność w tej rundzie.","","„Zdradź mi sekret”. – Ahri","Zaklęcie",[],["Ionia"],"ZWYKŁE"],"05IO020":["Piewca Wiatru","Zagraj: Wycofaj jednostkę.","","Chaos to broń słabych. Wilkowi goniącemu swą ofiarę przeszkodzi powalone drzewo. Orzeł nurkujący po zdobycz zatrzyma się przez nagłą wichurę. To my jesteśmy drzewem. Jesteśmy wiatrem.","Jednostka",[],["Ionia"],"ZWYKŁE"],"05IO007":["Sai’nen o Tysiącu Ogonów","Gdy mnie przywołasz, dobierz 2 karty oraz daj sojusznikom +1|+1 w tej rundzie.","","Las łatwo zdradza swoje sekrety… Niewielu jednak ośmieliło się o nie zapytać.","Jednostka",[],["Ionia"],"EPICKIE"],"05IO021":["Sadzonka Bogini Wierzby","Zagraj: Wycofaj sojusznika, by przywołać jego Efemeryczną kopię.\nOdlicz 3: Przywołaj kolejną Efemeryczną kopię.","","Bogini Wierzba niegdyś rosła w świętym zagajniku Omikayalan. To, co teraz tam wyrasta, może być silniejsze, może być słabsze. Liczy się jednak tylko tyle, że jest nowe.","Lokacja",[],["Ionia"],"RZADKIE"],"05IO024":["Dzieci Lasu","Wycofaj sojusznika lub wydaj 8 pkt. many, aby przywołać Efemeryczne kopie 3 Najsilniejszych stronników, których udało ci się Wycofać w tej grze.","","Wspomnienia mają kły.","Zaklęcie",[],["Ionia"],"EPICKIE"],"05IO001":["Opiekunka Lasu","Gdy mnie przywołasz, daj mi +1|+0 i Nieuchwytność w tej rundzie.","","„Mówią, że szczędzisz słów, by ocalić innych przed ciężarem swojej wiedzy. Hmm… A mnie się wydaje, że masz po prostu dość odpowiadania na pytania”. – Ahri","Jednostka",[],["Ionia"],"ZWYKŁE"],"05IO025":["Matriarchini Długiej Peleryny","Gdy w danej rundzie po raz pierwszy Wycofasz stronnika, przywołaj jego dokładną Efemeryczną kopię.","","Tajemnica jest lepsza niż jej odkrycie.","Jednostka",[],["Ionia"],"RZADKIE"],"05IO026":["Opłakiwana","Uderzenie w Nexus: Wycofaj mnie.","","Ci, którzy otaczają czcią polowanie, muszą umieć opłakiwać jego ofiary.","Jednostka",[],["Ionia"],"RZADKIE"],"05IO006":["Dziewięć Żyć","Przywołaj kartę Strażnik Granicy.","","Las potrzebował strażnika, kogoś, kto przez lata będzie bacznie strzegł jego granic. Może nawet przez wieki. Bez ruchu. Gai’sh chętnie zgłosił się do tej roli i szybko udowodnił swoje oddanie, ucinając sobie dziesięcioletnią drzemkę.","Zaklęcie",[],["Ionia"],"EPICKIE"],"05IO002":["Płaszcz Pamięci","Wybierz sojusznika obieranego za cel przez wrogie Szybkie zaklęcia, Powolne zaklęcia lub umiejętności wyznaczające tylko 1 sojuszniczy cel. Zatrzymaj je.","","Strzała nie zna zamiarów łowcy ani wartości jego ofiary.","Zaklęcie",[],["Ionia"],"ZWYKŁE"],"05SH014":["Xerath","Gdy zniszczysz sojuszniczą lokację, zadaj 1 pkt. obrażeń Najsłabszemu wrogowi.","Udało ci się zniszczyć 4+ sojusznicze lokacje.","„Niegdyś byli przyjaciółmi, lecz czas i zażyłość zmieniła ich w braci. Do wszystkich osiągnięć Azira z pewnością przyczynił się fakt, iż miał u swego boku Xeratha”. \n– Skryba Kah’nir, „Historia zastępu Wyniesionych”","Jednostka",["WYNIESIENI"],["Shurima"],"Bohater"],"05SH017":["Zwiastunka Maga","Gdy mnie przywołasz, a w tej grze udało ci się zniszczyć 4+ sojusznicze lokacje, przyznaj swoim bohaterom, gdziekolwiek są, +2|+2 oraz Zmiażdżenie.","","Zwiastunka rozłożyła szeroko swe ręce, kierując twarz ku słońcu, które skąpało Shurimę w swym krwawym świetle. „Chwała Wyniesionemu Magowi” – wypowiedziała z przejęciem, a jej głos odbił się echem od otaczających ją kolumn. „Chwała Xerathowi!”.","Jednostka",[],["Shurima"],"RZADKIE"],"05SH011":["Niepohamowany Gorliwiec","Ostatnie Tchnienie: Przywołaj kartę Sarkofag.","","Wystawność grobowca nie przydała się ani wyrzutkom, ani zmarłym.","Jednostka",[],["Shurima"],"RZADKIE"],"05SH022":["Pustynny Pojedynek","Daj wrogowi -2|-0 w tej rundzie. Sojusznik i ten wróg uderzają siebie nawzajem.","","„Podróżnik, który nie obawia się pustyni, nie zna pustyni”.\n– Shurimańskie przysłowie","Zaklęcie",[],["Shurima"],"ZWYKŁE"],"05SH003":["Obelisk Mocy","Odlicz 3 lub gdy mnie przywołasz, lub gdy mnie zniszczysz: Przyznaj Najsilniejszemu sojusznikowi +2|+0.","","Lśniące, popękane filary wyrastały z piasku. Te zepsute miejsca mocy mogły wzmocnić już potężną armię Xeratha.","Lokacja",[],["Shurima"],"ZWYKŁE"],"05SH016":["Niszczycielski Akolita","Zagraj: Zniszcz sojuszniczą lokację, aby przyznać sojuszniczym kartom Niszczycielscy Akolici +1|+1, gdziekolwiek są.","","Wszyscy akolici dokonywali poświęceń w zamian za zdobycie mocy. Najgorliwsi wyznawcy potrafili jednak wyrzec się zupełnie swego poprzedniego „ja”, przemieniając się w skorupy służące zarówno jako nośnik, jak i źródło energii ich nowego imperatora.","Jednostka",[],["Shurima"],"ZWYKŁE"],"05SH018":["Niewolnictwo Spustoszenia","Przywołaj kartę Posąg Inercji, aby przechować wewnątrz wszystkie sojusznicze jednostki oraz lokacje, które zginęły lub zostały zniszczone w tej rundzie.","","Energia magiczna nie jest marnowana, lecz wykorzystywana w innych celach.","Zaklęcie",[],["Shurima"],"EPICKIE"],"05SH012":["Wzniesiony Ołtarz","Odlicz 3 lub gdy mnie zniszczysz: Przywołaj kartę Dami’yin Uwolniony.","","„W każdym miejscu mocy należy wznieść obelisk, narzędzie, za pomocą którego Wyniesiony Mag może czerpać moc spod piasków”. – Zwiastunka Maga","Lokacja",[],["Shurima"],"EPICKIE"],"05SH020":["Konstrukt Spustoszenia","Stwórz w ręce kartę Niszczycielski Akolita lub Obelisk Mocy.","","„Stworzę Shurimę na swoje podobieństwo!” – Xerath","Zaklęcie",[],["Shurima"],"ZWYKŁE"],"05SH015":["Widząca w Piasku","Gdy mnie przywołasz, dobierz 1 kartę. Jeśli udało ci się dobrać lokację, powtórz tę czynność.","","Horyzont rozciągający się przed nią jarzył się energią. Tam, gdzie inni widzieli tylko piasek i kurz, ona dostrzegała wiodące linie, przepływające prądy czystej energii, które tylko czekały, by po nie sięgnąć.","Jednostka",[],["Shurima"],"EPICKIE"],"05SH004":["Wyzwolona Energia","Daj sojusznikowi +2|+1 w tej rundzie lub zniszcz sojuszniczą lokację, aby przyznać sojusznikowi +4|+2 w tej rundzie.","","„Wyrwę potęgę z głębi pustyni i zniszczę tych, którzy ośmielą się mi sprzeciwić!” – Xerath","Zaklęcie",[],["Shurima"],"ZWYKŁE"],"05SH002":["Wędrowca z Pustkowi","Gdy zniszczysz sojuszniczą lokację, przyznaj mi +1|+1.","","Akolici wiedzieli bardzo dużo, jeszcze zanim odszukali Xeratha. Gdy poszerzyli swoją wiedzę o wyniki jego badań, byli zaiste nie do zatrzymania.","Jednostka",[],["Shurima"],"ZWYKŁE"],"05SH007":["Tajemny Rytuał","Zniszcz sojuszniczą lokację lub jeden ze swoich kryształów many, aby zadać 4 pkt. obrażeń jednostce.","","„Niewielkie poświęcenie w zamian za wielką siłę”. – Xerath","Zaklęcie",[],["Shurima"],"RZADKIE"],"05NX009":["Zagubiona Dusza","Gdy mnie przywołasz lub odrzucisz, stwórz w ręce kartę Dwusieczna Zjawa.","","Demacianie czołgali się w kierunku swych umocnień, tylko po to, by znaleźć wśród nich śmierć. Mimo że udało im się zgładzić niektórych członków Szarego Legionu, mroczna fala wojny okazała się nie do powstrzymania.","Jednostka",[],["Noxus"],"EPICKIE"],"05NX006":["Odrodzony Grenadier","Aby zagrać, odrzuć 1 kartę.\nGdy mnie odrzucisz, przywołaj moją dokładną kopię.","","„Mamy do czynienia z pewną anomalią. Mimo że większość wskrzeszanych przez nas istot żywi wstręt wobec powrotu do życia, ten koleżka wydaje się rozumieć swoje położenie oraz doceniać możliwości, które ono oferuje. Ciekawe”.\n– Notatki Dr. Esslangera","Jednostka",[],["Noxus"],"ZWYKŁE"],"05NX005":["Pradawny Podżegacz","Gdy mnie odrzucisz, przyznaj swojemu Najsilniejszemu sojusznikowi +2|+0.","","Lady Noradi stawała się coraz potężniejsza, a w miarę, jak rosła w siłę, coraz częściej zastanawiała się, czy jest w stanie ożywić mieszkańców najstarszych grobowców Noxusu. Światło życia ledwie w nich migotało, lecz w tych gasnących płomieniach wciąż tańczyły cienie wojny.","Jednostka",[],["Noxus"],"RZADKIE"],"05NX001":["Sion","Gdy mnie odrzucisz, przyznaj swojemu Najsilniejszemu sojusznikowi Zmiażdżenie i umieść mnie w swojej talii.\nMam +1|+0 za każdą kartę, którą odrzucisz w tej grze (maksymalnie +7|+0).","Udało ci się odrzucić lub przywołać jednostki o łącznej Sile wynoszącej 35+.","Sion dostrzegał niewyraźne przebłyski swej przeszłości. Legiony stojące przed nim. Wyróżnienia. Korony. Wojna. Agonalne rzężenie króla. Wielka Nicość. Krew. Wspomnienia przemijały jednak niczym wyblakłe wstęgi na wietrze.","Jednostka",[],["Noxus"],"Bohater"],"05NX003":["Sól i Szwy","Aby zagrać, odrzuć 1 kartę.\nPrzywołaj kartę Odrodzony Grenadier i w tej rundzie daj jej +2|+0.","","„Powstań, moje dziecko…” – Dr Esslanger, Zadumany Lekarz","Zaklęcie",[],["Noxus"],"RZADKIE"],"05NX015":["Upadły Walecznik","Gdy mnie przywołasz, spraw, że Najsłabszy wróg nie może blokować.\nOstatnie Tchnienie: Stwórz w ręce kartę Wskrzeszony Walecznik.","","„Pierwsze minotaury, które wskrzesiłem, były potulnymi, bezużytecznymi stworzeniami. Nie ruszał ich ani ryk wojny, ani strach przed śmiercią”.\n– Notatki Dr. Esslangera","Jednostka",[],["Noxus"],"RZADKIE"],"05NX019":["Ku Chwale!","Reputacja: Kosztuję o 3 mniej. Przywołaj 2 karty Ambitne Tryfarianki.","","Poszukujący chwały nie cofną się przed niczym, aby ją zdobyć.","Zaklęcie",[],["Noxus"],"RZADKIE"],"05NX013":["Upadły Jeździec","Gdy mnie odrzucisz, stwórz w ręce kartę Wskrzeszony Jeździec.","","„Dopiero natarcie pancerza jeźdźca liśćmi Czarnocienia uchroniło go przed zaciekłością bazyliszka. Rośliny te pochodzą z przybrzeżnych terenów – podobnie jak te bestie – a ich liście są cierpkie i pełne trucizny”.\n– Notatki Dr. Esslangera","Jednostka",[],["Noxus"],"ZWYKŁE"],"05NX012":["Ryk Zabójcy","Aby zagrać, odrzuć 1 kartę. Zabij Najsłabszego wroga.","","„Nasi, nie-nasi… wszystko jedno”. – Sion","Zaklęcie",[],["Noxus"],"ZWYKŁE"],"05NX014":["Bronie Utraconych","Zadaj jednostce 3 pkt. obrażeń oraz przywołaj kartę Tryfariański Łamacz Tarcz.","","„Łamacz Tarcz!” – Sion","Zaklęcie",[],["Noxus"],"ZWYKŁE"],"05NX004":["Grobowy Lekarz","Zagraj: Odrzuć 1 kartę, aby dobrać jednostkę.","","Dr Esslanger był niegdyś szanowanym, szykującym się do emerytury lekarzem, który ukształtował swoje dobre imię latami ciężkiej pracy. Jednak dopiero gdy do jego gabinetu przyniesiono młodą szlachciankę o krwi sczerniałej od zdrady, zaczął prawdziwą służbę dla Noxusu.","Jednostka",[],["Noxus"],"ZWYKŁE"],"05NX016":["Dama Krwi","Gdy odrzucisz z ręki sojusznika niebędącego Ulotną kartą, stwórz w ręce jego Ulotną kopię.","","Lady Faris Noradi wyprowadziła swój Szary Legion z noxiańskiej stolicy pod osłoną nocy. Dotarcie do niewielkiego obozu Demacian, który wyśledzili jej zwiadowcy, zajęło im trzy naznaczone krwią tygodnie. Przyszedł czas na pokaz siły.","Jednostka",[],["Noxus"],"EPICKIE"],"05NX002":["Zbuntowana Szlachcianka","Przyznaj mi +2|+1, gdy w tej grze odrzucisz 3+ karty.","","„Czy jest coś, co lepiej umacnia lojalność potencjalnego zdrajcy niż widok zaszlachtowanej konspiratorki, przywróconej do walki pod noxiańskim sztandarem? Wszyscy będą walczyć – w ten czy inny sposób”. – Dama Krwi","Jednostka",[],["Noxus"],"ZWYKŁE"],"05BW005":["Nami","Gdy zagrasz zaklęcie, przyznaj +1|+0 innemu Najsłabszemu sojusznikowi, który nie jest Unieruchomiony.","Udało ci się zagrać 5+ zaklęć z sojuszniczą Nami w grze.","„Pożegnałaś się już, młoda Władczyni Przypływów?”\n„Tak, wielka matko”.\n„Boisz się?”\n„Tak, wielka matko…”\n„To dobrze. Strach oznacza ostrożność. Jednak wierz w siebie tak, jak my w ciebie wierzymy. Idź już. Niech prądy ci sprzyjają”.","Jednostka",[],["Bilgewater"],"Bohater"],"05BW006":["Odpływ","Zadaj 2 pkt. obrażeń losowemu wrogowi lub wrogiemu Nexusowi i stwórz w ręce kartę Przypływ.","","„Nie lekceważ potęgi fal…” – Nami","Zaklęcie",["ŻYWIOŁ"],["Bilgewater"],"ZWYKŁE"],"05BW002":["Podróżujący Piaskoskoczek","","","„Jasne, niektórzy na nas polują, ale oni polują na wszystko. Ogólnie większości lądowych, których miałem okazję spotkać, chodziło po prostu o fajny czas spędzony w wodzie, dokładnie tak samo, jak nam. Wszyscy jesteśmy podobni”.","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"05BW008":["Podmorski Stróż","Gdy zagrasz zaklęcie, daj mi +2|+0 w tej rundzie.","","„Wielu członków naszego plemienia widzi w Loto coś niepokojącego. Postrzegają go jako niestrudzonego wojownika o zatroskanym, pełnym dystansu spojrzeniu. Wiem jednak, że w głębi jego serca czai się strach – strach, że nie jest wystarczająco silny, by nas ocalić. Ale skrywa w sobie także… głęboką miłość”. – Tama, Marajska Pieśniarka","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"05BW011":["Admirałka Floty Shelly","Gdy zagrasz 2 zaklęcia w każdej rundzie, przyznaj innym sojusznikom +1|+1.","","„SŁUCHAJ NO, ŻÓŁWNIERZU. MUSISZ WIEDZIEĆ, ŻE MAM NA SWOJIM KONCIE PONAD PIĘŚSET POTWIERDZONYCH ZABÓJSTW I JEZDEM NAJWYŻSZĄ ADMIŁAŁOWĄ W SIŁACH MORSKICH. JAK MÓWIĘ, ŻE MASZ PŁYWAĆ, TO TY LEPIEJ PŁYWAJ, JASNE?! OKEJ, DZIENA!”","Jednostka",[],["Bilgewater"],"EPICKIE"],"05BW003":["Fala Przypływu","Zadaj 1 pkt. obrażeń dwóm losowym wrogom i stwórz w swojej talii kartę Wielka Fala.","","„Niech oceany wystąpią z brzegów!” – Nami","Zaklęcie",["ŻYWIOŁ"],["Bilgewater"],"RZADKIE"],"05BW004":["Wcielenie Fal","Jeśli masz otrzymać kryształ many, w zamian odzyskujesz manę zaklęć.\nGdy zagrasz zaklęcie, stwórz w ręce losowe zaklęcie o koszcie 3 lub mniejszym i przyznaj mu Ulotność.","","Leo’lei jest dla Marajów zapowiedzią wielkiej zmiany. Mówi się, że każde machnięcie jego wspaniałych skrzydeł wprawia fale w ruch.","Jednostka",[],["Bilgewater"],"EPICKIE"],"05BW001":["Strażniczka Marajów","Gdy mnie przywołasz, przywołaj losowego stronnika o koszcie 1.","","Marajowie rzadko oddalają się od swojego domostwa. Ai’la urodziła się jednak ciekawa świata. Mimo że w jej obowiązkach leży obrona plemienia, każdą chwilę poświęca marzeniom o prawdziwej wolności.","Jednostka",[],["Bilgewater"],"RZADKIE"],"05BW010":["Wielka Matka Marajów","Gdy mnie przywołasz, stwórz w talii 5 losowych zaklęć o koszcie 6+ i obniż ich koszt do 3.","","Pradawna ojczyzna Marajów jest chroniona przez astralne światło kamienia księżycowego. Co sto lat światło to zaczyna blednąć, a nowy Władca bądź Władczyni Przypływów ma za zadanie znaleźć kolejny kamień. Bez nich Marajowie pogrążyliby się w ciemności oraz padli ofiarą potworności kryjących się w głębinach.","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"05BW013":["Marajska Pieśniarka","Gdy mnie przywołasz, przyznaj mi Nieuchwytność, jeśli udało ci się zagrać w tej rundzie zaklęcie.","","„Ocean fali powrotu wyczekuje,\nna przypływ i odpływ zawsze się raduje.\nSłodki dźwięk, gdy fala przy brzegu się spłyca,\nsprawia, że ocean wiecznie się zachwyca”.\n– Zwrotka z „Serenady Władczyni Przypływów”","Jednostka",[],["Bilgewater"],"RZADKIE"],"05PZ015":["Sprawiedliwa Motocyklistka","Za każdym razem, gdy twój przeciwnik dobierze kartę, umieść 1 kartę Pułapka z Bombą Błyskową wśród pierwszych 8 kart z wierzchu talii przeciwnika.","","„Funkcjonariuszka ścigała podejrzanego, poruszając się z zawrotną prędkością, aż do zastawionej przez nią samą pułapki. Po zatrzymaniu podejrzanego sama złożyła wniosek, by ukarano ją mandatem za przekroczenie prędkości, twierdząc (dość teatralnie), że »sprawiedliwość to wyboista droga«”.\n– Fragment notatki policyjnej","Jednostka",[],["Piltover i Zaun"],"EPICKIE"],"05PZ012":["Posterunkowa Archiwistka","Zagraj: Wybierz zaklęcie z 5 pierwszych kart z wierzchu swojej talii i stwórz w ręce jego dokładną Ulotną kopię, a potem wtasuj te karty do swojej talii.","","Detektyw nie osiągnie nic bez dowodów, a to właśnie praca archiwisty polega na zbieraniu każdego skrawka informacji i dostarczaniu nowych poszlak.","Jednostka",[],["Piltover i Zaun"],"RZADKIE"],"05PZ026":["Linia Produkcyjna","Przywołaj 2 karty Pracownicy Kuźni.","","„Druga zmiana!” – Naczelniczka Kuźni","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"05PZ019":["Poszukiwany, Poszukiwana","Wybierz gracza, który odrzuci kartę o najmniejszym koszcie i dobierze 3 karty.","","„Wszystko ma swoją cenę”. – Corina Veraza","Zaklęcie",[],["Piltover i Zaun"],"EPICKIE"],"05PZ031":["Albus Ferros","Gdy mnie przywołasz, dobierz kartę Jayce. Atak: Zadaj 3 pkt. obrażeń wrogiemu Nexusowi. Za każde zaklęcie o koszcie 6+, które udało ci się zagrać w tej grze, zwiększ tę wartość o 1.","","„Wielkoduszny Albus Ferros po raz kolejny WKROCZYŁ w blask reflektorów, drastycznie przebijając ofertę rodów Cadwalder i Giopara o nabycie praw do sponsorowania badań Jayce’a nad hexbramą. Jak mówi przysłowie: »Dobry dzień dla Ferrosów to dobry dzień dla Piltover« – a wczorajszy dzień był istotnie bardzo dobry dla rodu Ferros!”\n– Fragment sponsorowanej rozkładówki z Dziennika Piltover","Jednostka",[],["Piltover i Zaun"],"EPICKIE"],"05PZ027":["Porażająca Eksplozja","Zadaj 3 pkt. obrażeń wrogowi lub wrogiemu Nexusowi i 3 pkt. kolejnemu.","","„Strzał!” – Jayce","Zaklęcie",[],["Piltover i Zaun"],"RZADKIE"],"05PZ022":["Jayce","Zagraj: Przyznaj mi Szybki Atak lub Wyzwanie.","Udało ci się zagrać dwa zaklęcia o koszcie 6+. Gdy awansuję, stwórz w ręce kartę Brama Przyspieszenia.","„– Jak więc wiesz, Roso, ta technologia mocoformacyjna może wkrótce zmienić ten świat.\n– Doprawdy przełomowa praca, Jayce. I ten sposób, w jaki łączą się współinhiberatory. Zapiera dech.\n– Owszem. I to wszystko pomysł Axela! Prawda, chłopcze?\n– Znasz mnie, stary. Nie lubię się przechwalać…”","Jednostka",[],["Piltover i Zaun"],"Bohater"],"05PZ017":["Śmierdząca Sprawa","Zadaj jednostce 2 pkt. obrażeń. Jeśli w tej rundzie udało ci się dodać do swojej ręki 2+ karty, zamiast tego zadaj jej 3 pkt. obrażeń.","","„Daj im chwilę zwietrzeć. Żółtodzioby nie są w stanie znieść tego smrodku. Ale uwierz… Jak już się przyzwyczaisz, nie ma nic lepszego!” – Handlarz Grzybów","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"05PZ013":["Rozjemca z Piltover","Zadaj 2 pkt. obrażeń jednostce i umieść 2 karty Pułapki z Bombą Błyskową wśród pierwszych 8 kart z wierzchu talii przeciwnika.","","„Oto MOJA wizytówka”. – Caitlyn","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"05PZ020":["Zasadzka","Daj sojusznikowi +2|+0 w tej rundzie. Jeśli w tej rundzie udało ci się dodać do swojej ręki 2+ karty, daj mu też Nieuchwytność w tej rundzie.","","„Otoczymy lokalizację, używając zadymiarek, by ukryć nasze położenie…” – Caitlyn","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"05PZ024":["Finansista Ferros","Zagraj: Pokaż zaklęcie o koszcie 6+ z twoich regionów.","","„Chyba jedyną dobrą rzeczą w finansowaniu mojej pracy przez ród Ferros było połączenie sił z Reggiem. To nie tylko jedna z najbardziej kompetentnych osób, z jakimi przyszło mi pracować, ale też naprawdę spoko koleś”.\n– Fragment wpisu z dziennika Jayce’a","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"05PZ010":["Taran Tajniaków","Umieść 2 karty Pułapka z Bombą Błyskową wśród pierwszych 8 kart z wierzchu talii przeciwnika. Dobierz 1 kartę.","","„Na mój znak”. – Caitlyn","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"05PZ014":["Intrygantka Corina","Zagraj: Umieść 5 kart Pułapka z Bombą Błyskową wśród pierwszych 5 kart z wierzchu talii przeciwnika lub aktywuj efekty wszystkich pułapek na pierwszych 5 kartach z wierzchu talii przeciwnika.","","Corina uśmiechnęła się na widok Strażników Piltover taranujących jej drzwi i depczących jednocześnie cenne kwiatki, które rozpościerały już swój trujący pyłek. Wszystko szło zgodnie z planem.","Jednostka",[],["Piltover i Zaun"],"EPICKIE"],"05PZ002":["Dla Wtajemniczonych","WSZYSCY gracze dobierają 2 karty.","","„To dość popularna sprawa. Przyglądał się jej wcześniej jakiś facet. Bardzo proszę!” – Posterunkowa Archiwistka","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"05PZ021":["Kuźnia Jutra","Gdy mnie przywołasz, przywołaj kartę Pracownik Kuźni. Gdy zagrasz zaklęcie o koszcie 6+, zniszcz mnie i odzyskaj manę zaklęć.","","Jeśli Piltover jest miastem napędzanym innowacją, to tamtejsze kuźnie stanowią jego silniki.","Lokacja",[],["Piltover i Zaun"],"RZADKIE"],"05PZ025":["Naczelniczka Kuźni","Uderzenie: Odzyskaj 1 pkt. many zaklęć.","","„Potrzeba dwóch rzeczy, żeby nadać życie pomysłowi na papierze. Jedną częścią równania są fundusze, drugą – dobra kuźnia. I nie chodzi tylko o narzędzia czy sprzęty w tej kuźni. Jeśli naczelnik nie ma w sobie daru do tego, co robi, to cóż – twój pomysł zostaje na papierze”. – Jayce","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"05PZ006":["Caitlyn","Uderzenie: Umieść 2 karty Pułapka z Bombą Błyskową wśród pierwszych 8 kart z wierzchu talii przeciwnika.","Udało ci się aktywować 5+ swoich pułapek.","Caitlyn zawsze była dociekliwa i dokładna, co pomogło jej w zawrotnym tempie zdobywać kolejne awanse w organach ścigania Piltover. Jednak dopiero pojawienie się sprawy dotyczącej tajemniczego „C”, porzuconej przez niezliczoną liczbę śledczych, sprawiło, że w końcu Caitlyn prawie natrafiła na godnego przeciwnika. Prawie.","Jednostka",[],["Piltover i Zaun"],"Bohater"],"05PZ004":["Patrol Oficerów","Gdy mnie przywołasz, stwórz w ręce kartę Poszukiwany, Poszukiwana.","","Ciche rozstawienie się na ulicy i przygotowanie tarana nie trwały długo. Właściwie czekaliśmy tylko na znak od Caitlyn.","Jednostka",[],["Piltover i Zaun"],"RZADKIE"],"05PZ009":["Policyjny Przykrywkowiec","Uderzenie w Nexus: Umieść 2 karty Pułapki z Bombą Błyskową wśród pierwszych 8 kart z wierzchu talii przeciwnika.","","Ciemne i pełne przemocy ulice Zaun sprawiły, że Zayne Asako musiał dorosnąć bardzo szybko, podobnie jak wszystkie inne dzieciaki z tych okolic. Śmierć jego brata w jednym z wielu bezsensownych zatargów gangów przekonała go, by dołączyć do organów ścigania Piltover. Miał nadzieję, że pilnowanie prawa i porządku uczyni jego dom bezpieczniejszym.","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"05PZ016":["Cios Łaski","Umieść wrogiego stronnika w talii przeciwnika. Następnie przeciwnik dobiera 1 kartę.","","Wielkie miasto Piltover jest domem wielu z najpotężniejszych umysłów Runeterry. Więzienie w Piltover również jest domem wielu z najpotężniejszych umysłów Runeterry.","Zaklęcie",[],["Piltover i Zaun"],"RZADKIE"],"05PZ030":["Anomalia Hextechowa","Gdy mnie dobierzesz lub stworzysz mnie w ręce albo na Początku rundy: Gdy jestem w ręce, przemień mnie w losowe zaklęcie o koszcie 6+.","","„…konfiguracja hextechu do stanu stabilnego była największą przeciwnością, z jaką przyszło mi się zmierzyć. Przez większość nocy miałem wrażenie, że kryształy i hexyt aktywnie spiskują przeciwko mnie. Tylko dzięki metodzie ciągłych prób i błędów udało mi się w końcu nakłonić komponenty do harmonijnej pracy…”\n– Fragment z dziennika Jayce’a","Zaklęcie",[],["Piltover i Zaun"],"RZADKIE"],"05PZ028":["Podniebny Wycieczkowiec Ferros","Przyznaj mi +2|+0, jeśli udało ci się zagrać zaklęcie o koszcie 6+ w tej grze.","","„Ludzie tego miasta padają na kolana u stóp »inteligencji«. Ale czym jest nawet największy z umysłów bez środków, dzięki którym mógłby się wyrazić? Nie. To ja pokażę Piltover prawdziwą wielkość. Będzie wznosić się ponad nimi. Przysłoni samo słońce. Będzie na niej wyryte moje imię”. – Albus Ferros","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"05PZ038":["Salwa Rakiet","Zadaj 4 pkt. obrażeń wrogowi i 1 pkt. obrażeń wszystkim innym wrogom.","","„Miały wystrzelić do góry, nie WSZĘDZIE DOOKOŁA! Wielkie nieba!” – Heimerdinger","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"05PZ035":["Śmierdzący Łomp","Ostatnie Tchnienie: Stwórz w talii wroga moją kopię. Umieść na niej 2 Trujące Grzyby.","","Smrodu Łompów w szczycie grzybowego sezonu nie można pomylić z niczym innym. Rynsztok wypełniony nieświeżymi rybami w połączeniu ze zgniłymi jajami to przy tym odświeżacz powietrza.","Jednostka",[],["Piltover i Zaun"],"RZADKIE"],"05PZ029":["Hextechowy Tragarz","Przyznaj sojuszniczym Maszynom +1|+0, gdziekolwiek są, jeśli udało ci się zagrać zaklęcie o koszcie 6+ w tej grze.","","Hextechowego Tragarza początkowo skonstruowano, aby transportował surowce przez Piltover, jednak z biegiem czasu mieszkańcy najwyraźniej wykształcili pewną sympatię względem niego. Załoga z kuźni Jayce’a zaczęła nazywać go Skarbek. Piltoverski lord rzekomo ofiarował mu swój kapelusz, a mijające go na ulicach dzieci ozdabiają go wszystkim, co akurat wpadnie im w ręce.","Jednostka",["MASZYNA"],["Piltover i Zaun"],"RZADKIE"],"05SI014":["Księga Żalu","Początek rundy: Stwórz w swojej ręce Ulotną kopię zagranego w ostatniej rundzie zaklęcia niebędącego Ulotnym.","","Błogosławione Wyspy zapominają. Wyspy Cienia pamiętają. Wyspy Cienia zapominają. Błogosławione Wyspy pamiętają.","Lokacja",[],["Wyspy Cienia"],"EPICKIE"],"05SI013":["Łapacze Mgły","W każdej rundzie, gdy po raz pierwszy zabijesz jednostkę za pomocą zaklęcia, przywołaj Efemeryczną kartę Zjawa z Mgły.","","Czarna Mgła wrzuca swe ofiary w nieskończony wir cierpienia. Tek i Kana, za pomocą Łapaczy Mgły, dają jej ofiarom szansę na uwolnienie się z tego okrutnego wiru.\n","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"05SI009":["Senna","Gdy mnie przywołasz lub Zaatakuję: Stwórz w ręce kartę Mrok, jeśli jej nie posiadasz. Twoje obrażenia oraz zaklęcia zabijające są Szybkie.","Widziałam, jak zabijasz 3+ jednostki za pomocą zaklęć lub ginie sojuszniczy Lucian.","„Być Strażnikiem oznacza walczyć. W imię utraconego „ja” lub utraconych bliskich. Ale czy tylko tyle? Być Strażnikiem oznacza też żyć – dla siebie… i dla tych, których kochamy”.","Jednostka",[],["Wyspy Cienia"],"Bohater"],"05SI016":["Świtający Cień","Zabij jednostkę i daj wszystkim wrogom -2|-0 w tej rundzie.","","„Nie ma cienia bez światła. Nie ma śmierci bez życia”. – Senna","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"05SI004":["Obserwator Wysp","W każdej rundzie zadaj 2 pkt. obrażeń wrogiemu Nexusowi za każde pierwsze zabicie jednostki za pomocą zaklęcia.","","„Pieski to pieski”. – Mądrość wyryta w duszy","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"05SI012":["Strażniczka Solari","Gdy mnie przywołasz, stwórz w ręce kartę Mrok, jeśli jej nie posiadasz.","","„Nie pamiętam już, kiedy widziałam słońce. Pamiętam jednak, jakie ono jest. To mi wystarczy”.","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"05SI008":["Ixtalska Strażniczka","Gdy mnie przywołasz, stwórz w ręce kartę Mrok, jeśli jej nie posiadasz. Gdy w tej rundzie zagrasz kolejną kartę Mrok, skopiuj ją. Kopia celuje we wrogi Nexus.","","„Senno, pytałaś mnie, co jest moim powodem uczestniczenia w tej walce. W końcu Mgła nic mi nie odebrała, nie zagraża mojemu domowi. Chodzi o to, że istnieje, a nie powinna. Chcę dowiedzieć się dlaczego. Czy sentymenty są aż tak ważne?”","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"05SI003":["Przeszywająca Ciemność","Zaczerpnij 5 pkt. Zdrowia z jednostki.","","„Śmierć przyciąga życie”. – Senna","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"05SI010":["Dess i Ada","Gdy mnie przywołasz, stwórz w ręce kartę Mrok, jeśli jej nie posiadasz. Koszt twojej kolejnej karty Mrok w tej rundzie wynosi 0 i zyskuje ona „Zadaję obrażenia wszystkim wrogim celom”.","","„Kolejny koszmar?”\n„Nie był taki zły. Nie było tam ciebie”.\n„Głuptaska. Co cię przestraszyło?”\n„Że nie było tam ciebie”.","Jednostka",[],["Wyspy Cienia"],"EPICKIE"],"05SI011":["Wschodząca Strażniczka","Gdy po raz pierwszy zabijesz jednostkę za pomocą zaklęcia, przyznaj mi +2|+1.","","Co widzi Mgła, gdy przygląda się Maeve? Entuzjazm, pewność siebie i wieczny optymizm. Co musiałoby się stać, by ten żywy płomień zgasł? Czegóż śmierć może bać się bardziej od życia?","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"05SI015":["Strażnik Buhru","Gdy po raz pierwszy zabijesz jednostkę za pomocą zaklęcia, przyznaj mi +2|+1.","","Filozofie Buhru i Strażników łączy jeden wspólny punkt – wszystko ma swój koniec, a niektórym rzeczom trzeba go ułatwić.","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"05MT004":["Camphor Zwiastunka Zwątpienia","Gdy mnie przywołasz, przyznaj mi Tarczę Magii, Zmiażdżenie oraz Wyzwanie, jeśli udało ci się obrać sojuszników za cel w 4 różnych rundach.","","Demonica Camphor przez wieki nawiedzała ziemie Targonu, obdzierając swoje ofiary z ich najmocniejszych stron. Potężnym wojownikom zabierała siłę, mędrcom – potęgę umysłu. Jednak czerpała przyjemność nie z tych dobrodziejstw, a z cierpienia, poczucia zwątpienia i beznadziejności, które wywoływała. Była potworem w każdym tego słowa znaczeniu.","Jednostka",[],["Targon"],"EPICKIE"],"05MT006":["Ranny Biały Płomień","","","„Mieszkańcy Targonu nie potrzebują już dowodu na okrucieństwo bogów. Spójrzcie, do czego nas doprowadzili. Przyjrzyjcie się, jak potraktowali naszych najdroższych kompanów”. – Pantheon","Jednostka",["SMOK"],["Targon"],"RZADKIE"],"05MT008":["Cios Tarczą","Daj sojusznikowi +1|+1 i Ogłusz wroga.","","Pantheon był wprawiony w boju. Niezliczone walki, które stoczył, nauczyły go, że przeciwnicy zwykle śledzą ruchy jego włóczni, a nie tarczy.","Zaklęcie",[],["Targon"],"RZADKIE"],"05MT014":["Astralny Cud","Ogłusz 2 wrogów.","","„Nocne niebo Targonu to istna wspaniałość niewyobrażalnego piękna. Wręcz zbyt łatwo jest zatracić się w jego bezmiarze, nie wiedząc, jak daleko sięgają gwiazdy i jakiego rodzaju istoty mogą z nich na nas spoglądać…”\n– Targoński wspinacz","Zaklęcie",[],["Targon"],"ZWYKŁE"],"05MT003":["Pantheon","","Udało ci się obrać sojuszników za cel w 5+ różnych rundach.","Stojącego tu Atreusa obdarły z wolności wychwalane przez niego Aspekty. Obejmują go teraz płonienie Wojny, w wyniku której otrzymał dary, jakich większość śmiertelników nie pojmuje. Oto mężczyzna gotowy na walkę i śmierć za tych, których darzy czcią.","Jednostka",[],["Targon"],"Bohater"],"05MT013":["Iula","Zagraj: Przyznaj sojusznikowi Tarczę Magii lub Zmiażdżenie. Jeśli tego nie zrobisz, przyznaj jedno z tych słów kluczy mnie.","","Iula wciąż pamięta palący ból, który przeszył całe jej ciało na wieść o śmierci jej małżonka. Gdy Pantheon odwiedził ją, pytając, czy zechciałaby pomóc mu w zabiciu monstrum odpowiedzialnego za to cierpienie, nie musiał długo czekać na odpowiedź.","Jednostka",[],["Targon"],"ZWYKŁE"],"05MT009":["Więzy Walki","Przyznaj 2 sojusznikom +2|+2.","","Choć sprzeciwienie się bogom wydaje się być daremne, to poprzez blizny i krzyki garstka dzielnych poznała cenną prawdę. Bogowie kierują się egoizmem oraz własnym interesem zamiast pamięcią o potędze braterstwa. Właśnie ta wiedza będzie ich bronią. Właśnie ta wiedza będzie ich tarczą.","Zaklęcie",[],["Targon"],"ZWYKŁE"],"05MT010":["Oślepiona Mistyczka","Zagraj: Przyznaj sojusznikowi +1|+1 oraz Ucisz wrogiego stronnika.","","Eshiyme była niegdyś poważaną wyrocznią, która używała swego Wzroku, by prowadzić zagubionych. Ten dar został jej odebrany przez Camphor, która chciała napawać się cierpieniem ofiary. Demonica nie doceniła jednak dzielnej Eshiyme.","Jednostka",[],["Targon"],"ZWYKŁE"],"05MT002":["Ramię w Ramię","Daj 2 sojusznikom +1|+2 w tej rundzie.","","„Potęgi musimy upatrywać w sile naszych więzów”. \n– Pantheon","Zaklęcie",[],["Targon"],"RZADKIE"],"05MT012":["Wyzwolony Kolos","Gdy mnie przywołasz lub zaatakuję: Stwórz w ręce kartę Klejnot.","","Kolosy to starożytni i otoczeni czcią obrońcy najznamienitszych stron Targonu. Zadanie im rany przyrównać można do zniewagi wyrządzonej górze. Dręczenie ich jest dla każdego Targonianina niewybaczalną zbrodnią.","Jednostka",[],["Targon"],"ZWYKŁE"],"05MT011":["Mimo Wszystko","Jeśli przeciwnik kontroluje więcej jednostek od ciebie, przyznaj sojusznikowi +1|+1 za każdą dodatkową jednostkę.","","Wojownicy wiedzieli, że ruszają w bój przeciw bytom o niewyobrażalnej mocy. Zdawali sobie sprawę, że mogą zginąć. Ale, mimo wszystko, wkroczyli do walki.","Zaklęcie",[],["Targon"],"EPICKIE"],"05MT005":["Bohater Sagi","","","Tor czuł, jak życie uchodzi z niego z każdym uderzeniem serca. Mogłoby się wydawać, że narastająca ciemność powinna przepełnić go lękiem. On jednak odnalazł w niej swój cel. Nie tylko ochoczo stawiał czoła śmierci, ale też gotów był zabrać ze sobą każdego demona, który śmiał pozbawić go życia. Właśnie tak zostanie zapamiętany. Oto saga Tora.","Jednostka",[],["Targon"],"ZWYKŁE"],"05DE003":["Gorlith Niezdobyty","Zagraj: Zamień moje Zdrowie ze Zdrowiem twojego Nexusa.\nWrogowie o niższej wartości Zdrowia niż moja nie mogą mnie zablokować.","","„Pełen honoru wyraz uznania dla tych, których nie ma już z nami, lecz którzy nigdy nie zostali zapomniani: Gdy lud Demacii ujrzy promienie słońca oświetlające jego postać, zazna nadziei, a niezłomny duch, który zainspirował jego powstanie, będzie żył za jego sprawą”. \n– Tablica z warsztatu Duranda","Jednostka",[],["Demacia"],"EPICKIE"],"05DE009":["Galio","Gdy mnie przywołasz, przyznaj innym sojusznikom +0|+3.","Koniec rundy: Łączne Zdrowie twoich sojuszników wynosi 25+.","Wiele lat po stworzeniu Galio trwał w uśpieniu – bez uczuć i w niewiedzy. Dopiero kiedy magia powołała go do życia i kiedy doświadczył wynikłego z tego smaku bitwy, zaznał on radości bycia wśród żywych. Teraz, kiedy spał, tęsknił za tymi wspaniałymi rzeczami!","Jednostka",[],["Demacia"],"Bohater"],"05DE020":["Tarcza Duranda","Przyznaj sojusznikowi +0|+3. Na początku kolejnej rundy przyznaj mu +0|+2.","","Sam widok Galio wystarcza, aby zainspirować szlachetne serca Demacian.","Zaklęcie",[],["Demacia"],"RZADKIE"],"05DE021":["Potęga Gwardii","Aby zagrać tę kartę, zużyj całą swoją manę. Przywołaj kartę Nieustraszona Gwardia i zwiększ jej statystyki do tej wartości. Jeśli zużyto 9+ many, przyznaj pozostałym sojuszniczym Elitarnym +2|+2.","","Gdy wydaje się, że cała nadzieja stracona, żołnierze Demacii zwracają wzrok ku Gwardii.","Zaklęcie",[],["Demacia"],"EPICKIE"],"05DE017":["Wichry Wojny","W pełni ulecz sojusznika. Następnie ten sojusznik i wróg uderzają siebie nawzajem.","","„Bierzmy się do roboty!” – Galio","Zaklęcie",[],["Demacia"],"RZADKIE"],"05DE010":["Rzeźbiarka Durandów","Gdy przywołasz innego sojusznika, przyznaj mu +0|+1.","","„Może nie jest to widoczne dla niewprawnego oka, ale praca wspaniałego artysty różni się od innych zaledwie jednym ruchem dłuta”.","Jednostka",[],["Demacia"],"ZWYKŁE"],"05DE013":["Petrucytowy Rogacz","Wsparcie: Otrzymuję wszystkie obrażenia zadane wspieranemu przez mnie sojusznikowi w tej rundzie.","","Biorąc przykład z łowcy dosiadającego jelenia, petrucytowy strażnik przyćmił stworzenie, które zainspirowało jego elegancką formę.","Jednostka",[],["Demacia"],"EPICKIE"],"05DE015":["Górski Smok","Furia przyznaje mi +0|+2 zamiast +1|+1.","","Mimo swojego wyglądu spokojne górskie smoki nie są prędkie do gniewu, a ich spokój w towarzystwie innych górskich stworzeń czyni z nich naturalnych obrońców bezbronnych stad.","Jednostka",["SMOK"],["Demacia"],"EPICKIE"],"05DE019":["Architekt Durandów","Wsparcie: Daj wspieranemu przeze mnie sojusznikowi +0|+2 i Ogrom w tej rundzie.","","„– Łowca Elmheart przyniósł nam ponure wieści – architekt powiedział spokojnie, skupiając się na ponownym zwinięciu zwoju, by ukryć, jak bardzo drżą mu ręce. Zwrócił się do oczekujących rzeźbiarzy i sztywno skinął w ich stronę. – Wygląda na to, że nadszedł już czas, aby niewidoczni obrońcy Demacii wyszli ze swojego ukrycia”.","Jednostka",[],["Demacia"],"RZADKIE"],"05DE014":["Protegowana Durandów","Zagraj: Przyznaj sojusznikowi +0|+1 i Wytrzymałość.","","Słysząc dźwięk kopyt bijących o ziemię, Shireen uniosła wzrok znad swojej pracy. Pośpiech łowcy wywołał w niej niepewność, lecz również ciekawość. Pospieszyła swojego petrucytowego ptaka, aby wzbił się w powietrze, i podążyła w ślad za łowcą.","Jednostka",[],["Demacia"],"ZWYKŁE"],"05DE012":["Petrucytowy Szerokoskrzydły","Gdy przywołasz innego sojusznika, przyznaj mi Wyzwanie.","","Gdy Szerokoskrzydły przeleciał ponad głowami demaciańskich żołnierzy, zainspirowani jego wytrzymałą postacią wydali oni z siebie okrzyk wiwatu.","Jednostka",[],["Demacia"],"RZADKIE"],"05DE018":["Petrucytowy Ogar","","","„Zawsze miło jest zobaczyć, jak ożywają. Zapomina się, jak odmienny jest każdy z nich, jak ich osobowości odzwierciedlają artystę, który je stworzył”. \n– Rzeźbiarka Durandów","Jednostka",[],["Demacia"],"ZWYKŁE"],"06NX024":["Lord Broadmane","Zagraj: Zadaj 2 pkt. obrażeń wrogowi.\nTwoje Szybkie zaklęcia, Powolne zaklęcia i Umiejętności zyskują „Gdy zadam obrażenia Ogłuszonemu lub zranionemu wrogowi, zabij go”.","","„Akt drugi: Dwulicowy władca, który posiada jedynie zwędzone rękawice Kashuri, próbuje zauroczyć Ionian. Jednak jego kamuflaż jest prymitywny i łatwo go przejrzeć. Błaga o oszczędzenie życia, tłumacząc się, że był ignorantem. Żelazna rękawica, za pomocą której pragnął rządzić, spoczywa pozbawiona właściciela”.","Jednostka",[],["Noxus"],"RZADKIE"],"06NX033":["Wykonanie Strategii","Ogłusz 2 wrogów lub wydaj 6 pkt. many, aby przywołać kartę Generał Legionu.","","Przydział to jedna z pierwszych ważnych decyzji przed bitwą. Dobry dowódca wie, że kluczem do zwycięstwa…","Zaklęcie",[],["Noxus"],"RZADKIE"],"06NX012":["Annie","Atak: Zadaję 2 pkt. obrażeń blokującej mnie jednostce. Jeżeli jest martwa lub zniknęła, zamiast tego zadaję 2 pkt. obrażeń wrogiemu Nexusowi.","Widziałam, jak zagrywasz 6 Szybkich zaklęć, Powolnych zaklęć lub Umiejętności. Gdy awansuję, stwórz w ręce kartę Tibbers.","Ponad dekadę temu Amoline Kiosar uciekła z Konserwatorium Ravenbloom i wzięła ze sobą żarzący się przedmiot o nieocenionej wartości. Zwiadowcy Ravenbloom szukali jej w każdym zakątku imperium, jednak żadne z plotek nie doprowadziły ich do dziewczynki. Lata później, gdy nadeszły wieści o zagubionej dziewczynce płonącej z nienawiści w północnych Żelaznych Szczytach, Fynn Retrick niechętnie spakował swoje rzeczy i wyruszył w drogę, by to sprawdzić. Nie spodziewał się, że coś znajdzie. Bardzo się pomylił.","Jednostka",[],["Noxus"],"Bohater"],"06NX029":["Szara Apteka","Gdy sojusznik o sile 5+ umrze, stwórz w ręce losowego stronnika o sile 5+.","","„Rozmyślałem dzisiaj o mojej lecznicy na wzgórzu Penrose i latach, które tam spędziłem, próbując odkryć tajniki fizjologii. Tyle lat! Służę Lady Noradi od zaledwie kilku miesięcy, ale teraz wiem, że niczego się nie nauczyłem. Kiedyś wszystko było takie proste. Miałem tyle szczęścia”.\n– Notatki dr. Esslangera","Lokacja",[],["Noxus"],"EPICKIE"],"06NX032":["Posłuszny Smoczy Ogar","Gdy sojusznik zaatakuje, ja atakuję razem z nim.","","„Smocze ogary są cudne, prawda? Takie chętne do pomocy. Takie uległe. Gdyby tylko moi wrogowie byli tacy sami”.\n– Cierń Róży","Jednostka",["PIES"],["Noxus"],"ZWYKŁE"],"06NX030":["Dezerter Legionu","Zyskuję wszystkie sojusznicze wzmocnienia, działające gdziekolwiek.","","„Akt pierwszy: Były żołnierz, który opuścił swoją wartę po wykradzeniu starożytnego artefaktu z Kashuri, ukrywa się teraz w barze w Qayanvi. Jest arogancki, wypił zdecydowanie za dużo. Nie wie, że skradziony przez niego skarb szepcze o wszystkim, co ujrzy, swemu prawowitemu właścicielowi! Jego krew rozlewa się niczym wino, noxiański szkarłat na ioniańskim złocie”.","Jednostka",[],["Noxus"],"RZADKIE"],"06NX013":["Miotacz Zaklęć","Zagraj: Ogłusz wroga lub, jeśli jest już Ogłuszony, zamiast tego zadaj mu 2 pkt. obrażeń.","","„Uczeń: Sydell Kythera\nNauczyciel: J. Willough\nRaport: Pająk ukąsił mnie w lewe przedramię. Sydell twierdzi, że to wypadek, jednak jego uśmieszek przeczy jego niewinności. Przydzieliłem mu dwa tygodnie dodatkowych obowiązków (refektarz)”.\n– Karta dyscyplinarna Ravenbloom","Jednostka",["PAJĄK"],["Noxus"],"ZWYKŁE"],"06NX040":["Tryfariańskie Areny Ćwiczebne","W każdej rundzie przy pierwszym ataku sojusznika z ponad 5 punktami Siły Zjednocz Siły.","","„Na moją komendę zaczniecie walczyć! Jeśli zabijecie swojego partnera, znajdźcie kolejnego! Jeśli polegniecie, umrzecie ze świadomością, że wasza śmierć wzmocniła Noxus! Tryfariańscy żołnierze… zaczynajcie!”\n– Tryfariańska Asesorka","Lokacja",[],["Noxus"],"EPICKIE"],"06NX028":["Konserwatorium Ravenbloom","Odlicz 11: Stwórz w ręce kartę Tybaulk.\nPosuwam się o 1 rundę Naprzód za każde Szybkie zaklęcie, Powolne zaklęcie oraz Umiejętność, które udało ci się zagrać w tej grze.","","„Z pewnością doszły cię słuchy o katastrofalnych kłopotach Akademii Roseguard. Mam nadzieję, że porażki siostrzanej szkoły będą dla ciebie cenną lekcją. Musisz zarządzać swoim ośrodkiem w sposób godny imperium”.\n– Spalony list znaleziony w zgliszczach konserwatorium","Lokacja",[],["Noxus"],"RZADKIE"],"06NX014":["Dezintegracja","Wybierz jednostkę. Następnym razem, gdy otrzyma ona co najmniej 1 pkt. obrażeń w tej rundzie, zabij ją.","","Dyrektorka Telsi opowiadała o Noxiańskich doktrynach, a słuchająca ją młodzież zasypiała z nudów. Większość uczniów powstrzymywała swe emocje, jednak nie Annie – ta reagowała najpierw dymem, a później ogniem.","Zaklęcie",["ŻYWIOŁ"],["Noxus"],"ZWYKŁE"],"06NX031":["Zniewolony Yeti","Reputacja: Kosztuję o 4 mniej.","","Tłum wstrzymał oddech, gdy dwa skute Yeti wylądowały na legendarnej arenie Bordenta. Nikt nie przypuszczał, że były w stanie zerwać swoje łańcuchy, ponieważ żaden z nich nie musiał jeszcze stawić czoła takiej sile.","Jednostka",["YETI"],["Noxus"],"ZWYKŁE"],"06NX009":["Zniewolony Szarogrzbiet","Atak: Zadaję 3 pkt. obrażeń blokującej mnie jednostce. Jeżeli jest martwa lub zniknęła, zamiast tego zadaję 3 pkt. obrażeń wrogiemu Nexusowi.","","„Akt trzeci: Okrutna właścicielka i jej zwierzak. Szarogrzbiet jest łagodny, nawet jeśli ma makabryczne zamiary – dzierżony artefakt zmusza do uległości. Właścicielka nie krzyczy, gdy staje się pokarmem dla swojego zwierzątka. Gdyby tylko wszyscy Noxianie byli tak szlachetni w obliczu swego końca”.","Jednostka",[],["Noxus"],"ZWYKŁE"],"06NX015":["Uczeń Manasoul","W każdej rundzie, gdy po raz pierwszy zagrasz Szybkie zaklęcie, Powolne zaklęcie lub Umiejętność, ja zagram umiejętność Magiczny Żar.","","„Me spotkanie z Daani miało miejsce parę lat temu. Fajny koleś. Ze spoko rodzinką. Podczas mojej ostatniej wycieczki zatrzymałem się w jego wiosce i ujrzałem, jak Daani siedzi w samotności. Mówił, że czeka na swoją rodzinę. Siedział tam chyba miesiącami. Nie miałem serca, by powiedzieć mu, co widziałem po drodze…” – Fynn Retrick","Jednostka",[],["Noxus"],"ZWYKŁE"],"06NX037":["Szeptokamienie z Noxusu","Stwórz w ręce Ulotną kartę Naostrzona Determinacja, Tornado Śmierci lub Bronie Utraconych.","","„Clara, kochanie, musisz zmyć krew z tokenów”. –\nOphelia Noradi, Szkarłatna Arystokratka","Zaklęcie",[],["Noxus"],"RZADKIE"],"06NX008":["Prefektka","Gdy zagrasz Szybkie zaklęcie, Powolne zaklęcie lub Umiejętność, przyznaj mi +1|+0.","","„Wiele dzieci jest teraz w wieku, w którym mają skłonności do buntu. Na szczęście najstarsza z nich jest przez nie lubiana i przychylna naszym zamiarom. Jeśli uczniowie zignorują nasze lekcje, to będziemy ich uczyć właśnie przez nią”.\n– Dyrektorka Telsi","Jednostka",[],["Noxus"],"EPICKIE"],"06MT044":["Gwiazdoróg Solari","Brzask: Daj innym sojusznikom +0|+2 w tej rundzie.","","Gwiazdorogi rodzą się z gwiazd, a niektóre z nich są gorętsze niż inne.","Jednostka",[],["Targon"],"ZWYKŁE"],"06MT036":["Pytanie do Niebios","W pełni ulecz wszystkich sojuszników i zwiększ ich Siłę do poziomu równego ich Zdrowiu.","","„Po pierwsze musimy okazywać bliźnim współczucie. Reszta przyjdzie sama”. – Soraka","Zaklęcie",[],["Targon"],"EPICKIE"],"06MT039":["Smocze Gniazdo","Odlicz 3: Przywołaj kartę Inviolus Vox.","","„Podobno astralne smoki rodzą się z mgławic, stworzone w całości z kosmicznego pyłu. Ale skąd zwykli śmiertelnicy mają taką wiedzę? Z tak dalekich zakątków widzimy jedynie rzucane przez nie światło”. – Zwiastunka Smoków","Lokacja",[],["Targon"],"EPICKIE"],"06MT045":["Astralna Trójca","Wezwij Astralną kartę o niskim, średnim i wysokim koszcie.","","„Gwiazdy przepowiadają wielki potencjał. Coś nadchodzi. Jaki kształt przybiorą? Nie jest mi dane dostąpić tej wiedzy! A ty co sądzisz, Kulun?” – Księżycem Śniąca","Zaklęcie",[],["Targon"],"RZADKIE"],"06MT043":["Szeptokamienie z Targonu","Stwórz w ręce Ulotną kartę Oblicze Nieskończoności, Cichutko lub Błogosławieństwo Targonu.","","„Shorin, cóż za dziwna rzecz… nie muszę przewrócić kamienia, by wiedzieć, jaką konstelację na nim namalowano”. – Tyari Wędrowiec","Zaklęcie",[],["Targon"],"RZADKIE"],"06MT029":["Esmus, Tchnienie Świata","Gdy mnie przywołasz, umieść Dzwonek na pierwszej karcie z wierzchu swojej talii.\nWsparcie: Przyznaj wspieranemu przeze mnie sojusznikowi +1|+1.","","„…podobno Esmus został stworzony przez samego Opiekuna, a po jego narodzinach na świecie pojawił się dźwięk!”\n„Co za bzdury! Przecież wszyscy wiedzą, że Esmus ma twarz starej śpiewaczki o anielskim sercu, jednak głosem przypominającej zmarłych… dopóki Bard nie dał jej pięknego głosu!”\n„Kłamstwa! Esmus to…”\n– Fragment Narodzin Esmus, popularnej gry bardów","Jednostka",[],["Targon"],"ZWYKŁE"],"06MT038":["Kręte Światło","Zmrok: Daj innym sojusznikom +2|+1 i Zmiażdżenie w tej rundzie.","","„Księżycowa Matko, daj nam siłę,\nbo mimo iż otacza nas ciemność,\ntwe światło rozświetli nam drogę”.\n– Modlitwa Lunari","Jednostka",[],["Targon"],"ZWYKŁE"],"06MT047":["Mistyczny Wir","Gdy mnie przywołasz lub gdy Odliczam, umieść 3 karty Dzwonki w swojej talii. Odlicz 2: Dobierz 1 kartę.","","„I wtedy ich zobaczyłem, całe tysiące. Śpiewali i tańczyli. Nagle ujrzałem błysk światła i wszyscy zniknęli, a świątynia wraz z nimi – nie został nawet kamień. A co znalazło się w mych dłoniach? Otóż okazało się, że trzymam dzwonek”. –\nOpowieść starego Gaffa, część 3","Lokacja",[],["Targon"],"RZADKIE"],"06MT041":["Stado Gwiezdnych Ogarów","Moje wzmocnienia Przeznaczenia są przyznawane sojuszniczym kartom Stada Gwiezdnych Ogarów wszędzie.","","Wspinacze nie byli w stanie przywołać lub przekonać gwiezdnych ogarów podczas ich podróży. Cały czas trzymały się z daleka, pozornie zahartowane na magię gór.","Jednostka",["PIES"],["Targon"],"ZWYKŁE"],"06MT049":["Błogosławieństwo Mikhaela","Przyznaj sojusznikowi +1|+2 i usuń z niego wszystkie negatywne słowa klucze.","","Kto słyszy dźwięk dzwonu, jest pod wrażeniem jego czystości.","Zaklęcie",[],["Targon"],"RZADKIE"],"06RU025":["Evelynn","Pochodzenie: Uścisk Śmierci.\nGdy mnie przywołasz, przywołaj losową Skorupę.","Kiedy zobaczę, jak ty lub sojusznik zabijacie sojuszniczą Skorupę, przekaż mi jej pozytywne słowa klucze w tej rundzie, a ja awansuję.","Źrenice kapłanki się poszerzyły, a jej ręka drżała w podnieceniu. Czuła się gotowa. Evelynn czekała na ten moment bardziej niż na jakikolwiek inny. Wyszczerzyła zęby i powoli pozbyła się swojego oblicza. Potem jak zwykle rozległy się krzyki.","Jednostka",[],["Runeterra"],"Bohater"],"06RU001":["Bard","Pochodzenie: Wędrujący Opiekun.\nAtak: Umieść 3 karty Dzwonki w swojej talii.","Udało ci się zwiększyć łączne statystyki sojuszników w grze lub ręce o 20+.","„Tak jest, Stary Gaff widział już dość dziwnych rzeczy! Za pierwszym razem był to chyba sam Opiekun. Przypominał gwiazdę pędzącą po niebie. Wydawało się, że cały świat zatrzymał się na chwilę, a to tylko ja i on…”\n– Opowieść Starego Gaffa, część 1","Jednostka",[],["Runeterra"],"Bohater"],"06RU002":["Jhin","Pochodzenie: Wirtuoz.\nAtak: Zadaj 2 pkt. obrażeń wszystkim Ogłuszonym wrogom.","Udało ci się zagrać 12+ Szybkich zaklęć, Powolnych zaklęć lub Umiejętności.","„Uwertura: Zaczynamy od miasta Qayanvi, gdzie stary mistrz przywołuje swojego młodego ucznia. Powierza mu zadanie rozprawienia się z nikczemnymi złoczyńcami i odzyskania skradzionych artefaktów. Aktor jest zainteresowany, ale nie zajmuje jeszcze jego miejsca. Na razie po prostu się przygotowuje, czekając na skrzydłach”.","Jednostka",[],["Runeterra"],"Bohater"],"06FR029":["Mrożące Przerażenie","Nałóż Odmrożenie na wroga i przywołaj kartę Sfora Szronozębnych.","","Razem z zimnem pojawiają się też mroźne żmije. Nie muszą one gonić swojej zwierzyny… wystarczy, że trochę poczekają.","Zaklęcie",["ŻYWIOŁ"],["Freljord"],"EPICKIE"],"06FR033":["Polujący Dzik","Ostatnie Tchnienie: Otrzymujesz pusty kryształ many.","","Cykl życia i śmierci wygląda inaczej we Freljordzie. Trudne warunki oznaczają, że rzadko coś się marnuje.","Jednostka",[],["Freljord"],"ZWYKŁE"],"06FR038":["Skrzydła Kriofeniksa","Zadaj 3 pkt. obrażeń WSZYSTKIM jednostkom.\nOświecenie: Zamiast tego zadaj 3 pkt. obrażeń wszystkim wrogom i ulecz swój Nexus o 3 pkt.","","W cieniu rozpościerających się skrzydeł Kriofeniksa jej stronnicy się radowali, a wrogowie drżeli.","Zaklęcie",["ŻYWIOŁ"],["Freljord"],"RZADKIE"],"06FR030":["Zwiastun Niewolników","Zagraj: Przywołaj kartę Zamarznięty Niewolnik lub poślij wszystkie swoje karty Zamarznięci Niewolnicy o 1 rundę Naprzód.","","Przedziwny, gwiżdżący płacz stworzenia nad głowami był ledwo słyszalny, ale gdy jego echo odbiło się od kamiennych ścian wąwozu, zwiadowcy poczuli jego wibracje w kościach. Powierzchnia lodu zaczęła chaotycznie pękać na ich oczach z zatrważającą szybkością.","Jednostka",["PTAK"],["Freljord"],"ZWYKŁE"],"06FR039":["Zaciekłość Dzikiego Pazura","Zmień sojuszniczego stronnika w kartę Dziki Pazur Alfa.","","„Wielki duchu dzikiego pazura, daj nam swoją siłę!” – Udyr","Zaklęcie",[],["Freljord"],"RZADKIE"],"06FR028":["Revna, Strażniczka Wiedzy","Gdy mnie przywołasz, przyznaj jednostkom w swojej talii moje statystyki, a następnie dobierz jednostkę o Sile 5+.","","Avarosańscy strażnicy wiedzy to często zaprawieni starsi plemienia, obrońcy ludzi, którzy świetnie opowiadają. Utrzymują tradycję polowań i walki żywą dzięki opowieściom i pieśniom. ","Jednostka",[],["Freljord"],"EPICKIE"],"06FR037":["Pękający Lód","Przyznaj wrogowi „Nałóż na mnie Odmrożenie na początku następnej rundy”.","","Zawsze należy sprawdzić lód, zanim się na niego wejdzie. Niezależnie od tego, jak gruby się on wydaje.","Zaklęcie",["ŻYWIOŁ"],["Freljord"],"ZWYKŁE"],"06BC045":["Kurzowy Kichacz!","Daj sojusznikom +1|+1 w tej rundzie. Jeśli zostali stworzeni, zamiast tego daj im +2|+2.","","„CZEŚĆ. JA GRZYB JA MÓWIĆ NIE WIEM DLACZEGO ANI CO SIĘ STAŁO. PROSZĘ POZWÓL MI BYĆ GRZYB. PROSZĘ. DZIĘKI. CZEŚĆ”. – Grzyb","Zaklęcie",[],["Bandle City"],"EPICKIE"],"06BC036":["Wielki Paparo","Zagraj: Pokaż Yordla.\nAtak: Przyznaj sojuszniczym Yordlom +1|+0.","","„WSZYSCY kochają Paparo! Każdego lata przywozi nam różne fanty z całego świata i za każdym razem są albo przepyszne, albo przepiękne, albo przedziwne! Czasem wszystko naraz!” – Ava Ambitniaczka","Jednostka",["YORDLE"],["Bandle City"],"EPICKIE"],"06BC040":["Szeptokamienie z Bandle","Stwórz w ręce Ulotną kartę Elektroharpun, Heroiczny Refren lub Yordlowe Ustrojstwo.","","Yordlowie zawsze kwapią się do gry… tylko nie zdziwcie się, jeśli jej zasady ulegną zmianie w trakcie!","Zaklęcie",[],["Bandle City"],"RZADKIE"],"06BC039":["Zrzuć bombę","Zadaj jednostce 2 pkt. obrażeń oraz przywołaj kartę Bomba Samoróbka.","","– Cóż, niedobrze – powiedziała cicho Giselle, kryjąc się za zasłoną.","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"06BC044":["Kosmiczne Uwiązanie","Zadaj wrogowi 2 pkt. obrażeń i Ogłusz innego wroga. Umieść 6 kart Dzwonki w swojej talii.","","„Mamo, dokąd chodzi Opiekun?”\n„Wszędzie, moja droga. Tam, gdzie wzrok sięga”.\n„Po co?”\n„Nie zastanawiaj się po co, moja droga. Nawet najmądrzejsi starsi nie potrafią pojąć zachowania Opiekuna…”\n– Matka z dzieckiem.","Zaklęcie",[],["Bandle City"],"RZADKIE"],"06BC026":["Byrd Dzwonnik","Gdy mnie przywołasz, umieść Dzwonek na pierwszej karcie z wierzchu swojej talii.","","„Za drugim razem było ciekawie. Zamiatałem podłogi, gdy nagle mój obiad został rozwalony po całym stole, a garnki i patelnie zaczęły łazić po pomieszczeniu! Pobiegłem najszybciej, jak tylko mogłem, i znalazłem ich w świątyni. Szukali czegoś”. – Opowieść Starego Gaffa, część 2","Jednostka",[],["Bandle City"],"ZWYKŁE"],"06BC030":["Grzyb Zbliżeniowy","Zadaj jednostce 1 pkt. obrażeń. Jeśli w tej rundzie aktywowano jedną z twoich pułapek lub darów, zamiast tego zadaj 3 pkt. obrażeń.","","„Jeśli zacznie się świecić, to znaczy, że wybuchnie!” – Zasada zwiadowców z Bandle City nr 463","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"06BC031":["Maduli, Strażnik","Gdy mnie przywołasz, umieść Dzwonek na pierwszej karcie z wierzchu swojej talii, następnie podwój dary w swojej talii.","","„Nieźle się spietrałem. Łapy jak grabie. Wielgachne kły. Gdy to coś przyłożyło młot do ust, wydało taki dźwięk, że prawie ducha wyzionąłem. Biegłem co sił w nogach, mówię wam. Nagle ujrzałem niebo wyglądające jak sito! Setki dziur w niebie!”\n– Opowieść Starego Gaffa, część 4","Jednostka",[],["Bandle City"],"RZADKIE"],"06BC035":["Drzewko Papierowe","Kiedy sojusznik z przywiązaną kartą zaatakuje, przyznaj jego przywiązanej karcie +1|+0.","","Liście drzewka papierowego lśnią tą samą magią wróżek, która je zrodziła. Niczym ptaki, które były inspiracją dla ich formy, nie mogą się one oprzeć błyskotkom.","Lokacja",[],["Bandle City"],"RZADKIE"],"06IO005":["Makabryczny Teatr","Wycofaj jednostkę o Zdrowiu 3 lub mniejszym.","","„Sztuka nie lubi pośpiechu”. – Jhin","Zaklęcie",[],["Ionia"],"ZWYKŁE"],"06IO038":["Wsparcie Moralne","Kosztuję o 2 mniej, jeśli udało ci się Wesprzeć sojusznika w tej grze. Daj sojusznikowi Barierę w tej rundzie.","","„Zaufaj równowadze. Przechadzaj się po granicy”. – Shen","Zaklęcie",[],["Ionia"],"ZWYKŁE"],"06IO012":["Zew Kinkou","Przywołaj kartę Powierniczka Masek teraz lub na początku następnej rundy. Dobierz 1 kartę.","","„Dzięki starym maskom młode oczy widzą wyraźnie”.\n– Powierniczka Masek","Zaklęcie",[],["Ionia"],"ZWYKŁE"],"06IO009":["Pułapka na Smoki","Rozpocznij Darmowy Atak 2 kartami Smoczątka.","","„Oto manifest pożądania”.\n– Władca Smoków","Zaklęcie",[],["Ionia"],"ZWYKŁE"],"06IO033":["Burza Ostrzy","Do końca gry, gdy Tańczysz z Ostrzami, przywołaj kolejną atakującą kartę Ostrze.\nTaniec z Ostrzami: 1 Ostrze.","","„Poprowadź mnie w tańcu, będę podążać za twymi krokami!” – Tancerka Szarf","Zaklęcie",[],["Ionia"],"EPICKIE"],"06IO004":["Tworzycielka","Zagraj: Wycofaj jednostkę o Sile mniejszej niż moja.","","„Niesamowita artystka – Tworzycielka. Legendarna autorka! Jej sztuka nie ma sobie równych! Wykonanie jest perfekcyjne! To wielki zaszczyt ją spotkać, nie mówiąc już o dzierżeniu stworzonego przez nią dzieła”. – Świadek Kashuri","Jednostka",[],["Ionia"],"RZADKIE"],"06IO010":["Potargany Pagórek","Gdy mnie przywołasz, dobierz kartę Yasuo i Ogłusz Najsilniejszego wroga.\nGdy zyskasz Token ataku, Ogłusz Najsilniejszego wroga.","","Dla większości szczęście to spokojny dom i cicha radość odnaleziona w uścisku bliskich. Dla Yasuo jest to ten rzadki moment, gdy wichry się uspokajają, niosąc nadzieję zamiast rozpamiętywania. ","Lokacja",[],["Ionia"],"EPICKIE"],"06IO036":["Szeptokamienie z Ionii","Stwórz w ręce Ulotną kartę Makabryczny Teatr, Rytuał Odnowienia lub Wsparcie.","","„Odczytywanie zamiarów przeciwnika to umiejętność konieczna nawet poza walką. Najważniejsze jednak jest, by podczas gry dobrze się bawić. Co z moją kąpielą stóp?”\n– Inspirujący Mentor","Zaklęcie",[],["Ionia"],"RZADKIE"],"06IO003":["Inspicjentka","Zagraj: Ogłusz wroga.","","„Akt czwarty: Młoda kapłanka staje się kolejną bohaterką naszego opowiadania. Jej historia jest tragiczna, przekazywana przez blade usta tych, których zdradziła. Zdesperowana, by zadośćuczynić za swe występki, nosi w swych dłoniach olbrzymie brzemię – pozłacany dar od Noxian, których powitała na swej ziemi. Pozostaje jedno pytanie: co rozdarło jej serce – kula czy żal?”","Jednostka",[],["Ionia"],"ZWYKŁE"],"06IO035":["Uczeń Kinkou","Gdy inny sojusznik otrzyma Barierę: zapewnij mi Barierę w tej rundzie, o ile jeszcze jej nie posiadam.","","„Przyjmij równowagę na każdym poziomie. Umysłu, ciała i ducha. Oprzyj się gwałtownym żądzom młodości. Spójrz na wszystko z innej perspektywy”. – Shen","Jednostka",[],["Ionia"],"RZADKIE"],"06PZ032":["Skowyczący Patefon","Wybierz jedno z dwóch nowych zaklęć o koszcie 2 i stwórz je w ręce. Jego koszt wynosi 0 w tej rundzie. Powtórz to jeszcze dwa razy.","","Pierwszy patefon Zaun był całkiem solidny. Problem w tym, że nikt nie wiedział, jak poprawnie kontrolować dźwięk.","Zaklęcie",[],["Piltover i Zaun"],"EPICKIE"],"06PZ042":["Okrutny Imperfekcjonista","Zagraj: Wybierz kartę w ręce. Stwórz dokładne 4 kopie tej karty w swojej talii i zmniejsz ich koszt o 1.","","„Cóż, o dzisiejszym dniu mogę powiedzieć tyle, że mógł być lepszy. Na tym poprzestańmy. Ja z przyszłości… już wiesz, co zrobiliśmy”.\n– Pamiętnik Kay","Jednostka",[],["Piltover i Zaun"],"EPICKIE"],"06PZ025":["Samotność","Gdy mnie przywołasz, przywołaj losową Skorupę.\nGdy przywołasz sojusznika o koszcie 1, przyznaj mu losowe słowo klucz.","","„Wracając do domu z Antresoli, znów zobaczyłam tę biedną włóczęgę płaczącą w małej alejce. To, że tak wiele osób obojętnie ją mija, w oczywisty sposób łamie mi serce niemal tak bardzo, jak jej przerażenie. Jeśli zatem jutro nasze ścieżki znów się skrzyżują, postaram się pomóc jej tak, jak tylko będę umiała”.\n– Notatki z pamiętnika Lady Sempescu","Jednostka",[],["Piltover i Zaun"],"RZADKIE"],"06PZ043":["Szeptokamienie z Piltover","Stwórz w ręce Ulotną kartę Reperkusje, Hextechowy Transmogulator lub Dzień Postępu!.","","„Nie znajdziesz lepszego zestawu w żadnym innym miejscu na ziemi. Moja córka włożyła serce w każdy najmniejszy szczegół”. – Corin Reveck ","Zaklęcie",[],["Piltover i Zaun"],"RZADKIE"],"06PZ027":["Dyskretne Zaproszenie","Stwórz Ulotną kartę Podejrzany Osobnik lub Chempunk Solówkarz w ręce i zmniejsz jej koszt o 1.","","Nocnego życia w Zaun zaznasz jedynie wtedy, gdy masz zaproszenie. Jeśli nie grasz w zespole, musisz być kimś, by zdobyć wejściówkę. Możesz też znaleźć bilet na ulicy.","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"06PZ038":["Wygrzebany Kamuflator","Przyznaj sojusznikowi Nieuchwytność i „Uderzenie w Nexus: Dobierz 1 kartę”.","","„Nie UWIERZYCIE, co dziś znalazłem”.\n– Poszukiwacz ze Slumsów","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"06PZ039":["Ocalony Złom","Aby zagrać, odrzuć do 2 kart. Stwórz tyle samo stronników z twoich regionów, którzy kosztują o 1 więcej, i zmniejsz ich koszt o 1.","","W głębi Zaun tubylcy są zmuszeni przekuwać znaleziony złom i resztki w przydatne materiały. Po dziesięcioleciach praktyki stali się w tym całkiem nieźli.","Zaklęcie",[],["Piltover i Zaun"],"RZADKIE"],"06BW006":["Illaoi","Atak: Powołaj do Życia 1, a następnie zyskuję Siłę twojej Najsilniejszej karty Macka w tej rundzie.","Widziałem, jak ja lub moje sojusznicze Macki zadaliśmy 15+ pkt. obrażeń.","Oko Nagakabourossy to tylko nazwa, jednak Illaoi za cel obrała sobie życie tak, jakby jej bogini była stałym i łatwo nudzącym się towarzyszem.","Jednostka",[],["Bilgewater"],"Bohater"],"06BW036":["Szczur Portowy","Mam +1|+0 za każdą odrębną rundę, w której udało ci się zadać obrażenia wrogiemu Nexusowi.","","„Nie ma miejsca bardziej spowitego krwią niż zatoka Bilgewater. Wystarczy spojrzeć na szczury chłepczące ją jak wodę. Zawsze im mało. Przeklęte gryzonie”. – Hardy Rzeźnik","Jednostka",[],["Bilgewater"],"EPICKIE"],"06BW038":["Megakieł","Gdy jesteś na Głębokości, ulecz swoich sojuszników i Nexus o 3 pkt.","","„Czego to chce?!”\n„To… chce pomarańczy!”\n„Na Brodatą Damę, DAJCIE TU CAŁY BUSZEL!”\n– Pechowi żeglarze","Jednostka",["POTWÓR MORSKI"],["Bilgewater"],"ZWYKŁE"],"06BW030":["Oko Nagakabourossy","Powołaj do Życia 2.\nDobierz 2 karty.","","Nagakabourossa to bogini zapewniająca opatrzność – o ile ktoś przetrwa oddanie jej czci.","Zaklęcie",[],["Bilgewater"],"ZWYKŁE"],"06BW011":["Nagakabourossa","Gdy mnie przywołasz lub na Początku rundy: Powołaj do Życia 2. Następnie, jeśli twoja Najsilniejsza karta Macka ma 12+ Siły, stwórz kartę Gniew Nagakabourossy w ręce.","","„Matka Węży. Wielki Kraken. Brodata Dama. Nagakabourossa nie dba o swe imiona, a jeszcze mniej o los niespokojnych umarlaków”. – Illaoi","Jednostka",[],["Bilgewater"],"EPICKIE"],"06BW021":["Kazanie Prądu Morskiego","Zadaj 3 pkt. obrażeń wrogiej jednostce.\nPowołaj do Życia 3.\nZadaj 1 pkt. obrażeń wrogiemu Nexusowi.","","„Jako dzieci uczymy się dać się ponieść nurtowi. Walczyć znaczy umrzeć. To oczywiste, że pierwsza próba dla kapłanki polega na zapomnieniu tej lekcji i walce z prądem z całych sił. Zwiastunka Prawdy nie jest bowiem pływaczką, tylko samym prądem”. – Illaoi","Zaklęcie",[],["Bilgewater"],"EPICKIE"],"06BW045":["Krew w Wodzie","Zadaj 1 pkt. obrażeń dowolnemu celowi, a następnie Zjednocz Siły.","","Ciężko jest przegonić krążące rekiny z Zatoki Rozpruwacza. Jak już posmakują krwi, są żądne więcej.","Zaklęcie",[],["Bilgewater"],"ZWYKŁE"],"06BW028":["Uderzenie Macką","Powołaj do Życia 2. Następnie twoja najsilniejsza karta Macka i wróg uderzają się wzajemnie.","","„Życie to próba. Ból daje nam nauczkę częściej, niż byśmy tego chcieli”. – Illaoi","Zaklęcie",[],["Bilgewater"],"RZADKIE"],"06BW035":["Głos Morza","Atak: Powołaj do Życia 1 i daj swojej Najsilniejszej karcie Macka Zmiażdżenie w tej rundzie.","","Przywołanie Nagakabourossy ma mało wspólnego z rytuałem. Bogini odpowiada na wołania tych, których dusze mogą wytrzymać każde uderzenie fal oceanu. Nie każdy może wygrać to starcie.","Jednostka",[],["Bilgewater"],"RZADKIE"],"06BW015":["Wysłuchana Modlitwa","Powołaj do Życia 2 lub wydaj 5 pkt. many, aby zamiast tego Powołać do Życia 4.","","Modlitwa do Nagakabourossy nie jest błaganiem czy prośbą o dar. Jej błogosławieństwo przypomina życie: dąż do celu, pokonuj trudności losu, dawaj z siebie wszystko – z czasem nagroda przyjdzie sama.","Zaklęcie",[],["Bilgewater"],"ZWYKŁE"],"06BW007":["Czujny Bożek","Początek rundy: Zadaj mi 2 pkt. obrażeń i Powołaj do Życia 1.","","Gdy koszmary wypełzają z Wysp Cienia, bożek zaczyna świecić ognistym snopem światła.","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"06BW037":["Bogaty Okup","Pokaż stronnika, na którego starczy ci many.","","„Dobra, Baz. Na pewno chcesz spróbować jeszcze raz?”\n„Do trzech razy sztuka, Gav. Poza tym wydaje mi się, że walczyliśmy już ze wszystkim, co kryje się w tym śmierdzącym mieście”.\n„Walczyliśmy i przegraliśmy, Baz”. – Baz i Gav, aspirujący łowcy nagród","Zaklęcie",[],["Bilgewater"],"EPICKIE"],"06BW041":["Szwindel","Wybierz 1 z 2 niebędących bohaterami kart z ręki wroga i stwórz jej kopię w swojej ręce. Grabież: Kosztuję o 1 mniej.","","„PIĘĆ asów? Wygląda na to, że znów wygrałem!”\n– Rekin Bilarda","Zaklęcie",[],["Bilgewater"],"RZADKIE"],"06BW016":["Pogranicznik Buhru","Gdy mnie przywołasz, Powołaj do Życia 3.","","Najlepsza w życiu jest jego prostota. Krople słonej wody spływające po policzku, śpiew ptaków… i nieskomplikowany przeciwnik na horyzoncie.","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"06BW009":["Dowódca Buhru","Zagraj: Sojusznik o koszcie 1 rozpoczyna Darmowy Atak.","","„Przypomnij sobie mądrość oceanu! Jeśli się nie ruszysz, to zostaniesz ruszony! Idź za mym głosem, jeśli nie możesz się odnaleźć, gdyż twój wróg na pewno zna drogę”. ","Jednostka",[],["Bilgewater"],"RZADKIE"],"06BW043":["Szeptokamienie z Bilgewater","Stwórz w ręce Ulotną kartę Więcej Prochu!, Psotny Rozrabiaka lub Mącenie Wody.","","„Nie próbujcie przyłapać kogoś na blefie w grze kamieni. Bilgewater ma pełno świetnych kłamców. Jeśli na poważnie myślisz o wygranej, to patrz im na ręce”. – Twisted Fate","Zaklęcie",[],["Bilgewater"],"RZADKIE"],"06BW018":["Steem","Gdy mnie przywołasz, przywołaj losową Skorupę.\nGdy przywołasz sojusznika o koszcie 1, przyznaj Najsilniejszemu wrogowi Podatność.","","Pierwsze spotkanie Evelynn ze Steemem było brutalnym i emocjonującym przeżyciem. Evelynn zapamiętała, jak uśmiechał się z nieskrywaną przyjemnością, gdy odzierała go ze skóry, i jak się jej odwdzięczył, gdy nadeszła jego tura. Po obezwładnieniu go Evelynn postanowiła nie zabijać pomniejszego demona, tylko związać się z nim na zawsze. Pomyślała, że być może połączy ich wspólna miłość do zarzynania.","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"06SH014":["Abominacja Pustki","Gdy mnie przywołasz, przyznaj mi wszystkie pozytywne słowa klucze, które mają moi sojusznicy w tej grze.\nGdy sojusznik ma nowe pozytywne słowo klucz, przyznaj mi je.","","„Słyszeliśmy już opowieści o Pustce i związanych z nią zniszczeniach, ale zobaczyć to na własne oczy… ten widok już na zawsze pozostanie w mojej głowie, a to przerażenie – w moim sercu”. – Ocalały z Belveth","Jednostka",[],["Shurima"],"EPICKIE"],"06SH016":["Herold Roju","Zagraj: Jedna z jednostek i ja przyznajemy sobie nawzajem nasze pozytywne słowa klucze.","","„Mówiło do mnie tak… jakby mnie znało. Jakby chciało, żebym spotkała się z… czymś”. – Kai’Sa","Jednostka",[],["Shurima"],"RZADKIE"],"06SH009":["Kai’Sa","Gdy mnie przywołasz lub na Początku rundy: Jeżeli posiadasz Token ataku, stwórz w ręce kartę Druga Skóra.","Przechodzisz Ewolucję.","Ledwie kilka dni wcześniej Kai’Sa zauważyła, że jej druga skóra najeżyła się z nowym entuzjazmem, ciągnąc ją z coraz większą siłą ku wybrzeży Shurimy. Coś było nie tak. Gdy Kai’Sa zbliżyła się do Belveth, wkrótce zdała sobie sprawę ze skali makabry, która działa się na jej oczach.","Jednostka",[],["Shurima"],"Bohater"],"06SH048":["Rytuał Przejścia","Pokaż sojuszniczą lokację, która została zniszczona w tej grze, i ją przywołaj.","","„Moment zachowany w czasie” – Zilean","Zaklęcie",[],["Shurima"],"ZWYKŁE"],"06SH037":["Wyschnięty Szpon Baccai","Zagraj: Przyznaj wrogowi Podatność.\nGdy wrogowi zostanie rzucone Wyzwanie, daj mu -2|-0 w tej rundzie.","","Jasność ich umysłów odleciała w dal niczym wydmy na wietrze. Zamiast niej pojawiło się ziarno gniewu. Wykwitła z niego furia, której nie mogły ugasić żadne wody pustyni.","Jednostka",[],["Shurima"],"ZWYKŁE"],"06SH008":["Starszy z Belveth","","","Shalatai wzdrygnęła się na ten przerażający widok. Przed nią leżało zmiażdżone ciało Ferai, córki uprzejmego rzeźnika. Obok niego znajdowały się zwłoki Gorruba, syna rybaka, którego pozbawione życia ręce wyciągały się w kierunku ukochanej. Zaginęło tak wiele wspomnień. Zginęło tak wiele istnień. Z grymasem na twarzy Shalatai odwróciła się ku złu, gotowa poświęcić życie, aby uratować resztę swojego ludu.","Jednostka",[],["Shurima"],"ZWYKŁE"],"06SH042":["Szeptokamienie z Shurimy","Stwórz w ręce Ulotną kartę Bezwzględny Drapieżnik, Ciężar Osądu lub Duchowy Ogień.","","„W partii szeptokamieni nigdy nie liczy się to, kto wygra, tylko jak dobrze prezentujesz się podczas gry!” – Akshan","Zaklęcie",[],["Shurima"],"RZADKIE"],"06SH050":["Piaski Czasu","Daj wrogom -2|-0 w tej rundzie. Stwórz Ulotną kartę Wiek w Oka Mgnieniu w ręce.","","Piaski czasu płyną bez żadnej refleksji czy zadumy. Ich działanie cechuje okrutna obojętność, ale nie wszyscy są niewolnikami ich bezdusznych machinacji…","Zaklęcie",[],["Shurima"],"RZADKIE"],"06SH049":["Zew Chwały","Kosztuję o 2 mniej za każdego innego Wyniesionego sojusznika, którego udało ci się przywołać w tej grze.\nPokaż kartę z talii Imperatora o koszcie 9 lub mniejszym.","","„Patrzcie na nasze dzieło. Patrzcie, co zbudowaliśmy”. – Azir","Zaklęcie",[],["Shurima"],"RZADKIE"],"06SH036":["Komnata Odnowienia","Gdy przywołasz bohatera, zniszcz mnie oraz przyznaj przywołanemu bohaterowi +2|+1 i Tarczę Magii.","","Nasus wyłonił się z sarkofagu. Miał czysty umysł, a jego rany się zagoiły. Zapisał kilka notatek i spojrzał na wiszące wysoko nad nim sarkofagi, kontemplując stan umysłu potwornych aberracji, które w nich spoczywały. Czas miał pokazać, czy ta magia była w stanie sprawić, że Baccai powrócą do zmysłów, choć inni Wyniesieni kiedyś protestowali przeciwko niej. Teraz jednak już ich nie było – w przeciwieństwie do Renektona i jego szaleństwa. Nasus nabazgrał kilka kolejnych słów w nadziei na to, że wreszcie odnalazł sposób na uratowanie swojego brata.","Lokacja",[],["Shurima"],"EPICKIE"],"06SH011":["Superdoładowanie","Przyznaj sojusznikowi Zmiażdżenie i Tarczę Magii.","","„Pokażę ci, jak się walczy”. – Kai’Sa","Zaklęcie",[],["Shurima"],"ZWYKŁE"],"06SH017":["Szperacz Pustki","Zadaj 1 pkt. obrażeń stronnikowi. Jeśli udało ci się przejść Ewolucję, zamiast tego zadaj 3 pkt. obrażeń jednostce.","","„Boli, co?” – Kai’Sa","Zaklęcie",[],["Shurima"],"RZADKIE"],"06SH007":["Pusklę","Kiedy jestem w twojej ręce, posiadam losowe słowo klucz, które zmienia się co rundę. Gdy mnie przywołasz, przyznaj mi to słowo klucz.","","Dharna przypomniała sobie, jak otworzyła okna tego ranka i poczuła zapach świeżo upieczonych bochnów chleba. Niedaleko rybacy zaczęli już sprzedawać złowione ryby na południowych targach. Pamiętała, że uśmiechnęła się i pomyślała, że to będzie dobry dzień.","Jednostka",[],["Shurima"],"ZWYKŁE"],"06SH010":["Dewastator Pustki","","","Wybuch Pustki w mieście Belveth był równie nagły, co przerażający. Większość cywili była przerażona chaosem, w którym szybko pogrążyło się miasto, i uciekła tak szybko, jak tylko się dało – ale nie Koyemi.","Jednostka",[],["Shurima"],"ZWYKŁE"],"06SH034":["Dominacja","Gdy mnie przywołasz, przywołaj losową Skorupę.\nGdy przywołasz sojusznika o koszcie 1, przyznaj mu +1|+0.","","Czasami potężni chcą jedynie poczuć się bezsilni.","Jednostka",[],["Shurima"],"EPICKIE"],"06DE045":["Inspirujące Światło","Przyznaj sojusznikom Ducha.","","„Przestań się ukrywać! Wyjdź na światło dzienne i świeć razem ze mną!” – Lux","Zaklęcie",[],["Demacia"],"ZWYKŁE"],"06DE038":["Lord Eldred, Przywódca Łowców Magów","Inni sojusznicy i twój Nexus mają Wytrzymałość.\nGdy sojusznik przetrwa obrażenia, przyznaj mu +1|+1.","","„Niechcący usłyszałem twój żarliwy szept, droga żono. Radzę ci zachować większą ostrożność, kiedy rozmawiasz o sprawach rodzinnych w tak publicznym miejscu. Nigdy nie możesz być pewna, kto akurat nadstawia uszu”.","Jednostka",[],["Demacia"],"EPICKIE"],"06DE037":["Królewski Dekret","Daj sojusznikowi +2|+2 i Wyzwanie w tej rundzie lub przywołaj kartę Czcigodny Lord.","","„Natychmiast, królu Jarvanie. Dokonamy tego za wszelką cenę”. – Barrett Buvelle, Czcigodny Lord","Zaklęcie",[],["Demacia"],"RZADKIE"],"06DE035":["Petrucytowy Filar","WSZYSTKIE zaklęcia kosztują o 2 więcej.\nOdlicz 2.","","Łowcy magów umieszczają petrycutowe obeliski w swoich kompleksach, dzięki którym nawet najpotężniejsi magowie są bezbronni.","Lokacja",[],["Demacia"],"ZWYKŁE"],"06DE042":["Szeptokamienie z Demacii","Stwórz w ręce Ulotną kartę Pryzmatyczna Bariera, Zniewolenie lub Za Demacię!.","","„Dlaczego nazywają to Gambitem Królewskim? Królowe również ryzykują!” – Cithria z Chmurowego Pola","Zaklęcie",[],["Demacia"],"RZADKIE"],"06DE036":["Opiekuńczy Ojciec Młodych","Atak: Dobierz jednostkę. Jeśli jest to Smok, przywołaj ją atakującą.","","„Całe szczęście z moich badań wynika, że rodzice najwięcej czasu spędzają na polowaniach z dala od swoich młodych. Jeśli samiec wróci, staniemy się smoczą przekąską! Ha, ha!” – Anden Mayne, Jajogłowy Badacz","Jednostka",["SMOK"],["Demacia"],"EPICKIE"],"06DE030":["Pokuszenie","Przywołaj losową Skorupę i przyznaj jej +1|+0.","Missing Translation","„Bliżej, kochanie.” – Evelynn","Zaklęcie",[],["Demacia"],"ZWYKŁE"],"06SI012":["Gwen","Atak: Gdy inny sojusznik zyska Siłę dzięki Uświęceniu, ja też ją zyskuję. Zaczerpnij 2 pkt. Zdrowia z wrogiego Nexusa.","Zadałem 10+ pkt. obrażeń.","Gwen wycięła sobie drogę przez Czarną Mgłę, myśląc, że to dziwne, że tak bardzo spowiła ona okolicę. Gdy już skończyła, zaklęta posiadłość wyróżniała się na tle ponurego lasu niczym latarnia morska. To zrozumiałe, że Gwen czuła jej przyciąganie. Wyglądała fascynująco… ale również wspaniale!","Jednostka",[],["Wyspy Cienia"],"Bohater"],"06SI020":["Kolec Nienawiści","Zabij sojusznika, aby zadać 3 pkt. obrażeń jednostce. Jeśli Evelynn zaczęła w twojej talii, przywołaj losową Skorupę.","","„Nie oszczędzaj strun głosowych”. – Evelynn","Zaklęcie",[],["Wyspy Cienia"],"RZADKIE"],"06SI013":["Wieczni Tancerze","Atak: Wskrześ Efemeryczną atakującą kopię Najsilniejszego martwego sojusznika innego niż Wieczni Tancerze o Sile takiej jak ja lub mniejszej.","","Zawsze łatwiej jest dołączyć do kogoś na parkiecie niż zatańczyć jako pierwszy, ale bliźniak zawsze chętnie pokaże temu drugiemu, jak to się robi.","Jednostka",[],["Wyspy Cienia"],"EPICKIE"],"06SI037":["Szeptokamienie z Wysp Cienia","Stwórz w ręce Ulotną kartę Znak Wysp, Duchowa Podróż lub Obrót w pył.","","„Dopracowane… dekoracje. Tokeny… naucz się zasad. Ciekawa gra. Zapierająca dech w piersiach… niezrównany kunszt… nie da się tego zapomnieć”. – Odzyskany dziennik","Zaklęcie",[],["Wyspy Cienia"],"RZADKIE"],"06SI040":["Przerażający Powrót","Wskrześ Najsilniejszego poległego sojuszniczego stronnika i przyznaj mu Efemeryczność oraz Postrach. Daj wrogom -1|-0 w tej rundzie.","","Duchy można wygonić na jakiś czas, ale zawsze powracają.","Zaklęcie",[],["Wyspy Cienia"],"EPICKIE"],"06SI027":["Nawlekanie Igły","Zabij sojusznika, aby zadać obrażenia równe jego Sile dowolnemu wrogowi.","","„Wyciągnąć igły!” – Gwen","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"06SI018":["Vora","Gdy mnie przywołasz, przywołaj losową Skorupę.","","W przeciwieństwie do innych demonów, które wabią swoje ofiary fałszywymi pozorami, Vora jest na to zbyt skupiona na swoim pragnieniu i zbyt ogarnięta pożądaniem. Żaden z niej drapieżnik, który tropi swoją zwierzynę, a raczej dzika bestia, która musi zostać nakarmiona.","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"06SI015":["Nie Może Zabraknąć Kapeli","Przywołaj dwie karty Odrażający Zespół.","","„Ruszać się! Dwa razy szybciej!” – Dyrygent Mgieł","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"06SI030":["Oficjalne Zaproszenie","Stwórz w ręce kopie 2 sojuszniczych stronników, którzy zginęli w tej grze.","","„Przybyliśmy. Ponoć dzisiejszy wieczór ma być dość spektakularny i spodziewam się, że zobaczymy wiele znajomych twarzy!” – Widmowy Imprezowicz","Zaklęcie",[],["Wyspy Cienia"],"RZADKIE"],"06SI026":["Dyrygent Mgieł","Ostatnie Tchnienie: Stwórz w ręce kartę Odrażający Zespół.","","„Grajcie dalej, przyjaciele! Ten koncert będzie najżwawszy w historii!”.","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"06SI033":["Nawiedzony Grobowiec","Odlicz 2: Wskrześ Najsilniejszego poległego sojusznika.","","Dźwięk uderzenia miecza o tarczę zabrzmiał niczym dzwon pogrzebowy, przyciągając duchy, których więź ze światem nie została jeszcze zerwana, a ich woli nie zdołała zdusić nawet śmierć.","Lokacja",[],["Wyspy Cienia"],"EPICKIE"],"06SI016":["Głośny Gospodarz","","","„SERDECZNIE ZAPRASZAMY na imprezę twojego życia w ramach PÓŁNOCNEGO FESTYNU. Dołącz do nas w PORCELANOWEJ POSIADŁOŚCI, aby pić, tańczyć i cieszyć się życiem! (Obchody mają zakończyć się niezwłocznie po upływie 13. godziny)”.\n– Zaproszenie napisane elegancką kursywą","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"06SI028":["Widmowy Lokaj","","","Czy elegancka impreza mogłaby się odbyć bez wyszukanych trunków?","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"06SI043":["Niedorozwój","Wyrzuć 3 karty.\nZaczerpnij 2 pkt. Zdrowia z jednostki.","","Nawet na Wyspach Cienia stary rozwój zawsze znajduje nowy cel.","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"06SI022":["Widmowy Kochanek","","","Niezależnie od tego, czy był duchem, wspomnieniem, czy snem, było w nim coś znajomego…","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"06SI019":["Sultur","Gdy mnie przywołasz, przywołaj losową Skorupę.","","„Strzeżcie się tych, którzy uśmiechają się na tych nawiedzonych wyspach. Być może są tu zbyt krótko, aby zrozumieć brutalność tego miejsca. Być może postradali zmysły. Być może są zupełnie czymś innym. Tak czy siak, strzeżcie się ich”.\n– Notatki Jensa Tommena","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"06NX022":["Obowiązek Legionisty","Dobierz sojusznika o Sile 5+ lub zwiększ Siłę sojusznika do 5 w tej rundzie.","","„Niewielu ma okazję służyć w Legionie Tryfariańskim. Nie zaprzepaść tej szansy”. – Tryfariańska Asesorka","Zaklęcie",[],["Noxus"],"EPICKIE"],"06NX019":["Noxiański Dezerter","Atak: Zrównaj moją Siłę z Siłą Najsilniejszego sojusznika z Wyposażeniem w tej rundzie.","","„Znowu mam sny, słyszę ten głos w ciemnościach. Dziesięć lat… całe cholerne dziesięciolecie spędzone na byciu usłużnym psem imperium. Idź tam. Zabij tamto. I w imię czego? Chwały Noxusu? Ta chwała to chała i kłamstwo, a ja się dałem złapać. Ale koniec z tym. Kayn pokazał mi inną drogę. Drogę do zemsty”.\n– Dziennik Royce’a Rzeźnika","Jednostka",["KULTYSTA"],["Noxus"],"ZWYKŁE"],"06NX023":["Ioniańska Mistrzyni Wędkarstwa","Gdy mnie przywołasz, Improwizuję.","","Życie Trisk wywróciło się do góry nogami. Podczas turnieju wędkarskiego, który miał być jej ostatnim, jakimś cudem wyłowiła pryskającego Jaxa. Ten nie chce rozmawiać o zajściu, ale potwór morski, przed którym Trisk go uratowała, robi się większy za każdym razem, gdy dziewczyna opowiada tę historię.","Jednostka",["WIRTUOZ BRONI"],["Noxus","Ionia"],"ZWYKŁE"],"06NX044":["Przyczajona Tkaczka","Atak: W tej rundzie Siła pozostałych sojuszników będzie równa mojej.","","„Dobra matka uczy swoje dzieci, jak polować. Ale najlepsza matka… poluje za nie”. – Elise","Jednostka",["PAJĄK"],["Noxus"],"ZWYKŁE"],"06NX041":["Szkarłatny Gołąb","Wsparcie: Zadaj 1 pkt. obrażeń wspieranemu przeze mnie sojusznikowi, aby przyznać mi +1|+1 w tej rundzie.","","„Całkiem przyjemnie karmi się te ptaki. Założyłem się z biednym Feowardem, że będą spijać krew z taką chęcią, jak bazyliszek Bordenta, i oto patrzcie i podziwiajcie: gołębie istotnie są noxiańskie!” – Edvin Cortain, Szkarłatny Opiekun","Jednostka",["PTAK"],["Noxus"],"EPICKIE"],"06NX020":["Balista Darkinów","Możesz wydać 8 pkt. many, by zagrać mnie jako kartę Naganeka z Zuretty.","","Stepy wschodniego Valoranu znane były z jałowości. Nie były w stanie wykarmić ani utrzymać domostw ludu Noxii. Po upływie stuleci powstało jednak nowe imperium, które łaknęło rozwoju. Jałowe ziemie uprawiane nowymi technikami zaznały płodności, a bronie, niegdyś bezpiecznie zakopane, znów ujrzały światło dzienne.","Wyposażenie",["DARKIN"],["Noxus"],"EPICKIE"],"06NX039":["Uczta Rozkoszy","Zadaj 2 pkt. obrażeń sojusznikowi, aby dać sojusznikom +2|+0 w tej rundzie.","","„Póki ktoś nie zacznie krzyczeć, żadna to uczta. Więc krzycz, chłopcze”. – Vladimir","Zaklęcie",[],["Noxus"],"ZWYKŁE"],"06NX026":["Wielkie Młoty","","","Vessid nie jest najszybszym walecznikiem Bordenta, ale gdy jego wielkie młoty trafią cel, z przeciwnika nigdy nie zostaje wystarczająco wiele, aby mu oddać.","Wyposażenie",[],["Noxus"],"ZWYKŁE"],"06NX034":["Wściekły Władający","Sojusznik z Wyposażeniem Uderza wroga.","","„Bracia we krwi, po raz kolejny!” – Noxiański Dezerter","Zaklęcie",["KULTYSTA"],["Noxus"],"RZADKIE"],"06NX036":["Dziedzic Run","Gdy mnie przywołasz, Przekuj.","","Miesiącami zmagał się z zimnem i deszczem, wykonując niewdzięczne zadanie, które zdawało się ciągnąć w nieskończoność. A jednak koniec ostatecznie nadszedł. Wreszcie stał się kimś.","Jednostka",[],["Noxus"],"ZWYKŁE"],"06NX027":["Brutalna Potyczka","Zniszcz Wyposażenie wroga. Sojusznik i ten wróg Uderzają siebie nawzajem.","","„Raz, dwa, trzy i krzyk,\nŻołnierza zajął o-gień,\nCztery, pięć, pali się,\nTibbers już zwiększa pło-mień!” – Annie","Zaklęcie",[],["Noxus"],"RZADKIE"],"06MT035":["Xolaani Tkająca Krew","Dostaję +2|+2 za każdego sojusznika, który zginął, mając zwiększoną Siłę.\nWzmocnienie 16: Przemień mnie w kartę Xolaani Zguba Aspektu.","","Xolaani obserwowała, jak Anaakca pada na kolana, upokorzony przez tego samego wroga, którego z taką desperacją próbował zniszczyć. Jego tętno powoli łączyło się w jedności z pozostałymi. Kolejne serce do przejęcia. Kolejne ciało pod jej kontrolą.","Jednostka",["DARKIN"],["Targon"],"EPICKIE"],"06MT007":["Anielska Wiwerna","Wzmocnienie 5: Zmiażdżenie.","","„Ach, teraz rozumiem… figury odciśnięte w górze były zaledwie piętnem, kanałami dla istot ze świata spoza gwiazd…” – Strażnik Wiedzy Skai’en","Jednostka",["SMOK"],["Targon"],"RZADKIE"],"06MT037":["Przypieczętowanie w Stali","Unicestwij sojusznika i stwórz kartę Spaczona Postać z jego statystykami.","","Poległych bogów-wojowników pogrzebanych w tych broniach nie można było w prosty sposób pokonać, dlatego też ich zapieczętowano.","Zaklęcie",[],["Targon"],"RZADKIE"],"06MT031":["Mihira Aspekt Sprawiedliwości","Koniec rundy: Przyznaj sojusznikom w grze i w ręce +1|+1.\nWzmocnienie 5: Nieuchwytność, Kradzież Życia i Zmiażdżenie.","","„Niektórzy oddają Aspektom cześć niczym bóstwom. Inni postrzegają je jako posłańców z innego świata. Inni natomiast wciąż się ich obawiają… i możliwe, że słusznie”.\n– Strażnik Wiedzy Skai’en","Jednostka",[],["Targon"],"EPICKIE"],"06MT010":["Boski Osąd","Daj sojusznikowi „Nie mogę otrzymać obrażeń ani zginąć” w tej rundzie.\nDaj wszystkim sojusznikom +1|+0 w tej rundzie.","","„Chronieni płomieniem prawości!” – Kayle","Zaklęcie",[],["Targon"],"RZADKIE"],"06MT016":["Skrzydlaty Posłaniec","Wzmocnienie 3: Nieuchwytność.","","„Tak… poznaję cię. Wiadomość, którą dzierżysz… może być wyłącznie wezwaniem”. – Ryze","Jednostka",[],["Targon"],"ZWYKŁE"],"06MT015":["Oczyszczające Płomienie","Przyznaj 2 sojusznikom w ręce +2|+2.","","„Zło spłonie!” – Kayle","Zaklęcie",[],["Targon"],"ZWYKŁE"],"06MT042":["Obrońca Półmroku","Brzask: Daj sojusznikom z Brzaskiem +1|+1 w tej rundzie.\nZmrok: Przyznaj sojusznikom ze Zmrokiem +1|+0.","","Po zachodzie słońca i tuż przed jego wschodem słychać pohukiwania sowy. Ich dźwięk przypomina o tym, co dzieje się pomiędzy zmierzchem a świtem.","Jednostka",["PTAK"],["Targon"],"RZADKIE"],"06MT008":["Kayle","Dostaję +1|+0 za każdym razem, gdy sojusznik zaatakował ze zwiększoną Siłą.\nGdy mnie przywołasz, przyznaj sojusznikom +1|+0.\nWzmocnienie 6: Szybki Atak.","Początek rundy: Mam 11+ Siły.","„Demacianie znają ją jako Skrzydlatą Obrończynię, za to my, którzy żyjemy pod gwieździstym sklepieniem w Targonie, zwiemy ją córką Sprawiedliwości, mającą boski cel i dzierżącą miecz z płomieni gwiazd”. – Strażnik Wiedzy Skai’en","Jednostka",[],["Targon"],"Bohater"],"06MT004":["Wędrujący Pasterz","Zagraj: Wybierz sojusznika. Wybrany sojusznik Improwizuje. Jeśli nie wybierzesz sojusznika, ja Improwizuję.","","Jax pomógł Chasce uratować stado przed wściekłymi wróżkoludziami. Potem Jax został uratowany przez Chaskę przed tym samym zagrożeniem. Teraz podróżują razem.","Jednostka",["WIRTUOZ BRONI"],["Targon","Bandle City"],"ZWYKŁE"],"06MT017":["Boski Klerk","Wzmocnienie 3: Kradzież Życia.","","„Mówi się, że kiedy Mihira opuściła ten pałac, zostawiła w nim część siebie – święty ogień, który płonie jasno. Przez lata moja rodzina go doglądała, podtrzymując jego żar w nadziei, że ona jeszcze powróci”.","Jednostka",[],["Targon"],"RZADKIE"],"06MT040":["Ochrona Bezkresu","Kiedy udało ci się wręczyć Wyposażenie sojusznikowi w tej grze, kosztuję o 2 mniej.\nDaj sojusznikowi Tarczę Magii w tej rundzie.","","Spójrz na nocne niebo i skup się na niewielkim skrawku firmamentu. A teraz pomyśl o wszystkich tych, którzy na nim żyli, o całej zdobytej wiedzy i doświadczeniach zgromadzonych przez niezliczone milenia. Wyobraź sobie, że te wszystkie informacje skondensowano w odłamku, który mieści się w twojej dłoni. Pomyśl o tym, jak ogromna wiedza byłaby do twojej dyspozycji. Jaka ogromna moc.","Zaklęcie",["KULTYSTA"],["Targon"],"RZADKIE"],"06MT034":["Astralne Uderzenie","Unicestwij jednostkę lub lokację. Ulecz swój Nexus o 3 pkt.","","„Któż pojawiłby się w naszej czarnej godzinie?” – Starszy z Shurimy","Zaklęcie",[],["Targon"],"RZADKIE"],"06MT033":["Smocze Zarękawia","Trzymająca mnie karta jest Smokiem.","","Wielu wzywa potęgę smoków, choć przejawia się ona inaczej w poszczególnych obszarach Runeterry. Ci, którzy wzywają moc astralnego smoka, mogą odkryć, że posiadają wewnętrzną siłę płonącą równie jasno i gorąco, co gwiazdy na niebie.","Wyposażenie",[],["Targon"],"ZWYKŁE"],"06MT053":["Hojna Rzemieślniczka Klejnotów","Gdy zagrasz zaklęcie, przyznaj losowemu sojusznikowi w ręce +1|+1.","","Jej oczy emanują dobrem, lecz twarz ma skrytą za welonem. Oferuje kryształowe różańce tym, którzy rozpoczynają pielgrzymkę. Nic nie chce w zamian. Cena zostanie zapłacona na Górze.","Jednostka",[],["Targon"],"EPICKIE"],"06MT006":["Magnetyt Darkinów","Wsparcie: Przyznaj wspieranemu przeze mnie sojusznikowi +1|+1.\nMożesz wydać 8 pkt. many, by zagrać mnie jako kartę Horazi.","","Być może ci, którzy uwięzili Darkinów, sądzili, że pogrzebanie legendarnej wojowniczki Horazi wewnątrz kuli z gwiezdnego metalu wystarczająco przyćmi jej porywczą wolę. Jednak gdy zbudził się jej generał, zbudziła się również Horazi i przekonała się, że nawet pradawnych obrońców Targonu można zwieść szeptanymi obietnicami.","Wyposażenie",["DARKIN"],["Targon"],"EPICKIE"],"06MT018":["Stróż Prawa","Zagraj: Ogłusz wrogów o Sile mniejszej niż moja.","","„Obawiam się, że ten dzień w końcu nadszedł… Sprawiedliwość powraca na złocistych skrzydłach, a za nią maszeruje lśniąca armia!” – Strażnik Wiedzy Skai’en","Jednostka",[],["Targon"],"ZWYKŁE"],"06MT052":["Astralne Błogosławieństwo","Przyznaj sojusznikowi w grze i sojusznikowi w ręce Ducha.","","„Z boską łaską”. – Kayle","Zaklęcie",[],["Targon"],"ZWYKŁE"],"06MT032":["Kultystka Lunari","Gdy mnie przywołasz lub jeżeli udało ci się wręczyć Wyposażenie sojusznikowi w tej grze, stwórz w ręce kartę Klejnot.","","Pragnęła zakończyć konflikt między Słońcem a Księżycem, dniem a nocą. Łuk oferował jej moc, choć wiązała się ona z przerażającym kosztem. Mimo tego złożyła ślubowanie, mając nadzieję, że raz na zawsze zakończy to wojnę. ","Jednostka",["KULTYSTA"],["Targon"],"ZWYKŁE"],"06RU008":["Jax","Pochodzenie: Mistrz Broni.\nAutomatyczne Wyposażenie: Światło Icathii.","Sojusznicy z Wyposażeniem zaatakowali z łączną Siłą wynoszącą 16+.","Wieki temu Jax stracił swoją ojczyznę w odmętach Pustki. Teraz podróżuje on po świecie, poszukując wojowników, którym nie brak siły woli – ani najzwyczajniej tupetu – aby pewnego dnia stawić czoła przerażającemu wrogowi.","Jednostka",["WIRTUOZ BRONI"],["Runeterra"],"Bohater"],"06RU006":["Ryze","Pochodzenie: Mag Run.\nGdy mnie przywołasz lub na Początku rundy: Stwórz w swojej talii 2 karty Zgłębienie Przeszłości.","Widzę 3+ niepowtarzalne Runy Świata.","Ryze dotarł na szczyt wzniesienia w towarzystwie nieskorego do rozmowy sługi Kayle. Skierował wzrok w dół, patrząc na okaleczone przez wojnę ziemie. Spostrzegł wtedy walczące ze sobą darkińskie monstra. Przez wieki przyglądał się, jak ludzkość gnała od jednej katastrofy do kolejnej. W myślach zadał sobie pytanie: co jeśli jego starania nie mają znaczenia, a Runeterra jest skazana na śmierć?","Jednostka",[],["Runeterra"],"Bohater"],"06RU005":["Kayn","Pochodzenie: Żniwiarz Cienia.\nAutomatyczne Wyposażenie: Kosa Darkinów.\nGdy zabiję wroga, ulecz mnie o 2 pkt.","Uderzyłem dwa razy. Gdy awansuję, Wycofaj mnie.","Gdy na ziemię zwaliło się kolejne ciało, Kayn wydał z siebie radosny śmiech. Doskonale wiedział, że niebawem uwolni drugą z pogrzebanych broni Darkinów. W jego wnętrzu narastało też podekscytowanie Rhaasta, który wiedział, że w końcu zbliża się koniec Kayna.","Jednostka",["DARKIN"],["Runeterra"],"Bohater"],"06RU026":["Aatrox","Pochodzenie: Zagłada Świata.\nAutomatyczne Wyposażenie: Ostrze Darkinów.\nGdy mnie przywołasz lub Uderzę: Ulecz swój Nexus o 2 pkt. i stwórz w ręce kartę Zagłada Świata, jeśli jej nie masz.","Udało ci się zagrać kartę Zagłada Świata.","Nawet pomimo dzielących ich kontynentów Aatrox wyczuł jej przebudzenie. Czuł, jak pali ją nienawiść. Zniszczył już jej posągi, a teraz wypowie ostateczną wojnę Tchórzowi z Icathii i zakończy jej żałosną egzystencję poprzez całkowite zniszczenie.","Jednostka",["DARKIN"],["Runeterra"],"Bohater"],"06RU009":["Varus","Pochodzenie: Strzała Odkupienia.\nAutomatyczne Wyposażenie Łuk Darkinów.","Udało ci się obrać za cel 7+ sojuszników.","A co by się stało, gdyby człowiek, który stał się Darkinem, przypomniał sobie o sobie samym, zachęcony wewnętrznymi głosami śmiertelników? A co by było, gdyby zamiast przezwyciężać te głosy, zaczął im wierzyć?","Jednostka",["DARKIN"],["Runeterra"],"Bohater"],"06FR004":["Uczennica Kowala Broni","Gdy po raz pierwszy Wyposażysz sojusznika, Wykuj go.","","Ornn stworzył żywą kuźnię wiele, wiele lat temu, ale przypomniał sobie o niej niedawno. Nigdy nie przeszło mu przez myśl, że ta będzie sobie szukać nowego właściciela i sama dokądś pójdzie.","Jednostka",[],["Freljord"],"ZWYKŁE"],"06FR011":["Ornn","Zagraj: Wyposażam dokładną kopię Wyposażenia sojusznika lub znajdującego się w ręce Najsilniejszego Wyposażenia.\nAtak: Wykuj mnie dwukrotnie.","Sojusznik Uderzył za 8+ pkt. obrażeń jednym Uderzeniem.","Jeżeli ktokolwiek spytałby Ornna, dlaczego ma tak mało cierpliwości, to odpowiedziałby po prostu, że ma cierpliwość. Ogromną cierpliwość, będąc zupełnie szczerym, i to właśnie dlatego jego prace nie mają sobie równych. On po prostu nie ma cierpliwości do LUDZI. Ale nikt o to nie zapytał, a więc i on nie odpowiedział.","Jednostka",[],["Freljord"],"Bohater"],"06FR035":["Na Ratunek","Daj sojusznikowi +0|+3 w tej rundzie. Jeśli jest zraniony, zamiast tego daj mu +2|+3.","","„Nie obawiaj się, mały Poro. Jestem z tobą!” – Braum","Zaklęcie",[],["Freljord"],"ZWYKŁE"],"06FR034":["Bezwzględne Zimno","Nałóż Odmrożenie na Najsilniejszego wroga. Jeśli udało ci się wręczyć sojusznikowi Wyposażenie w tej grze, skopiuj mnie.","","Anaakca poruszała się z taką prędkością, że sam Freljord zdawał się za nią podążać. Ci, którzy przetrwali niesioną przez nią rzeź, niebawem odczuli na swojej skórze mróz, a ich serca zamarły w bezruchu.","Zaklęcie",["KULTYSTA"],["Freljord"],"ZWYKŁE"],"06FR018":["Włócznia Darkinów","Atak: Przyznaj 2 pierwszym sojusznikom z wierzchu talii +1|+1.\nMożesz wydać 8 pkt. many, by zagrać mnie jako kartę Anaakca.","","„– Wojmatko, zima zacisnęła swoje szpony. Avarosanie porzucili swoje obozy. Na północy rozciąga się morze… pozostaje nam jedynie ruszyć na wschód.\n– Nie słuchaj go, Wojmatko. Tam leży Bladość, a za nią ciągnie się szepcząca dzicz. Jak na moje, lepiej jest umrzeć, niż zmierzyć się z tymi przeklętymi ziemiami.\n– Jakże wielkie macie szczęście, że żadne z was nie musi decydować o losie mojego ludu.\n– To prawda, Wojmatko. Być może jest jednak trzecia możliwość. Pozwól mi wyruszyć na wschód. Lepiej, żeby ciemność pochłonęła tylko zwiadowcę, nie cały nasz lud”.\n– Wojmatka Sejuani podczas narady ze swoimi generałami","Wyposażenie",["DARKIN"],["Freljord"],"EPICKIE"],"06FR012":["Rzemieślnik spod Szczęśliwej Gwiazdy","Gdy mnie przywołasz, stwórz w ręce kartę Czas i Poświęcenie.","","„Matka opowiadała mi o Ornnie, tak jak jej matka opowiadała jej, a jej matce opowiadała jej matka… i jak teraz ja wam opowiem. Słuchajcie uważnie. Nie przerywajcie. Dawno temu po drugiej stronie wielkiego, gorącego, wzburzonego morza…”","Jednostka",[],["Freljord"],"ZWYKŁE"],"06FR005":["Kuźnia Ornna","Gdy mnie przywołasz lub na Początku rundy: Stwórz w ręce Ulotną kartę Czas i Poświęcenie.","","On jeden w kuźni Paleniska, mając do towarzystwa wyłącznie odgłos leniwie płynącej w głębinach stopionej rzeki i dźwięczenie Młota o kowadło… to właśnie lubił.","Lokacja",[],["Freljord"],"RZADKIE"],"06FR040":["Strażnik Plemion","Gdy mnie przywołasz, przyznaj sojusznikom +1|+1 za każdy rodzaj podtypu, jaki udało ci się przywołać w tej grze.","","„…i tam było takie DUŻE stworzonko i ono dbało o wszyyyyystkie te MAŁE stworzonka…” – Ingvar Młodsza","Jednostka",[],["Freljord"],"EPICKIE"],"06FR020":["Roztrzaskanie","Zadaj 1 pkt. obrażeń WSZYSTKIEMU lub zniszcz Wyposażenie jednostki.","","Zimno nie oszczędza nikogo ani niczego.","Zaklęcie",["ŻYWIOŁ"],["Freljord"],"RZADKIE"],"06FR027":["Włochaty Ślimakomut","Wzmocnienie 8: Regeneracja.","","Chociaż trolle nie są zwykle kojarzone z intelektem, to potrafią być jednak zaskakująco genialne.","Jednostka",[],["Freljord"],"RZADKIE"],"06FR032":["Dar Ognistokrwistych","Ulecz swój Nexus o 4 pkt. i przyznaj wszystkim sojusznikom oraz Wyposażeniom w swojej talii +1|+1. Dobierz jednego z nich.","","„Podejdź, ogrzej się przy ogniu”.\n– Naprawiacz Ognistokrwistych","Zaklęcie",[],["Freljord"],"EPICKIE"],"06FR022":["Ognisty Miech","Wykuj sojusznika i zadaj 1 pkt. obrażeń WSZYSTKIM jednostkom. Zrób to ponownie.","","„Żelazo należy przekuć!” – Ornn","Zaklęcie",["ŻYWIOŁ"],["Freljord"],"RZADKIE"],"06FR021":["Nadąsany Poro","Wzmocnienie 3: Zmiażdżenie, Regeneracja i Wytrzymałość.","","„No już, musisz wziąć lekarstwo! Nie poczujesz się lepiej, jeśli go nie weźmiesz!” – Ingvar Młodsza","Jednostka",["PORO"],["Freljord"],"ZWYKŁE"],"06FR023":["Kuty Kolos","Gdy po raz pierwszy otrzymam Wyposażenie, stwórz w ręce moją kopię o koszcie 4. Przyznaj jej statystyki Wyposażenia.","","Choć Ornn nigdy by tego nie przyznał, to był całkiem zadowolony z kolosów. Służyli dokładnie celowi, który im wyznaczył, a najlepsze, że się nie odzywali.","Jednostka",[],["Freljord"],"EPICKIE"],"06FR008":["Naprawiacz Ognistokrwistych","Zagraj: Wykuj sojusznika dwukrotnie. Ulecz jego oraz swój Nexus o 3 pkt.","","Kiedy Ornn postanowił opuścić świat, nie było już na nim Ognistokrwistych – ani jednego. Mijały pokolenia, a ich imię popadało w zapomnienie. Ostatnimi czasy jednak na nowo zaczęto opowiadać o Ornnie, a szeptem wspomina się, że niektórzy zaczęli zwracać się ku nauce Ognistokrwistych.","Jednostka",[],["Freljord"],"ZWYKŁE"],"06FR009":["Zdolny Kowal Broni","Zagraj: Wykuj sojusznika.","","Kiedy Fiske po raz pierwszy pomyślał o adepcie, wyobrażał sobie kogoś oddanego i poważnie podchodzącego do swojej sztuki – kogoś silnego i zdolnego. Kindra nie spełniała żadnego z tych kryteriów. Miała skłonność do bujania w obłokach i wolała dobrze się bawić niż pracować. Zawsze wygłupiała się z tym swoim małym żółwiem. Ale… uczyła się. I to się liczyło.","Jednostka",[],["Freljord"],"ZWYKŁE"],"06FR024":["Kościana Maczuga","","","„Chrup!” – Tarkaz Bezplemienny","Wyposażenie",[],["Freljord"],"ZWYKŁE"],"06FR017":["Kultysta z Lodowej Doliny","Twoi sojusznicy z Wyposażeniem mają Zmiażdżenie.","","Zimowy Szpon miał rację. Avarosanie BYLI zbyt łagodni. Nastał czas na nowego przywódcę – przywódcę, który nie próbowałby zjednoczyć Freljordu w pokoju, ale który przejąłby nad nim władzę. ","Jednostka",["KULTYSTA"],["Freljord"],"RZADKIE"],"06FR041":["Dotyk Zimy","Otrzymujesz pusty kryształ many. Oświecenie: Kosztuję 1. Dobierz 1 kartę.","","Dziwne runy emanują energią z kryształu w twojej dłoni. Po upiornym rozbłysku ich światło wynosi się ponad powierzchnię, otulając twoją rękę w chłodnym uścisku. Jednak nie czujesz chłodu, lecz orzeźwienie, jakby samo zimno nasyciło cię swą esencją. ","Zaklęcie",["ŻYWIOŁ"],["Freljord"],"EPICKIE"],"06FR036":["Zwierzęcy Mistycyzm","Otrzymujesz pusty kryształ many.\nPrzywołaj kartę Dziki Mistyk.","","„Duchy, gwiazdy… znów nas jednoczą”. – Hyara Wszystkowidząca","Zaklęcie",[],["Freljord"],"EPICKIE"],"06BC015":["Norra","Uderzenie w Nexus: Umieść kartę Tajemniczy Portal wśród pierwszych 4 kart z wierzchu swojej talii.","Udało ci się przywołać 6+ stworzonych sojuszników.","Norra pracowała w pośpiechu. Jej umysł wypełniały myśli o domu. Praca z portalami nagminnie bywała zdradliwa, a ona nawet jeszcze nie wypiła swojej pierwszej filiżanki herbaty. Norra uwielbiała jednak dobre zagadki, szczególnie takie, które porzucały ją beznadziejnie zagubioną w kieszonkowych wymiarach pomiędzy czasem a przestrzenią. Pracowała jeszcze szybciej, myśląc z czułością o swojej kotce, która przecież musiała się martwić i czekać na obiad.","Jednostka",["YORDLE"],["Bandle City"],"Bohater"],"06BC043":["Opowieści Poro","Stwórz w ręce 3 losowe Poro o koszcie 1.","","„…NO I POTEM PORO MIAŁ TAKIE »EJ, TY, JA TEŻ CHCĘ CHRUPKA!« NO TO SIĘ PORO ZEBRAŁY RAZEM NA TAKIM WIELKIM SPOTKANIU WSZYSTKICH PORO, ŻEBY ROZMAWIAĆ O WSZYSTKICH TYCH TAKICH PROBLEMACH PORO, ŻE GDZIE SĄ CHRUPKI I CZEMU WIĘCEJ PORO NIE MA I…” – Ingvar Młodsza","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"06BC051":["Bananowa Dewastacja","Zagraj: Zadaj jednostce obrażenia równe mojej Sile.","","„HEJ! CZY KTOŚ POTRZEBUJE POTASU?” – profesor Nanners na chwilę przed „incydentem”. ","Jednostka",["YORDLE"],["Bandle City"],"RZADKIE"],"06BC047":["Trzeba Się Dzielić","Daj sojusznikowi z przywiązaną kartą statystyki i słowa klucze przywiązanej do niego karty w tej rundzie i przenieś tę przywiązaną kartę na innego sojusznika.","","Można by pomyśleć, że pole bitwy nie jest miejscem dla pasterza, jednak pasterskie umiejętności są tu zaskakująco przydatne. Wystarczy tylko uznać wszystkich walczących za owce, które trzeba wyprowadzić na pastwisko.","Zaklęcie",["WIRTUOZ BRONI"],["Targon","Bandle City"],"RZADKIE"],"06BC019":["Herbaciarka","Gdy mnie przywołasz, umieść kartę Tajemniczy Portal wśród pierwszych 4 kart z wierzchu swojej talii.","","Nim Ashane zagubiła się na Końcu Świata, była poważaną zaparzaczką herbaty. Któregoś razu, kiedy eksperymentowała z nowymi smakami, przez niefortunne połączenie dwóch liści zapadła w głęboki sen. Śniła wtedy o przedziwnych stworzeniach i niemożliwych strukturach, których sylwetki majaczyły na niekończącym się horyzoncie. Po przebudzeniu się odkryła jednak, że to wcale nie był sen.","Jednostka",["WRÓŻKA"],["Bandle City"],"ZWYKŁE"],"06BC029":["Kostur Darkinów","Uderzenie: Odzyskaj 1 pkt. many zaklęć.\nMożesz wydać 8 pkt. many, by zagrać mnie jako kartę Baalkux.","","Las Bandle wydawał się być idealnym ukryciem dla broni Darkinów – do takiego wniosku doszli. Z natury nie sposób odnaleźć w nim drogę, natomiast Yordlowie wiedzieliby doskonale, że należy trzymać się z dala od tak skrajnego ucieleśnienia wrogości. Targonianie nie przewidzieli jednak oddziaływania magii z Bandle ani sposobów, w jakie może wpłynąć na lokalną roślinność.","Wyposażenie",["DARKIN"],["Bandle City"],"EPICKIE"],"06BC038":["Nagły Przypływ Mocy","Kiedy udało ci się wręczyć Wyposażenie sojusznikowi w tej grze, kosztuję o 2 mniej.\nZwiększ statystyki sojusznika do 4|4 w tej rundzie.","","„Jest w nas tyle mocy” – Varus","Zaklęcie",["KULTYSTA"],["Bandle City"],"RZADKIE"],"06BC017":["Portale na Całego","Umieść 2 karty Tajemnicze Portale wśród pierwszych 4 kart z wierzchu swojej talii.\nDobierz 1 kartę.","","„Częściej powinnam chodzić tymi nisko położonymi ścieżkami! Ale ze mnie gapa, zawsze zapomnę o własnej głowie…”\n– Norra","Zaklęcie",[],["Bandle City"],"RZADKIE"],"06BC020":["Zacinarka Origami","Daj mi +1|+0 za każdą z twoich pułapek lub darów aktywowanych w tej rundzie.","","Magia origami może być dość nieprzewidywalna. Chodzi w niej zarówno o intencję włożoną w stworzenie czegoś nowego, jak i o pragnienie tworu do zostania ukształtowanym.","Wyposażenie",[],["Bandle City"],"RZADKIE"],"06BC028":["Kwitnący Kultysta","Jeżeli udało ci się wręczyć Wyposażenie sojusznikowi w tej grze, przyznaj mi Nieuchwytność.","","Osoba, roślina, zwierzę… wypaczający wpływ Darkinów nie oszczędza nikogo ani niczego.","Jednostka",["KULTYSTA"],["Bandle City"],"ZWYKŁE"],"06BC021":["Złomotwór","Ostatnie Tchnienie: Umieść kartę Tajemniczy Portal wśród pierwszych 4 kart z wierzchu swojej talii.","","Choć Marv – jak pieszczotliwie nazywała go Norra – narodził się dopiero wczoraj, to rola asystenta stała się dla niego źródłem wielkiej dumy. Niemniej jednak twór stanowczo upiera się, aby nazywać go „złomem”, a nie „śmieciami”, aby uniknąć negatywnych konotacji.","Jednostka",["WRÓŻKA"],["Bandle City"],"ZWYKŁE"],"06BC042":["Ciekawskie Zmienniątka","Gdy sojuszniczy stronnik przemieni się w innego stronnika, przemień mnie w dokładną kopię tej jednostki.","","Kameleon widzieć, kameleon być.","Jednostka",[],["Bandle City"],"RZADKIE"],"06BC023":["Mylące Drogowskazy","Przywróć Szybkie lub Powolne zaklęcie do ręki lub zniszcz Wyposażenie jednostki. Dobierz 1 kartę.","","„Ojejciu! To było tędy czy tamtędy… czy w ogóle siamtędy? Nigdy nie pamiętam!” – Norra","Zaklęcie",[],["Bandle City"],"RZADKIE"],"06BC041":["Częściomnogość Skrappy","Gdy mnie odrzucisz, przywołaj mnie. Gdy przywołasz Mecha Yordla, przyznaj mu losowe słowo klucz.","","Duże czy małe, ożywione czy też nie, jeśli trzeba ci jakiegoś dynksa, poszukaj u Skrappy! Tylko nie pytaj jej, gdzie to może być. Skrappy nie wyznaje katalogowania.","Lokacja",[],["Bandle City"],"RZADKIE"],"06BC011":["Magiczna Podróż","Umieść kartę Tajemniczy Portal wśród pierwszych 4 kart z wierzchu swojej talii i umieść kartę Dzwonek na karcie z wierzchu swojej talii.","","Wędrując przez przeróżne światy, gdy tylko tego zapragnie, Bard się przysłuchuje. Wie bowiem, że zbliża się wielki konflikt, który może uciszyć pieśń stworzenia.","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"06BC032":["Eklektyczna Kolekcja","Za każdego sojusznika umieść kartę Tajemniczy Portal i 3 karty Dzwonki wśród pierwszych 10 kart z wierzchu swojej talii oraz umieść kartę Pułapka z Bombą Błyskową i 3 karty Trujące Grzyby w talii przeciwnika.","","„Portale, portale, wszędzie portale!”\n– Norra","Zaklęcie",[],["Bandle City"],"EPICKIE"],"06BC024":["Opiekun Świata","Podczas pierwszej aktywacji jednej z twoich pułapek lub darów w danej rundzie daj sojusznikom +1|+1 i Wpływ w tej rundzie.","","Gaspar był pierwszym Yordlem, który znalazł się na Końcu Świata. Przez wiele lat błądził w samotności wśród wijących się ścieżek i portali, które wydawały się prowadzić donikąd. Postanowiwszy, że nikt inny nie powinien już nigdy przez to przechodzić, teraz pomaga innym zagubionym wędrowcom odnaleźć drogę do domu.","Jednostka",["WRÓŻKA"],["Bandle City"],"RZADKIE"],"06BC033":["Mechapiąchator","Aby zagrać, odrzuć 1 kartę.","","„Podziwiajcie! Z pozostałości zatopionego promu pozyskałem rękawicę bokserską. Z czeluści miasta zwanego Zaun wydobyłem sprężyny, a z kuźni Demacii otrzymałem metal! Stoi przed wami prawdziwe dzieło całego świata!”\n– Wielki Paparo","Wyposażenie",[],["Bandle City"],"ZWYKŁE"],"06BC016":["Żywa Biblioteka","Gdy mnie przywołasz, jeśli w tej rundzie aktywowano jedną z twoich pułapek lub darów, dobierz 1 kartę.","","Za swoje zadanie uznając posiadanie niemożliwych pokładów wiedzy, kolekcjonuje on księgi od przeróżnych podróżników, którzy odwiedzili Koniec Świata. Niestety cała ta wiedza najwyraźniej uderzyła mu do głowy.","Jednostka",["WRÓŻKA"],["Bandle City"],"ZWYKŁE"],"06IO044":["Podniebny Śpiewak","Przywołanie mnie zmniejszy koszt zaklęć w twojej talii o połowę, zaokrąglając w górę.","","„Wielu próbuje odnaleźć spokój w medytacji. Inni szukają wiedzy, by przemyśleć swoje postępowanie. Ci, którzy odnajdują się przez wyrażanie siebie i tworzenie, mogą przynieść spokój ducha innym” – Karma","Jednostka",[],["Ionia"],"EPICKIE"],"06IO013":["Styl Wuju","Daj sojusznikowi +2|+0 w tej rundzie.\nStwórz w ręce kartę Medytacja.","","„O jedno cięcie za dużo”.\n– Master Yi","Zaklęcie",[],["Ionia"],"RZADKIE"],"06IO023":["Wachlarz Darkinów","Atak: Przywołaj atakującą kartę Smoczątko.\nMożesz wydać 9 pkt. many, by zagrać mnie jako kartę Praa, Stąpający przez Wyrwy.","","„Na moście między światami od dawna wyczuwałem cień pulsujący niemą wściekłością. Chociaż wiem, że nie należy się zagłębiać w leżący za nim mrok, to od niedawna pulsuje silniej, szybciej. Żywię obawę, że stworzenia ze świata duchów niebawem zaczną go szukać”. – Shen","Wyposażenie",["DARKIN"],["Ionia"],"EPICKIE"],"06IO029":["Duch Wuju","Przypływ: Kosztuję o 2 mniej.\nGdy mnie przywołasz, dobierz zaklęcie.","","„Mistrz Doran wierzył, że każde z oczu Ducha Wuju oferowało wyjątkowy wgląd w istotę danej osoby. Ale nieważne, ile ja próbuję, soczewki mojego hełmu widzą tylko różne odcienie zieleni. Czego mi brakuje?”\n– Lui, Uczeń Dorana","Jednostka",[],["Ionia"],"ZWYKŁE"],"06IO037":["Czarny Płomień","Zagraj: Zniewól sojusznika. Gdy atakujesz po raz pierwszy w każdej rundzie, przywołaj Efemeryczną atakującą kopię tego sojusznika.","","„Czym jest jedno życie, jeśli nie cieniem egzystencji? Przyjmij mrok, a będziesz żyć po wieki”. – Zed","Lokacja",[],["Ionia"],"EPICKIE"],"06IO031":["Miecz Duszy","Przypływ: Kosztuję o 2 mniej.","","„Ostrze i ciało”. – Master Yi","Wyposażenie",[],["Ionia"],"ZWYKŁE"],"06IO014":["Vastajański Uczeń","Uderzenie w Nexus: Wycofaj mnie i przemień mnie w kartę Wiatr Shimonów.","","Ting wyszczerzył się, gdy agresorzy zalali świątynię. W końcu szansa, by udowodnić swoje zdolności! Najpierw Wukong, potem Yi… żaden z nich nie dostrzegał jego talentów. Niech pozostali biegną szukać swojego „mistrza”! On był gotów. On był Wiatrem Shimonów. ","Jednostka",[],["Ionia"],"EPICKIE"],"06IO008":["Master Yi","Początek rundy: Zmniejsz koszt zaklęcia w ręce o 1 oraz Przypływ: Przyznaj wszystkim sojuszniczym kartom Masterzy Yi +2|+0, gdziekolwiek są.","Sojusznicze karty Masterów Yi zadały 12+ pkt. obrażeń.","Myśli Mastera Yi pobiegły ku broni Darkinów. Od momentu jej odkrycia dręczyło go okropne poczucie wiszącej w powietrzu grozy. Niektórzy z jego uczniów wykazywali głębokie – zbyt głębokie – zainteresowanie znaleziskiem, więc umieścił krągłe ostrza pod strażą w głębi świątyni. Nie bez wysiłku, lecz odepchnął niechciane myśli z dala od swojego umysłu i kontynuował swoją medytację. Liczyło się jedynie przekazywanie nauk Wuju, a Jun zapowiadała się bardzo obiecująco.","Jednostka",[],["Ionia"],"Bohater"],"06IO040":["Technika Bliźniaczego Wiatru","Wybierz stronnika. Przywołaj jego dokładną Efemeryczną kopię. Jeśli jest to wróg, Ogłusz go.","","Dla Ionian wiatr jest najbardziej kapryśnym z żywiołów. Kapryśnym, lecz nie niemożliwym do poskromienia. ","Zaklęcie",[],["Ionia"],"RZADKIE"],"06IO011":["Jun Uzdolniona","Gdy po raz pierwszy otrzymam Wyposażenie, daj mi Barierę i Kradzież Życia w tej rundzie.","","Na jego sygnał Jun wyprowadziła serię ciosów. Każdy z nich cechował się precyzją, której nie powstydziłby się on sam. Choć Yi zgrabnie uchylił się przed atakiem, to skłonił się przed nią. W jego uśmiechu widoczna była duma.","Jednostka",[],["Ionia"],"RZADKIE"],"06IO015":["Świadkini","Przypływ: Kosztuję o 2 mniej.\nZagraj: Ogłusz wroga.","","Jaką gra rolę w tym przedziwnym i makabrycznym pokazie? Ach, ona jest więcej niż widownią – to obserwatorka; soczewka, przez którą przenika wszystko, co następnie zostaje zmierzone na tle prawdy i piękna. Oto Świadkini!","Jednostka",[],["Ionia"],"ZWYKŁE"],"06IO030":["Mgłopady","Gdy mnie przywołasz, dobierz Wyposażenie.\nKiedy po raz pierwszy w danej rundzie sojusznik bez Wyposażenia otrzyma Wyposażenie, odzyskaj 2 pkt. many zaklęć.","","„Mgłopady to święta ziemia. Znajdujące się tu miecze są tutaj od stuleci… i wierzę, że każde pozostawione tu ostrze z wierszem wyrytym na rękojeści będzie zaproszeniem dla duchów zagubionych mistrzów broni, aby napełnili je swoim błogosławieństwem”.\n– Uczeń Dorana, zapisany odręcznie zwój","Lokacja",[],["Ionia"],"RZADKIE"],"06IO034":["Wybór Wielkiej Wagi","Jeśli udało ci się wręczyć Wyposażenie sojusznikowi w tej grze, kosztuję o 1 mniej.\nDaj sojusznikowi +2|+0 lub +0|+2 w tej rundzie.","","Łzy wściekłości płynęły po policzkach Jun, gdy patrzyła na ciała ścielące ziemię. Zawiodła ich. Zawiodła swojego mistrza. A teraz pozostał jej tylko jeden wybór…","Zaklęcie",["KULTYSTA"],["Ionia"],"RZADKIE"],"06IO028":["Hipnotyzująca Przynęta","Daj sojusznikowi Wyzwanie w tej rundzie. Jeśli ma on Wyposażenie, dobierz 1 kartę.","","Wszystko łyknie, o ile dobierzesz odpowiednią przynętę.","Zaklęcie",["WIRTUOZ BRONI"],["Ionia","Noxus"],"RZADKIE"],"06IO025":["Fanatyk Cienistego Ostrza","Jeżeli udało ci się wręczyć Wyposażenie sojusznikowi w tej grze, stwórz w ręce kartę Mroczny Upiór.","","Widział ją pośród mroku – broń, która rozcinała cienie. W tej właśnie chwili usłyszał wzywający go głos; odległy, lecz potężny. Podążał za nim do Kayna, a prowadziła go prawda kryjąca się w jego słowach.","Jednostka",["KULTYSTA"],["Ionia"],"ZWYKŁE"],"06IO039":["Navoriański Długoogon","Zagraj: Przywołaj kartę Navoriański Rabuś lub daj innym sojusznikom +1|+1 w tej rundzie.","","Długoogon zacieśnił więzi z rabusiem pewnego zimowego wieczoru, kiedy razem ogrzewali się przy dogasającym, porzuconym ognisku. Z końcem tygodnia nawzajem odkryli, że łączy ich skłonność do złośliwych psikusów i silna fascynacja złotym blaskiem monet.","Jednostka",[],["Ionia"],"ZWYKŁE"],"06IO032":["Niegodna Dusza","Przypływ: Kosztuję o 2 mniej.\nWycofaj jednostkę lub lokację. Jeżeli jest do niej przywiązana jakaś karta, najpierw ją zniszcz.","","„Nie jesteś godzien mocy, którą posiadasz”. – Rhaast","Zaklęcie",[],["Ionia"],"RZADKIE"],"06IO001":["Uczeń Dorana","Gdy mnie przywołasz, stwórz w ręce kartę Przygotowanie.","","„Posiadłem każdą wiedzę, jaką byłem w stanie, aby kontynuować tę świętą sztukę. Jeśli chodzi o Dorana, jego mistrza i mistrza jego mistrza… Mam nadzieję, że ich duchy poprowadzą mój młot”.\n– Uczeń Dorana, zapisany odręcznie zwój","Jednostka",[],["Ionia"],"ZWYKŁE"],"06IO016":["Przyzywacz Smoków","Początek rundy: Przypływ: Przywołaj kartę Empireum i przyznaj jej Efemeryczność.","","„Kształt wody odzwierciedla kształt twojego pożądania. Powiedz mi, wędrowcze… co takiego widzisz?”","Jednostka",[],["Ionia"],"EPICKIE"],"06PZ034":["Hexniszczyciel","Zadaj 6 pkt. obrażeń jednostce. Jeśli miałaby zginąć, Unicestwij ją zamiast tego.","","Niektórym istotom śmierć najzwyczajniej nie wystarcza.","Zaklęcie",[],["Piltover i Zaun"],"RZADKIE"],"06PZ006":["Bis","Stwórz w ręce losowe nowe zaklęcie o koszcie 2, zmniejsz jego koszt o 2 i przyznaj mu Ulotność.","","Nic nie satysfakcjonuje bardziej niż dobre brzmienie.","Zaklęcie",[],["Piltover i Zaun"],"RZADKIE"],"06PZ021":["Seraphine","Gdy mnie przywołasz, stwórz w ręce losowe nowe zaklęcie o koszcie 2.","Udało ci się zagrać 9+ nowych zaklęć.","Seraphine i jej ojciec nigdy nie rozmawiali o jej „tajemniczych” wycieczkach do Miasta pod Miastem lub subtelnych poprawkach, które wprowadzała na swojej scenie. Była pewna, że zabroniłby jej udziału w najbardziej szemranej bitwie muzycznej w całym Zaun, ale pewnego wieczora on po prostu wsunął ulotkę pod jej drzwi. W tej sytuacji mogła się tylko uśmiechnąć i zabrać się do pracy.","Jednostka",[],["Piltover i Zaun"],"Bohater"],"06PZ040":["Podejrzana Oberża","Gdy mnie przywołasz, przywołaj kartę Podejrzany Oberżysta.\nTwoje nowe karty kosztują o 1 mniej.","","Po wytarciu ostatniej ze szklanek oberżysta rozejrzał się po swoim przybytku. W tym miejscu, w tym domu z dala od domu, tak wielu nieznajomych stało się przyjaciółmi, a wszystkich graffiti i obdrapań po wszystkich tych szalonych nocach nie sposób było zliczyć. Oberżysta uśmiechnął się do siebie. To miejsce może i nie było idealne, ale było jego.","Lokacja",[],["Piltover i Zaun"],"EPICKIE"],"06PZ008":["Harfa Darkinów","Możesz wydać 8 pkt. many, by zagrać mnie jako kartę Styraatu.","","Gdy Targonianie rozważali, gdzie powinni rozrzucić bronie Darkinów, jeden z nich zasugerował ziemie, które później świat poznał jako Zaun. Założyli, że zagrzebanie ich głęboko wewnątrz ścian przepastnych, wijących się korytarzy będzie idealnym rozwiązaniem. Znajdą się daleko poza zasięgiem ludzkości. Lecz nie poza zasięgiem Chireana.","Wyposażenie",["DARKIN"],["Piltover i Zaun"],"EPICKIE"],"06PZ018":["Wysoka Nuta","Zadaj 2 pkt. obrażeń jednostce. Jeśli udało ci się zagrać 6+ innych nowych zaklęć w tej grze, zadaj 1 pkt. obrażeń innej jednostce.","","Prosta i czysta.","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"06PZ014":["Przewodnicząca Fanklubu","Zagraj: Pokaż zaklęcie o koszcie 5 i ustal jego koszt na 2.","","„Nie chodzi o to, jak wielki jest twój głos! Chodzi o to, jak wielkie jest twoje serce!” – Przewodnicząca Fanklubu","Jednostka",[],["Piltover i Zaun"],"RZADKIE"],"06PZ030":["Plany Pełne Inspiracji","Atak: Stwórz w ręce nowe zaklęcie o koszcie 2 i przyznaj mu Ulotność.","","„– O nie, zbliża się nawałnica.\n– Hm? Tato, na zewnątrz jest jasno.\n– Szybko, zakryj plany! Zbliża się burza MÓZGÓW!\n– Taaaaaato.”\n– Seraphine i jej ojciec","Wyposażenie",[],["Piltover i Zaun"],"RZADKIE"],"06PZ046":["Formuła","Dobierz 2 karty. Odzyskaj manę zaklęć.","","„Magia to naukowa prawda, której jeszcze nie odkryto”. \n– Jayce","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"06PZ007":["Ambitny Kultysta","Jeżeli udało ci się wręczyć Wyposażenie sojusznikowi w tej grze, stwórz w ręce nowe zaklęcie o koszcie 2 i ustal jego koszt na 0 w tej rundzie.","","„Zawsze byłem skłonny do poświęceń w imię nauki. Niezależnie od podejmowanego przeze mnie ryzyka, nieograniczona i niewyczerpana moc, którą zdobywałem dzięki wymianie, była dla mnie czymś więcej niż nagrodą”.","Jednostka",["KULTYSTA"],["Piltover i Zaun"],"ZWYKŁE"],"06PZ041":["Przebiegły Kociak","Gdy mnie przywołasz, jeśli mnie stworzono, dobierz 1 kartę i przyznaj mi +2|+1.","","Koty zawsze myślą o tym, co można by spsocić – o ile nie śpią akurat w środku dnia albo nie wymiotują punktualnie w środku nocy.","Jednostka",["KOT"],["Piltover i Zaun"],"ZWYKŁE"],"06PZ036":["Zauńska Diwa","Zagraj: Zadaj 1 pkt. obrażeń wszystkim wrogom. Jeśli udało ci się zagrać 6+ nowych zaklęć w tej grze, zamiast tego zadaj 3 pkt. obrażeń.","","„Zaun! Mam nadzieję, że jesteście gotowi na krzyki, bo zamierzamy zatopić to miejsce ponownie!” \n– Zauniańska Diwa","Jednostka",[],["Piltover i Zaun"],"RZADKIE"],"06PZ010":["Akustyk","Uderzenie: Stwórz w ręce losowe nowe zaklęcie o koszcie 2.","","Kiedyś marzył o opuszczeniu Zaun i podróżowaniu po świecie z pieśnią w sercu. Teraz cały jego świat śpi smacznie w swoim pokoju, czekając na piosenki, jakie mogą nadejść jutro.","Jednostka",[],["Piltover i Zaun"],"EPICKIE"],"06PZ022":["Solówka na Perkusji","Dobierz 2 karty.\nPrzypływ: Zmniejsz koszt tych kart o 1.","","W muzyce chodzi o wyczucie dobrego momentu, ale od czasu do czasu trzeba się rozluźnić.","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"06PZ029":["Ulubienica Tłumów","Daj sojusznikowi +2|+0 i Szybki Atak w tej rundzie.\nPrzypływ: Stwórz w ręce nowe zaklęcie o koszcie 2.","","„Nie słyszę was, Zaun!” – Seraphine","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"06PZ020":["Hextechnik Żołądź","Uderzenie w Nexus: Zmniejsz koszt najdroższego zaklęcia w swojej ręce o 1.","","Jego imię nie figurowało na żadnych planach i nie wspomniano go w żadnych pieśniach, ale ci wtajemniczeni zgadzali się co do jednego: Żołądź był sercem całej operacji.","Jednostka",[],["Piltover i Zaun"],"EPICKIE"],"06PZ009":["Żrący Riff","Przypływ: Kosztuję o 2 mniej.\nZadaj 1 pkt. obrażeń wszystkim wrogom.","","Trzeba naprawdę wyjątkowego brzmienia, żeby zagłuszyć wieczny terkot i szczęk niosący się po Zaun, ale Diva zawsze temu podoła.","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"06PZ037":["Agresywny Rozdźwięk","Zadaj 1 pkt. obrażeń jednostce. Jeśli udało ci się wręczyć sojusznikowi Wyposażenie w tej grze, skopiuj mnie z tym samym celem.","","Skoro dysonans jest kakofonią zniszczenia, to kalecz każdy dźwięk.","Zaklęcie",["KULTYSTA"],["Piltover i Zaun"],"RZADKIE"],"06PZ019":["Zauński Robodajło","Początek rundy: Przypływ: Odzyskaj 2 pkt. many zaklęć.","","Gdyby miał robić to po swojemu, to NIKT by nie wszedł.","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"06PZ033":["Gatalizator v1.0","Twoje zaklęcia i Umiejętności zadają 1 dodatkowy pkt. obrażeń.","","„Lokacja: Sektor 3, pozycja 19B\nPrzedmiot: Nielegalna broń palna\nUwagi: Skonfiskowano podczas operacji »Światło Slumsów«. Broń wysoce niebezpieczna. Zachować szczególną ostrożność”.\n– Raport terenowy Strażnika z Piltover","Wyposażenie",[],["Piltover i Zaun"],"ZWYKŁE"],"06BW029":["Piltoverski Rozbitek","Gdy mnie przywołasz, Improwizuję.","","Pesh spotkał Jaxa podczas bijatyki w dokach, a ich idealnie wyliczona w czasie ucieczka wynikała bardziej ze sprzyjającego toku wydarzeń niż z partnerstwa. Od tamtej pory Pesh jednak z chęcią przewozi Jaxa, bo w pobliżu Jaxa wszystko się niszczy… a jeśli jest coś, co Pesh lubi bardziej niż porządna sterta złomu, to sterta złomu, która wymaga naprawy.","Jednostka",["WIRTUOZ BRONI"],["Bilgewater","Piltover i Zaun"],"ZWYKŁE"],"06BW034":["Metale Ciężkie","Zniszcz Wyposażenie jednostki i zadaj jej 2 pkt. obrażeń.","","„KTO RZUCA KOTWICĄ W KARCZEMNEJ ROZRÓBIE?! CO JEST Z WAMI NIE TAK, CO?!!” – Barman z Bilgewater","Zaklęcie",[],["Bilgewater"],"RZADKIE"],"06BW027":["Części Złączone w Całość","Aby zagrać, odrzuć 1 kartę. Dobierz 2 karty. Jeżeli odrzucona karta to Wyposażenie, przywołaj kartę Icathiańska Miraż.","","Załoga Jaxa jest dowodem na to, że całość może być większa niż suma jej części. Pesh upiera się jednak przy innym rozumowaniu: czasami części są wielkie same w sobie.","Zaklęcie",["WIRTUOZ BRONI"],["Bilgewater","Piltover i Zaun"],"RZADKIE"],"06BW039":["Niekończąca Się Fala","Kiedy udało ci się wręczyć Wyposażenie sojusznikowi w tej grze, kosztuję o 2 mniej.\nDobierz 2 karty i przyznaj im Ulotność.","","Choć stare kości Ibaarosa poruszały się powoli, to wody gnające przed nim przemieszczały się z wręcz niepojętą prędkością.","Zaklęcie",["KULTYSTA"],["Bilgewater"],"RZADKIE"],"06BW026":["Kultystka Buhru","Gdy sojusznicy posiadający Wyposażenie atakują, zadaj 1 pkt. obrażeń wrogiemu Nexusowi.","","Nieważne było, skąd pochodziła moc – jej bogini o to nie dbała. Liczyła się jedynie chwała, jaką zdobędzie dzięki zgładzonym potworom.","Jednostka",["KULTYSTA"],["Bilgewater"],"ZWYKŁE"],"06BW014":["Harpun Darkinów","Atak: Dobierz 1 kartę na Początku kolejnej rundy i przyznaj jej Ulotność.\nMożesz wydać 9 pkt. many, aby zagrać mnie jako kartę Ibaaros.","","„Od przesmyku Daray płyń z daleka,\nWoda szepcze tam, a deska pęka,\nPtak ni bestia nie zapuści się tam z prędka.\nOd mroku spod przesmyku Daray trzymaj się z daleka”.\n– Rymowanka z Bilgewater","Wyposażenie",["DARKIN"],["Bilgewater"],"EPICKIE"],"06BW004":["Próba Ducha","Nałóż na wroga Podatność w tej rundzie. Jeśli zginie w tej rundzie, zadaj 1 pkt. obrażeń wrogiemu Nexusowi.","","„Staniesz twardo czy skulisz się ze strachu?” – Illaoi","Zaklęcie",[],["Bilgewater"],"RZADKIE"],"06BW044":["Szczwany Traszkopław","Uderzenie w Nexus: Dobierz 1 kartę i przyznaj jej Ulotność.","","„Wstrętne, małe złodziejaszki, takie to są stwory. Przynajmniej łatwo je zauważyć, jak coś zwędzą”.","Jednostka",["GAD"],["Bilgewater"],"ZWYKŁE"],"06BW047":["Psotna Marajka","Gdy zagrasz zaklęcie, przywołaj kartę Beczka Prochu.","","„Bibi jest nieco… szalona. Ale to w niej kochamy!” \n– Ai’la, Strażniczka Marajów","Jednostka",[],["Bilgewater"],"RZADKIE"],"06BW023":["Wyszczerbiony Kordelas","Grabież: Kosztuję o 2 mniej.","","– Jak mówi powiedzenie, nic nie kończy mordobicia w Bilgewater szybciej niż kordelas.\n– No chyba, że spluwa.\n– Zamknij się, Baz.\n– Baz i Gav, aspirujący łowcy nagród","Wyposażenie",[],["Bilgewater"],"ZWYKŁE"],"06BW042":["Załadowana Łajba","Zadaj 2 pkt. obrażeń jednostce. Dobierz 1 kartę na Początku następnej rundy za każdy zadany punkt obrażeń i przyznaj dobranym kartom Ulotność.","","„Rex się zajmie wysadzaniem, nic nie bój, a ja się zajmę skarbami. Rexa część też przygarnę, bo inaczej to też będzie próbował wsadzić do armaty, a z tego zawsze syf się robi”.\n– Bosman","Zaklęcie",[],["Bilgewater"],"EPICKIE"],"06BW040":["Oko Bogini","Atak: Powołaj do Życia 2.","","„Stań w sile, gdy spocznie na tobie Jej wzrok!” – Illaoi","Wyposażenie",[],["Bilgewater"],"RZADKIE"],"06SH032":["Pogrzebana Zbrojownia","Odlicz 2: Stwórz w ręce kartę Skarby Piasków.","","– Dlaczego ty musisz wszystkiego dotykać?\n– A co, myślisz, że to pułapka? Myślisz, że jakiś wielki głaz się skądś nagle wytoczy i…\n– WIEEEEJ!\n– Argus i Silvio, hieny grobowe","Lokacja",[],["Shurima"],"ZWYKŁE"],"06SH035":["Ołtarz Krwi","Gdy Zgładzisz jednostkę, zmniejsz koszt następnej zagrywanej przez ciebie jednostki Darkinów o 1.","","Ołtarz ponownie zatętnił życiem, wzruszając okoliczne piaski w powolnym, równomiernym rytmie. Wszyscy wyznawcy Xolaani poczuli w głębi serca to samo drżenie, każdym mięśniem, każdą myślą i w każdym momencie… gotowi, by służyć.","Lokacja",[],["Shurima"],"RZADKIE"],"06SH046":["Relikwiarz Akolity","Gdy mnie przywołasz, stwórz w ręce kartę Niszczycielski Akolita. Gdy mnie zniszczysz, stwórz kartę Relikwiarz Akolity wśród pierwszych 5 kart z wierzchu swojej talii.","","„Nasze dłonie kształtują pustynię!” – Niszczycielski Akolita","Lokacja",[],["Shurima"],"RZADKIE"],"06SH033":["Klątwa Grobowca","Spójrz w Przyszłość. Daj jednostce „Otrzymuję podwójne obrażenia, a kiedy mam zginąć, Unicestwij mnie” w tej rundzie.","","„Tylko głupcy poszukują potęgi, której nie potrafią kontrolować”. – Xerath","Zaklęcie",[],["Shurima"],"RZADKIE"],"06SH028":["Brama Pustki","Gdy przywołasz sojusznika lub sojusznik zginie, przyznaj każde z jego pozytywnych słów kluczy 3 sojusznikom w swojej talii.","","Herold Roju uniósł dwie ręce w kierunku wznoszącej się ponad nim ogromnej budowli. – TRON DLA WŁADCZYNI – krzyczał. Brama Pustki ponad nim tętniła życiem. Już niedługo.","Lokacja",[],["Shurima"],"EPICKIE"],"06SH005":["Zapomniany Baccai","Zagraj: Spójrz w Przyszłość. Jeśli wybierzesz Darkina lub Wyposażenie, przyznaj mi +1|+1.","","W ręce trzymał pleciony pas – podarunek od przyjaciela, Rhaasta, wręczony mu jeszcze przed ceremonią ich Wyniesienia. Choć wielbił moc Darkina, to jednak w głębi swojego bestialskiego serca skrywał odrazę.","Jednostka",["KULTYSTA"],["Shurima"],"ZWYKŁE"],"06SH056":["Chłosta","Zabij WSZYSTKICH stronników.","","Czasami przyciąga cię światło. Innym razem to ty je przyciągasz.","Zaklęcie",[],["Shurima"],"RZADKIE"],"06SH040":["Niedbałe Zmartwychwstanie","Kiedy udało ci się wręczyć Wyposażenie sojusznikowi w tej grze, kosztuję o 2 mniej. Wskrześ Najsilniejszego martwego sojuszniczego bohatera.","","„Nigdy nie umrzesz, bo nigdy ci na to nie pozwolę”.\n– Xolaani","Zaklęcie",["KULTYSTA"],["Shurima"],"EPICKIE"],"06SH021":["Zakamuflowana Potworność","Zagraj: Uderzam wroga.","","Atak nie ustał, a z otwierających się bram wylewały się hordy coraz większych i dzikszych stworzeń. Jednak los zaiste potrafił być okrutny. Choć miasto Belveth zostało spisane na straty, jego imię miało przetrwać.","Jednostka",[],["Shurima"],"RZADKIE"],"06SH051":["Pasterz Niedźwiedzi Skalnych","Gdy przywołasz innego sojusznika, poślij Naprzód lokację o najwyższej liczbie rund do Odliczenia o 1 rundę.\nGdy mnie przywołasz, przywołaj kartę Hibernujący Niedźwiedź Skalny.","","„Skalniaczki traktują Sadirę jak swoją. Ta mała łobuziara od razu by z nimi uciekła, gdybym tylko na to pozwoliła!”\n– Kadira, Pustynna Przyrodniczka","Jednostka",[],["Shurima"],"RZADKIE"],"06SH055":["Kapłanka Pustynnego Światła","Początek rundy: Zadaj mi 4 pkt. obrażeń. Dobierz bohatera i przyznaj mu +2|+2. Jeśli twoja talia zawierała na początku gry 6+ różnych bohaterów, zamiast tego przywołaj go.","","Wierni nie dają się złamać, gdy nadciąga zło. Oferują ostatki swych sił, by nadać mocy światłu sprawiedliwości. Zanim mrok ich pochłonie, otrzymają odpowiedź na desperackie wołanie o ratunek.","Jednostka",[],["Shurima"],"EPICKIE"],"06SH004":["Darkińskie Upuszczacze Krwi","Ostatnie Tchnienie: Jeśli trzymająca mnie karta nie jest kartą Niewolnik Darkinów, przywołaj kartę Niewolnik Darkinów.\nMożesz wydać 6 pkt. many i zabić sojusznika, aby zagrać mnie jako kartę Xolaani.","","Podczas gorzejącej walki Jun, zdesperowana i ciężko ranna, zwróciła się do głosu szepczącego w jej myślach.\n– Nigdy nie umrzesz – rozbrzmiewał, delikatny niczym letni deszcz – bo nigdy na to nie pozwolę.","Wyposażenie",["DARKIN"],["Shurima"],"EPICKIE"],"06SH038":["Kołysząca Się Glewia","Uderzenie: Stwórz w ręce kartę Szczęśliwe Znalezisko.","","„Bierz, co chcesz. Nie oglądaj się na innych”. – Zdobywczyni Ruin\n","Wyposażenie",[],["Shurima"],"ZWYKŁE"],"06DE048":["Obronny Borsumiś","","","„Jeśliś przyjaciel, krocz śmiało, lecz biada ci, jeśli przybywasz z zawiścią w sercu, bowiem posmakujesz zemsty potężnego obrońcy!”","Jednostka",["ELITARNY"],["Demacia"],"ZWYKŁE"],"06DE024":["Orientuj Się!","Daj sojusznikowi +1|+1 w tej rundzie lub wręcz mu z ręki Wyposażenie o koszcie 2 lub mniejszym.","","Boli jeszcze bardziej, jeśli drużyna jeszcze nie jadła.","Zaklęcie",["WIRTUOZ BRONI"],["Demacia","Freljord"],"RZADKIE"],"06DE025":["Rekrut o Gołębim Sercu","Gdy mnie przywołasz, daj sojusznikom z Wyposażeniem Barierę w tej rundzie.","","„Ten chłopak to kula u nogi. Stanowczo twierdziłem, że nie powinniśmy go zabierać na polowanie, bo ciągle nazywa to plugawe stworzenie swoją »siostrą«. To naiwność w postaci tak czystej, że aż oburzającej. Chociaż, tak właściwie, to jest mi go też szkoda. Przynajmniej będzie to dla niego ważna lekcja”. – Wpis z osobistego dziennika Siriusa Rowilla, Gorliwego Zwiadowcy Rycerstwa","Jednostka",[],["Demacia"],"RZADKIE"],"06DE033":["Uciszyć i Zdusić","Zniszcz Wyposażenie jednostki, a jeżeli jest to stronnik, Ucisz go.","","„Sam to na siebie sprowadziłeś”. – Lord Eldred, Przywódca Łowców Magów","Zaklęcie",[],["Demacia"],"RZADKIE"],"06DE039":["Ryk Icathii","Przywołaj 2 karty Icathiańskie Miraże Wyposażone w maksymalnie 2 elementy Wyposażenia z ręki o koszcie 2 lub mniejszym.","","Jax walczył u boku swoich utraconych braci w niezliczonych snach. Niektóre walki wygrywają, inne przegrywają, ale zawsze trzymają się razem.","Zaklęcie",["WIRTUOZ BRONI"],["Demacia"],"RZADKIE"],"06DE011":["Egida Darkinów","Możesz wydać 5 pkt. many, by zagrać mnie jako kartę Joraal.","","– Posłuchaj, mój synu. Tej tarczy pod żadnym pozorem nie wolno dotknąć. Dawno temu została podarowana naszej rodzinie pod warunkiem, że dopilnujemy jej bezpieczeństwa i zostawimy ją w spokoju. To moja odpowiedzialność, a kiedy ja odejdę, przejdzie ona na ciebie. Słyszysz, co mówię? Nigdy więcej nie próbuj się po nią wspinać. Pod żadnym pozorem nie wolno ci jej dotknąć.\n– Ale mamo, ten głos ze środka… płacze do mnie. Brzmi tak smutno.\n– …tym bardziej, mój synu.\n– Lady Fortis i jej syn","Wyposażenie",["DARKIN"],["Demacia"],"EPICKIE"],"06DE021":["Vayne","Gdy mnie przywołasz lub na Początku rundy: Stwórz w ręce kartę Akrobacja lub – jeśli już taką masz – zmniejsz jej koszt o 1.","Widziałam, jak atakujesz 4 razy.","„Nasz cel był kiedyś człowiekiem, co oznacza, że jest sprytniejszy niż przeciętna bestia. Jeden zły ruch może skończyć się dla nas śmiercią. Trzymajmy się nawzajem w zasięgu wzroku, sygnalizujmy wszystko, co podejrzane, a przede wszystkim pamiętajmy…”","Jednostka",[],["Demacia"],"Bohater"],"06DE043":["Wierny Psaran","Gdy po raz pierwszy przywołasz Elitarnego, przyznaj mi +2|+2.","","„Nie jest tak szybka jak srebrnoskrzydły, ale jej małe łapki potrafią ją ponieść zaskakująco prędko”.\n– Cithria Pani Chmur","Jednostka",["PIES"],["Demacia"],"ZWYKŁE"],"06DE018":["Potępienie","Jeśli udało ci się zaatakować 2+ razy w tej rundzie, kosztuję o 5 mniej.\nSojusznik Uderza wroga.","","„Oczyszczające bełty”. – Vayne","Zaklęcie",[],["Demacia"],"ZWYKŁE"],"06DE041":["Siła Bohaterów","Daj sojusznikom +4|+4 w tej rundzie i Zjednocz Siły.","","„Ruszajmy do walki ze światłem w sercu!” – Lux","Zaklęcie",[],["Demacia"],"EPICKIE"],"06DE026":["Icathiańskie Mity","Stwórz w ręce kartę Icathiańska Miraż, która kosztuje 0 w tej rundzie, lub stwórz w ręce kartę Złota Szpatułka.","","Legendy głoszą, że pierwszą postacią dzierżącą złotą szpatułkę było morskie stworzenie o wybitnych zdolnościach kulinarnych – stworzenie, które pragnęło stać się wojownikiem tak silnym i nieustraszonym, jak Jax.\n\nInne, bardziej wiarygodne legendy mówią, że ta konkretna opowieść została w całości sfabrykowana przez pewnego kucharza, który bardzo, ale to BARDZO popłynął z sosem.","Zaklęcie",[],["Demacia"],"RZADKIE"],"06DE044":["Petrucytowy Taran","Nie otrzymuję obrażeń od wrogich zaklęć ani Umiejętności.","","„Nie ma nic silniejszego niż petrucyt”. – Architekt Durandów","Jednostka",[],["Demacia"],"RZADKIE"],"06DE017":["Bitwa na Ryby","Sojusznik i wróg Uderzają siebie nawzajem lub sojusznik z Wyposażeniem Uderza wroga, a następnie traci Wyposażenie.","","„Rybko, oto gęba!” – Ioniańska Mistrzyni Wędkarstwa","Zaklęcie",["WIRTUOZ BRONI"],["Demacia"],"ZWYKŁE"],"06DE040":["Kusząca Perspektywa","Wybierz stronnika lub Wyposażenie spośród 4 kart z wierzchu swojej talii. Dobierz wybraną kartę, pozostałe karty umieść z powrotem w swojej talii.","","Delikatne, pociągające szepty sieją w głębi serca pragnienie, które tkwi w nim niczym drzazga, zaognia się i rozrasta do głodu. Głód ustępuje występkom, a te z kolei przynoszą śmierć. Cykl trwa dalej.","Zaklęcie",["KULTYSTA"],["Demacia"],"ZWYKŁE"],"06DE028":["Harpia Przeklętej Krwi","Zagraj: Wręcz mi Wyposażenie o koszcie 2 lub mniejszym z ręki.\nJeśli mam zginąć po raz pierwszy, posiadając Wyposażenie, w pełni mnie ulecz i w zamian zniszcz moje Wyposażenie.","","„Kianie, jeśli to czytasz… to mam nadzieję, że już nie żyję. Nie kontroluję tego, co się ze mną dzieje. Nie mogę zmyć krwi spod paznokci. Wszystko mnie swędzi. Drapię i drapię, ale nic nie pomaga. Boli. Chcę, żeby to się wreszcie skończyło. Jeśli jakimś cudem jeszcze oddycham, obiecaj mi, że przestaniesz próbować mnie odnaleźć.\n\nProsiłabym o wybaczenie, ale nie zasługuję na nie. Opiekuj się matką, dobrze?\n– Pognieciony list znaleziony w podartej sakwie","Jednostka",[],["Demacia"],"EPICKIE"],"06DE027":["Gorliwy Zwiadowca Rycerstwa","Atak: Daj sojusznikom z Wyposażeniem +1|+1 w tej rundzie.","","– Na imię ci Janan, tak? Co możesz mi powiedzieć o Siriusie?\n– Och, o zwiadowcy rycerstwa Rowillu? Kilka lat temu odebrano mu tytuł. Podobno z pełną świadomością lekceważył każdy wydany rozkaz. Zdaje się, że robi to, co mu się żywnie podoba i nie rozumie słowa „nie”.\n– Ach.\n– Więc… dlaczego w ogóle pozwoliłaś mu dołączyć do tego polowania?\n– Nie pozwoliłam.\n– To czemu… a, no tak. Świetnie.\n– Vayne i Janan, Owdowiała Łowczyni","Jednostka",[],["Demacia"],"RZADKIE"],"06DE019":["Owdowiała Łowczyni","Zagraj: Wręcz mi Wyposażenie o koszcie 2 lub mniejszym z ręki.","","„Ta kobieta zdaje się być dość kompetentną wojowniczką, ale jej żal jest świeży i w każdej chwili może ją przytłoczyć. Owszem, rozpacz jest przekonującą motywacją, wiem to po sobie, ale tak nieokiełznana? Być może ona pragnie śmierci…” – Wpis z osobistego dziennika Siriusa Rowilla, Gorliwego Zwiadowcy Rycerstwa","Jednostka",[],["Demacia"],"ZWYKŁE"],"06DE032":["Demaciańska Stal","","","Miecz i tarcza standardowo wykorzystywane przez skrywających się pod hełmami bitewnych kompanów z Demacii.","Wyposażenie",[],["Demacia"],"ZWYKŁE"],"06DE029":["Niezłomny Jeleniowaty","Gdy po raz pierwszy sojusznik otrzyma Wyposażenie, przyznaj mi Wytrzymałość.","","„Cofnij się, plugawa kreaturo! Niech choćby włos ubędzie z nieskazitelnego futra Czystości, a dopilnuję, żebyś cierpiała w WIECZNEJ AGONII!” – Sirius Rowill, Gorliwy Zwiadowca Rycerstwa","Jednostka",[],["Demacia"],"ZWYKŁE"],"06DE010":["Zbiegła Zwiadowczyni Rycerstwa","Jeżeli udało ci się wręczyć sojusznikowi Wyposażenie w tej grze, przyznaj mi Zwiad.","","Lata duszenia w sobie magicznych umiejętności wywołały w niej niepojętą nienawiść do samej siebie, którą w szale przelewała na swoje ofiary. Po ucieczce od zwiadowców rycerstwa jej gniew nie był ukierunkowany, dopóki nie przemówił do niej głos z mroku. Szeptał o nowym porządku, w którym nieskrępowana mogłaby praktykować swoje okrucieństwo.","Jednostka",["KULTYSTA"],["Demacia"],"RZADKIE"],"06DE006":["Kucharz Bitewny","Gdy mnie przywołasz, Improwizuję. Następnie Wykuj mnie.","","Po czasie spędzonym w demaciańskim wojsku Breshi sądził, że przejdzie w stan spoczynku i będzie gotował w oberży w jakiejś spokojnej osadzie. Jax zniszczył mu te plany emerytalne bijatyką w oberży i wyjątkowo niepochlebną opinią na temat jaj na twardo. Od tamtej pory Breshi wyznaczył sobie nowy cel w życiu: nauczenie Jaxa odrobiny smaku.","Jednostka",["WIRTUOZ BRONI"],["Demacia","Freljord"],"ZWYKŁE"],"06DE034":["Wierny Wilczak","Jeśli sojusznik zginął w tej rundzie, kosztuję o 2 mniej.\nZagraj: Wręcz mi Wyposażenie o koszcie 2 lub mniejszym z ręki i Wykuj mnie.","","„Mam Maggie, odkąd była szczeniakiem. Może i ma już swoje lata, ale jej kły dalej są ostre jak świeżo naostrzony miecz. Oddałabym za nią życie i wiem, że ona oddałaby swoje za mnie”. – Janan, Owdowiała Łowczyni","Jednostka",["PIES"],["Demacia"],"ZWYKŁE"],"06SI045":["Rozpłatanie Duszy","Zabij sojusznika, aby przywołać jego 2 Efemeryczne kopie.","","I tak z tego nie korzystali.","Zaklęcie",[],["Wyspy Cienia"],"RZADKIE"],"06SI007":["Halabarda Darkinów","Aby mnie zagrać, zabij sojusznika.\nMożesz wydać 10 pkt. many, aby zagrać mnie jako kartę Taarosh.","","Taarosh usłyszał wezwanie swojego generała podczas swoich zmagań z poskramiającą go celą. Musiał na nie odpowiedzieć – nieważne, w jaki sposób.","Wyposażenie",["DARKIN"],["Wyspy Cienia"],"EPICKIE"],"06SI034":["Upiór Echa","Koniec rundy: Za każdego sojusznika, który zginął w tej rundzie, przyznaj wszystkim sojuszniczym kopiom tego sojusznika +1|+1, gdziekolwiek są.","","„Nie mam pojęcia, jakiej przerażającej magii używają. NIE CHCĘ wiedzieć. Wystarczy mi świadomość, że jeśli powstaną, obrócimy ich w pył. Ponownie”. – Obserwator Wysp","Jednostka",[],["Wyspy Cienia"],"EPICKIE"],"06SI029":["Złowieszcza Włócznia","Jeśli sojusznik zginął w tej rundzie, kosztuję o 2 mniej.","","„Nie ma sprawiedliwości… jest tylko zemsta”. – Kalista","Wyposażenie",[],["Wyspy Cienia"],"ZWYKŁE"],"06SI032":["Kres","Zabij jednostkę, której łączna wartość Siły i Zdrowia wynosi 4 lub mniej, lub zniszcz Wyposażenie jednostki.","","Jakkolwiek śmierć objawi się na Wyspach Cienia, niechaj będzie zbawiennie szybka.","Zaklęcie",[],["Wyspy Cienia"],"RZADKIE"],"06SI031":["Ostrza Poległych","Daj sojusznikowi „Ostatnie Tchnienie: Przywołaj kartę Icathiańska Miraż z moim Wyposażeniem” w tej rundzie.","","Czasami najlepszą rzeczą, jaką możesz zrobić dla poległego sojusznika, jest chwycenie za jego broń i ruszenie w dalszy bój.","Zaklęcie",["WIRTUOZ BRONI"],["Wyspy Cienia","Shurima"],"RZADKIE"],"06SI014":["Wystawna Sala","Gdy mnie przywołasz, przywołaj kartę Odrażający Zespół.\nPoczątek rundy: Jeżeli posiadasz Token ataku, przywołaj kartę Odrażający Zespół.","","„Gracze są gotowi, scena jest ustawiona, a publika czeka. Maestro, zaczynaj!” – Głośny Gospodarz","Lokacja",[],["Wyspy Cienia"],"EPICKIE"],"06SI038":["Odkupiony Geniusz","Atak: Przywołaj atakującą kartę Odrażający Zespół.","","Gonienie za perfekcją było ograniczające, sztywne. Perfekcja nie miała w sobie życia; nie oddychała. Natomiast perfekcyjna niedoskonałość – tak, to już jest coś, za czym można gonić.","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"06SI003":["Fireth Żniwiarka Piasków","Gdy mnie przywołasz, Improwizuję.","","W pierwszych tygodniach wspólnej podróży Jax pytał Fireth o imię ze dwadzieścia razy, ale ona za każdym razem odwarkiwała tylko: „Jestem Żniwiarką!”. Breshi znalazł jednak błyskotliwe rozwiązania – otóż najzwyczajniej w świecie upiekł ciasto i potrzebował imienia najsilniejszego członka grupy, aby odpowiednio je zadedykować.","Jednostka",["WIRTUOZ BRONI"],["Wyspy Cienia","Shurima"],"EPICKIE"],"06SI006":["Strażniczka Pudła","Jeżeli udało ci się wręczyć Wyposażenie sojusznikowi w tej grze, przyznaj mi Kradzież Życia.","","„Pudło nie rozdaje swoich sekretów za darmo, Shiedo Kaynie. Trzeba zapłacić za nie ponurą cenę. Jeśli masz jednak odwagę spojrzeć w cień cieni, przekonasz się, że kryją się w nim cudowne, przerażające rzeczy”. – Ysdra Strażniczka Pudła","Jednostka",["KULTYSTA"],["Wyspy Cienia"],"ZWYKŁE"],"06SI039":["Kształt Strachu","Zabij sojusznika, aby przywołać kartę Wdzierająca Się Mgła.","","Tylko głupiec wpatrywałby się w Czarną Mgłę z nadzieją, że rozpozna w niej znajomy kształt.","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"06SI042":["Nieznający Śmierci Rycerz","Jeśli miałaby zostać nałożona na mnie Efemeryczność, zamiast tego przyznaj mi +1|+1.","","Żołnierze, których za życia szkolono do znoszenia kar, są o wiele bardziej sumienni i uzdolnieni po śmierci. Nie wzrusza ich chłód, ból ani strach.","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"06SI036":["Niewypowiedziane Zniszczenie","Zabij WSZYSTKIE jednostki z wyjątkiem sojuszniczych Darkinów i Wyposażonych sojuszników.","","Gdy chwyciła za bronie, uszła z niej cała ludzkość. W jej miejsce wślizgnęła się pełna nienawiści esencja, szybko wypełniając świeżo opustoszałą powłokę, która jeszcze przed chwilą była uczennicą Jun. Esencja zalała ją od wewnątrz, od zewnątrz, okalała ją i cały świat, wybudzając Darkina z jego snu.","Zaklęcie",["KULTYSTA"],["Wyspy Cienia"],"RZADKIE"],"06SI046":["Niezłomny Wartownik","Ostatnie Tchnienie: Dobierz 1 kartę.",""," „Będę stać na straży aż po wieki, gdyż mój obowiązek jest ponad życiem i śmiercią”.","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"06SI041":["Opiekun Doliny w Świetle Księżyca","Gdy przywołasz Efemerycznego sojusznika, przyznaj mu +1|+0.\nZmrok: Przywołaj kartę Sadzonka.","","Z dala od wybrzeży Wysp Cienia znajdują się powykręcane pnie drzew dawno uznanych za martwe. Postronnym obserwatorom wydają się nieruchome, ale czujne oko zauważy, że w skąpanej w księżycu glebie rodzi się nowe życie.","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"07PZ009":["Ulepszony Tykający Golem","Zagraj: Spójrz w Przyszłość, a następnie dobierz 1 kartę i zmniejsz jej koszt o 1.","","„Maluch potrzebował tylko drobnego podkręcenia. Tu para nowych zębatek, tam nowe ramię i może na nowo cieszyć się życiem. Zawsze powtarzam, że czas to dar, którego każdy powinien dostawać trochę więcej”. – Ekko","Jednostka",[],["Piltover i Zaun"],"EPICKIE"],"07PZ017":["Handlarz Bomb Błyskowych","Kiedy zagrasz zaklęcie, umieść 1 kartę Pułapka z Bombą Błyskową wśród pierwszych 8 kart z wierzchu talii przeciwnika.","","„…a wiesz, dlaczego te maleństwa są lepsze od grzybów? Bo to ty decydujesz, kiedy wybuchną! TO dopiero wartość dodana, prawda?”","Jednostka",[],["Piltover i Zaun"],"RZADKIE"],"07PZ005":["Odrzut","Zadaj 1 pkt. obrażeń wrogowi i wrogiemu Nexusowi. Odrzuć do 2 kart, aby zwiększyć obrażenia o 1 pkt. za każdą odrzuconą kartę.",""," „No dobra, dobra, może i zadziała tylko raz, ale uwierz mi, będzie bombowo!” – Jinx","Zaklęcie",[],["Piltover i Zaun"],"RZADKIE"],"07NX009":["Stylowy Strzał","Zadaj 1 pkt. obrażeń wrogiemu Nexusowi. Następnym razem, gdy sojusznik Uderzy Nexus w tej rundzie, stwórz w ręce kartę Stylowy Strzał.","","„Nikt nie dotrzyma mi kroku, nawet gdybym nie miała nic poza kijami i kamieniami. A z tym, co mam w zanadrzu? Nawet nie próbuj”. – Samira","Zaklęcie",[],["Noxus"],"EPICKIE"],"07NX008":["Eleganckie Ostrze","Grabież: Przyznaj mi +2|+0.","","„Słono sobie liczę i nie pracuję dla byle kogo. Jeśli masz wystarczająco szczęścia, żeby mnie zatrudnić, możesz liczyć na grację, elegancję i ostrza, które nigdy nie pudłują. Ale przede wszystkim – na styl. Bo przecież kto nie lubi zabijać z odrobiną szyku?”","Jednostka",[],["Noxus"],"ZWYKŁE"],"07NX014":["Piruet","Grabież: Kosztuję o 2 mniej.\nZadaj 1 pkt. obrażeń dowolnemu celowi i Ogłusz wroga.","","„Co? Ja się tylko przeciągam. Nie mów mi, że nie żyjesz od mojego przeciągania się”. – Eleganckie Ostrze","Zaklęcie",[],["Noxus"],"RZADKIE"],"07NX007":["Samira","Grabież lub Uderzenie: Stwórz w ręce kartę Smykałka, jeśli jeszcze jej nie posiadasz.","Widziałam, jak zagrywasz 6 kart. Licznik resetuje się, gdy zaczynasz rundę z Tokenem ataku.","„Zawsze ścigam jakiś cel, który narobił sobie długów bez szansy na spłatę. A uciekaniem od tych długów robisz sobie najgorszych wrogów – takich, którzy wzywają mnie”.","Jednostka",[],["Noxus"],"Bohater"],"07NX006":["Szykowny Elegancik","Grabież: Podwój moją Siłę.",""," „Słuchaj no, normalnie lubię ustalać jakieś zasady, powiedzmy, na ten przykład, »łapy precz od twarzy i włosów«, ale kogo ja oszukuję? Nawet mnie nie tkniesz”.","Jednostka",[],["Noxus"],"ZWYKŁE"],"07NX015":["Dama Profanatorka","Grabież: Przyznaj sojusznikom +1|+0.","","„Ach, Dama. Ona ma upodobanie do dramatyzmu, tak. Niektórzy mogą kręcić nosem na odrobinę przepychu, ale kiedy ona jest w swoim żywiole, to wszyscy na pewno dostaną swoją zapłatę”. – Eleganckie Ostrze","Jednostka",[],["Noxus"],"ZWYKŁE"],"07NX003":["Na Całego","Daj sojusznikowi +2|+0 w tej rundzie.\nGrabież: Zamiast tego daj sojusznikowi +2|+1.",""," „Indari pociągnęła za parę sznurków, żeby nas tu wcisnąć bez zbędnego szumu. Ja mam nadzieję, że będę miała czas, żeby go narobić przy wyjściu”. – Samira","Zaklęcie",[],["Noxus"],"ZWYKŁE"],"07NX004":["Wszechstronna Rzemieślniczka","Gdy mnie przywołasz, aktywuj wszystkie sojusznicze efekty Grabieży.","","„W niektórych miejscach niełatwo jest otworzyć sklep, ale wystarczyło, że tylko spojrzeli na towary moje i Lani, a pieniądze same się nam pchały do kieszeni. Nie widziałam naszego celu wśród przeglądających, ale była cała masa innych, którym tej nocy marzyła się przemoc. A przecież wyłapanie, kto chce zabić kogo, to całkiem niezły sposób na wybadanie terenu”. – Miel","Jednostka",[],["Noxus"],"RZADKIE"],"07NX001":["Brawurowa Niszczycielka","Zagraj: Zadaj 1 pkt. obrażeń wrogiemu Nexusowi lub aktywuj efekt Grabieży sojusznika.","","„Siedzenie w biznesie zbrojeniowym oznacza bycie w zdrowej relacji z danymi. Koncept, testy, przebudowa, modyfikacje: wszystko to wymaga informacji. Nie ma nic lepszego niż drobne testy terenowe, żeby stworzyć zdrowych rozmiarów próbę, no i parę kraterów!” – Lani","Jednostka",[],["Noxus"],"RZADKIE"],"07NX005":["Kapitan Indari","Gdy mnie przywołasz, Improwizuję.\nGrabież: Wykuj innych sojuszników.","","„Pracowałam już z wieloma agentami. Z niektórymi było łatwo, inni byli wyzwaniem… ale Samira to co innego. Pogodziłam się z faktem, że nad nią nie zapanuję. Mogę tylko ukierunkować ten chaos, wymierzyć go… i czasami dołączyć tu czy tam”.","Jednostka",["WIRTUOZ BRONI"],["Noxus"],"RZADKIE"],"07BW018":["Stara Szalona Babs","Gdy odzyskujesz manę, przyznaj mi +1|+0 za każdy odzyskany punkt many.","","„Jack, skarbie, patrzy tutaj! Ja znaleźć coś, co zainteresować, tak?”","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"07BW021":["Bezczelna Korsarka","Grabież: Przywołaj losowego stronnika o koszcie 1 i przyznaj mu Zuchwałość.","","„Na twoim miejscu trzymałabym się od niej z daleka. Ma wyjątkowo paskudny nawyk zrzucania swoich problemów na innych”. – Samira","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"07BW002":["Jack","Uderzenie: Stwórz w ręce kartę Moneta.\nGdy odzyskujesz manę, ulecz mnie o 1 za każdy odzyskany punkt many.","Udało ci się wydać 12+ pkt. many w jednej rundzie.","„Trzeba być bardzo odważnym albo wybitnie durnym, żeby mierzyć się ze mną. Tak czy inaczej, rezultat jest jeden. Drobna rada: martw się o to, żeby przeżyć”.","Jednostka",[],["Bilgewater"],"Bohater"],"07BW040":["Nukkle","Gdy mnie przywołasz, stwórz Ulotną kartę Mako w ręce.","","„Małe draśnięcie tu, małe nacięcie tam, taka tam zabawa. Odrobina krwi w wodzie jeszcze nikomu krzywdy nie zrobiła. Znaczy, przynajmniej nie mi”. – Nukkle","Jednostka",[],["Bilgewater"],"RZADKIE"],"07BW001":["Perfidny Organizator","Gdy odzyskujesz manę, stwórz w ręce losowego Ulotnego stronnika o koszcie dokładnie równym twojej manie.","","„Chcesz, żeby polał się szkarłat – chcesz Jacka? Chcesz wiedzieć, gdzie, kiedy, co i za ile? Wtedy przychodzisz do mnie”.","Jednostka",[],["Bilgewater"],"RZADKIE"],"07BW003":["Kieszonkowiec","Ostatnie Tchnienie: Stwórz w ręce kartę Moneta.","","„Ej, wracaj no tu, ty kupo szlamu! To pieniądze na ziemniaczki!” – Anioł","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"07BW014":["Pablo Pięć Pięści","Gdy mnie przywołasz, stwórz Ulotną kartę Walka o Nagrodę w ręce.","","„Właśnie tak, Jackie, chłoptasiu! Dalej roztaczaj ten swój urok godny Bilgewater, a ja już przypilnuję, żebyś ty się do naparzanki nadawał. Ach, przypominają mi się moje dni chwały, kiedy to wołali na mnie »Pablo Jak z Obrazka«… Co tam marudzisz? Że wcale tak nie mówili? A pewnie, że mówili! O jedną piąchę w łeb za dużo dostałeś, w pamięci ci się musiało namieszać”. – Pablo Pięć Pięści","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"07BW013":["Anioł","Grabież: Stwórz w ręce 3 karty Monety.","","„Tylko na tyle cię stać? Urocze. Teraz moja kolej”.","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"07BW006":["Ryzykowny Interes","Zadaj 3 pkt. obrażeń jednostce. Jeśli uderzona jednostka zginie od tego ciosu, stwórz w ręce 2 karty Monety.","","„Nie robisz interesów – niczego nie zyskasz. A te szczęki są wręcz stworzone do interesów”. – Jack","Zaklęcie",[],["Bilgewater"],"EPICKIE"],"07BW026":["Kolczasty Łańcuch","Grabież: Kosztuję o 2 mniej.\nDobierz 2 karty na Początku kolejnej rundy i przyznaj im Ulotność.","","Jeśli słyszysz szczękanie, na ucieczkę jest już za późno.","Zaklęcie",[],["Bilgewater"],"RZADKIE"],"07BW027":["Ojciec Furia","Grabież: Odzyskaj 1 pkt. many zaklęć i stwórz w ręce losowe zaklęcie o koszcie 1 z twoich regionów.","","Pochodzenie Ojca Furii jest zaciemnione niczym burzowe chmury. Nawet ci, którzy pytali, nie dostali bezpośredniej odpowiedzi – a przynajmniej nie usłyszeli jej wśród łoskotu sianego przez niego zniszczenia.","Jednostka",[],["Bilgewater"],"RZADKIE"],"07BW008":["Walka o Nagrodę","Sojusznik i wróg Uderzają siebie nawzajem. Ich Zdrowie nie może spaść poniżej 1 pkt. w wyniku tego Uderzenia.","","Jednego dnia wymieniasz olej do lamp na monety, drugiego – sierpowe na cudze zęby. Takie życie. Ale sprawiedliwa wymiana? To zawsze dobry interes!","Zaklęcie",[],["Bilgewater"],"ZWYKŁE"],"07BW041":["Pięściąkle","Uderzenie: Stwórz w ręce kartę Moneta.","","„Hmmm, no ja wiem, że to nie jest takie do końca typowe, tyle ci mogę przyznać. Ale daj im szansę, a rozstać się nie będziecie mogli”. – Byk","Wyposażenie",[],["Bilgewater"],"RZADKIE"],"07BW004":["Królewski Dwór","Gdy mnie przywołasz, dobierz kartę Jack.\nGdy przywołasz sojusznika, stwórz w ręce Ulotną kartę Walka o Nagrodę.\nGdy sojusznik przetrwa obrażenia, przyznaj mu Zuchwałość.","","Osobisty okręt Jacka poniósł go oraz jego towarzystwo przez wody Runeterry, z Bilgewater do Ionii. Nikt nie wie, jakim sposobem ten statek podróżuje pod wodą bez pójścia na dno, mówią jednak, że to poniżej jej powierzchni czają się prawdziwe niebezpieczeństwa…","Jednostka",[],["Bilgewater"],"EPICKIE"],"07BW025":["Inferna","Gdy aktywujesz Grabież, dobierz 1 kartę i przyznaj jej Ulotność.","","„Bycie piromanką na morzu ma swoje zalety. Dzięki wodzie ogień nigdy nie wymknie się spod kontroli, a do tego nigdy nie kłóci się o swoją działkę”.","Jednostka",[],["Bilgewater"],"RZADKIE"],"07IO020":["Odpadasz!","Wycofaj sojusznika i stwórz w ręce kartę Moneta lub wydaj 5 pkt. many, aby Wycofać wroga i stworzyć w ręce kartę Moneta.","","„Wchodzę w to tylko pod dwoma warunkami. Po pierwsze, twój przeciwnik aż za dobrze się bawi przy spuszczaniu ci łomotu. Po drugie, to ty bawisz się aż za dobrze, a ja chcę dołączyć do zabawy!” – Zawodowiec z Areny","Zaklęcie",[],["Ionia"],"RZADKIE"],"07IO014":["Mistrz Bingwen Odsiewacz","Zagraj: Kiedy podczas tej rundy zagrasz kolejną jednostkę, przywołaj jej dokładną Efemeryczną kopię.","","Bingwen Ptak był kiedyś wojownikiem, a swój przydomek zyskał za sprawą przypominającej żurawia postawy i zwinności. Odkąd przeszedł na emeryturę, przejął rolę trenera. Teraz swój bystry wzrok wykorzystuje do oddzielania prawdziwego talentu od plew.","Jednostka",[],["Ionia"],"EPICKIE"],"07IO023":["Stary Wyjadacz","Zagraj: Wycofaj Najsilniejszego wroga. Jeśli udało ci się wydać 16+ pkt. many w tej rundzie, zamiast tego Wycofaj wszystkich wrogów.","","„Maska zostaje tam, gdzie jest, dziewczyno. A jeśli nie chcesz wyglądać jak ta rzecz, to nie proś więcej”.","Jednostka",[],["Ionia"],"RZADKIE"],"07IO011":["Sett","Gdy moje Zdrowie po raz pierwszy ma spaść poniżej 1 podczas ataku, zamiast tego daj mi Barierę.","Udało ci się wydać 40+ pkt. many.","Pławiąc się w ryku tłumu przepełniającego ekskluzywną podziemną arenę Setta, pozwala on sobie na rzadki moment introspekcji. Pamięta, za co walczył, świadomy, co jeszcze może go spotkać. Jedną rzecz wie jednak na pewno: dobrze jest być Gangsterem.","Jednostka",[],["Ionia"],"Bohater"],"07IO046":["Królewski Połyskoskrzydły","Inne sojusznicze Ptaki mają +1|+0 i Szybki Atak.","","„W tych dżunglach nieustannie przekonuję się, że najpiękniejsze osobniki są najbardziej śmiercionośnymi drapieżnikami”. – Anura","Jednostka",["PTAK"],["Ionia"],"RZADKIE"],"07IO009":["Uważna Finansjerka","Uderzenie w Nexus: Stwórz w ręce kartę Moneta.","","Na tle wszystkich ambitnych łowców i egoistycznych knowaczy Lise ma jedną cechę charakteru, którą Sett ceni ponad wszystkie inne: jest niezawodna. Nigdy nie znika, nigdy niczego jej nie brakuje, nigdy nie dała Settowi najmniejszego powodu do zmartwień. Dzięki temu Lise może liczyć na jego wsparcie i wykorzystać je jako ostrzeżenie dla wszystkich, którzy szukają zwady. Stawiasz przeciwko nam – przegrywasz.","Jednostka",[],["Ionia"],"RZADKIE"],"07IO019":["Wygadany Miksolog","Zagraj: Ulecz sojusznika lub swój Nexus o 3 pkt. i stwórz w ręce kartę Moneta.","","„Pierwsza kolejka to tylko przywitanie, druga kolejka naprawdę rozluźnia. Problemy pojawiają się przy trzeciej, a od czwartej i dalej języki są już zupełnie rozwiązane. Pojęcia nie masz, czego można się tutaj dowiedzieć!”","Jednostka",[],["Ionia"],"ZWYKŁE"],"07IO017":["Obstawiajcie Zakłady","Dobierz 2 karty i stwórz w ręce 2 karty Monety.",""," „Oni dają nam prawdziwą kasę, a my dajemy im szansę. He, he… a niektórzy naprawdę zastanawiają się, jak to jest, że to my zawsze wygrywamy”.","Zaklęcie",[],["Ionia"],"ZWYKŁE"],"07IO047":["Zwodnicza Kobra","Gdy w danej rundzie po raz pierwszy zagrasz innego stronnika, przywołaj jego dokładną kopię. Jeśli twoja plansza jest pełna, zamiast tego przyznaj mi jego statystyki i słowa klucze.","","„Myślisz, że te kwiaty są coś warte? I nie bierz mnie za szaleńca, ale czy one nie wyglądają, jakby… tańczyły?”\n– Kłusownik z Piltover","Jednostka",["GAD"],["Ionia"],"EPICKIE"],"07IO013":["Zawodowiec z Areny","Gdy mnie przywołasz, stwórz w ręce kartę Moneta.","","„Niektórzy siedzą w tym dla pieniędzy, inni – dla rozlewu krwi, a jeszcze inni – dla ryków tłumu. Ja? Nigdy nie mogłem wybrać tylko jednego. Potrzeba mi tego wszystkiego, a tutaj mam tego na pęczki”.","Jednostka",[],["Ionia"],"ZWYKŁE"],"07IO012":["Ochrona Pojedynku","Gdy mnie przywołasz, stwórz w ręce Ulotną kartę Ochrona Pojedynku i przyznaj innej karcie Ochrona Pojedynku +1|+1.\nWzmocnienie 5: Szybki Atak.","","„Skoro myślą, że jesteś tępy, to proszę bardzo, niech tak myślą. Niech te przegniłe jabłka wierzą, że mogą pogrywać w te swoje gierki. Nie ma nic lepszego niż wyraz ich twarzy, kiedy w końcu dociera do nich, że cię nie doceniali”. – Sett","Jednostka",[],["Ionia"],"RZADKIE"],"07IO007":["Rozbijacz Twarzy","Ogłusz 2 wrogów i stwórz w ręce kartę Moneta.","","„Co? Powiedział, że pasuje jak pięść do nosa. Nie powiedział, czyjego!” – Sett","Zaklęcie",[],["Ionia"],"ZWYKŁE"],"07SH023":["Generał Upadłych Piasków","Mam +1|+0 za każdego Efemerycznego sojusznika, którego udało ci się przywołać w tej grze.","","„Choć dla tego przeciwnika możecie nie być niczym więcej, jak tylko ziarnami piasku, ja was widzę. Czuję waszą obecność w wydmach. Użyczcie mi swej siły, a wspólnie powalimy naszych wrogów!”","Jednostka",[],["Shurima"],"RZADKIE"],"07SH018":["Stróż Tajemnic","Gdy mnie przywołasz, stwórz na spodzie swojej talii dwóch losowych bohaterów 2. poziomu. Żaden z nich nie może znajdować się w twojej ręce, talii ani wśród zagrywanych przez ciebie kart.","","Nie wiedział do końca, co takiego ujrzał, jaką postać może przyjąć kataklizm ani kiedy ma on nastąpić… ale zna ten świat i jego mieszkańców. Nie są gotowi. Mogą nigdy nie być gotowi.","Jednostka",[],["Shurima"],"EPICKIE"],"07SH008":["Atak Stada","Rozpocznij Darmowy Atak dokładną Ulotną kopią każdego sojuszniczego Kota.","","Samotna łowczyni jest wystarczająco groźna – ale całe stado jest naprawdę niebezpieczne.","Zaklęcie",[],["Shurima"],"ZWYKŁE"],"07FR008":["Szronowłose Szczenię","Wydaj 6 pkt. many, aby zagrać mnie jako kartę Szronowłosa Matka.","","We Freljordzie czyha wiele niebezpieczeństw. Czają się szczególnie na tych, którzy jeszcze nie poznali jego zimnych prawd.","Jednostka",["PIES"],["Freljord"],"ZWYKŁE"],"07FR009":["Nowatorska Kowalka","Gdy mnie przywołasz, Improwizuję.\nGdy w danej rundzie po raz pierwszy Wykujesz lub dasz sojusznikowi Wyposażenie, ulecz swój Nexus o 1.","","„Ta puchata kulka może i nie pomaga mi pracować szybciej, ale z całą pewnością daje mi powód do uśmiechu. To wystarczająca pomoc”. – Nowatorska Kowalka","Jednostka",["WIRTUOZ BRONI"],["Freljord"],"RZADKIE"],"07FR005":["Niewolniczy Bastion","Nie otrzymuję obrażeń od sojuszniczych zaklęć ani Umiejętności.","","„Już rozpoczętej lawiny nie da się powstrzymać”. – Lissandra","Jednostka",[],["Freljord"],"RZADKIE"],"07SI002":["Żniwa Dusz","Zabij stronnika o Sile 3 lub mniejszej lub wydaj 3 pkt. many, aby zabić bohatera o Sile 3 lub mniejszej.","","To zaledwie szept na wietrze; nieznacznie słyszalna, lecz dogłębnie odczuwalna wymiana jednego życia na drugie.","Zaklęcie",[],["Wyspy Cienia"],"RZADKIE"],"07SI001":["Eradykacja","Zabij WSZYSTKIE jednostki o Sile 3 lub mniejszej.","","Ktokolwiek podniesie na mnie wzrok, zazna dotyku niebytu i nigdy już się od niego nie uwolni.","Zaklęcie",[],["Wyspy Cienia"],"EPICKIE"],"07SI007":["Grobowy Towarzysz","Gdy w danej rundzie po raz pierwszy zginie sojusznik, dobierz 1 kartę.","","„Właśnie nauczyłam go nowej sztuczki! Chcesz zobaczyć?”\n– Widmowa Figlarka","Jednostka",["PIES"],["Wyspy Cienia"],"ZWYKŁE"],"07MT003":["Dziecię Kosmosu","Początek rundy: Ulecz mnie i swój Nexus o 1 pkt.","","Niczym łza jutrzenki przemierza po niebiosach, a jego promieniste spojrzenie przynosi spokój, kojąc rany i naprawiając, co zniszczone.","Jednostka",[],["Targon"],"RZADKIE"],"07MT001":["Spadająca Gwiazda","Zadaj 4 pkt. obrażeń wrogowi, który zaatakował w tej rundzie lub jest Ogłuszony.","","Gwiazdy spoglądają z góry na nasze czyny, dobre i złe. Sprawiedliwi są wynoszeni, zaś niegodziwców poddaje się osądowi.","Zaklęcie",[],["Targon"],"ZWYKŁE"],"07MT007":["Ofiarny Uczony","Ostatnie Tchnienie: Stwórz w ręce kopie 3 pierwszych zaklęć, które udało ci się na mnie zagrać.","","„Camphor zabrała zbyt wiele od zbyt wielu. Gdy nadejdzie twoja pora, aby umrzeć, pamiętaj, żeby umrzeć na własnych warunkach. Nie dawaj jej satysfakcji”. – Pantheon","Jednostka",[],["Targon"],"EPICKIE"],"07BC005":["Rzeźbiony Ostrzowładny","","","„Tego jeszcze nie było”. – Fae Ostrzowładna","Jednostka",["WRÓŻKA"],["Bandle City"],"ZWYKŁE"],"07BC009":["Rzut Ciastem","Zadaj 1 pkt. obrażeń jednostce. Stwórz w ręce kartę Drapieżny Wypiek.","","Przygotujcie się.","Zaklęcie",[],["Bandle City"],"RZADKIE"],"07BC015":["Kondensacja","Wybierz stronnika. Stwórz w ręce jego kopię o koszcie 1 i ustaw jego statystyki na 1|1.","","„Hmm… Mniejsze chyba jednak nie zawsze oznacza słodsze!” – Lulu","Zaklęcie",[],["Bandle City"],"RZADKIE"],"07DE002":["Nakaz Przeszukania","Sojusznik o Sile 4+ Zniewala jednostkę lub sojusznik Zniewala lokację.","","„Nie ruszaj się i zachowaj ciszę. Jakikolwiek opór byłby niemądrym posunięciem”. – Inspektor Łowców Magów","Zaklęcie",[],["Demacia"],"RZADKIE"],"07DE005":["Formować Szyk!","Daj sojusznikowi +2|+2 w tej rundzie.","","„Nie ustępować! Możecie być ugięci, ale nie złamani!” \n– Nieustraszona Gwardia","Zaklęcie",[],["Demacia"],"ZWYKŁE"],"07DE008":["Ołtarz Jedności","Gdy mnie przywołasz, dobierz jednostkę.\nGdy przywołasz sojusznika, podnieś jego statystyki tak, aby były równe jego kosztowi.","","Gdy Cithria po raz pierwszy ujrzała Ołtarz, nie była w stanie wykrztusić z siebie słowa. Przez chwilę stała jedynie w miejscu, pełna zachwytu dla majestatu uhonorowanych tu bohaterów. Czy wystarczy jej śmiałości, aby pewnego dnia stanąć u ich boku?","Lokacja",[],["Demacia"],"RZADKIE"],"07PZ019":["Chemtechowa Karoca","Mam +1|+0 za każdego sojusznika o koszcie 1, którego udało ci się przywołać w tej grze.","","„Muszę narysować wiele nóg temu koniu, panie Jaszczur, bo trzeba nam szybko udać się do zamku. Wyszedł trochę… dziwnie. I jakoś zielono”. – Ingvar Młodsza","Jednostka",[],["Piltover i Zaun"],"RZADKIE"],"07PZ021":["Anura i Froop","Sojusznicy z innym podtypem niż pozostali sojusznicy w grze kosztują o 1 mniej.","","„Nie skrzywdzę cię! Jestem tu w imię nauki, nie zniszczenia”.","Jednostka",["GAD"],["Piltover i Zaun"],"EPICKIE"],"07PZ022":["Boski Powiew","Zadaj 1 pkt. obrażeń wrogowi lub wrogiemu Nexusowi i 1 pkt. kolejnemu celowi.","","Większość Piltoverczyków ma gdzieś schematy wiatru. Jednak Zaunici wyczuwają zbawienie nawet w bryzie.","Zaklęcie",["ŻYWIOŁ"],["Piltover i Zaun"],"ZWYKŁE"],"07PZ013":["Monument Slumsów","Jeśli twój Nexus otrzyma obrażenia inne niż od karty Trujący Grzyb, twój wróg umieszcza zamiast tego 5 kart Trujących Grzybów w twojej talii za każdy punkt obrażeń.","","Glęboko pod ulicami Zaun jesteś tym, co jesz.","Lokacja",[],["Piltover i Zaun"],"EPICKIE"],"07PZ015":["Epickie Ustrojstwo","Aby zagrać tę kartę, zużyj całą swoją manę. Przywołaj kartę Zbiegła Złomopułapka i zwiększ jej statystyki do tej wartości.","","„Największą odpowiedzialnością naukowca jest kontrolowanie zmiennych. Konsekwencje wypadków w naszej dziedzinie nauki mogą być niewyobrażalne!”\n– Profesor Heimerdinger","Zaklęcie",[],["Piltover i Zaun"],"ZWYKŁE"],"07NX028":["Kapitan Kalrix","Uderzenie w Nexus: Zadaj wrogiemu Nexusowi obrażenia równe połowie jego zdrowia (zaokrąglając w górę).","","Noxus to imperium powstałe w celu ekspansji ponad wszystko. Drewno, kamień, stal – nic nie powstrzyma rozwoju noxiańskiego Tarana.","Jednostka",[],["Noxus"],"EPICKIE"],"07NX034":["Szkarłatna Sala Bankietowa","Sojusznicy kosztują o 1 mniej. Gdy zagrasz sojusznika, zadaj mu 2 pkt. obrażeń.","","„Rozsiądźcie się, przyjaciele! Mamy doborowe towarzystwo i przepyszne napoje. Nie mogę się doczekać, aż zobaczycie, co jest na kolację”. – Vladimir","Lokacja",[],["Noxus"],"EPICKIE"],"07NX032":["Księga Ravenborn","Gdy trzymająca mnie karta zagra Umiejętność, skopiuj ją.","","Konserwatorium Ravenbloom było znane w szczególności ze swoich archiwów zapisków, z których wiele stało się paliwem dla olbrzymiego ognia, będącego sprawką pewnego podopiecznego…","Wyposażenie",[],["Noxus"],"RZADKIE"],"07NX033":["Kościoskóry Trójgon","Gdy mnie przywołasz, przyznaj mi +1|+1 za każdy inny podtyp sojuszników.","","„Ostrożnie, patafiany! Noxianie kupują bestie bojowe tylko w idealnym stanie. Jedno zadrapanie i utnę wam z wypłaty!”\n– Potentat Grubej Zwierzyny","Jednostka",["KOT"],["Noxus"],"ZWYKŁE"],"07RU015":["Król Poro","Pochodzenie: Dekret Króla Poro.\nGdy w danej rundzie po raz pierwszy przywołasz innego Poro, stwórz kartę Poro-Chrupki w ręce.","Udało ci się przywołać 6+ innych nowych Poro. Gdy awansuję, stwórz w ręce losową kartę Specjalnych Chrupek.","Ingvar rozpoznaje potencjał, gdy go zobaczy. Pomijając domowy wygląd, ten towarzysz mógłby z łatwością władać biliardem gazylionów Poro. Potrzeba tylko nieco wyobraźni. ","Jednostka",["PORO"],["Runeterra"],"Bohater"],"07RU012":["Neeko","Pochodzenie: Dżunglowi przyjaciele o różnych kształtach!\nZagraj: Możesz mnie przebrać za 1 z 3 stronników o koszcie 2 mojego Pochodzenia.","Atak: Atakujesz z sojusznikami, którzy mają 6+ innych podtypów.","Neeko może przyjąć różne postaci, ale jej serce nigdy się nie zmienia. Zawsze zaprowadzi ją z powrotem do rodziny i lasu.","Jednostka",["ZMIENNOKSZTAŁTNA"],["Runeterra"],"Bohater"],"07BW043":["Inwokacja Przypływu","Zadaj 1 pkt. obrażeń jednostce. Powołaj do Życia 1 za każdy punkt zadanych obrażeń.","","Tylko najlepsi potrafią kontrolować moc żywiołów.","Zaklęcie",["ŻYWIOŁ"],["Bilgewater"],"RZADKIE"],"07BW035":["Szulernia","Twoje karty w ręce mają Ulotność.\nGdy zagrasz kartę, dobierz 1 kartę.","","„Trzeba dobrze znać swoje karty i ich pilnować, lub być przygotowanym na utratę wszystkiego”. – Twisted Fate","Lokacja",[],["Bilgewater"],"EPICKIE"],"07BW042":["Łowca Pokładowy","Zagraj: Pokaż stronnika, który ma inny podtyp niż sojusznicy w grze.","","„Nie bez powodu trzymamy na pokładzie tego brudnego kudłacza: od lat nie mieliśmy tu szczurów!”\n– Majtek Drogi przez Mękę","Jednostka",["KOT"],["Bilgewater"],"ZWYKŁE"],"07BW039":["Smoczy Książę Grinzo","Kiedy po raz pierwszy w danej rundzie przywołasz sojusznika o koszcie 1, odzyskaj 1 pkt. many zaklęć.","","„Panie Jaszczur, co pan tu robi? Również lubi pan Poro?”\n– Ingvar Młodsza","Jednostka",["SMOK"],["Bilgewater"],"RZADKIE"],"07BW033":["Syrenia Pieśń","Przywołaj losową Skorupę.\nPrzyznaj sojusznikom o koszcie 1 +1|+1, gdziekolwiek są.","","Niektórzy żeglarze z Bilgewater wypychają sobie uszy bawełną w najcichsze noce na morzu. Dobrze wiedzą, że muzyka dochodząca z fal zwiastuje podwodny grobowiec.","Zaklęcie",[],["Bilgewater"],"ZWYKŁE"],"07IO041":["Orzeźwiająca Bryza","Ulecz swój Nexus o 3 pkt. i dobierz 2 zaklęcia.","","„Wiatr to jedyny przyjaciel podróżnika”. – Yasuo","Zaklęcie",["ŻYWIOŁ"],["Ionia"],"ZWYKŁE"],"07IO043":["Wszechwidząca Wyrocznia","Zagraj: Wybierz 1 z 3 Szybkich lub Powolnych zaklęć z ręki lub talii przeciwnika. Stwórz dla niego kartę Boskie Rzeźby.","","Oko niezwiązane ze światem materialnym widzi wszystko. Może i wygląda na ślepca, ale ci, którzy stwierdzą, że wyrocznia jest łatwym celem, zostają szybko i bezlitośnie skarceni.","Jednostka",[],["Ionia"],"RZADKIE"],"07IO049":["Airis","Uderzenie w Nexus: Przyzwij losową Skorupę.","","„Cichutko, już prawie jesteśmy na miejscu. Chcesz spotkać mojego przyjaciela, prawda? Zaufaj mi, polubi cię”.","Jednostka",[],["Ionia"],"RZADKIE"],"07SH038":["Kocię Pakaa","Zasadzka 1\nUderzenie w Nexus: Przywołaj Obrońca Pakaa.","","Wyglądają słodko, ale mają instynkt zabójców. Wystarczy nieco czasu i treningu, aby nawet najmniejsze z nich wyrosły na dzikich, silnych wojowników.","Jednostka",["KOT"],["Shurima"],"ZWYKŁE"],"07SH041":["W Ciemno","Pokaż kartę z Zasadzką.","","Rekonesans w dżungli to najgorsze zadanie głównie z jednego względu: pełno w niej niespodzianek.","Zaklęcie",[],["Shurima"],"RZADKIE"],"07SH004":["Grasowanie","Daj sojusznikowi +2|+0 w tej rundzie. Jeśli jest kartą Cień w Krzakach, zamiast tego daj mu +2|+2.","","„Krocz lekko, pakiti. Uderzaj celnie”. – Nidalee","Zaklęcie",[],["Shurima"],"ZWYKŁE"],"07SH013":["Nidalee","Zasadzka 2","Widziałam, jak przywołujesz lub przemieniasz 4 innych sojuszników.","„Zawsze będę cię chronić, jaszczurko. Razem zemścimy się na kłusownikach”. – Nidalee","Jednostka",["KOT"],["Shurima"],"Bohater"],"07SH009":["Mściciel Vastayów","Zasadzka 3\nGdy przemienię się z karty Zasadzka Mściciela Vastajów, powstrzymaj wszystkie wrogie Szybkie zaklęcia, Powolne zaklęcia i Umiejętności.","","„Nie lękajcie się, maleństwa. Ochronię was i spłacę swój dług Nidalee”.","Jednostka",[],["Shurima"],"ZWYKŁE"],"07SH039":["Żołnierz Terenowy","Zasadzka 0\nGdy mnie przywołasz lub przemienisz, przyznaj Najsłabszemu wrogowi Podatność.","","„To cacuszko potrafi przemienić nowicjusza we wspinającego się po drzewach i skałach profesjonalistę. Kosztowało mnie fortunę, ale z pewnością spłacę długi dzięki skórze kilku rzadkich bestii…”","Jednostka",[],["Shurima"],"RZADKIE"],"07SH044":["Aurora Hallunatis","Zasadzka 4\nGdy się przemienię, przywołaj kartę Aurora Hallunatis.","","„Jakże chcę ją zobaczyć! Większość podróżników wierzy, że Aurora Hallunatis to mit, ale pewien młody mężczyzna przyrzeka, że tak nie jest. Twierdzi, że ptak ma upierzenie o niesamowitym kolorze, a rozpiętość skrzydeł dorównuje wzrostowi człowieka. Po spojrzeniu temu stworzeniu w oczy od razu staje się jasne, kto jest tu zdobyczą”.\n– Dziennik polowy Anury, dzień 21","Jednostka",["PTAK"],["Shurima"],"RZADKIE"],"07SH003":["Kłusownik ze Sterowcem","Zasadzka 3\nGdy przemienię się z karty Zasadzka Kłusownika ze Sterowcem, następnym razem, gdy zablokuję lub zostanę zablokowana w tej rundzie, Zniewól mojego wroga.","","„Ha! Spróbujcie złapać mnie teraz, głupie bestie. Nawet grawitacja nie pokona inteligentniejszego gatunku!”","Jednostka",[],["Shurima"],"EPICKIE"],"07SH011":["Pułapka w Dziczy","Gdy mnie przywołasz albo gdy sojusznik po raz pierwszy się przemieni w danej rundzie, przyznaj Najsłabszemu wrogowi Podatność.","","„Czuć krew w powietrzu”. – Nidalee","Lokacja",[],["Shurima"],"ZWYKŁE"],"07SH046":["Dolina Imitacji","Gdy zagrywasz stronnika, przemień mnie w jego dokładną kopię na czas trwania tej rundy.","","„A to je NAJPIEKNIEJSZY punkt naszej wycieczki. Tak wielu lubi mojo wycieczke, że wybudowali DUŻEGO GŁAZKA, co sie bedzie wycieczkował po wsze wieki. Wszyscy mówimy »CZEŚĆ WIELKI GŁAZEK!«. Wielki Głazek kocha WSZYTKICH, szczególnie tych co sie załapali na wycieczka”. – Przygody z Głazkiem, cz. 6.","Lokacja",[],["Shurima"],"ZWYKŁE"],"07SH043":["Ogromny Pairofant","Zasadzka 5","","Jako najstarsi mieszkańcy dżungli, pairofanty mają w swej pieczy jej umysł i serce. Zazwyczaj to łagodne stworzenia, ale nie zawahają się obronić swojego domu przed zagrożeniem wszelakiej maści. ","Jednostka",[],["Shurima"],"EPICKIE"],"07SH040":["Jeżowieprz","Gdy po raz pierwszy sojusznik się przemienia, przyznaj mi +2|+1.","","„Małe ssaki pokryte kolcami przypominającymi futro. Mogą nimi strzelać, gdy poczują się zagrożone. Ogon również jest pokryty kolcami i niezwykle giętki – używają go w samoobronie. Według doświadczonych badaczy stworzenia te są niezwykle marudne i trudno się nimi zająć…”\n– Dziennik Polowy Anury, dzień 3","Jednostka",[],["Shurima"],"RZADKIE"],"07SH005":["Potentat Grubej Zwierzyny","Zagraj: Pokaż kartę z Zasadzką.\nGdy sojusznik się przemieni, podwój jego Siłę i Zdrowie.","","„Że jak wszystko przepadło? Naukowiec i jakiś gad? I co tak stoicie, tumany? Odzyskać moją kasę!”","Jednostka",[],["Shurima"],"RZADKIE"],"07FR011":["Świątynia Prawdziwego Lodu","Gdy przywołasz sojusznika, podnieś jego Zdrowie tak, aby było równe jego Sile.","","Nikt już nie wie, skąd wzięła się ta świątynia, ale nadal pilnuje jej kamienny strażnik, niezniechęcony wieloma lawinami. Jest pokryty szronem i wydaje się nasycony osobliwym, powabnym światłem…","Lokacja",[],["Freljord"],"EPICKIE"],"07FR010":["Śnieżny Brzytwiak","Grabież: Podnieś statystyki sojusznika do wysokości moich.","","Śnieżny Brzytwiak poluje głównie na drobne ssaki, ale ta bestia z Freljordu ma wystarczająco szponów, by poszatkować niemal wszystko.","Jednostka",["PTAK"],["Freljord"],"ZWYKŁE"],"07FR015":["Ingvar Młodsza","Zagraj: Wybierz sojusznika. Przyznaj mu i wszystkim innym sojusznikom z tym samym podtypem +1|+1 lub Pokaż sojusznika z tym samym podtypem.","","Samozwańcza nadzorczyni Poro i odkrywczyni Freljordu, Ingvar, jest pewna, że czeka ją przygoda – i rusza w jej poszukiwaniu. ","Jednostka",[],["Freljord"],"EPICKIE"],"07FR017":["Kryształowy Burzodziób","Zagraj: Zadaj 2 pkt. obrażeń WSZYSTKIM pozostałym jednostkom.","","Kryształowy burzodziób jest niesamowicie brutalny i każdy może stać się jego ofiarą. Odwraca losy bitwy w jednej chwili. Ptak ten jest uważany przez wielu za pierwszy omen wielkiego i gwałtownego sztormu – mającego na nowo ukształtować ziemski szkielet.","Jednostka",["PTAK"],["Freljord"],"RZADKIE"],"07FR016":["Lodowy Saurian","Gdy mnie przyzwiesz, przyznaj 3 jednostkom z wierzchu swojej talii +1|+1. Jeśli sojusznik ma inny podtyp niż ja, dobierz jedną z tych jednostek.","","Ich wielkie serca chowają się pod kościstą kopułą – te niezawodne rumaki są kluczowe do przemieszczania się po oblodzonych górskich przełęczach.","Jednostka",["GAD"],["Freljord"],"RZADKIE"],"07SI010":["Nekrotyczny Pajęczak","Gdy mnie przywołasz, przywołaj 2 karty Nekrotyczne Pisklęta.\nGdy zginie inny sojusznik, Zaczerpnij 1 pkt. Zdrowia z wrogiego Nexusa.","","Te pająki można spotkać tylko w najmroczniejszych zakątkach Wysp Cienia. Wydzielają one nekrojad wywołujący drętwienie skóry, która następnie zaczyna gnić.","Jednostka",["PAJĄK"],["Wyspy Cienia"],"EPICKIE"],"07SI012":["Nogoprządka Czubata","Zagraj: Jeśli sojusznik ma inny podtyp ode mnie, daj wrogowi -2|-0 w tej rundzie.","","Nogoprządki czubate pieczołowicie tworzą swoje gniazda. Kochają swoje pajączki i staną w ich obronie w obliczu każdego zagrożenia.","Jednostka",["PAJĄK"],["Wyspy Cienia"],"ZWYKŁE"],"07SI013":["Mnożąca Się Mroczna Zjawa","Ostatnie Tchnienie: Stwórz w talii dokładną kopię twojej Najsilniejszej karty Mnożąca Się Mroczna Zjawa w talii, a następnie podwój statystyki karty Mnożąca Się Mroczna Zjawa w talii.","","„Mgła dała mi cenną lekcję. Dzięki niej wiem, kiedy uciekać”. – Ixtalska Strażniczka","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"07SI004":["Święte Nożyce","Atak: Gdy inny sojusznik zyska Siłę dzięki Uświęceniu, moja karta też ją zyskuje.","","„Dobra para nożyc i porządna nić mogą rozwiązać każdy problem!” – Gwen","Wyposażenie",[],["Wyspy Cienia"],"RZADKIE"],"07MT009":["Epoka Smoków","Dobierz każdego Smoka spośród 9 kart z wierzchu swojej talii i obniż ich koszt do 0 w tej rundzie, a pozostałe karty wtasuj z powrotem.","","„Poznanie jednego smoka to znajomość samego siebie. Poznanie wielu to opanowanie całego świata”.\n– Wielbiciel Smoków z Ottrani","Zaklęcie",[],["Targon"],"RZADKIE"],"07MT013":["Kosmiczne Wezwanie","Wezwij Astralnego stronnika o koszcie 7 lub wyższym albo zapłać 8 i zmniejsz koszt swoich Astralnych stronników o połowę (zaokrąglając w górę), gdziekolwiek są.","","Sędzia nieprzemijalnie obserwuje błogosławieństwa zsyłane przez niebiosa.","Zaklęcie",[],["Targon"],"ZWYKŁE"],"07MT006":["Gwiezdni Kochankowie","Zagraj: Wycofaj sojusznika i przyznaj mu moje statystyki.","","„Nie ma lepszego widoku niż spotkanie słońca z księżycem”. – Diana","Jednostka",[],["Targon"],"ZWYKŁE"],"07BC020":["Pan Thrift","Gdy aktywuje się 1 lub więcej pułapek albo Darów, umieść 2 z nich w talii tego gracza.","","Nikt nie wie, od jak dawna pan Thrift jest kolekcjonerem, ani skąd pochodzi. Wydaje się być przyjaźnie nastawiony. Nie przejmujcie się pozostawianym przez niego śladem pułapek.","Jednostka",[],["Bandle City"],"RZADKIE"],"07BC016":["Klucz-Wróć","Gdy mnie odrzucisz, Wyposaż we mnie losowego sojusznika bez wyposażenia.","","„Nie zamierzam ściemniać – często gubię narzędzia. Na szczęście to tutaj zawsze pojawia się wtedy, gdy go potrzebuję!” – Inspektor Bezpieczeństwa","Wyposażenie",[],["Bandle City"],"ZWYKŁE"],"07BC018":["Znawca Portali","Gdy mnie przywołasz, umieść Tajemniczy Portal wśród pierwszych 4 kart z wierzchu swojej talii.\nGdy przywołasz stworzonego sojusznika, przyznaj mu Wpływ.","","Moje badania zawsze są pełne niespodzianek. Ta na szczęście należy do tych przyjemnych. ","Jednostka",["WRÓŻKA"],["Bandle City"],"EPICKIE"],"07BC011":["Groźny Puch","Gdy mnie przywołasz, przyznaj innym sojusznikom z podtypami +1|+1 oraz Wpływ.","","Na nieszczęście tej załogi kłusowników z Piltover, jedynie wyglądają na nieszkodliwych.","Jednostka",["PTAK"],["Bandle City"],"ZWYKŁE"],"07DE014":["Baczny Sierżant","Zagraj: Wybierz jednostkę spośród 5 kart z wierzchu swojej talii, która kosztuje 3 lub mniej. Przywołaj ją i umieść pozostałe karty w swojej talii.","","Na barkach sierżanta poborowego Demacii spoczywa wielka odpowiedzialność. Jego rekruci zajmą różne stanowiska, a wszyscy będą zjednoczeni przez obowiązek i miłość do Demacii.","Jednostka",["ELITARNY"],["Demacia"],"EPICKIE"],"07DE015":["Lwiostrząb Grzywiasty","Zagraj: Jeśli sojusznik ma inny podtyp ode mnie, Pokaż demaciańskie zaklęcie.","","„Dokumentuję pierwszy potwierdzony kontakt z lwiostrzębiem od niemal 50 lat. Piękny, błękitny grzebień, mądre oczy. Ma opancerzone ciało, ale kości są na tyle lekkie, że pozwalają wspinać się po drzewach, a nawet szybować. Skrzydła przypominają demaciańskie srebrnoskrzydłe. Należy dokonać dodatkowych pomiarów”.\n– Dziennik polowy Anury, dzień 12","Jednostka",["PTAK"],["Demacia"],"RZADKIE"],"07DE011":["Młodszy Łowca Magów","Zaklęcia, których koszt wynosi mniej niż 3, kosztują 3.","","„Cisza! To nie zwykła gra, lecz przykrywka jakiegoś sekretnego spisku. Dowiodę, że jesteś oszustem i magiem, ty stara łachudro – nawet jeśli przy okazji będzie trzeba spalić całą tę ruderę!”","Jednostka",[],["Demacia"],"ZWYKŁE"],"07DE016":["Balen Życzliwy","Atak: Przyznaj innym Ogromnym sojusznikom +0|+1, gdziekolwiek są.","","Odwieczny towarzysz rodziny Durandów. Ogromne rozmiary Balena nie wskazują na jego delikatną precyzję. Rozpoczął jako pomocnik. Świetnie zna się na swoim rzemiośle, które go inspiruje. Durandowie są dumni, że mogą go nazywać swoim przyjacielem.","Jednostka",[],["Demacia"],"EPICKIE"],"08SI042":["Mordekaiser","Zagraj: Zabij do 2 sojuszników.\nGdy Zgładzisz kolejnego sojusznika, wskrześ go.","Zginęło 15+ sojuszników. Sojusznicy o Sile 5+ liczą się podwójnie.","Związany ze swoim pancerzem trzymanym w sercu Bastionu Nieśmiertelności Mordekaiser wykuł w Krainie Szarości swój własny tron. W miejsce każdego, kto ośmieliłby się podjąć prób targnięcia się na niego, znajdzie się o wielu więcej, którzy będą służyć mu w życiu i śmierci.","Jednostka",[],["Wyspy Cienia","Noxus"],"Bohater"],"08SI040":["Erastin Zhańbiony","Gdy mnie przywołasz, przyznaj mi Bezśmiertność.\nAtak: Daj wrogom -1|-0 w tej rundzie.","","Smoki Camavoru były niegdyś majestatycznymi i szanowanymi istotami. Nawet one padły jednak ofiarą wszechogarniającego spaczenia niesionego przez Zrujnowanie. Erastin nie jest od tego wyjątkiem – jego dawno zatracona królewskość przeinaczyła się w kłujące w oczy oblicze bezśmiertności.","Jednostka",["SMOK"],["Wyspy Cienia"],"EPICKIE"],"08SI007":["Legion Odciętych","Zagraj: Przyznaj Bezśmiertność sojusznikowi w ręce.","","Nie ma znaczenia, jaką formę dusze przyjmowały przed uwięzieniem w Krainie Szarości. To miejsce, w którym indywidualność jest bezwartościowa. Legion niemający własnych twarzy i nieznający strachu właśnie dzięki swojej jednolitości tak dobrze służy Żelaznemu Upiorowi.","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"08SI003":["Skute Zmory","Ostatnie Tchnienie: Gdy następnym razem wskrzesisz sojusznika, stwórz moją kopię w ręce.","","„Wiele czasu minęło, odkąd nas zakuto. Wkrótce i ty zaznasz naszego cierpienia, a wtedy będziemy cierpieć razem po wsze czasy, póki nasz Pan nie zezwoli nam odejść w nicość…”","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"08SI021":["Samotny Dzwoniśluz","Gdy zginie inny sojusznik lub Ostatnie Tchnienie: Umieść 4 karty Dzwonki w swojej talii.","","Nie przejmuj się tym niepokojącym dzwonieniem, to tylko stary Dzwoniśluz się tu kręci. Zawsze z radością wita nowe twarze… chociaż one nie pałają radością na jego widok.","Jednostka",[],["Wyspy Cienia"],"ZWYKŁE"],"08SI030":["Wodna Mogiła","Unicestwij 6 kart ze spodu wrogiej talii.","","Dla niektórych potworów z najgłębszych otchłani mórz Runeterry ogromne statki to zaledwie lekkie przekąski.","Zaklęcie",[],["Wyspy Cienia"],"EPICKIE"],"08SI037":["Widmowy Żelazny Ogar","Aby mnie zagrać, zabij sojusznika.\nGdy mnie przywołasz, przywołaj kartę Śmiertnik Tysiąca Szponów.","","Te ogary nie zapominają woni uciekającej ofiary. A gdy już ją dopadną, śmiertnik kroczy tuż za nimi.","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"08SI041":["Śmiertelny Uścisk","Zabij sojusznika, aby zadać 5 pkt. obrażeń jednostce.","","„Mrok jest przeznaczeniem każdego z wyjątkiem mnie”.\n– Mordekaiser","Zaklęcie",[],["Wyspy Cienia"],"ZWYKŁE"],"08SI036":["Próg Szarości","Zagraj: Nałóż na wroga Klątwę: Trwoga.\nGdy przywołasz Tytanicznego sojusznika, zniszcz mnie, aby dobrać 2 karty.","","„Te oto dusze tobie składamy. Tę oto ścieżkę dla ciebie kośćmi wykładamy. Te oto krainy rozdzieramy, aby drogę otworzyć tobie i twojej armii żelaznego trwania wiecznego”. – Kultystka Uścisku Śmierci","Lokacja",[],["Wyspy Cienia"],"RZADKIE"],"08SI004":["Wymiar Śmierci","Sojusznik rozpoczyna Darmowy Atak, rzucając Wyzwanie Najsilniejszemu wrogowi.\nZabij WSZYSTKIE inne jednostki.","","„Śmierć jest moim królestwem”. – Mordekaiser","Zaklęcie",[],["Wyspy Cienia"],"EPICKIE"],"08SI026":["Kultystka Uścisku Śmierci","Gdy przywołasz mnie lub Tytanicznego sojusznika, nałóż Klątwę: Trwoga na Najsilniejszego wroga.","","W oczach swoich zwolenników Żelazny Upiór jest jedyną nadzieją dla tych, którzy pragną niebytu. Pokój poprzez dominację – ci kultyści przyjmują tę ideę z otwartymi ramionami.","Jednostka",[],["Wyspy Cienia"],"RZADKIE"],"08SI018":["Duchowy Inspektor","Zagraj: Wybierz zaklęcie Odkrywcy do stworzenia w ręce.","","„Teren jest nieprzenikniony. Widoczność – prawie żadna. Wróg czyha tu na każdym zakręcie… ale co dziwne, udało mi się też znaleźć niespodziewanych sojuszników”. – Zapiski ekspedycji Dywizji Zakamarków Świata Gildii Odkrywców, przydział: Wyspy Cienia","Jednostka",[],["Wyspy Cienia","Targon"],"RZADKIE"],"08SI015":["Amalgamat Plugawych Rytuałów","Aby mnie zagrać, zabij sojusznika.\nOstatnie Tchnienie: Ulecz swój Nexus o 2 pkt.","","W każdej armii ceni się bestie wojenne. W Krainie Szarości rolę tych bestii odgrywają udręczone zlepki dusz, z których każda w swoim braku świadomości pragnie jedynie brutalnie pochłaniać. ","Jednostka",[],["Wyspy Cienia"],"EPICKIE"],"08BW008":["Nilah","Atak: Stwórz kartę Ślizganie wśród pierwszych 6 kart z wierzchu swojej talii.","Udało ci się dobrać 15+ kart.","Na północy na Nilah i jej załogę czeka nowe wyzwanie: stworzenie zwane Volibearem, które grozi zniszczeniem Freljordu, gdzie niegdyś go czczono. Dla Nilah to kolejna okazja, by sprawdzić swoje umiejętności przeciwko potworowi, którego inni zwą bogiem. Z pewnością zgładzi też szereg pomniejszych potworów, przedłużając swoją listę osiągnięć. ","Jednostka",[],["Bilgewater"],"Bohater"],"08BW032":["Nieskończona Radość","Daj sojusznikom +1|+0 w tej rundzie i ulecz zranionych sojuszników o 2 pkt.","","„Nieustanna i wieczna radość!” – Nilah","Zaklęcie",["ŻYWIOŁ"],["Bilgewater"],"ZWYKŁE"],"08BW038":["Tańcząca z Czakramami","Zagraj: Zadaj 1 pkt. obrażeń dowolnemu celowi.\nTwoje Umiejętności Czerpią.","","Porusza się w tańcu wody i ostrzy, dobywając stali ze wzburzonej piany i bryzgających strumieni. Nie potrzebuje wzroku, by czuć pływy swoich broni – są one ożywioną wodą i w wodę obrócić się muszą.","Jednostka",[],["Bilgewater"],"EPICKIE"],"08BW015":["Tańcząca na Falach","Gdy mnie przywołasz, dobierz Nilah.\nW każdej rundzie, gdy zagrasz swoją trzecią kartę, przyznaj innym sojusznikom +2|+0 i Zuchwałość w tej rundzie.\nJeśli miałaby zostać nałożona na mnie Ulotność, zamiast tego mnie ujawnij.","","„Ponoć ten dziwny statek jest najszybszym w Bilgewater. I zwrotnym. Ma osobliwą kapitan, ale zna się na rzeczy. Może czegoś się od niej nauczymy”. – Karczmarz z Bilgewater","Jednostka",[],["Bilgewater"],"EPICKIE"],"08BW002":["Bezkształtne Ostrze","Zadaj 2 pkt. obrażeń jednostce. Nie może spaść poniżej 1 pkt. zdrowia po otrzymaniu tych obrażeń.","","„Potwory nazywające się bogami długo upadają. W każdej krainie”. – Nilah","Zaklęcie",["ŻYWIOŁ"],["Bilgewater"],"ZWYKŁE"],"08BW025":["Fachowy Obserwator","Po dobraniu 3+ kart w rundzie w tej grze przyznaj mi +1|+1 i Zuchwałość.","","„Hej, o co tyle szumu? Spokojnie! W tych wodach nie ma nic, z czym byśmy sobie nie poradzili!” – Oddany Wyzwaniom","Jednostka",[],["Bilgewater"],"ZWYKŁE"],"08BW026":["Oddany Wyzwaniom","Gdy mnie przywołasz, wywołaj Wzlot w swojej ręce, przyznaj mi +1|+1 za każdą kartę dobraną za pomocą Wzlotu i dobierz 2.","","„Ty się w ogóle starasz? Muszę się powstrzymywać, nie lubię tak robić!”","Jednostka",[],["Bilgewater"],"RZADKIE"],"08BW028":["Przygodowa Ośmiornica","Zagraj: Wybierz zaklęcie Odkrywcy do stworzenia w ręce.","","„Dziwny okaz. Bardzo niebieski. Oczy strasznie wielkie. Niepokojąco duże. Pozyskam do dalszych badań”. – Zapiski ekspedycji Dywizji Zakamarków Świata Gildii Odkrywców, przydział: Piltover","Jednostka",[],["Bilgewater","Piltover i Zaun"],"RZADKIE"],"08BW009":["Wiekowy Sternik","Zagraj: Pokaż dwa różne zaklęcia Żywiołów, które udało ci się zagrać w tej grze. Kosztują w tej rundzie 0.","","„Umysł jest jak rzeka. Z czasem jej nurt niszczy góry. Tak jak umysł może odkryć nowe brzegi”.","Jednostka",[],["Bilgewater"],"RZADKIE"],"08BW010":["Potop","Do końca gry wszystkie twoje zaklęcia i Umiejętności Żywiołów zadają dodatkowy 1 pkt. obrażeń.","","„W rozsądnych rękach woda ukształtuje wszystko”. \n– Oddany Mądrości","Zaklęcie",["ŻYWIOŁ"],["Bilgewater"],"EPICKIE"],"08BW031":["Sefirsa Postrach Głębin","Gdy zużywasz manę, żeby zagrać inną jednostkę, stwórz w ręce losową kartę o tym samym koszcie. Kosztuje ona 0 many i ma Ulotność.","","Zaprawieni kapitanowie z Bilgewater mają wielki apetyt na najdziwniejsze morskie stwory, ale nawet oni nie polują na niektóre z monstrów. Przyciszonym głosem opowiadają sobie o Sefirsie, potworze, którego hipnotyczne światło można spotkać na dużej głębinie, a który strzeże olbrzymiego cmentarzyska zatopionych statków i topielców.","Jednostka",["POTWÓR MORSKI","SMOK"],["Bilgewater"],"EPICKIE"],"08BW037":["Szczery Krupier","Kiedy zagrasz kartę o koszcie równym mojej Sile, przyznaj mi +1|+1.","","„Powiedz no, um, nie chcesz no może wyłożyć jeszcze trochę? Wiesz, bez ryzyka nie ma nagrody. Mówię ci, siedzisz przy szczęśliwym stoliku. A w tym zacnym przybytku rozdajemy sprawiedliwie – przyrzekam na język mojej mamusi”.","Jednostka",[],["Bilgewater"],"RZADKIE"],"08BW036":["Iglica Rafy Marajów","Kiedy wydajesz manę, aby zagrać jednostkę, odnów 1 pkt. many zaklęć.","","„Rafa od dawna jest nam schronieniem i sojuszniczką. Dba o nas tak, jak i my dbamy o nią, aby nikt z nas nie padł ofiarą mroku Toni”. – Wielka Matka Marajów","Lokacja",[],["Bilgewater"],"ZWYKŁE"],"08BW023":["Vikrash Entuzjasta","Gdy mnie przywołasz, stwórz kartę Ślizganie wśród pierwszych 6 kart z wierzchu swojej talii.","","„Spójrzcie, przyjaciele. Cały świat za nami podąża! Fale tańczą pod statkiem, wiatr w żaglach, ptaki w chmurach. Dołączcie do mnie i się radujcie!”","Jednostka",[],["Bilgewater"],"EPICKIE"],"08PZ007":["Stado Wichrowej Pieśni","Przywołaj kartę Wichrowa Jaskółka i przyznaj jej +1|+1 za każde inne zaklęcie lub Umiejętność Żywiołu, jakie udało ci się zagrać w tej grze.\nDobierz 1 kartę.","","Gdy wichrowe jaskółki gromadzą się w duże stada, sztorm nadchodzi wielkimi krokami.","Zaklęcie",["ŻYWIOŁ"],["Piltover i Zaun"],"RZADKIE"],"08PZ031":["Podejrzane Okulary","Wybierz sojuszniczego stronnika. Przemień trzymającą mnie kartę w jego dokładną kopię, dopóki jestem wyposażeniem tej karty.","","Nie pytaj, jak one działają.","Wyposażenie",[],["Piltover i Zaun"],"RZADKIE"],"08PZ025":["Prototyp Porobota","Ostatnie Tchnienie: Przyznaj losowemu zaklęciu o koszcie 6+ w ręce „Gdy mnie Zagrasz, przywołaj kartę Prototyp Porobota”.","","– To tylko prototyp – uczeń zawołał, podczas gdy płomienie pochłaniały laboratorium. – Nie programowałem go, żeby zjadał każdą zębatkę, jaką zobaczy! Ja nawet nie wiem, gdzie TRAFIA cały ten metal!”","Jednostka",["PORO"],["Piltover i Zaun"],"RZADKIE"],"08PZ005":["Oko Cyklonu","Daj sojusznikowi +2|+0 w tej rundzie.\nDobierz 2 karty.","","„Bądź spokojny! Burza może szaleć dookoła ciebie, ale nie wyrządzi ci krzywdy”. – Janna","Zaklęcie",["ŻYWIOŁ"],["Piltover i Zaun"],"ZWYKŁE"],"08PZ019":["Boska Trąba Powietrzna","Jeśli udało ci się dobrać 3+ kart w tej rundzie, kosztuję o 2 mniej.\nZadaj 3 pkt. obrażeń jednostce oraz 2 pkt. obrażeń wrogiemu Nexusowi.","","„Potęga wiatru jest do mej dyspozycji”. – Janna","Zaklęcie",["ŻYWIOŁ"],["Piltover i Zaun"],"RZADKIE"],"08PZ028":["Chemtechowy Smok","Gdy zagrasz zaklęcie, dobierz 1 kartę. Gdy dobierasz karty, mając pełną rękę, zadaj 1 pkt. obrażeń wrogiemu Nexusowi.","","Zaun wymaga adaptacji, a chemtechowy smok nie jest tu wyjątkiem. Spowity chorobliwie zieloną poświatą wzmocnień stara się przetrwać w trzewiach miasta. Podwójny cień zdewastowanych smoczych skrzydeł spowija mroczne aleje, zwiastując gniew wzbudzony własną degeneracją.","Jednostka",["SMOK"],["Piltover i Zaun"],"EPICKIE"],"08PZ001":["Janna","Zagraj: Wywołaj Wzlot 2 kart, aby dobrać 2 karty na Początku kolejnej rundy.\nW każdej rundzie przy pierwszych 3 dobraniach karty zmniejsz koszt dobranej karty o 1 w danej rundzie.","Widziałam, jak zagrywasz 8 kart o zmniejszonym koszcie.","„Zaun jest Jannie bliższe niż jakiekolwiek inne miejsce. Przecież to właśnie ona uratowała biedne dusze porzucone przez Piltover na śmierć. Tak – jeśli istnieją jakieś odpowiedzi, to zdobędę je właśnie tam”. – Niesiony Wiatrem Żeglarz","Jednostka",[],["Piltover i Zaun"],"Bohater"],"08PZ026":["Wezwanie Wichrowej Pieśni","Przywołaj kartę Wichrowa Jaskółka.","","„Wszelkie dzieci wiatru odpowiadają na moje wezwanie”. \n– Janna","Zaklęcie",["ŻYWIOŁ"],["Piltover i Zaun"],"ZWYKŁE"],"08PZ006":["Iascylla Marionetka Głębin","Gdy zagrasz zaklęcie lub Umiejętność Żywiołu, skopiuj je z tymi samymi celami.","","„Chodź, Iascyllo! Naprawdę musisz być stara, skoro Ashlesh zna twoje imię. Ale stara czy młoda, ładna czy brzydka, to zupełnie bez znaczenia. Dla żadnego potwora nie ma większego honoru, niż paść od mojego miecza prosto w otwarte wody morza”. – Nilah","Jednostka",[],["Piltover i Zaun"],"EPICKIE"],"08PZ018":["Niesiony Wiatrem Żeglarz","Jeśli udało ci się dobrać 3+ kart w tej rundzie, kosztuję o 2 mniej.","","„Tak, miałem to, czego chciałem. Ale miałem to wszystko przez odbieranie innym, a odbieranie innym zostawia człowieka pustego w środku. Pierwszą rzeczą, za którą nauczyłem się podążać, był wiatr. Dlatego tu teraz jestem, z nadzieją, że to ona popchnie mnie ku lepszej drodze”.","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"08PZ008":["Maryam, Opiekunka Świątyni","Zagraj: Wywołaj Wzlot 1 karty, aby dobrać 1 kartę lub odzyskać manę zaklęć.","","Maryam – przekonana, że została ocalona przez ducha wiatrów jako młoda dziewczyna – opiewa cnoty Janny od swojej ojczystej Shurimy aż po samo Zaun. Teraz, służąc jako matrona świątyni w Zaun, w całości oddaje się przekazywaniu życzliwości i dobroci Janny młodym i uciskanym.","Jednostka",[],["Piltover i Zaun"],"EPICKIE"],"08PZ009":["Zatopiona Świątynia","Koniec rundy: Wywołaj Wzlot wszystkich kart z ręki.\nPoczątek rundy: Dobierz tyle samo kart plus 1 dodatkową.","","Wiele zatracono w katastrofalnym upadku, który ostatecznie oddzielił Zaun od Piltover. Janna straciła swoją świątynię wśród fal, lecz ocaliła tych, którzy modlili się w jej wnętrzu.","Lokacja",[],["Piltover i Zaun"],"EPICKIE"],"08PZ002":["Wyjąca Wichura","Zadaj 2 pkt. obrażeń jednostce.\nZwiększ zadawane przez mnie obrażenia o 1 za każdą inną kartę, jaką udało ci się zagrać w tej rundzie, maksymalnie do 3 razy.","","„Moją furię niosą wyjące wiatry!” – Janna","Zaklęcie",["ŻYWIOŁ"],["Piltover i Zaun"],"RZADKIE"],"08PZ024":["Szarlatański Sprzedawca Ryb","Początek rundy: WSZYSCY gracze dobierają 1 kartę. Następnie przyznaj karcie przeciwnika Ulotność.","","„Dzisiaj u mnie dwa za jeden, tylko i wyłącznie dzisiaj! Świeżutkie rybki, złowione dopiero co… ee, w tym miesiącu? Dwie w cenie jednej! Ale jak to, nie chcesz tej drugiej? Za darmo jest!”","Jednostka",[],["Piltover i Zaun"],"ZWYKŁE"],"08PZ020":["Błogosławiony Chmuroplot","Jeśli udało ci się dobrać 3+ kart w tej rundzie, kosztuję o 2 mniej.\nGdy mnie przywołasz, dobierz 2 karty na Początku kolejnej rundy.","","„Mój drogi Zefirze. Przestań bujać w chmurach i zechciej usiąść na trochę na moim ramieniu, dobrze?” – Janna","Jednostka",[],["Piltover i Zaun"],"RZADKIE"],"08FR012":["Inwokacja Pioruna","Dobierz 1 kartę.\nPrzywołaj kartę Pieczęć Burzy.","","„W imię Valhira składamy tę ofiarę…” – Wieszczka Valhira","Zaklęcie",["ŻYWIOŁ"],["Freljord"],"ZWYKŁE"],"08FR033":["Berserkerka Ostrza","Gdy zagrasz Powolne zaklęcie, które obiera za cel pojedynczego sojusznika, skopiuj to zaklęcie na mnie.","","„Myślisz, że powstrzyma mnie jakaś strzała czy dwie? Ha! Wszystko, czym uderzysz, stanie się bronią w moim arsenale. A co zostanie stracone, przekuję na nowo w lodzie!”","Jednostka",[],["Freljord"],"ZWYKŁE"],"08FR019":["Rozszczepiacz Niebios","Daj sojusznikowi +1|+3 w tej rundzie.","","Przyodziany w płaszcz chmur i ukoronowany błyskawicami bóg-niedźwiedź stoi nietykalny w samym sercu burzy.","Zaklęcie",["ŻYWIOŁ"],["Freljord"],"ZWYKŁE"],"08FR001":["Volibear","Zagraj: Zagraj Bezlitosny Grom 3 razy. Za każdym razem celem jest inny losowy wróg, a w przypadku braku wrogów – wrogi Nexus.","Koniec rundy: Udało ci się zadać 50+ pkt. obrażeń.","„Padnij przede mną na kolana, śmiertelniku, a może nawet cię oszczędzę! Twoja moc jest wątła, ale możliwe, że wystarczy, żeby mi służyć. Na kolana, inaczej zmiotę cię z powierzchni ziemi!”","Jednostka",[],["Freljord"],"Bohater"],"08FR018":["Starcie Gigantów","Przywołaj 2 losowych Tytanicznych stronników.\nKosztuję o 1 mniej za każde zaklęcie lub Umiejętność Żywiołu, które udało ci się zagrać w tej grze (maks. 10).","","„Jego ciałem wyrzeźbiłem góry. Ogniem z jego paszczy wyciosałem tysiąc fiordów”. – Volibear","Zaklęcie",["ŻYWIOŁ"],["Freljord"],"EPICKIE"],"08FR011":["Kozia Przyzywaczka Płomieni","Gdy zagrasz zaklęcie lub Umiejętność Żywiołu, Wykuj mnie.","","„Pan Kuźni obiecał zmianę, a zamiast tego wykuł łańcuchy bezczynności. Ci, którzy czczą słabego boga, sami są słabi. Tylko dzięki potędze Valhira będzie nam dana dawna chwała!”","Jednostka",[],["Freljord"],"RZADKIE"],"08FR008":["Zwiastun Burzy","Zadaj 4 pkt. obrażeń WSZYSTKIM jednostkom z wyjątkiem Tytanicznych sojuszników.","","„Niech tundra spłynie czerwienią!” – Volibear","Zaklęcie",["ŻYWIOŁ"],["Freljord"],"RZADKIE"],"08FR024":["Yadulski Pies Śnieżny","Atak: Przyznaj 2 pierwszym sojusznikom z wierzchu talii +1|+1.","","Choć psy te wywodzą się z Yadulska, zostały udomowione przez wiele freljordzkich plemion do pomocy przy tropieniu, polowaniu i szukaniu zasypanych przez lawiny. Ich ogromna wytrzymałość i zdrowy apetyt na zabawę sprawiły, że są ukochanymi zwierzakami od tundry aż po tajgę.","Jednostka",["PIES"],["Freljord"],"ZWYKŁE"],"08FR015":["Rhond, Wąż Magmy","Zagraj: Przywołaj 3 karty Pieczęcie Burzy.","","Choć niewielu nadal go czci, to wszyscy Freljordczycy znają opowieść o wielkiej walce Volibeara i Rhonda. Na długo przed tym, jak śmiertelnicy postawili pierwsze kroki na skutej lodem północy, ta rozdzierająca ziemię bitwa utworzyła wzniesienia i rzeki samej tundry.","Jednostka",[],["Freljord"],"EPICKIE"],"08FR030":["Boadir Sczerniałego Lodu","Gdy mnie przywołasz, przywołaj 2 karty Zamarznięci Niewolnicy i rusz je Naprzód do 2.","","„Była o-okrutna! Niewolnicy spaleni na czarny lód, całe lawiny pod szponami, a jej ryk zrzucał śnieg ze szczytów! Jak nic, wojownicza królowa! Z-zabijanie niewolników to dzieło wojowniczej królowej” – Bełkoczący Bjerg","Jednostka",["SMOK"],["Freljord"],"EPICKIE"],"08FR002":["Wieszczka Valhira","Gdy mnie przywołasz, przywołaj kartę Pieczęć Burzy.","","„Widzę to, czego inni nie dostrzegają: burzę, która strzaska tę górę, pękające kości tej ziemi. Stary Freljord zostanie wykuty na nowo we krwi. To tylko kwestia czasu”.","Jednostka",[],["Freljord"],"ZWYKŁE"],"08FR028":["Praktyczna Uprząż","Mam +1|+0 za każdy rodzaj podtypu, jaki udało ci się przywołać w tej grze.","","„Mamy tu bestie, których nawet lawina nie powstrzyma. Właśnie dlatego dobra uprząż jest warta każdego grosza”.\n– Avarosański Traper","Wyposażenie",[],["Freljord"],"EPICKIE"],"08FR003":["Berserker Niedźwiedzi","Gdy zagrasz zaklęcia lub Umiejętność, przywołaj kartę Pieczęć Burzy.","","Zdarza się, że wyznawcy Volibeara zatracają się w swoim fanatyzmie tak bardzo, że zaczynają przyjmować aspekty samego niedźwiedzia. Nic nie stanie na drodze woli Valhira – nawet ci, których Niedźwiedzie nazywali niegdyś rodakami.","Jednostka",[],["Freljord"],"RZADKIE"],"08RU014":["Starszy Smok","Pochodzenie: Aspekt Smoka.\nKosztuję o 1 mniej za każdy poszczególny Smoczy Dar zagrany przez ciebie w tej grze.\nZagraj: Zagraj każdy Smoczy Dar na mnie.","Twoi sojusznicy zaatakowali z łączną Siłą wynoszącą 75+.","„Legenda głosi, że to najstarszy ze wszystkich smoków – król wszystkich uskrzydlonych bestii. Jeśli go ujarzmimy… Alatisie, co innego mogłoby nam stanąć na drodze? Świat w końcu zrozumie, że człowiek i smok najsilniejsi są razem”. \n— Volix Oddany Smokom","Jednostka",["SMOK"],["Runeterra"],"Bohater"],"08NX003":["Wściekły Ogniomiot","Zagraj: Zadaj 2 pkt. obrażeń wrogowi oraz 2 pkt. obrażeń wrogiemu Nexusowi.","","Noxiańska ekspansja pochłonęła wiele ludów, osad i kultur. Dzikie zwierzęta często skazane są na łaskę wojennej machiny, ale w przypadku tego smoka każdy brutalny krok Noxusu spotyka odpowiedź w postaci równie brutalnego huraganu ognistej furii.","Jednostka",["SMOK"],["Noxus"],"EPICKIE"],"08NX024":["Żelazny Legionista","Zagraj: Zadaj 3 pkt. obrażeń sojusznikowi, aby zadać 3 pkt. obrażeń wrogowi.","","„Wyrwijcie ich dusze z tego cielesnego więzienia!”\n– Mordekaiser","Jednostka",[],["Noxus"],"RZADKIE"],"08NX011":["Dziki Ogień","Zadaj 1 pkt. obrażeń wrogiemu Nexusowi. Zwiększ obrażenia o 1 za każdą inną kopię karty Dziki Ogień, którą udało ci się zagrać. Stwórz w swojej talii kartę Dziki Ogień.","","„Popiół, popiół…” – Annie","Zaklęcie",["ŻYWIOŁ"],["Noxus"],"ZWYKŁE"],"08NX028":["Niezniszczalność","Przyznaj sojusznikowi Bezśmiertność.","","„Wieczne żelazo”. – Mordekaiser","Zaklęcie",[],["Noxus"],"ZWYKŁE"],"08NX019":["Czerwonokolcy Brzytwobuch","Uderzenie w Nexus: Nałóż na swojego przeciwnika Klątwę: Posoka.","","Choć brzytwobuch jest użyteczną częścią noxiańskiej machiny wojennej, ceni się go również na arenach stolicy. Niewielu – czy to ludzi, czy zwierząt – ma odwagę stanąć przeciwko tej bestii, więc nieczęste walki brzytwobucha zawsze przyciągają tłumy z całego miasta.","Jednostka",["GAD"],["Noxus"],"ZWYKŁE"],"08NX014":["Dyrektorka Telsi","Sojusznicze efekty Ataku i Wsparcia aktywują się dodatkowy raz.","","Zajęcia Dyrektorki Telsi z dyscypliny osobistej to nic tylko żmudne zadania, bicie po nadgarstkach i ciągłe kary. Zajęcia od zawsze są obowiązkowe dla wszystkich uczniów Konserwatorium Ravenbloom – inaczej nikt nie chciałby się na nie zapisać.","Jednostka",[],["Noxus"],"EPICKIE"],"08NX012":["Uzbrojony Akwizytor","Zagraj: Wybierz zaklęcie Odkrywcy do stworzenia w ręce.","","„Wydawałoby się, że łatwiej będzie kopać na pustyni, ale gdzie tam! Przy upływie czasu piach z wielką chęcią zamienia się w kamień. Po raz kolejny wnoszę o udostępnienie funduszy na nowe narzędzia”. – Zapiski ekspedycji Dywizji Zakamarków Świata Gildii Odkrywców, przydział: Shurima","Jednostka",[],["Noxus","Shurima"],"RZADKIE"],"08NX029":["Smagnięcie Kashuri","Zabij zranioną jednostkę. Jeśli nie jest zraniona, zadaj jej 2 pkt. obrażeń.","","„To leży w twoim najlepszym interesie. Zaufaj mi”. \n– Lord Broadmane","Zaklęcie",[],["Noxus"],"EPICKIE"],"08NX009":["Lord Mallat","","","„Zapieczętowanie tego straszliwego podżegacza wymagało całych stuleci planowania, a ty i twoi żałośni przyjaciele zamierzacie pokonać go »radością«? Ty głupia dziewczyno. Nie osiągniesz niczego poza rozgniewaniem Upiora – a robiąc to, położysz życie nas wszystkich na szali”.","Jednostka",[],["Noxus"],"ZWYKŁE"],"08NX025":["Przebity Ostrzem Upiór","Gdy sojusznik zostanie wskrzeszony, przyznaj mu Wyzwanie.","","„Uśmiechasz się, ale ja znam prawdę czyhającą w twym zdradzieckim sercu! Oni też uśmiechali się do mnie, jedli z mojego stołu, nawet kiedy zamierzali wbić mi miecz w plecy. Już nikt więcej nie weźmie mnie za głupca. Umrzesz, tak jak i oni, wykrzykując swoje marne przeprosiny!”","Jednostka",[],["Noxus"],"RZADKIE"],"08SH009":["Prastare Przekleństwo","Nałóż na wroga Klątwę: Trwoga.","","Niektóre rzeczy najlepiej pozostawić pod powierzchnią piasków.","Zaklęcie",[],["Shurima"],"ZWYKŁE"],"08SH014":["Rogaty Przyzywacz Roju","Zagraj: Przyznaj dwóm wrogom -1|-0 i zablokuj ich pozytywne słowa klucze.","","Pomimo swoich budzących przerażenie rozmiarów ten przyzywacz roju rzadko ucieka się do przemocy. Gdy jego rój zbliża się do shurimańskiej osady, mieszkańcy zostawiają tym stworzeniom składające się z miękkich owoców ofiary na pobliskiej pustyni, aby odciągnąć uwagę gości od ważniejszych upraw.","Jednostka",["SMOK"],["Shurima"],"ZWYKŁE"],"08SH004":["Generał z Wydm","Brzask lub gdy aktywujesz inny Brzask: przyznaj Najsłabszemu wrogowi Podatność.","","Liczne armie Shurimy są gotowe, aby udowodnić potęgę pustyni. Gdy rozkaz zostanie wydany, maszerują naprzód bez najmniejszego wahania.","Jednostka",["ELITARNY"],["Shurima"],"RZADKIE"],"08SH005":["Obrońcy Słonecznego Dysku","Brzask: Dobierz kartę Obrońcy Słonecznego Dysku.","","„Jesteśmy strażnikami trwającej po wieki pustyni, żywą historią, kroczącymi drogą ku świetlistości. Kłaniamy się Słonecznemu Dyskowi i niczemu więcej, aby świat pokłonił się chwale Shurimy”. – Azir","Jednostka",["ELITARNY"],["Shurima"],"ZWYKŁE"],"08SH012":["Barbara Łupieżczyni Grobowców","Gdy w danej rundzie po raz pierwszy zginie inny sojusznik lub Ostatnie Tchnienie: Stwórz w ręce kartę Szczęśliwe Znalezisko.","","„Wspaniałe zdobycze, Barb. Wiedziałem, że mogę na ciebie liczyć. Zaraz… co ma znaczyć, że cię widzieli?!”\n– Vekaurański Osiłek","Jednostka",["GAD"],["Shurima"],"RZADKIE"],"08SH002":["Połykacz Diun","Aby mnie zagrać, zabij sojusznika lub zniszcz jeden ze swoich kryształów many 3 razy.","","Połykacz Diun drzemie dużo głębiej niż jego mniejsi kuzyni Xer’Sai. Ta istota z łatwością pożera inne drapieżniki Xer’Sai, z czego niewielu zdaje sobie sprawę, gdyż potrafi połykać wydmy w całości (wraz z potencjalnymi świadkami). ","Jednostka",[],["Shurima"],"EPICKIE"],"08MT003":["Morgana","Zagraj: Nałóż na wroga Klątwę: Kajdany dwukrotnie.","Jednostki stały się twoim celem 10+ razy.","„Przybywasz do mnie obita i krwawiąca, a mimo tego twoje oblicze promieniuje radością, jakiej w życiu nie widziałam. Zaiste jesteś dziwną kobietą… ale jesteś tu bezpieczna. Odpocznij, proszę, a gdy poczujesz się lepiej, z chęcią wysłucham twojej historii”.","Jednostka",[],["Targon","Demacia"],"Bohater"],"08MT005":["Mihira Wyniesiony Aspekt","Zagraj: Nałóż Klątwę: Kajdany na 2 wrogów dwukrotnie.","","„To w imię moich córek przyjęłam boskość. To dla mojej rodziny porzuciłam własną ludzkość, aby tym oto płonącym mieczem na nowo stworzyć świat prawdy i sprawiedliwości”.","Jednostka",[],["Targon"],"EPICKIE"],"08MT042":["Pęta Grzesznika","Nałóż na wroga Klątwę: Kajdany.\nZwiększ koszt Klątw rzucanych przez wroga o 1, gdziekolwiek są.","","„Aby odnaleźć wolność, przyznaj się do mroku w swojej głębi”. – Morgana","Zaklęcie",[],["Targon"],"RZADKIE"],"08MT024":["Sztukmistrz o Rubinowych Oczach","Zagraj: Przyznaj Tarczę Magii lub Zmiażdżenie sojusznikowi w ręce.","","„Nie lękajcie się! Idźcie i nie patrzcie za siebie! My też kiedyś przebyliśmy tę drogę. Teraz naszym obowiązkiem jest dopilnowanie, aby i wam się to udało. Ruszajcie szybko do jej sanktuarium, a Skryta za Woalem udzieli wam ochrony, której potrzebujecie”.","Jednostka",[],["Targon"],"ZWYKŁE"],"08MT045":["Spętany Czarownik","Zagraj: Nałóż na mnie Klątwę: Kajdany.","","Łowcy magów potrafili łamać ludzi jak nikt inny. Spętali nie tylko jego ręce, ale i jego magię. Odebrali mu głos. Już raz przetrwał jednak te katusze. Tym razem miał u swojego boku Zamaskowaną Panią.","Jednostka",[],["Targon"],"RZADKIE"],"08MT015":["Lisa i Dolly","Zagraj: Nałóż na wroga Klątwę: Kajdany.","","„Spójrz, Dolly! Udało mi się, dokładnie tak, jak mówiłaś! Myślisz, że kiedyś będziemy mogły pokazać mamie, ile się nauczyłam? Myślisz, że ona już wie? Naprawdę?! Mam nadzieję, że masz rację”. – Lisa","Jednostka",[],["Targon"],"ZWYKŁE"],"08MT030":["Łagodny Klejnotowy Smok","Kiedy zagrasz Szybkie zaklęcie, Powolne zaklęcie lub Umiejętność, przyznaj innym sojusznikom będącym Smokami +1|+1.","","Temperament smoków bywa zróżnicowany tak samo, jak zróżnicowany jest ich wygląd. Zdarzają się gatunki skłonne do rozsiewania zniszczenia, na przykład Piekielne Smoki, ale są też gatunki z równym oddaniem dbające o swoje rodziny i otoczenie – choćby powolny i czuły Klejnotowy Smok.","Jednostka",["SMOK"],["Targon"],"RZADKIE"],"08MT023":["Mroczne Uwiązanie","Ogłusz wroga i nałóż na niego Klątwę: Kajdany.","","„Cierp tak, jak oni cierpią przez ciebie!” – Morgana","Zaklęcie",[],["Targon"],"RZADKIE"],"08MT031":["Wielbiciel Smoków z Ottrani","Gdy mnie przywołasz, ulecz swój Nexus o 2 pkt. i zyskaj dodatkowy kryształ many w następnej rundzie.","","Na sięgających nieba zboczach Targonu samotny Ottran poświęcił swoje życie smokom. Przyozdobiony zrzuconymi łuskami i starymi kośćmi swoją drogę naprzód odczytuje z rozrzuconych smoczych zębów i kłębów dymu niesionych na wietrze ku szczytowi góry.","Jednostka",[],["Targon"],"EPICKIE"],"08MT009":["Zamaskowany Obrońca","Gdy przywołasz mnie lub Tytanicznego sojusznika, ulecz swój Nexus o 3 pkt.","","Ten zamaskowany obrońca nie zapomniał błogosławieństwa, które wyniosło go ponad szeregi zwykłych bestii. Teraz spłaca swój dług, dbając o to, by nie stała się krzywda nikomu, kto szuka schronienia na zboczach Targonu.","Jednostka",[],["Targon"],"RZADKIE"],"08MT006":["Mroczna Tarcza","Daj sojusznikowi Tarczę Magii w tej rundzie i nałóż na niego Klątwę: Kajdany.","","„Ochrona przed prześladowaniami!” – Morgana","Zaklęcie",[],["Targon"],"RZADKIE"],"08MT027":["Zwiastun Astralnej Konwergencji","Zagraj: Aktywuj efekty Brzasku i Zmroku innych sojuszników.\nBrzask: Przyznaj mi Zmiażdżenie.\nZmrok: Przyznaj mi Tarczę Magii.","","„Ognisty krąg płonie ponad nami. W zwiastowanej ciemności wszyscy jesteśmy tacy sami”. – Kaznodzieja Lunari","Jednostka",["PTAK"],["Targon"],"EPICKIE"],"08MT025":["Sejsmiczny Odłamek","Jeśli Widzisz Tytaniczną jednostkę, kosztuję o 3 mniej.\nZadaj 7 pkt. obrażeń jednostce.","","„Ups, o-oł, się wogle nie przejmuj tym tutaj, takie tylko maciupcie pęknięcie w kamyku, wypadek taki, nie, tatko, NIE! Idziemy stąd!” – Głazek","Zaklęcie",["ŻYWIOŁ"],["Targon"],"ZWYKŁE"],"08DE006":["Uczony Pionier","Zagraj: Wybierz zaklęcie Odkrywcy do stworzenia w ręce.","","„Jest zimno. Marznę. Wszystko jest zlodowaciałe, cały czas. Są miejsca, które nie są po prostu przeznaczone dla ludzi. Proszę, wyślijcie mnie potem w jakieś ciepłe miejsce”. – Zapiski ekspedycji Dywizji Zakamarków Świata Gildii Odkrywców, przydział: Freljord","Jednostka",[],["Demacia","Freljord"],"RZADKIE"],"08DE020":["Magiczne Spętanie","Przyznaj sojusznikowi +0|+2. Nałóż na swojego przeciwnika Klątwę: Stłumienie.","","„Poznaj ciężar swoich grzechów!” – Morgana","Zaklęcie",[],["Demacia"],"ZWYKŁE"],"08DE017":["Łowca Magów Inkwizytor","Gdy mnie przywołasz, nałóż na swojego przeciwnika Klątwę: Stłumienie.","","„Nie możemy im pozwolić dotrzeć do sanktuarium upadłej siostry. Jej magia jest pradawna i wypaczona, niemożliwa do stłumienia nawet z moimi zdolnościami. Szybko, zabierzcie te abominacje z powrotem na statek, a potem wyruszamy w góry, pochwycić resztę!”","Jednostka",[],["Demacia"],"RZADKIE"],"08DE025":["Podniebny Smok","Gdy mnie przywołasz, zmniejsz koszt wszystkich sojuszniczych jednostek w ręce o 1.","","Te smoki posiadają na ciele kępy grubego futra, dzięki któremu są w stanie osiągać znacznie wyższe pułapy niż większość innych smoków. Pełne życia i nieuchwytne, często widywane są wysoko na niebie, gdzie ich skrzydła przecinają chmury podczas ich zabaw wśród wiatrów i wichur.","Jednostka",["SMOK"],["Demacia"],"EPICKIE"],"08DE010":["Pojedynek Dżentelmenów","Daj sojusznikowi +0|+2 w tej rundzie.\nTen sojusznik i wróg uderzają siebie nawzajem.","","„En garde, przyjacielu! Z pewnością nie ma w tobie tyle tchórzostwa, ażeby odmówić dżentelmeńskiego pojedynku?” – Kawaler z Rodu Laurentów","Zaklęcie",[],["Demacia"],"ZWYKŁE"],"08DE022":["Królewski Rybak","Gdy mnie przywołasz, dobierz 1 kartę każdego bohatera z talii.\nGdy w danej rundzie po raz pierwszy przywołasz bohatera, Zjednocz Siły.","","„Tylko pamiętaj, synu, że każda pogoń za horyzontem musi odbywać się w służbie ojczyzny, którą zostawiasz za plecami” – Król Jarvan III","Jednostka",[],["Demacia"],"EPICKIE"],"08DE027":["Szponiasty Cios","Przyznaj sojuszniczym Ptakom +1|+1, gdziekolwiek są. Sojuszniczy Ptak Uderza wroga.","","Skrzek Srebrnoskrzydłego oznacza spadającą z nieba śmierć.","Zaklęcie",[],["Demacia"],"RZADKIE"],"08DE026":["Alatis Waleczny","Twoje Smocze Dary obierają za cel wszystkich sojuszników będących Smokami.","","„Dla jasności, ja nie zawsze byłem oddany smokom. To Alatis mnie przekonał, kiedy po raz pierwszy uratował mi życie. Wiele mnie nauczył, ale co z tych nauk było najważniejsze? Nie ma lepszego życia, niż służenie Demacii na grzbiecie smoka”. – Oddany Smokom","Jednostka",["SMOK"],["Demacia"],"EPICKIE"],"08DE013":["Oddany Smokom","Gdy mnie przywołasz, dobierz Smoka, jeśli Widzisz Smoka.","","„Wiesz, trudno mi to przyznać, staruszku, ale sami nie damy rady go oswoić. Zrobiliśmy już wszystko, co było możliwe. Poślę słowo do generała. Z całą potęgą Demacii za plecami na pewno uda nam się zmusić tę fantastyczną bestię do ugięcia się”.","Jednostka",[],["Demacia"],"ZWYKŁE"],"08IO012":["Oceaniczny Smok","Gdy zagrasz Szybkie zaklęcie, Powolne zaklęcie lub Umiejętność, ulecz swój Nexus o 1 pkt.","","„Wspaniała z ciebie bestia! Tyle jest szczęścia w tym, jak przesuwasz pazurami po falach. Gdybyś kiedyś postanowił zapolować na coś więcej niż ryby i nadmorskie ptaki, z radością się z tobą zmierzę”. – Nilah","Jednostka",["SMOK"],["Ionia"],"RZADKIE"],"08IO014":["Heisho Skorupa Świata","W każdej rundzie pierwsza karta, którą zagrasz, kosztuje o 9 mniej.","","Dla mieszkańców tej ioniańskiej wioski Heisho jest zarówno wielce szanowanym opiekunem, jak i przyjacielem. Nosi ich domy na swoim grzbiecie od niepamiętnych czasów, a oni ufają, że w czasach niepokoju będzie szukał spokojnych wybrzeży.","Jednostka",["GAD"],["Ionia"],"EPICKIE"],"08IO021":["Podniebny Taniec","Zatrzymaj wrogie Szybkie zaklęcie, Powolne zaklęcie lub Umiejętność, Wycofaj wroga i przywołaj kartę Empireum.","","„W tańcu trwa nasza pamięć”. – Irelia","Zaklęcie",[],["Ionia"],"RZADKIE"],"08IO019":["Spolegliwy Adnere","Gdy mnie przywołasz, przywołaj kartę Ptasznicy Adnere.","","„W tej krainie można się wiele nauczyć. Zawsze pamiętaj, należy celebrować upływ każdej pory roku, gdyż tylko z kresu rodzi się nowy początek”.","Jednostka",[],["Ionia"],"RZADKIE"],"08IO010":["Do Góry Dnem","Wycofaj wroga, aby zwiększyć koszt kolejnej jednostki, którą twój przeciwnik zagra w tej rundzie o 2.","","„Ci, którzy pragną naszej krzywdy, znajdą wytchnienie na dnie morza”. – Rzekotwórca","Zaklęcie",["ŻYWIOŁ"],["Ionia"],"ZWYKŁE"],"08IO023":["Brykające Morskie Duchy","Zagraj: Przywołaj moją dokładną Efemeryczną kopię.","","Gdy wiatr zawieje nad morzem w określonych chwilach w ciągu roku, niektórzy Zaunici zarzekają się, że widzą nikłe sylwetki dwóch dużych, posiadających płetwy stworzeń, które tańczą radośnie wśród fal oceanu.","Jednostka",[],["Ionia"],"ZWYKŁE"],"08BC020":["Ranny Ptaszek","Twój przeciwnik odrzuca swoją kartę o najwyższym koszcie.","","„Wyobraź sobie, że jesteś dżdżownicą, a ostatnia rzecz, jaką widzisz przed śmiercią, to te oczy. Och, dżdżownice nie widzą? No, to w sumie dobrze dla nich”. \n– Elle Poirytowana Podróżniczka","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"08BC005":["Wybuchający Plecak","Za każdą zagraną kartę Wybuchający Plecak w tej grze umieść 4 Dzwonki w twojej talii i 4 Trujące Grzyby w talii wroga. Stwórz w swojej talii kartę Wybuchający Plecak.","","„Zasada 207: Zwiadowca nigdy nie bierze ze sobą więcej, niż musi!” – Ava Ambitniaczka","Zaklęcie",[],["Bandle City"],"RZADKIE"],"08BC021":["Podstępna Zamiana","Wycofaj sojusznika i wezwij na jego miejsce kartę Głodna Kotosowa.","","„KRZEEEEK?” – Kotosowa","Zaklęcie",[],["Bandle City"],"RZADKIE"],"08BC002":["Skip, „Król Raf”","Zagraj: Wybierz 1 z 2 niebędących bohaterami kart z ręki wroga. Zniewolę ją.","","„Tak, jestem szybki, przystojny i niesamowicie czadowy. Nie wiesz, starcze? Jestem królem tej rafy, a ty jesteś tu nieproszony!”\n„Chwila! Wracaj tu w tej chwili! Potrzebuję tego okazu do moich badań!” – Konchiolog","Jednostka",[],["Bandle City"],"EPICKIE"],"08BC006":["Portalowy Pionier","Zagraj: Wybierz zaklęcie Odkrywcy do stworzenia w ręce.","","„Martwię się o Bunchesa! Coraz bardziej się zamartwia. Nawet szybki skok przez portal to dla niego trud! Nie rozumiem dlaczego”. – Zapiski ekspedycji Dywizji Zakamarków Świata Gildii Odkrywców, przydział: Bandle City","Jednostka",["YORDLE"],["Bandle City","Ionia"],"RZADKIE"],"08BC004":["Osobliwa Portia","Zagraj: Pokaż Tytanicznego stronnika i ustaw jego statystyki na 1|1 oraz koszt na 0.","","„Pewnie, że znam starą Portię! Trochę szurnięta, ale w razie potrzeby otworzy ci portal, dokąd zechcesz. Smagnie ogonem i już lecisz” – Portalowy Pionier","Jednostka",["SMOK"],["Bandle City"],"EPICKIE"],"08BC018":["Słodka Pułapka","Umieść sojusznika na spodzie swojej talii, aby przywołać pierwszego sojusznika z wierzchu swojej talii.","","„Zasada nr 571: Zwiadowca zawsze powinien być czujny. Nigdy nie wiadomo, co jest pyszną przekąską, a co może być pułapką”. – Ava Ambitniaczka","Zaklęcie",[],["Bandle City"],"RZADKIE"],"09SI015":["Piękna Katastrofa","I: Zabij jednostkę, której łączna wartość Siły i Zdrowia wynosi 5 lub mniej.\nII: Zaczerpnij 2 pkt. Zdrowia z wrogiego Nexusa.\nIII: Przywołaj dokładną kopię sojusznika. Otrzymuje Efemeryczność i statystyki 1|1.","","Wszedł na scenę z wierszem w dłoni. Nie reklamował swojego występu, ponieważ miał już jedyną publiczność, jakiej chciał.","Lokacja",["FABUŁA"],["Wyspy Cienia"],"EPICKIE"],"09SI013":["Żelazny Podbój","I-II: Wybierz sojuszniczego stronnika. Stwórz jego Efemeryczną kopię z +1|+1 w ręce.\nIII: Wskrześ Najsilniejszego poległego sojuszniczego stronnika i przyznaj mu Efemeryczność.","","W Krainie Szarości torturowane postaci tworzą widmową armię. Nic jej nie powstrzyma, gdy wrota do świata śmiertelników staną otworem.","Lokacja",["FABUŁA"],["Wyspy Cienia"],"RZADKIE"],"09SI012":["Lęk Egzystencjalny","Przyznaj wrogom Posępność.","","„Czy cokolwiek ma w ogóle sens?” – Vex","Zaklęcie",[],["Wyspy Cienia"],"RZADKIE"],"09SI017":["Kharox","Gdy zginie sojusznik (nie Macka) lub Ostatnie Tchnienie: Powołaj do Życia 2 razy.","","Kharox, samotny wioślarz widmowego statku nazywanego Ostatnim Promem, ponoć komunikuje się z duchami wszystkich żeglarzy, którzy zginęli, próbując dopłynąć na wyspy.","Jednostka",[],["Wyspy Cienia"],"EPICKIE"],"09SI014":["Grimm","Zagraj: 4-krotnie przyznaj jednostce Posępność.","","Mroczny romantyk, udręczony poeta i koneser wszystkiego, co związane z filozofią. Grimm nie lęka się odrobiny posępności i grozy. Obiekt jego uczuć potrafi zranić, ale w oczach Grimma to urocza cecha jej charakteru.","Jednostka",["YORDLE"],["Wyspy Cienia"],"ZWYKŁE"],"09DE033":["Duszki","","","„Duszki to niesamowite stworzenia. Przy odpowiednim śpiącym i odrobinie cierpliwości ich potencjał nie zna granic!” – Matka Duszków","Jednostka",[],["Demacia","Ionia"],"ZWYKŁE"],"09DE039":["Światło Demacii","I: Przyznaj sojusznikowi Ducha.\nII: 2-krotnie przyznaj sojusznikowi Ducha.\nIII: Dodaj Sił wszystkim sojusznikom.","","Wiwaty tłumu przybrały na sile, gdy jej blask objął ich twarze. Jedyne, czego pragnęła, to wspierać i podnosić na duchu swój lud. Ten zaś w podzięce wspierał też ją, oddając jej hołd i wołając: „Luxanna! Luxanna! Luxanna!”","Lokacja",["FABUŁA"],["Demacia"],"RZADKIE"],"09DE034":["Lux: Rozświetlona","Wsparcie: Przyznaj wspieranemu przeze mnie sojusznikowi Ducha i daj mi Barierę w tej rundzie.","Sojusznicy podczas atakowania zdobyli łącznie 20+ pozytywnych słów kluczy lub zaatakowali za ich pomocą.","Ludzie na ulicy pełni zachwytu patrzyli, jak światło wiruje i tętni dookoła Luxanny. Tutaj była ona Panią Światła \nDemacii – przykładną, młodą Obrończynią Korony oraz utalentowaną magiczką. Tutaj Demacia była wszystkim tym, czego ona zawsze pragnęła.","Jednostka",[],["Demacia"],"Bohater"],"09DE047":["Zapomniany Artefakt","Przywołaj kartę Piaskowy Szarżownik, a następnie daj sojusznikom Wyzwanie w tej rundzie.","","W głębi skarbca łowców magów, w którym trzymano skonfiskowane magiczne przedmioty, znajdowała się dziwna rzeźba. Brakowało jej opisu, a jej cel dawno został już zapomniany…","Zaklęcie",[],["Demacia"],"RZADKIE"],"09DE041":["Petrucytowa Sala","I: Sojusznik Zniewala jednostkę.\nII: Nałóż na swojego przeciwnika Klątwę: Stłumienie.\nIII: Unicestwij wszystkie karty Zniewolone przez sojuszników.","","Wiwaty tłumu ucichły, gdy weszła na salę. Posągi przyglądały się jej w milczeniu. Przed nią trwała nieprzenikniona ciemność, lecz ona nie mogła zawrócić. Nikt inny nie powstrzyma upadku i pochłonięcia Demacii przez koszmar.","Lokacja",["FABUŁA"],["Demacia"],"EPICKIE"],"09DE030":["Rozblask","Dodaj Sił wszystkim jednostkom.","","„Nic nie przyćmi naszego blasku!” – Lux: Rozświetlona","Zaklęcie",[],["Demacia"],"ZWYKŁE"],"09DE043":["Narastające Światło","3-krotnie Dodaj Sił wszystkim jednostkom.","","„Spowici światłem!” – Lux: Rozświetlona","Zaklęcie",[],["Demacia"],"RZADKIE"],"09DE031":["Jarro Światłopióry","Zagraj: Przyznaj sojusznikowi w ręce Ducha.","","Młody mężczyzna w masce balowej pojawił się przed nią w pełnej okazałości. Jego nadejście zwiastowały niesione wiatrem płatki róży i świetliste stworzenia. \n– Na imię mi Światłopióry. Jarro Światłopióry – przedstawił się. – Powiedziano mi, że możesz być w potrzebie pomocy, moja pani?","Jednostka",[],["Demacia"],"RZADKIE"],"09DE046":["Rozpalający Uśmieszek","Dodaj Sił 2 sojusznikom, którzy następnie Uderzą wroga jeden po drugim.","","„Spokojnie, moje panie. Wystarczy mnie dla każdej”. \n– Jarro Światłopióry","Zaklęcie",[],["Demacia"],"ZWYKŁE"],"09DE045":["Alina Senne Światło","Gdy mnie przywołasz, przywołaj 5 kart Duszki. Za każdą z nich, na którą nie ma miejsca, 2-krotnie przyznaj Najsłabszemu sojusznikowi Ducha.","","„Kiedy byłam w twoim wieku, to światło tak bardzo mnie przerażało. Nie miałam nikogo, kto by mi powiedział, że moja magia jest darem, że została mi nadana z jakiejś przyczyny. Ale ty masz mnie, więc to właśnie ci mówię. Nie bój się, Alino. Pozwól mu lśnić”. – Lux: Rozświetlona","Jednostka",[],["Demacia"],"EPICKIE"],"09DE040":["Odmienny Łowca Magów","Gdy mnie przywołasz, przyznaj innym sojusznikom Ducha.","","– Panienka Obrończyni Korony. – Łowca magów wyłonił się spomiędzy cieni, wyciągając dłoń w jej kierunku. Jego upraszający wręcz uśmiech wydawał się nieprzyjemnie szeroki względem jego częściowo przysłoniętej twarzy. – Może zechcesz udać się ze mną?","Jednostka",[],["Demacia"],"ZWYKŁE"],"09DE036":["Duszki Drzewa","Zagraj: Dodaj Sił wszystkim innym jednostkom.","","„No dalej, maleństwa. Wskażcie swojemu śniącemu drogę”. \n– Lillia","Jednostka",[],["Demacia","Bandle City"],"ZWYKŁE"],"09DE029":["Rozświetloduch","Wsparcie: Daj wspieranemu przeze mnie sojusznikowi wszystkie moje pozytywne słowa klucze i ich ładunki w tej rundzie.","","„Chodź, Panie Duchu. Prześwietlmy wszystkie te okropne cienie!” – Alina Senne Światło","Jednostka",[],["Demacia"],"RZADKIE"],"09SH010":["Rekonstruktorka Imperium","Zagraj: Przyznaj sojuszniczej lokacji „Po moim zniszczeniu wskrześ mnie”.","","Narodziny imperatora rozbudziły nadzieję w sercach Shurimian. Ta magiczka i samozwańcza „Rekonstruktorka Imperium” uparcie przemierza pustynię, by przywrócić pogrzebanym ruinom ich dawny blask i spełnić wizję Azira.","Jednostka",[],["Shurima"],"ZWYKŁE"],"09SH009":["Armia Imperatora","I: Przywołaj 2 karty Piaskowi Żołnierze.\nII: Spójrz w Przyszłość.\nIII: Kiedy przywołasz sojusznika w tej rundzie, daj mu +2|+0 w tej rundzie.","","Azir wie, jaka Shurima była, jest i będzie. Wierzy, że jego wizja to coś więcej niż zwykły sen. To przepowiednia, którą musi spełnić.","Lokacja",["FABUŁA"],["Shurima"],"EPICKIE"],"09SH012":["Wezwanie Zrodzonych ze Słońca","Wybierz 1 z 3 bohaterów, którzy na początku znajdowali się w twojej talii, i dobierz go.","","Mnóstwo artefaktów pradawnych wojowników zrodzonych ze słońca zostało zapomnianych. Nie zawsze można jednak powiedzieć to samo o bogach-wojownikach, których reprezentują.","Zaklęcie",[],["Shurima"],"RZADKIE"],"09PZ044":["Modlitwa przy Świetle Świec","I-II: Wywołaj Wzlot 1 karty, aby dobrać 1 kartę.\nIII: Dobierz 1 kartę.","","Ta świątynia wzniesiona ku czci Janny posiada niewiele solidnych ścian, aby jak najlepiej połączyć się z mocami bogini. Mimo tego niezliczone świece zdają się wiecznie płonąć, nawet gdy nad resztą Zaun szaleje wyjąca burza.","Lokacja",["FABUŁA"],["Piltover i Zaun"],"EPICKIE"],"09PZ045":["Szybujący Kartograf","Zagraj: Wywołaj Wzlot 1 karty, aby dobrać inną kartę o koszcie większym lub mniejszym od karty, której Wzlot wywołano.","","„Wysokość jest najskuteczniejszym sposobem dostrzeżenia swojej własnej nieistotności”.","Jednostka",[],["Piltover i Zaun"],"RZADKIE"],"09PZ046":["Malmutacja","Wybierz sojuszniczego stronnika. Przywołaj 2 karty Głodne Kotosowy, po czym przemień sojuszników w dokładne kopie wybranego sojusznika.","","„Jeszcze tylko jedna kopia… i będzie idealnie”. \n– Okrutny Imperfekcjonista","Zaklęcie",[],["Piltover i Zaun"],"EPICKIE"],"09IO055":["Płatkowa Wróżka","Gdy mnie przywołasz, przywołaj kartę Duszki.","","„Włosy Lillii to katastrofa! Weź coś z nimi zrób, co? Pamiętajcie, że pierwszy włos spełnia życzenia, drugi służy marzeniom, a ostatni wszystkiemu, co nie jest tym, czym się wydaje”. – Matka Duszków","Jednostka",[],["Ionia"],"RZADKIE"],"09IO056":["Taniec Duszków","Wycofaj sojusznika i przyznaj wszystkie ładunki jego Ducha innemu sojusznikowi.","","„Dzięki marzeniom można oderwać się od rzeczywistości!” – Lillia","Zaklęcie",[],["Ionia"],"RZADKIE"],"09IO048":["Matka Duszków","Gdy mnie przywołasz, przyznaj sojuszniczym kartom Duszki i Matki Duszków Ducha, gdziekolwiek są.","","Duszki są uduchowione, zmienne i nie zawsze chętne do słuchania. Matka Duszków opiekuje się nimi, a w razie potrzeby je karci, aby każdy z nich dotarł do swojego śniącego.","Jednostka",[],["Ionia"],"EPICKIE"],"09IO049":["Żniwa Rosy","I: Przywołaj kartę Duszki.\nII: Uśpij sojusznika.","","Każda kropla rosy z Drzewa Matki pozwala nam wejrzeć w sen kogoś w Runeterze. Każdą kroplę należy ostrożnie zebrać, pielęgnować i chronić.","Lokacja",["FABUŁA"],["Ionia"],"ZWYKŁE"],"09IO052":["Lillia","Gdy mnie przywołasz lub Uderzę: Stwórz w ręce kartę Konar Snów lub – jeśli już taką masz – zmniejsz jej koszt o 1.","Udało ci się przywołać 15+ sojuszników lub lokacji.","W samym sercu Ogrodu Zapomnienia trwają zbiory rosy. Choć Lillia i pozostali opiekunowie utrzymują krople w pięknym stanie, można w nich dostrzec osobliwe spaczenie. Sny, które pokazują, są mroczne i upiorne…","Jednostka",[],["Ionia"],"Bohater"],"09IO046":["Pani Ogrodu Ofeliów","Zagraj: W pełni ulecz sojusznika, po czym Uśpij go.","","Sprawowanie opieki nad Śniącym Drzewem i otaczającym je ogrodem to niezwykły zaszczyt, ale wymaga poświęceń. Jeśli chce być częścią tego rytuału szacunku i wdzięczności, opiekun musi oddać swoje własne wspomnienia, każdej nocy tracąc cząstkę siebie.","Jednostka",[],["Ionia"],"ZWYKŁE"],"09IO051":["Zakorzeniona Ścieżka","I-II: Dobierz 1 kartę.\nIII: Zmniejsz koszt kart w ręce o 1 w tej rundzie.","","Ogród Zapomnienia jest domem różnorodnych stworzeń, zarówno małych, jak i dużych. Niektóre są bardziej świadome, niżby tego chciały.","Lokacja",["FABUŁA"],["Ionia"],"RZADKIE"],"09IO053":["Pan Korzeń","Gdy mnie przywołasz, dobierz 1 kartę.","","„Pewnego dnia całe to piękno będzie martwe, a my wraz z nim. Obym był pierwszy. He, he!”","Jednostka",[],["Ionia"],"ZWYKŁE"],"09IO045":["Kwitnący Pąk","Uśpij jednostkę.","","„Sny kwitną!” – Lillia","Zaklęcie",[],["Ionia"],"RZADKIE"],"09IO058":["Serce Drzewa","I: Ulecz swój Nexus o 3 pkt. i przywołaj kartę Duszki.\nII: Przyznaj sojusznikom Ducha, gdziekolwiek są.\nIII: Pokaż kartę o koszcie 8 lub wyższym i zmniejsz jej koszt o połowę (zaokrąglając w górę).","","Duchy snów są jednymi z liczniejszych mieszkańców Ogrodu. Różnią się kształtami, rozmiarami i temperamentami, a wiele z nich decyduje się wniknąć do kropli rosy, aby poprowadzić swojego śniącego ku jego najgłębszym pragnieniom.","Lokacja",["FABUŁA"],["Ionia"],"EPICKIE"],"09IO059":["Stalowa Wichura","Ogłusz wroga. Ogłusz go ponownie na początku kolejnej rundy.","","„Ostrze ponad wszystko”. – Yone Ścigający Wiatr","Zaklęcie",[],["Ionia"],"ZWYKŁE"],"09FR009":["Parada Poro","I-II: Pokaż stronnika, który ma inny podtyp niż sojusznicy w grze.\nIII: Daj sojusznikowi +1|+1 w tej rundzie za każdego sojusznika z podtypem.","","Ingvar znacząco umocniła swoją relację z podwładnymi Króla Poro od czasu jej wizyty w królestwie. Szarżowanie przez Freljord w poszukiwaniu przygód to jeden z najlepszych sposobów na zacieśnianie stosunków dyplomatycznych.","Lokacja",["FABUŁA"],["Freljord"],"EPICKIE"],"09FR014":["Brynhir Grzmotopieśni","Zagraj: Unicestwij jednostkę w ręce, aby przywołać dokładną kopię tej jednostki i kartę Burzowa Iglica, której Odliczanie jest równe jej kosztowi (co najmniej 1).","","„Wykuto mnie w górskiej burzy i pieśni mego ludu!”","Jednostka",[],["Freljord"],"EPICKIE"],"09FR010":["Mięciusieńki Poro","Zagraj: Ulecz swój Nexus o 1 pkt. za każdego sojusznika z podtypem.","","„Spójrzcie tylko na ten puch!” – Pasterz Poro","Jednostka",["PORO"],["Freljord"],"ZWYKŁE"],"09FR012":["Lodowcowy Topór","Przyznaj sojusznikowi Zdrowie równe jego Sile oraz Ogrom. Następnie ustaw jego Siłę na 0.","","Niektóre drzewa we Freljordzie można ściąć tylko potęgą zimy.","Zaklęcie",[],["Freljord"],"RZADKIE"],"09BC020":["Wściekłe Spojrzenie","Przyznaj jednostce Posępność, aby dobrać 1 kartę.","","„Gratulacje. Nienawidzę cię”. – Vex","Zaklęcie",[],["Bandle City","Wyspy Cienia"],"ZWYKŁE"],"09BC012":["Spotkanie Rodzinne","I: Przyznaj jednostce Posępność.\nII: Przyznaj sojusznikowi Wpływ.\nIII: Dodaj Sił 2 jednostkom.","","Nieobecność nie jest w stanie bardziej rozczulić tego serca. Ale przynajmniej rodzinne obiady przebiegają tu w ciszy – tak, jak Vex lubi.","Lokacja",["FABUŁA"],["Bandle City"],"EPICKIE"],"09BC001":["Vex","Atak: Przyznaj Najsilniejszemu wrogowi Posępność.","Udało ci się przyznać Posępność 5+ razy.","„Uch, durna, różowa dziewucha. Już jej mówiłam, że NIE ZNOSZĘ imprez, a szczególnie jeśli są na nich torty. Ohyda. Weźcie mnie obudźcie, jak sobie pójdzie”.","Jednostka",["YORDLE"],["Bandle City","Wyspy Cienia"],"Bohater"],"09BC002":["Wujek Milty","Przyznaj mi 2-krotnie Ducha, jeśli udało ci się ukończyć historię.","","Choć z całą pewnością diametralnie różni się on od swojej ponurej kuzynki, Wujek Milty zawsze robi, co w jego mocy, aby odnaleźć z nią wspólny język – szczególnie jeśli może to zrobić dzięki strasznej historii opowiedzianej przy świetle świec.","Jednostka",["YORDLE"],["Bandle City"],"RZADKIE"],"09BC013":["Skrzydłonadawanie","I-II: Wybierz sojusznika. Następnie wybierz 1 z 3 stronników kosztujących o 1 więcej, w którego chcesz go przemienić.\nIII: Wybierz sojusznika. Następnie wybierz 1 z 3 stronników kosztujących o 2 więcej, w którego chcesz go przemienić.","","Stary Trevor Drzemkozad jakimś cudem zawsze odpływa w taki czy inny sen. Na szczęście ten konkretny wydaje się być dość spokojny… choć w niewyjaśniony sposób każdy, kto się z nim spotka, nagle chce mieć takie same skrzydła…","Lokacja",["FABUŁA"],["Bandle City"],"RZADKIE"],"09BC004":["Allay","Zagraj: Przyznaj mi Ducha lub przyznaj jednostce Posępność.","","„Veeeee! Czeeekaaaaj! Mam coś dla ciebie! To zaproszenie na twoje własne PRZYJĘCIE URODZINOWE! I twój prezent, tak trochę wcześniej! NIE MOGŁAM się doczekać. Nie cieszysz się? Musimy pogadać o tym, co założyć, no i o TORCIE, no i… Vee?”","Jednostka",["YORDLE"],["Bandle City"],"ZWYKŁE"],"09BC016":["Potworna Erupcja","Zwiększ Siłę lub Zdrowie sojusznika do 5 w tej rundzie.","","„Najgorszy. Prezent. Na świecie”. – Vex","Zaklęcie",[],["Bandle City"],"ZWYKŁE"],"09BC003":["Groteskowy Prezent","Za pierwszym razem, gdy zostanie przywołany wróg, przyznaj mu Posępność.","","„A to ci, nawet nie taki zły był ten prezent”. – Vex","Jednostka",[],["Bandle City"],"RZADKIE"],"09BC018":["Cień","Gdy mnie przywołasz, dobierz kartę Vex.\nMam +1|+0 za każdy raz, gdy udało ci się nałożyć Posępność w tej grze.","","„Tak, pokaż im, Cieniu! Żadnych prezentów, żadnego konfetti, a już NA PEWNO żadnych papierowych czapeczek”. – Vex","Jednostka",[],["Bandle City","Wyspy Cienia"],"EPICKIE"],"09BC011":["Posępne Duchy","Uderzenie: Przyznaj mi Wpływ.","","„Sny zmieniają duchy w śmieszny sposób. Te wydają się być… och, czy to ciasto?” – Lillia","Jednostka",[],["Bandle City"],"ZWYKŁE"],"09BC006":["Napakowany Burmistrz","Początek rundy: Dodaj mi Sił.","","Czas zwolnił, gdy niecodziennie umięśniony burmistrz wyskoczył nagle z niemożliwie wysokiego tortu. \n– Wszystkiego BAAAAAAARDZO NAJLEPSZEGO – burmistrz zawołał, prężąc muskuły – od najwspanialszego i najsilniejszego demokratycznie wybranego urzędnika Bandle!\n\nZe wszystkich swoich snów tego konkretnie Vex nienawidziła najbardziej.","Jednostka",["YORDLE"],["Bandle City"],"ZWYKŁE"],"09BW022":["Czempionka Areny","I: Sojusznik i wróg Uderzają siebie nawzajem. Ich Zdrowie nie może spaść poniżej 1 pkt. w wyniku tego Uderzenia.\nII: W pełni ulecz sojusznika.\nIII: Stwórz w ręce 3 karty Monety.","","Angel całe lata spędziła na łowieniu zwycięstwa w walce, która położy kres wszystkim walkom. Każdej nocy śni o stercie złota tak wielkiej, że mogłaby wypełnić całą Zatokę Bilgewater. Mowa, oczywiście, o złocie z plantacji ziemniaków.","Lokacja",["FABUŁA"],["Bilgewater"],"EPICKIE"],"09BW028":["Gorliwy Pasjonat","Mam +1|+0 za każdą dobraną w tej rundzie kartę.","","„Ale jak to »muszę więcej trenować«? Przecież TRENOWAŁEM, patrz, patrz!”","Jednostka",[],["Bilgewater"],"RZADKIE"],"09BW027":["Najemnicze Maniery","Skradnij w tej rundzie wrogiego stronnika o Zdrowiu 3 lub mniejszym. (Nie możesz zagrać, gdy masz już 6 sojuszników lub lokacji).","","„Krew za złoto to zawsze dobry początek dnia”. \n– Najemniczka","Zaklęcie",[],["Bilgewater"],"ZWYKŁE"],"09MT002":["Dymnołuski Nosiciel","I–II: Odrzuć 1 kartę, aby aktywować. Wezwij Astralną kartę o koszcie 7 lub większym.\nIII: Zmniejsz koszt losowej karty ze swojej ręki o 5.","","Ten samotny Ottrańczyk poświęcony jest czczeniu i uwielbianiu smoków do tego stopnia, że dostrzega te dostojne bestie zarówno w zbudzonych, jak i śniących światach.","Lokacja",["FABUŁA"],["Targon"],"EPICKIE"],"09MT004":["Błogosławieństwa zza Całunu","2-krotnie przyznaj sojusznikowi Ducha.","","„Ja będę ich sanktuarium”. – Morgana","Zaklęcie",[],["Targon"],"ZWYKŁE"],"09MT005":["Śniąca Smoczej Pieśni","Gdy w danej rundzie po raz pierwszy Wezwiesz kartę, przywołaj kartę Smoczątko.","","„Smoki są blisko. Czuję to. Nawet w tej chwili dryfują przez moje sny”.","Jednostka",[],["Targon"],"EPICKIE"],"09NX025":["Największy Wojownik Areny","I-II: Daj sojusznikowi +2|+0 w tej rundzie.\nIII: Spraw, by wróg Nie mógł blokować w tej rundzie.","","Popularność areny po części wynika z faktu, że wszyscy mogą tu zawalczyć o sławę i uznanie. Ten konkretny fan widział każdy pojedynek Dravena, na jakim tylko mógł się pojawić. Jest pewien, że gdyby miał taką szansę, on też byłby w stanie dotrzeć na sam szczyt.","Lokacja",["FABUŁA"],["Noxus"],"EPICKIE"],"09NX032":["Treser Yeti","Aby mnie zagrać, odrzuć 1 kartę.\nGdy mnie przywołasz, przywołaj kartę Wściekły Yeti.","","Sukces noxiańskich machin wojennych wynika po części z ich elastyczności. Jeśli trudny teren lub nieprzyjazne warunki wymagają dostosowania się, wojsko wykorzysta nawet najmniej oczywiste z lokalnych zasobów.","Jednostka",[],["Noxus"],"RZADKIE"],"09NX033":["Skażony Topór Wojenny","Koniec rundy: Jeśli trzymająca mnie karta nie atakowała w tej rundzie, przyznaj jej Posępność.","","Tchórzostwo słono kosztuje.","Wyposażenie",[],["Noxus"],"RZADKIE"]};
window.ATLAS_I18N_LOR_G={"sets":{"Call of the Mountain":"Zew Góry","Beyond the Bandlewood":"Po Drugiej Stronie Lasu Bandle","Foundations":"Fundamenty","Rising Tides":"Wzbierający Przypływ","Worldwalker":"Wędrowcy Świata","Empires of the Ascended":"Imperia Wyniesionych","Dreamlit Paths":"Ścieżki w Blasku Snów","Glory in Navori":"Chwała w Navori","Fate's Voyage":"Podróż Przeznaczenia","Heart of the Huntress":"Serce Łowczyni","Events":"Wydarzenia","The Darkin Saga":"Saga Darkinów"},"regions":{"Noxus":"Noxus","ElderDragon":"Starszy Smok","Ryze":"Ryze","Jhin":"Jhin","Varus":"Varus","Aatrox":"Aatrox","Neeko":"Neeko","Jax":"Jax","Kayn":"Kayn","PoroKing":"Król Poro","Evelynn":"Evelynn","Bard":"Bard","Demacia":"Demacia","Runeterra":"Runeterra","Freljord":"Freljord","ShadowIsles":"Wyspy Cienia","Targon":"Targon","Ionia":"Ionia","Shurima":"Shurima","Bilgewater":"Bilgewater","PiltoverZaun":"Piltover i Zaun","BandleCity":"Bandle City","SpiritBlossom":"Duchowy Rozkwit"},"rarities":{"COMMON":"ZWYKŁE","RARE":"RZADKIE","EPIC":"EPICKIE","CHAMPION":"Bohater","NONE":"Brak"}};
